/**
 * Extra checklist items for a specific destination, appended after the
 * fixed TRAVEL_CHECKLIST_ITEMS — general guidance only, NOT medical advice.
 * Each item's own label says so; components/travel-checklist.tsx also
 * shows a standing disclaimer above the checklist when any of these apply.
 */
export function healthChecklistItemsFor(country: string): ChecklistItem[] {
  const items: ChecklistItem[] = [];
  if (YELLOW_FEVER_CERTIFICATE_COUNTRIES.has(country)) {
    items.push({
      key: 'travel_yellow_fever_certificate',
      label: 'Confirm whether a yellow fever vaccination certificate is required for entry',
    });
  }
  if (MALARIA_RISK_COUNTRIES.has(country)) {
    items.push({ key: 'travel_malaria_prevention', label: 'Talk to a doctor about malaria prevention for this region' });
  }
  if (GENERAL_TRAVEL_HEALTH_COUNTRIES.has(country)) {
    items.push({
      key: 'travel_routine_vaccines',
      label: 'Confirm routine travel vaccines (commonly Hepatitis A and Typhoid) with a doctor or travel clinic',
    });
  }
  return items;
}
