import { useRouter } from 'expo-router';
import { useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, TextInput } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { supabase } from '@/lib/supabase';

const TINT = Colors.light.tint;

export default function AddConnectionScreen() {
  const router = useRouter();
  const { session } = useAuth();

  const [email, setEmail] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  async function handleSend() {
    if (!session) return;
    const trimmedEmail = email.trim();
    if (!trimmedEmail) {
      setError('Enter an email address.');
      return;
    }

    setError(null);
    setSuccess(false);
    setIsSending(true);
    const myId = session.user.id;

    const { data: otherId, error: lookupError } = await supabase.rpc('find_user_id_by_email', {
      p_email: trimmedEmail,
    });

    if (lookupError) {
      setIsSending(false);
      setError(lookupError.message);
      return;
    }
    if (!otherId) {
      setIsSending(false);
      setError('No Cluster user found with that email.');
      return;
    }
    if (otherId === myId) {
      setIsSending(false);
      setError('You can’t connect with yourself.');
      return;
    }

    const { data: existing, error: existingError } = await supabase
      .from('connections')
      .select('*')
      .or(`and(requester_id.eq.${myId},recipient_id.eq.${otherId}),and(requester_id.eq.${otherId},recipient_id.eq.${myId})`)
      .maybeSingle();

    if (existingError) {
      setIsSending(false);
      setError(existingError.message);
      return;
    }

    if (existing) {
      if (existing.status === 'pending') {
        setIsSending(false);
        setError('A connection request is already pending with this person.');
        return;
      }
      if (existing.status === 'accepted') {
        setIsSending(false);
        setError('You are already connected with this person.');
        return;
      }

      // declined or removed — reopen as a fresh invite from me, resetting
      // who's requester/recipient so the accept-only-by-recipient trigger
      // still points at the right person this time around.
      const { error: reopenError } = await supabase
        .from('connections')
        .update({ requester_id: myId, recipient_id: otherId, status: 'pending' })
        .eq('id', existing.id);
      setIsSending(false);
      if (reopenError) {
        setError(reopenError.message);
        return;
      }
      setSuccess(true);
      setEmail('');
      return;
    }

    const { error: insertError } = await supabase
      .from('connections')
      .insert({ requester_id: myId, recipient_id: otherId, status: 'pending' });

    setIsSending(false);
    if (insertError) {
      setError(insertError.message);
      return;
    }
    setSuccess(true);
    setEmail('');
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ThemedView style={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: TINT }}>
            Add Someone
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
        {success ? (
          <ThemedText style={styles.success}>
            Request sent. They&apos;ll need to accept it before you&apos;re connected.
          </ThemedText>
        ) : null}

        <ThemedText type="defaultSemiBold">Their email</ThemedText>
        <TextInput
          value={email}
          onChangeText={setEmail}
          autoCapitalize="none"
          autoCorrect={false}
          keyboardType="email-address"
          placeholder="friend@example.com"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: TINT }]}
        />

        <Pressable onPress={handleSend} disabled={isSending} style={[styles.button, { backgroundColor: TINT }]}>
          {isSending ? (
            <ActivityIndicator color={Colors.light.backgroundSolid} />
          ) : (
            <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Send request</ThemedText>
          )}
        </Pressable>
      </ThemedView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  error: {
    color: Colors.light.negative,
  },
  success: {
    color: Colors.light.positive,
  },
});
