import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput } from 'react-native';

import { CountryAutocompleteInput } from '@/components/country-autocomplete-input';
import { CountryFlag } from '@/components/country-flag';
import { DateInput } from '@/components/date-input';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useCurrency } from '@/contexts/currency-context';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import type { PriorResidencyRow } from '@/types/database';

const TINT = Colors.light.tint;

export default function PriorResidenciesScreen() {
  const router = useRouter();
  const { session } = useAuth();
  const { hiddenFlagCountries } = useCurrency();

  const [residencies, setResidencies] = useState<PriorResidencyRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [showForm, setShowForm] = useState(false);
  const [country, setCountry] = useState('');
  const [city, setCity] = useState('');
  const [startDate, setStartDate] = useState<Date | null>(null);
  const [endDate, setEndDate] = useState<Date | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const load = useCallback(async () => {
    if (!session) return;
    setError(null);
    const { data, error: fetchError } = await supabase
      .from('prior_residencies')
      .select('*')
      .order('start_date', { ascending: false });
    if (fetchError) {
      setError(fetchError.message);
    } else {
      setResidencies(data ?? []);
    }
    setIsLoading(false);
  }, [session]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  function resetForm() {
    setCountry('');
    setCity('');
    setStartDate(null);
    setEndDate(null);
    setShowForm(false);
  }

  async function handleAdd() {
    if (!session || !country.trim() || !startDate || !endDate) return;
    setError(null);
    setIsSaving(true);
    const { error: insertError } = await supabase.from('prior_residencies').insert({
      user_id: session.user.id,
      country: country.trim(),
      city: city.trim() || null,
      start_date: toDateOnlyString(startDate),
      end_date: toDateOnlyString(endDate),
    });
    setIsSaving(false);
    if (insertError) {
      setError(insertError.message);
      return;
    }
    resetForm();
    await load();
  }

  async function handleRemove(id: string) {
    setError(null);
    const { error: deleteError } = await supabase.from('prior_residencies').delete().eq('id', id);
    if (deleteError) {
      setError(deleteError.message);
      return;
    }
    setResidencies((prev) => prev.filter((r) => r.id !== id));
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: TINT }}>
            Prior residencies
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText style={styles.hint}>
          Countries you used to live in, before your current home country. The country you were living in becomes
          your home country for that date range, so trips you log elsewhere during that window are not blocked by
          it, and you do not need to log it as a trip of its own.
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {isLoading ? (
          <ActivityIndicator color={TINT} style={styles.loading} />
        ) : (
          <>
            {residencies.length === 0 ? <ThemedText style={styles.hint}>None added.</ThemedText> : null}
            {residencies.map((r) => (
              <Surface key={r.id} accentColor={TINT} style={styles.row}>
                <ThemedView style={styles.rowInfo}>
                  <ThemedView style={styles.inputRow}>
                    <CountryFlag countryName={r.country} hiddenFlagCountries={hiddenFlagCountries} size={18} />
                    <ThemedText type="defaultSemiBold">{r.city ? `${r.city}, ${r.country}` : r.country}</ThemedText>
                  </ThemedView>
                  <ThemedText style={styles.hint}>
                    {formatDateDisplay(r.start_date)} &rarr; {formatDateDisplay(r.end_date)}
                  </ThemedText>
                </ThemedView>
                <Pressable onPress={() => handleRemove(r.id)} hitSlop={12}>
                  <IconSymbol name="trash" size={18} color={Colors.light.negative} />
                </Pressable>
              </Surface>
            ))}

            {showForm ? (
              <Surface accentColor={TINT} style={styles.formSurface}>
                <ThemedText type="defaultSemiBold">Country</ThemedText>
                <CountryAutocompleteInput
                  value={country}
                  onChangeText={setCountry}
                  onSelectCountry={setCountry}
                  hiddenFlagCountries={hiddenFlagCountries}
                  accentColor={TINT}
                />

                <ThemedText type="defaultSemiBold">City (optional)</ThemedText>
                <TextInput
                  value={city}
                  onChangeText={setCity}
                  placeholder="e.g. New York"
                  placeholderTextColor={Colors.light.textMuted}
                  style={[styles.input, { color: Colors.light.text, borderColor: TINT }]}
                />

                <ThemedText type="defaultSemiBold">Start date</ThemedText>
                <DateInput
                  value={startDate}
                  onChange={(date) => {
                    setStartDate(date);
                    if (endDate && endDate < date) setEndDate(date);
                  }}
                  accentColor={TINT}
                />

                <ThemedText type="defaultSemiBold">End date</ThemedText>
                <DateInput value={endDate} onChange={setEndDate} accentColor={TINT} minimumDate={startDate ?? undefined} />

                <ThemedView style={styles.formActions}>
                  <Pressable onPress={resetForm} hitSlop={8}>
                    <ThemedText style={styles.muted}>Cancel</ThemedText>
                  </Pressable>
                  <Pressable
                    onPress={handleAdd}
                    disabled={isSaving || !country.trim() || !startDate || !endDate}
                    style={[
                      styles.saveButton,
                      { backgroundColor: TINT, opacity: isSaving || !country.trim() || !startDate || !endDate ? 0.5 : 1 },
                    ]}>
                    {isSaving ? (
                      <ActivityIndicator color={Colors.light.backgroundSolid} />
                    ) : (
                      <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Save</ThemedText>
                    )}
                  </Pressable>
                </ThemedView>
              </Surface>
            ) : (
              <Pressable onPress={() => setShowForm(true)} style={[styles.addRow, { borderColor: TINT }]}>
                <ThemedText style={{ color: TINT }}>+ Add residency</ThemedText>
              </Pressable>
            )}
          </>
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 4,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  muted: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
  loading: {
    marginTop: 24,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  rowInfo: {
    gap: 2,
  },
  inputRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 10,
    marginBottom: 8,
  },
  addRow: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingVertical: 12,
    alignItems: 'center',
    marginTop: 4,
  },
  formSurface: {
    gap: 4,
  },
  formActions: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginTop: 8,
  },
  saveButton: {
    borderRadius: 8,
    paddingVertical: 10,
    paddingHorizontal: 20,
    alignItems: 'center',
  },
});
