import { documentTypeLabel } from '@/lib/documents';
import { formatMoney } from '@/lib/currency';
import { formatDateDisplay } from '@/lib/format';
import { DOCUMENT_EXPIRY_NOTICE_WINDOW_DAYS } from '@/lib/notices';
import { daysUntilRenewal } from '@/lib/renewal';
import type { TripSummary } from '@/lib/trips';
import type { DocumentType } from '@/types/database';

export type ReportSelection = {
  transactions: boolean;
  accounts: boolean;
  cards: boolean;
  travel: boolean;
  citizenship: boolean;
  documents: boolean;
  connections: boolean;
};

export type ReportAccount = {
  name: string;
  institution: string | null;
  account_type: string;
  currency: string;
  latestBalance: number | null;
};

export type ReportCard = {
  issuer: string;
  name: string;
  renewal_date: string;
  points_program: string | null;
  pointsBalance: number | null;
};

/**
 * daysRemaining/thresholdDays are null (and overLimit false) outside "all
 * time" mode — a date-ranged export shows plain days-in-range instead of
 * the residency-threshold framing, which only makes sense anchored to
 * today. thresholdDays is per country (lib/residencyRules.ts), not a global
 * constant. documented reflects a linked proof_of_travel document somewhere
 * in that country (see ReportDocument.linkedLabel).
 */
export type ReportCountryRow = {
  country: string;
  daysUsed: number;
  daysRemaining: number | null;
  overLimit: boolean;
  thresholdDays: number | null;
  documented: boolean;
};

export type ReportDocument = {
  name: string;
  doc_type: DocumentType;
  expiry_date: string | null;
  /** e.g. "Spain, Jun 1 – Jun 10" or "Flight: Madrid → Paris" — set only for proof_of_travel documents linked to a stop/leg. */
  linkedLabel: string | null;
};
export type ReportCitizenship = { country: string; is_primary: boolean };
export type ReportVisa = { country: string; visa_type: string | null; expiry_date: string | null };
export type ReportBudget = { category: string | null; country: string | null; amount: number; currency: string };
export type ReportCategorySpend = { category: string; total: number };
export type ReportConnection = { displayName: string; shared: string[] };

export type ReportData = {
  fullName: string | null;
  email: string;
  homeCountry: string | null;
  homeCity: string | null;
  displayCurrency: string;
  generatedAt: Date;
  /** null = full/all-time export; otherwise "Jun 1 – Jun 30, 2026" for the header and to relabel the country table. */
  dateRangeLabel: string | null;
  /** "Personal only" / "Business only" when the All/Personal/Business switch was narrowed at export time; null for everything. */
  scopeLabel: string | null;

  /** null if Accounts wasn't selected — net worth is derived from the same ledger as the Accounts section, so it rides on that toggle rather than getting its own. */
  netWorth: number | null;
  netWorthAsOfLabel: string;

  accounts: ReportAccount[];
  cards: ReportCard[];
  countrySummaries: ReportCountryRow[];
  trips: TripSummary[];
  documents: ReportDocument[];
  citizenships: ReportCitizenship[];
  visas: ReportVisa[];
  budgets: ReportBudget[];
  categorySpend: ReportCategorySpend[];
  transactionCount: number;
  connections: ReportConnection[];
};

function esc(value: string | null | undefined): string {
  if (!value) return '';
  return value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function sectionTitle(color: string, label: string): string {
  return `<div class="sec-title" style="color:${color}"><span class="sec-dot"></span>${esc(label)}</div>`;
}

function table(headerCells: string[], rowsHtml: string): string {
  const head = headerCells.map((h, i) => `<th${i > 0 ? ' class="num"' : ''}>${esc(h)}</th>`).join('');
  return `<table><tr>${head}</tr>${rowsHtml}</table>`;
}

/**
 * Builds the report's HTML for expo-print's printToFileAsync. Uses plain
 * system fonts (serif/sans/monospace) rather than the app's real Marcellus/
 * Figtree/IBM Plex Mono — those are loaded into the RN font registry via
 * useFonts() for on-screen text, not available to the separate WebView-
 * based engine that renders this HTML into a PDF, and embedding them would
 * mean inlining base64 font files into the HTML string. Same layout/colors
 * as the app either way, just a substitute typeface.
 */
export function buildReportHtml(data: ReportData, selection: ReportSelection): string {
  const COUNTRIES = '#2F6690';
  const CARDS = '#B98A2E';
  const ACCOUNTS = '#6E4F9B';
  const DOCUMENTS = '#6E6A61';
  const SPEND = '#C4483A';
  const NEG = '#C4483A';

  const isRolling = data.dateRangeLabel === null;

  const statCards: { num: string; label: string }[] = [];
  if (selection.accounts && data.netWorth != null) {
    statCards.push({ num: formatMoney(data.netWorth, data.displayCurrency), label: `Net Worth (${data.netWorthAsOfLabel})` });
  }
  if (selection.travel) {
    statCards.push({ num: String(data.countrySummaries.length), label: 'Countries Tracked' });
    statCards.push({ num: String(data.trips.length), label: 'Trips Logged' });
  }
  if (selection.transactions) statCards.push({ num: data.transactionCount.toLocaleString(), label: 'Transactions' });
  if (selection.documents) statCards.push({ num: String(data.documents.length), label: 'Documents on File' });

  const statStripHtml =
    statCards.length > 0
      ? `<div class="stat-strip">${statCards
          .map((s) => `<div class="stat"><div class="stat-num">${esc(s.num)}</div><div class="stat-lbl">${esc(s.label)}</div></div>`)
          .join('')}</div>`
      : '';

  let sections = '';

  if (selection.accounts && data.accounts.length > 0) {
    const rows = data.accounts
      .map(
        (a) =>
          `<tr><td>${esc(a.name)}</td><td class="muted">${esc(a.institution) || '-'}</td><td class="muted">${esc(a.account_type)} · ${esc(a.currency)}</td><td class="num mono">${a.latestBalance != null ? esc(formatMoney(a.latestBalance, a.currency)) : '-'}</td></tr>`
      )
      .join('');
    sections += sectionTitle(ACCOUNTS, 'Accounts') + table(['Name', 'Institution', 'Type', 'Balance'], rows);
  }

  if (selection.cards && data.cards.length > 0) {
    const rows = data.cards
      .map(
        (c) =>
          `<tr><td>${esc(c.name)}</td><td class="muted">${esc(c.issuer)}</td><td class="muted mono">${esc(formatDateDisplay(c.renewal_date))}</td><td class="num mono">${c.pointsBalance != null ? c.pointsBalance.toLocaleString() : '-'}</td></tr>`
      )
      .join('');
    sections += sectionTitle(CARDS, 'Credit Cards') + table(['Card', 'Issuer', 'Renews', 'Points Balance'], rows);
  }

  if (selection.travel && data.countrySummaries.length > 0) {
    const headers = isRolling
      ? ['Country', 'Days Used', 'Threshold', 'Remaining', 'Documented']
      : ['Country', 'Days in Range', 'Documented'];
    const rows = data.countrySummaries
      .map((c) => {
        const documentedCell = `<td class="num mono">${c.documented ? '✓' : '-'}</td>`;
        if (isRolling) {
          return `<tr><td>${esc(c.country)}</td><td class="num mono">${c.daysUsed}</td><td class="num mono muted">${c.thresholdDays ?? '-'}</td><td class="num mono${c.overLimit ? ' flag' : ''}">${c.daysRemaining}${c.overLimit ? ' ⚠' : ''}</td>${documentedCell}</tr>`;
        }
        return `<tr><td>${esc(c.country)}</td><td class="num mono">${c.daysUsed}</td>${documentedCell}</tr>`;
      })
      .join('');
    sections +=
      sectionTitle(
        COUNTRIES,
        isRolling ? "Country Day-Count (each country's own residency window)" : `Days in Country (${data.dateRangeLabel})`
      ) + table(headers, rows);
  }

  if (selection.travel && data.trips.length > 0) {
    const rows = data.trips
      .map(
        (t) =>
          `<tr><td>${esc(t.displayName)}</td><td class="muted">${esc(t.countries.join(', '))}</td><td class="muted mono">${esc(formatDateDisplay(t.startDate))} – ${t.endDate ? esc(formatDateDisplay(t.endDate)) : 'Ongoing'}</td><td class="num mono">${t.stops.length}</td></tr>`
      )
      .join('');
    sections += sectionTitle(COUNTRIES, 'Trips') + table(['Trip', 'Countries', 'Dates', 'Stops'], rows);
  }

  if (selection.citizenship && (data.citizenships.length > 0 || data.visas.length > 0)) {
    const rows = [
      ...data.citizenships.map(
        (c) => `<tr><td>${esc(c.country)}</td><td class="muted">Citizenship${c.is_primary ? ' (primary)' : ''}</td><td class="num mono muted">-</td></tr>`
      ),
      ...data.visas.map(
        (v) =>
          `<tr><td>${esc(v.country)}</td><td class="muted">${esc(v.visa_type) || 'Visa'}</td><td class="num mono${v.expiry_date && daysUntilRenewal(v.expiry_date) <= DOCUMENT_EXPIRY_NOTICE_WINDOW_DAYS ? ' flag' : ''}">${v.expiry_date ? esc(formatDateDisplay(v.expiry_date)) : 'No expiry'}</td></tr>`
      ),
    ].join('');
    sections += sectionTitle(COUNTRIES, 'Citizenship & Visas') + table(['Country', 'Type', 'Expires'], rows);
  }

  if (selection.citizenship && data.budgets.length > 0) {
    const rows = data.budgets
      .map(
        (b) =>
          `<tr><td>${esc(b.category) || esc(b.country) || 'General'}</td><td class="muted">${esc(b.country) || '-'}</td><td class="num mono">${esc(formatMoney(b.amount, b.currency))}</td></tr>`
      )
      .join('');
    sections += sectionTitle(ACCOUNTS, 'Budgets') + table(['Category', 'Country', 'Amount'], rows);
  }

  if (selection.documents && data.documents.length > 0) {
    const rows = data.documents
      .map((d) => {
        const isExpiringSoon = d.expiry_date && daysUntilRenewal(d.expiry_date) <= DOCUMENT_EXPIRY_NOTICE_WINDOW_DAYS;
        return `<tr><td>${esc(d.name)}</td><td class="muted">${esc(documentTypeLabel(d.doc_type))}</td><td class="muted">${esc(d.linkedLabel) || '-'}</td><td class="num mono${isExpiringSoon ? ' flag' : ''}">${d.expiry_date ? esc(formatDateDisplay(d.expiry_date)) + (isExpiringSoon ? ' ⚠' : '') : 'No expiry'}</td></tr>`;
      })
      .join('');
    sections += sectionTitle(DOCUMENTS, 'Documents on File') + table(['Name', 'Type', 'Proof For', 'Expires'], rows);
  }

  if (selection.transactions && data.categorySpend.length > 0) {
    const total = data.categorySpend.reduce((sum, c) => sum + c.total, 0);
    const rows = data.categorySpend
      .map(
        (c) =>
          `<tr><td>${esc(c.category)}</td><td class="num mono">${esc(formatMoney(c.total, data.displayCurrency))}</td><td class="num mono muted">${total > 0 ? Math.round((c.total / total) * 100) : 0}%</td></tr>`
      )
      .join('');
    sections +=
      sectionTitle(SPEND, `Spend by Category (converted to ${data.displayCurrency})`) +
      table(['Category', 'Total', '% of Spend'], rows);
  }

  if (selection.connections && data.connections.length > 0) {
    const rows = data.connections
      .map((c) => `<tr><td>${esc(c.displayName)}</td><td class="muted">${c.shared.length > 0 ? esc(c.shared.join(', ')) : 'Nothing shared'}</td></tr>`)
      .join('');
    sections +=
      sectionTitle(DOCUMENTS, 'Connections') +
      table(['Connection', "What you've shared with them"], rows) +
      `<p class="fine">Only what you share out is listed. Never a connection's own data.</p>`;
  }

  const generatedLabel = data.generatedAt.toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' });
  const zipName = `cluster-export-${data.generatedAt.toISOString().slice(0, 10)}`;

  return `<!doctype html>
<html>
<head>
<meta charset="utf-8" />
<style>
  * { box-sizing: border-box; }
  body { margin: 0; font-family: Georgia, 'Times New Roman', serif; color: #1A241F; }
  .page { padding: 40px 46px; }
  .brand-row { display: flex; justify-content: space-between; align-items: baseline; font-family: Helvetica, Arial, sans-serif; }
  .brand { font-size: 19px; font-weight: 700; color: #2C6E4A; }
  .gen-date { font-size: 10.5px; color: #4A554F; font-family: 'Courier New', monospace; text-align: right; }
  .doc-title { font-size: 27px; margin: 16px 0 2px; }
  .doc-sub { font-size: 12.5px; color: #4A554F; margin-bottom: 4px; font-family: Helvetica, Arial, sans-serif; }
  .range-sub { font-size: 11.5px; color: #2F6690; margin-bottom: 20px; font-family: Helvetica, Arial, sans-serif; font-weight: 700; }
  .stat-strip { display: flex; border-top: 1px solid #E2E6E1; border-bottom: 1px solid #E2E6E1; padding: 14px 0; margin-bottom: 22px; font-family: Helvetica, Arial, sans-serif; }
  .stat { flex: 1; text-align: center; border-right: 1px solid #E2E6E1; padding: 0 4px; }
  .stat:last-child { border-right: none; }
  .stat-num { font-family: 'Courier New', monospace; font-size: 17px; font-weight: 700; }
  .stat-lbl { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.04em; color: #4A554F; margin-top: 3px; }
  .sec-title { font-family: Helvetica, Arial, sans-serif; font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; font-weight: 700; padding-bottom: 5px; margin: 20px 0 8px; border-bottom: 1.5px solid currentColor; }
  .sec-dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: currentColor; margin-right: 6px; }
  table { width: 100%; border-collapse: collapse; margin-bottom: 6px; font-family: Helvetica, Arial, sans-serif; }
  th { text-align: left; font-size: 9px; text-transform: uppercase; letter-spacing: 0.03em; color: #4A554F; padding: 0 8px 5px 0; border-bottom: 1px solid #E2E6E1; }
  th.num, td.num { text-align: right; }
  td { font-size: 11px; padding: 6px 8px 6px 0; border-bottom: 1px solid #E2E6E1; }
  .mono { font-family: 'Courier New', monospace; }
  .muted { color: #4A554F; }
  .flag { color: ${NEG}; font-weight: 700; }
  .fine { font-size: 9.5px; color: #4A554F; font-family: Helvetica, Arial, sans-serif; margin: 0 0 10px; }
  .foot { margin-top: 28px; padding-top: 12px; border-top: 1px solid #E2E6E1; font-size: 9px; color: #4A554F; font-family: Helvetica, Arial, sans-serif; line-height: 1.6; }
</style>
</head>
<body>
  <div class="page">
    <div class="brand-row">
      <div class="brand">Cluster</div>
      <div class="gen-date">Generated ${esc(generatedLabel)}${data.dateRangeLabel ? `<br/>${esc(data.dateRangeLabel)}` : ''}</div>
    </div>
    <div class="doc-title">Personal Data &amp; Travel Summary</div>
    <div class="doc-sub">${esc(data.fullName) || esc(data.email)} · ${esc(data.email)}${data.homeCity || data.homeCountry ? ` · Home base: ${esc([data.homeCity, data.homeCountry].filter(Boolean).join(', '))}` : ''}</div>
    ${data.dateRangeLabel ? `<div class="range-sub">Scoped to ${esc(data.dateRangeLabel)}: accounts, cards, documents, and citizenship reflect current state, not just this range</div>` : ''}
    ${data.scopeLabel ? `<div class="range-sub">${esc(data.scopeLabel)}: accounts, cards and transactions tagged the other way are left out of every figure in this report</div>` : ''}

    ${statStripHtml}
    ${sections}

    <div class="foot">
      Cluster · Personal Data &amp; Travel Summary. This is a summary; full transaction-level detail lives in
      your Cluster account. ⚠ marks a document or visa expiring within ${DOCUMENT_EXPIRY_NOTICE_WINDOW_DAYS} days,
      or a country at or past its residency day-count trigger. Reference: ${esc(zipName)}
    </div>
  </div>
</body>
</html>`;
}
