import { useEffect, useRef, useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, TextInput, View } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { Colors } from '@/constants/theme';
import { supabase } from '@/lib/supabase';

const DEBOUNCE_MS = 350;
const MIN_QUERY_LENGTH = 2;

export type PlaceSuggestion = { name: string; country: string; displayName: string; lat: number; lon: number };

/**
 * A city text field backed by a live search (search-places Edge Function,
 * itself a proxy for OpenStreetMap's Nominatim — see that function for why
 * it can't be called directly from a browser) instead of a fixed curated
 * list. Solves two problems the curated-list approach couldn't: it isn't
 * capped to a handful of cities per country (any real place Nominatim
 * knows about is reachable), and picking a suggestion can't introduce a
 * spelling mistake the way free typing can — the name AND its real
 * coordinates come from the same selection, so there's nothing left to
 * separately geocode or get wrong.
 *
 * Still lets you keep typing past what the search matched (e.g. a place
 * too small for Nominatim, or you just don't want to wait) — onChangeText
 * fires on every keystroke either way; onSelectPlace only fires when a
 * suggestion is actually tapped.
 */
export function CityAutocompleteInput({
  value,
  onChangeText,
  onSelectPlace,
  countryCode,
  placeholder,
  accentColor,
  onBlur,
}: {
  value: string;
  onChangeText: (text: string) => void;
  onSelectPlace: (place: PlaceSuggestion) => void;
  /** ISO 3166-1 alpha-2 code (lib/countries.ts's flagCodeForCountry, first segment only) — hard-limits results to this country when known. Omit to search worldwide. */
  countryCode?: string;
  placeholder?: string;
  accentColor: string;
  /** For a screen that autosaves on blur instead of a submit button (e.g. account/index.tsx's home city) — fires alongside the internal focus-tracking blur handler below, doesn't replace it. */
  onBlur?: () => void;
}) {
  const [suggestions, setSuggestions] = useState<PlaceSuggestion[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isFocused, setIsFocused] = useState(false);
  const [searchError, setSearchError] = useState<string | null>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const requestIdRef = useRef(0);

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (value.trim().length < MIN_QUERY_LENGTH) {
      setSuggestions([]);
      setIsSearching(false);
      setSearchError(null);
      return;
    }
    setIsSearching(true);
    setSearchError(null);
    debounceRef.current = setTimeout(async () => {
      const requestId = ++requestIdRef.current;
      // Not wrapping this in try/catch would leave isSearching stuck true
      // forever on a genuine failure (network error, function down, etc.)
      // — the dropdown would just spin, never showing why. Logged the same
      // way lib/geocoding.ts's functions do, for the same reason: this
      // silent-failure shape is exactly what made the CORS issue earlier
      // this session so hard to diagnose.
      try {
        const { data, error } = await supabase.functions.invoke<{ results: PlaceSuggestion[]; error?: string }>(
          'search-places',
          { body: { query: value.trim(), countryCode } }
        );
        if (requestId !== requestIdRef.current) return;
        if (error) {
          console.error(`CityAutocompleteInput(${value}): function error`, error);
          setSearchError('Search failed.');
          setSuggestions([]);
        } else if (data?.error) {
          console.error(`CityAutocompleteInput(${value}): ${data.error}`);
          setSearchError('Search failed.');
          setSuggestions([]);
        } else {
          setSuggestions(data?.results ?? []);
        }
      } catch (err) {
        if (requestId !== requestIdRef.current) return;
        console.error(`CityAutocompleteInput(${value}): threw`, err);
        setSearchError('Search failed.');
        setSuggestions([]);
      } finally {
        if (requestId === requestIdRef.current) setIsSearching(false);
      }
    }, DEBOUNCE_MS);
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
  }, [value, countryCode]);

  const showDropdown =
    isFocused && value.trim().length >= MIN_QUERY_LENGTH && (isSearching || suggestions.length > 0 || !!searchError);

  return (
    // zIndex bumped only while a dropdown is actually open — every
    // CityAutocompleteInput on a form shares the same base stacking
    // level, so without this a LATER field (e.g. "To") paints over an
    // EARLIER field's open dropdown (e.g. "From") rather than the other
    // way around, since same-z-index siblings stack by DOM order. That's
    // exactly what made a later field's own placeholder text appear to
    // bleed into an open dropdown above it.
    <View style={[styles.container, showDropdown ? styles.containerOpen : null]}>
      <TextInput
        value={value}
        onChangeText={onChangeText}
        onFocus={() => setIsFocused(true)}
        // Delayed so a suggestion's onPress still registers before the
        // dropdown unmounts — a plain onBlur firing first would close it
        // out from under the tap.
        onBlur={() => {
          onBlur?.();
          setTimeout(() => setIsFocused(false), 150);
        }}
        placeholder={placeholder}
        placeholderTextColor={Colors.light.textMuted}
        style={[styles.input, { color: Colors.light.text, borderColor: accentColor }]}
      />
      {showDropdown ? (
        <View collapsable={false} style={[styles.dropdown, { borderColor: accentColor }]}>
          {/* No ScrollView — see CountryAutocompleteInput's own copy of
              this comment: confirmed by direct A/B testing on a real
              device that this nesting breaks selection on native, even
              with collapsable={false} also in place. search-places caps
              results at 8, and styles.dropdown's maxHeight below is sized
              to fit all 8 without clipping instead. collapsable={false}
              stays — a real, separate fix for a tap/drag over this box
              reaching whatever's behind it instead. */}
          {isSearching && suggestions.length === 0 ? (
            <ActivityIndicator color={accentColor} style={styles.loading} />
          ) : searchError ? (
            <ThemedText style={styles.rowSubtext}>{searchError}</ThemedText>
          ) : suggestions.length === 0 ? (
            <ThemedText style={styles.rowSubtext}>No matches.</ThemedText>
          ) : (
            suggestions.map((s, index) => (
              <Pressable
                key={`${s.name}-${s.lat}-${s.lon}-${index}`}
                collapsable={false}
                onPress={() => onSelectPlace(s)}
                style={[styles.row, index < suggestions.length - 1 ? styles.rowBorder : null]}>
                <ThemedText numberOfLines={1}>{s.name}</ThemedText>
                <ThemedText numberOfLines={1} style={styles.rowSubtext}>
                  {/* displayName's own name segment is dropped — it's already the line above; what's left (district, state, country) is exactly what's needed to tell two same-named places apart, e.g. two different "Ranakpur"s in different states. */}
                  {s.displayName.split(',').slice(1).join(',').trim() || s.country}
                </ThemedText>
              </Pressable>
            ))
          )}
        </View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    position: 'relative',
    zIndex: 10,
  },
  containerOpen: {
    zIndex: 100,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
  },
  dropdown: {
    position: 'absolute',
    top: '100%',
    left: 0,
    right: 0,
    marginTop: 4,
    backgroundColor: Colors.light.backgroundSolid,
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    // Fits all 8 results (search-places' own limit) without clipping —
    // see CountryAutocompleteInput's own copy of this comment for why.
    maxHeight: 460,
    overflow: 'hidden',
    zIndex: 20,
    elevation: 6,
  },
  loading: {
    paddingVertical: 12,
  },
  row: {
    paddingHorizontal: 16,
    paddingVertical: 10,
  },
  rowBorder: {
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: Colors.light.cardBorder,
  },
  rowSubtext: {
    fontSize: 12,
    opacity: 0.6,
    color: Colors.light.textMuted,
  },
});
