import type { Session } from '@supabase/supabase-js';

import { fetchAllRows } from '@/lib/fetchAll';
import { computeForeignAssetPeak, hasReportingCitizenship } from '@/lib/foreignAssetReporting';
import { computeActiveNotices } from '@/lib/notices';
import { supabase } from '@/lib/supabase';
import type { BalanceSnapshotRow } from '@/types/database';

/**
 * Computes the full set of currently-active notices (same inputs
 * hooks/use-notice-count.ts already independently re-fetches for the
 * TopBar badge, not Summary's own richer display fetch — this app's
 * established pattern for anything that just needs to know WHICH notices
 * are active, not render them) and writes it as the "seen as of now"
 * snapshot, same upsert app/summary/index.tsx's own load() already does.
 *
 * Summary writing this on every visit was the only way the badge ever
 * cleared — visiting Insights did nothing, since it had no notice logic
 * at all. Rather than duplicate Summary's inline fetch-and-write block
 * (which also serves its own much richer display needs) into Insights
 * too, this is the one-call version any other screen that should ALSO
 * count as "I've seen my notices" can use.
 */
export async function writeNoticeSnapshot(params: {
  session: Session;
  homeCountry: string | null;
  convertToCurrency: (amount: number, fromCurrency: string, toCurrency: string) => number;
}): Promise<void> {
  const { session, homeCountry, convertToCurrency } = params;

  const [
    cardsResult,
    visitsResult,
    documentsResult,
    accountsResult,
    transactionsResult,
    snapshotsResult,
    citizenshipsResult,
    pendingShareRequestIdsResult,
    pendingPlanRequestIdsResult,
    acceptedPlanRequestIdsResult,
    sharedTripIdsResult,
    pendingTripCollaborationInvitesResult,
    cityVisitsResult,
    loyaltyResult,
    tripNotesFromOthersResult,
  ] = await Promise.all([
    supabase.from('credit_cards').select('id, renewal_date, payment_due_day'),
    supabase.from('countries_visited').select('*'),
    supabase.from('documents').select('id, expiry_date'),
    supabase.from('accounts').select('*'),
    fetchAllRows<{ date: string; amount: number; currency: string; account_id: string | null }>((from, to) =>
      supabase.from('transactions').select('date, amount, currency, account_id').order('date').order('id').range(from, to)
    ),
    fetchAllRows<BalanceSnapshotRow>((from, to) =>
      supabase.from('balance_snapshots').select('*').order('date').order('id').range(from, to)
    ),
    supabase.from('user_citizenships').select('country'),
    supabase.from('connection_share_requests').select('id').eq('to_user_id', session.user.id).eq('status', 'pending'),
    supabase.from('trip_plan_requests').select('id').eq('status', 'pending').neq('requested_by', session.user.id),
    supabase.from('trip_plan_requests').select('id').eq('requested_by', session.user.id).eq('status', 'accepted'),
    supabase.from('trips').select('id').eq('user_id', session.user.id).eq('created_via_share', true),
    supabase.rpc('pending_trip_collaboration_invites'),
    supabase.rpc('city_visit_alerts'),
    supabase.from('loyalty_accounts').select('id, expiry_date'),
    supabase.from('shared_trip_notes').select('id').neq('author_id', session.user.id),
  ]);

  const accounts = accountsResult.data ?? [];
  const transactions = (transactionsResult.data ?? []) as { date: string; amount: number; currency: string; account_id: string | null }[];
  const snapshots = snapshotsResult.data ?? [];
  const citizenships = citizenshipsResult.data ?? [];
  const hasUsCitizenship = hasReportingCitizenship(citizenships, 'fbar');
  const hasCanadianCitizenship = hasReportingCitizenship(citizenships, 't1135');

  const activeNotices = computeActiveNotices({
    cards: cardsResult.data ?? [],
    homeCountry,
    countryVisits: visitsResult.data ?? [],
    documents: documentsResult.data ?? [],
    fbarPeakUsd: hasUsCitizenship
      ? computeForeignAssetPeak(accounts, transactions, snapshots, 'fbar', convertToCurrency)
      : null,
    hasUsCitizenship,
    t1135PeakCad: hasCanadianCitizenship
      ? computeForeignAssetPeak(accounts, transactions, snapshots, 't1135', convertToCurrency)
      : null,
    hasCanadianCitizenship,
    pendingShareRequestIds: (pendingShareRequestIdsResult.data ?? []).map((r) => r.id),
    pendingPlanRequestIds: (pendingPlanRequestIdsResult.data ?? []).map((r) => r.id),
    acceptedPlanRequestIds: (acceptedPlanRequestIdsResult.data ?? []).map((r) => r.id),
    sharedTripIds: (sharedTripIdsResult.data ?? []).map((r) => r.id),
    pendingTripCollaborationInviteIds: (pendingTripCollaborationInvitesResult.data ?? []).map((r) => r.id),
    cityVisitStopIds: (cityVisitsResult.data ?? []).map((r) => r.stop_id),
    loyaltyAccounts: loyaltyResult.data ?? [],
    tripNoteIds: (tripNotesFromOthersResult.data ?? []).map((r) => r.id),
    citizenshipCountries: citizenships.map((c) => c.country),
  });

  const { error } = await supabase.from('user_settings').upsert(
    {
      user_id: session.user.id,
      last_viewed_summary_at: new Date().toISOString(),
      last_viewed_summary_notices: activeNotices,
    },
    { onConflict: 'user_id' }
  );
  if (error) {
    console.error('Failed to save viewed notices:', error.message);
  }
}
