import { Alert } from 'react-native';

import type { AlertButton } from './alert-types';

/**
 * Drop-in for Alert.alert, kept as a cross-platform pair with alert.web.ts
 * because react-native-web's Alert.alert is a complete no-op (`static
 * alert() {}`) — every confirm dialog built directly on Alert.alert (delete
 * account, delete document, remove connection, etc.) silently did nothing
 * on web; tapping "Delete" looked like the app was refusing to let you.
 * Native keeps the real Alert.alert, which already works correctly.
 */
export function showAlert(title: string, message?: string, buttons?: AlertButton[]): void {
  Alert.alert(title, message, buttons);
}
