import { Stack } from 'expo-router';

export default function SpendLayout() {
  return (
    <Stack screenOptions={{ headerShown: false }}>
      <Stack.Screen name="index" />
      <Stack.Screen name="[categoryId]" />
      <Stack.Screen name="subscriptions" />
      <Stack.Screen name="budgets/index" />
      <Stack.Screen name="budgets/new" options={{ presentation: 'modal' }} />
      <Stack.Screen name="budgets/[id]/edit" options={{ presentation: 'modal' }} />
    </Stack>
  );
}
