import { useFocusEffect } from '@react-navigation/native';
import { Link, useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { Pressable, RefreshControl, ScrollView, StyleSheet, useWindowDimensions } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { CountryFlag } from '@/components/country-flag';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import {
  daysInCountryForYear,
  daysRemainingInYear,
  effectiveHomeCountryFor,
  homeCountryDaysForYear,
  homeCountryDaysThisYear,
  lifetimeDaysInCountry,
  projectedHomeCountryDaysByYearEnd,
  type PriorResidencyLike,
} from '@/lib/days';
import { ca4Status, CA4_LIMIT_DAYS } from '@/lib/ca4';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import { isCitizenshipTaxed, residencyRuleFor } from '@/lib/residencyRules';
import { isExemptFromSchengenRule, schengenStatus, SCHENGEN_LIMIT_DAYS } from '@/lib/schengen';
import { yearsSpannedByRanges } from '@/lib/spend';
import { supabase } from '@/lib/supabase';
import { computeTripSummaries } from '@/lib/trips';
import type { CountryVisitedRow, TripRow, TripSegmentRow } from '@/types/database';

const ACCENT = ModuleAccents.countries;
type YearOption = 'all' | number;

export default function CountriesScreen() {
  const router = useRouter();
  const { homeCountry, hiddenFlagCountries } = useCurrency();
  const { width: windowWidth } = useWindowDimensions();
  // 6 per row on a wide web window, 3 on native/narrow web — same
  // breakpoint and reasoning as app/countries/passport.tsx's grid.
  const gridTileMinWidth = windowWidth < 700 ? '31%' : '15%';
  const [visits, setVisits] = useState<CountryVisitedRow[]>([]);
  const [trips, setTrips] = useState<TripRow[]>([]);
  const [segments, setSegments] = useState<TripSegmentRow[]>([]);
  const [priorResidencies, setPriorResidencies] = useState<PriorResidencyLike[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  // Defaults to the current year, matching the country detail screen — "All
  // time" (the live rolling/tax-year residency-rule tally, unchanged from
  // before) stays available as a chip for browsing full history.
  const [selectedYear, setSelectedYear] = useState<YearOption>(() => new Date().getFullYear());
  const [citizenshipCountries, setCitizenshipCountries] = useState<string[]>([]);

  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const loadVisits = useCallback(async () => {
    setError(null);
    const [visitsResult, tripsResult, segmentsResult, citizenshipsResult, priorResidenciesResult] = await Promise.all([
      supabase.from('countries_visited').select('*').order('entry_date', { ascending: false }),
      supabase.from('trips').select('*'),
      supabase.from('trip_segments').select('*'),
      supabase.from('user_citizenships').select('country'),
      supabase.from('prior_residencies').select('*'),
    ]);

    if (visitsResult.error) {
      setError(visitsResult.error.message);
    } else if (tripsResult.error) {
      setError(tripsResult.error.message);
    } else {
      setVisits(visitsResult.data ?? []);
      setTrips(tripsResult.data ?? []);
      setSegments(segmentsResult.data ?? []);
      setCitizenshipCountries((citizenshipsResult.data ?? []).map((c) => c.country));
      setPriorResidencies(priorResidenciesResult.data ?? []);
    }
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      loadVisits();
    }, [loadVisits])
  );

  const today = toDateOnlyString(new Date());
  const thisYear = new Date().getFullYear();

  // Wherever you lived at a given year's December 31 is that year's home
  // country (see lib/days.ts's effectiveHomeCountryFor and app/account/
  // prior-residencies.tsx) — not always whatever the current home country
  // setting is. effectiveHomeCountryNow covers "today"/'all'-time views;
  // effectiveHomeCountryForSelectedYear covers the year-chip-scoped hero
  // tile and "other countries" list further down.
  const effectiveHomeCountryNow = effectiveHomeCountryFor(today, homeCountry, priorResidencies);
  const effectiveHomeCountryForSelectedYear =
    selectedYear === 'all' ? effectiveHomeCountryNow : effectiveHomeCountryFor(`${selectedYear}-12-31`, homeCountry, priorResidencies);

  // A country only counts as "visited" if it has a trip that's actually
  // started (entry_date <= today) — a purely future-dated visit shouldn't
  // make a country show up here yet, only in "Trips planned" below. A
  // country with both a past/current trip and a future one correctly shows
  // in both sections; that overlap is intentional, not a duplicate bug.
  // (otherCountries below enforces this implicitly: both
  // lifetimeDaysInCountry and daysInCountryForYear cap at today, so a
  // future-only visit always contributes 0 days and gets filtered out by
  // its own daysUsed > 0 check — no separate set needed here anymore.)

  // Every year each stay actually touched, not just the year it started in
  // (a multi-year stop logged as one row would otherwise only ever show
  // its start year).
  const availableYears = yearsSpannedByRanges(visits.map((v) => ({ start: v.entry_date, end: v.exit_date })));
  const yearOptions: YearOption[] = ['all', ...availableYears];

  // "Current" reproduces each country's genuine lifetime day total (every
  // distinct day ever logged there, not bounded to any one test's window)
  // — this used to be each country's live rolling/tax-year residency-rule
  // tally instead (lib/days.ts's summarizeCountries), which could show
  // FEWER days than a single one of the year chips below it once older
  // visits aged out of that window, reading as if it were dropping trips.
  // Picking a specific year still switches to that year's own actual day
  // count (lib/days.ts's daysInCountryForYear) — a different, narrower
  // question ("how many days was I there in 2025") than either lifetime
  // total or a compliance test's tally.
  const otherCountries = Array.from(new Set(visits.map((v) => v.country)))
    .filter((country) => country !== (selectedYear === 'all' ? effectiveHomeCountryNow : effectiveHomeCountryForSelectedYear))
    .map((country) => {
      const daysUsed = selectedYear === 'all' ? lifetimeDaysInCountry(visits, country) : daysInCountryForYear(visits, country, selectedYear);
      const rule = residencyRuleFor(country);
      return {
        country,
        daysUsed,
        daysRemaining: Math.max(0, rule.thresholdDays - daysUsed),
        overLimit: daysUsed >= rule.thresholdDays,
      };
    })
    .filter((s) => s.daysUsed > 0)
    .sort((a, b) => b.daysUsed - a.daysUsed);

  const homeDays = !effectiveHomeCountryForSelectedYear
    ? null
    : selectedYear === 'all'
      ? homeCountryDaysThisYear(visits, effectiveHomeCountryForSelectedYear)
      : homeCountryDaysForYear(visits, effectiveHomeCountryForSelectedYear, selectedYear);
  // "Days left"/"projected by year-end" are current-year-only concepts —
  // meaningless once browsing a past year, since that year is already over.
  const isCurrentYearView = selectedYear === 'all' || selectedYear === thisYear;
  const daysLeft = daysRemainingInYear();
  const projectedHomeDays =
    effectiveHomeCountryNow && isCurrentYearView ? projectedHomeCountryDaysByYearEnd(visits, effectiveHomeCountryNow) : null;

  const schengen = schengenStatus(visits);
  const schengenBanner =
    isExemptFromSchengenRule(citizenshipCountries)
      ? null
      : schengen.overLimit
        ? { color: Colors.light.negative, message: `Schengen: ${schengen.daysUsed}/${SCHENGEN_LIMIT_DAYS} days used — over the 90-day limit.`, href: '/countries/schengen' as const }
        : schengen.nearLimit
          ? { color: '#B8860B', message: `Schengen: ${schengen.daysUsed}/${SCHENGEN_LIMIT_DAYS} days used — getting close to the limit.`, href: '/countries/schengen' as const }
          : null;

  const ca4 = ca4Status(visits);
  const ca4Banner = ca4.overLimit
    ? { color: Colors.light.negative, message: `CA-4: ${ca4.daysUsed}/${CA4_LIMIT_DAYS} days used — over the limit.`, href: '/countries/ca4' as const }
    : ca4.nearLimit
      ? { color: '#B8860B', message: `CA-4: ${ca4.daysUsed}/${CA4_LIMIT_DAYS} days used — getting close to the limit.`, href: '/countries/ca4' as const }
      : null;

  // Trips planned: any TRIP (not raw stop) that hasn't started yet, grouped
  // by country — a country can appear here and in "Countries visited" at
  // the same time (past trips + a future one aren't mutually exclusive).
  // Grouping by trip rather than by individual stop matters for a
  // multi-city trip: a single trip to India with 4 stops should show as
  // one row spanning its overall start→end dates, not the first stop's own
  // dates plus "+3 more planned" (which read as 3 separate trips).
  // computeTripSummaries skips stops with no trip_id at all (a plain,
  // ungrouped visit — see CountryVisitedRow.trip_id's doc comment), so
  // those are added back in as their own single-stop entry below.
  type PlannedEntry = { startDate: string; endDate: string | null };
  const plannedByCountry = new Map<string, PlannedEntry[]>();
  function addPlanned(country: string, startDate: string, endDate: string | null) {
    if (country === effectiveHomeCountryNow) return;
    const entries = plannedByCountry.get(country) ?? [];
    entries.push({ startDate, endDate });
    plannedByCountry.set(country, entries);
  }

  const tripSummaries = computeTripSummaries(trips, visits, segments);
  for (const trip of tripSummaries) {
    if (trip.startDate <= today) continue;
    for (const country of trip.countries) addPlanned(country, trip.startDate, trip.endDate);
  }
  for (const visit of visits) {
    if (visit.trip_id || visit.entry_date <= today) continue;
    addPlanned(visit.country, visit.entry_date, visit.exit_date);
  }

  const plannedTrips = Array.from(plannedByCountry.entries())
    .map(([plannedCountry, entries]) => {
      const sorted = [...entries].sort((a, b) => (a.startDate < b.startDate ? -1 : 1));
      return { country: plannedCountry, nextTrip: sorted[0], additionalCount: sorted.length - 1 };
    })
    .sort((a, b) => (a.nextTrip.startDate < b.nextTrip.startDate ? -1 : 1));

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView
        contentContainerStyle={styles.content}
        refreshControl={<RefreshControl refreshing={isLoading} onRefresh={loadVisits} />}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            {effectiveHomeCountryForSelectedYear ?? 'Countries'}
          </ThemedText>
          <ThemedView style={styles.titleLinks}>
            <Pressable onPress={() => router.push('/countries/passport')} hitSlop={8} accessibilityLabel="Passport">
              <ThemedText type="link" style={styles.titleLinkEmoji}>🗺</ThemedText>
            </Pressable>
            <Pressable onPress={() => router.push('/countries/trips')} hitSlop={8} accessibilityLabel="Trips">
              <ThemedText type="link" style={styles.titleLinkEmoji}>✈</ThemedText>
            </Pressable>
            <Pressable onPress={() => router.push('/countries/schengen')} hitSlop={8} accessibilityLabel="Schengen tracker">
              <ThemedText type="link" style={styles.titleLinkEmoji}>🇪🇺</ThemedText>
            </Pressable>
            <Pressable onPress={() => router.push('/countries/ca4')} hitSlop={8} accessibilityLabel="CA-4 tracker">
              <ThemedText type="link" style={styles.titleLinkEmoji}>🌎</ThemedText>
            </Pressable>
          </ThemedView>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
        {schengenBanner ? (
          <Pressable onPress={() => router.push(schengenBanner.href)}>
            <Surface accentColor={schengenBanner.color} style={styles.schengenBanner}>
              <ThemedText style={[styles.schengenBannerText, { color: schengenBanner.color }]}>
                {schengenBanner.message}
              </ThemedText>
            </Surface>
          </Pressable>
        ) : null}
        {ca4Banner ? (
          <Pressable onPress={() => router.push(ca4Banner.href)}>
            <Surface accentColor={ca4Banner.color} style={styles.schengenBanner}>
              <ThemedText style={[styles.schengenBannerText, { color: ca4Banner.color }]}>{ca4Banner.message}</ThemedText>
            </Surface>
          </Pressable>
        ) : null}

        {effectiveHomeCountryForSelectedYear ? (
          <Pressable onPress={() => router.push(`/countries/${encodeURIComponent(effectiveHomeCountryForSelectedYear)}?year=${selectedYear}`)}>
            <Surface accentColor={ACCENT} style={styles.homeRow}>
              <ThemedView style={styles.homeFlagBox}>
                <CountryFlag countryName={effectiveHomeCountryForSelectedYear} hiddenFlagCountries={hiddenFlagCountries} size={64} />
              </ThemedView>
              <ThemedView style={styles.homeStats}>
                <ThemedText type="mono" style={styles.homeStatValue}>
                  {homeDays} days home
                </ThemedText>
                {isCurrentYearView ? (
                  <>
                    <ThemedText type="mono" style={styles.homeStatValue}>
                      {daysLeft} days left
                    </ThemedText>
                    <ThemedText type="mono" style={[styles.homeStatValue, styles.muted]}>
                      {projectedHomeDays} projected by year-end
                    </ThemedText>
                  </>
                ) : null}
              </ThemedView>
            </Surface>
          </Pressable>
        ) : (
          <Surface accentColor={ACCENT}>
            <ThemedText style={styles.muted}>
              Set your home country in{' '}
              <Link href="/account">
                <ThemedText type="link" style={styles.muted}>
                  Account settings
                </ThemedText>
              </Link>{' '}
              to see days spent there this year.
            </ThemedText>
          </Surface>
        )}

        <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
          Countries visited
        </ThemedText>
        <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chipRow}>
          {yearOptions.map((option) => {
            const isSelected = selectedYear === option;
            return (
              <Pressable
                key={String(option)}
                onPress={() => setSelectedYear(option)}
                style={[styles.chip, { borderColor: ACCENT, backgroundColor: isSelected ? ACCENT : 'transparent' }]}>
                <ThemedText style={isSelected ? { color: ModuleAccentOnColor.countries } : undefined}>
                  {option === 'all' ? 'Current' : String(option)}
                </ThemedText>
              </Pressable>
            );
          })}
        </ScrollView>
        {otherCountries.length === 0 && !isLoading ? (
          <ThemedText style={styles.muted}>No trips logged yet. Add your first one below.</ThemedText>
        ) : null}
        <ThemedView style={styles.grid}>
          {otherCountries.map((summary) => (
            <Pressable
              key={summary.country}
              style={[styles.gridTile, { minWidth: gridTileMinWidth }]}
              onPress={() => router.push(`/countries/${encodeURIComponent(summary.country)}`)}>
              <Surface accentColor={ACCENT} style={styles.tileSurface}>
                <CountryFlag countryName={summary.country} hiddenFlagCountries={hiddenFlagCountries} size={36} />
                <ThemedText type="mono" style={styles.tileStat}>
                  {summary.daysUsed} days traveled
                </ThemedText>
                <ThemedText
                  type="mono"
                  style={[
                    styles.tileStat,
                    summary.overLimit && !isCitizenshipTaxed(summary.country, citizenshipCountries)
                      ? styles.overLimit
                      : styles.muted,
                  ]}>
                  {summary.daysRemaining} remaining
                </ThemedText>
              </Surface>
            </Pressable>
          ))}
        </ThemedView>

        <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
          Trips planned
        </ThemedText>
        {plannedTrips.length === 0 ? <ThemedText style={styles.muted}>No upcoming trips logged.</ThemedText> : null}
        <ThemedView style={styles.grid}>
          {plannedTrips.map((planned) => (
            <Pressable
              key={planned.country}
              style={[styles.gridTile, { minWidth: gridTileMinWidth }]}
              onPress={() => router.push(`/countries/${encodeURIComponent(planned.country)}`)}>
              <Surface accentColor={ACCENT} style={styles.tileSurface}>
                <CountryFlag countryName={planned.country} hiddenFlagCountries={hiddenFlagCountries} size={36} />
                <ThemedText type="mono" style={styles.tileStat} numberOfLines={1}>
                  {formatDateDisplay(planned.nextTrip.startDate)} &rarr;
                </ThemedText>
                <ThemedText type="mono" style={styles.tileStat} numberOfLines={1}>
                  {formatDateDisplay(planned.nextTrip.endDate)}
                </ThemedText>
                {planned.additionalCount > 0 ? (
                  <ThemedText style={styles.muted}>+{planned.additionalCount} more planned</ThemedText>
                ) : null}
              </Surface>
            </Pressable>
          ))}
        </ThemedView>
      </ScrollView>

      <Pressable onPress={() => router.push('/countries/visit/new')} style={[styles.fab, { backgroundColor: ACCENT }]}>
        <IconSymbol name="plus" size={28} color={ModuleAccentOnColor.countries} />
      </Pressable>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 96,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  titleLinks: {
    flexDirection: 'row',
    gap: 14,
  },
  titleLinkEmoji: {
    fontSize: 22,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  chipRow: {
    flexDirection: 'row',
    gap: 8,
    marginTop: 8,
    marginBottom: 4,
  },
  chip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 16,
    paddingHorizontal: 16,
    paddingVertical: 8,
  },
  grid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 10,
  },
  gridTile: {
    // flexGrow (not justifyContent:'space-between' + a fixed width) — a
    // final row with fewer tiles than the column count still packs them
    // together and grows them to fill the row, instead of space-between
    // spreading two or three tiles across the FULL row width with huge
    // gaps between them (confirmed directly: exactly what a 2-item "2022"
    // row and a 3-item "Trips planned" row both looked like). minWidth
    // (applied inline as gridTileMinWidth) caps how many fit per row: 3 on
    // native/narrow web, 6 on wide web.
    flexGrow: 1,
    flexBasis: 0,
  },
  tileSurface: {
    alignItems: 'center',
    gap: 4,
  },
  tileStat: {
    fontSize: 13,
  },
  homeRow: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  homeFlagBox: {
    width: '50%',
    alignItems: 'center',
  },
  homeStats: {
    width: '50%',
    gap: 6,
  },
  homeStatValue: {
    fontSize: 15,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  overLimit: {
    color: Colors.light.negative,
    fontSize: 14,
  },
  error: {
    color: Colors.light.negative,
  },
  schengenBanner: {
    paddingVertical: 10,
  },
  schengenBannerText: {
    fontSize: 14,
    fontWeight: '600',
    textAlign: 'center',
  },
  fab: {
    position: 'absolute',
    right: 20,
    bottom: 28,
    width: 56,
    height: 56,
    borderRadius: 28,
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: '#000',
    shadowOpacity: 0.2,
    shadowRadius: 6,
    shadowOffset: { width: 0, height: 3 },
    elevation: 4,
  },
});
