import type { ConvertedAmount } from '@/contexts/currency-context';
import { toDateOnlyString } from '@/lib/format';
import type { Period } from '@/lib/wealthSeries';
import type { TransactionRow } from '@/types/database';

export type SpendGranularity = 'week' | 'month' | 'custom';

export type BarBucket = { label: string; amount: number };

function startOfWeekSunday(date: Date): Date {
  const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  d.setDate(d.getDate() - d.getDay());
  return d;
}

/**
 * Buckets a period into bars one level finer than the selected granularity
 * — week shows bars by day, month by week, custom by month (a custom range
 * could span several months, where daily bars would be too dense).
 *
 * Simplification, not a full solve: sums converted amounts numerically per
 * bucket regardless of resulting currency. If "Local" display currency
 * (no real conversion) is selected and spend spans multiple currencies,
 * bucket totals mix currencies rather than showing them separately — unlike
 * the category breakdown elsewhere, which keeps per-currency totals. A bar
 * chart can't cleanly show stacked-by-currency bars without real added
 * complexity, and the common case (one primary currency, or a real display
 * currency already selected) isn't affected.
 */
export function computeSpendBarBuckets(
  period: Period,
  granularity: SpendGranularity,
  transactions: Pick<TransactionRow, 'date' | 'amount' | 'currency'>[],
  convert: (amount: number, fromCurrency: string) => ConvertedAmount
): BarBucket[] {
  const subUnit = granularity === 'week' ? 'day' : granularity === 'month' ? 'week' : 'month';
  const ranges: { label: string; start: Date; end: Date }[] = [];

  if (subUnit === 'day') {
    for (let d = new Date(period.start); d <= period.end; d.setDate(d.getDate() + 1)) {
      const day = new Date(d);
      ranges.push({ label: day.toLocaleDateString(undefined, { weekday: 'short' }), start: day, end: day });
    }
  } else if (subUnit === 'week') {
    let weekStart = startOfWeekSunday(period.start);
    let weekIndex = 1;
    while (weekStart <= period.end) {
      const weekEnd = new Date(weekStart);
      weekEnd.setDate(weekEnd.getDate() + 6);
      ranges.push({ label: `Wk ${weekIndex}`, start: weekStart, end: weekEnd });
      weekStart = new Date(weekStart);
      weekStart.setDate(weekStart.getDate() + 7);
      weekIndex++;
    }
  } else {
    let monthStart = new Date(period.start.getFullYear(), period.start.getMonth(), 1);
    while (monthStart <= period.end) {
      const monthEnd = new Date(monthStart.getFullYear(), monthStart.getMonth() + 1, 0);
      ranges.push({
        label: monthStart.toLocaleDateString(undefined, { month: 'short' }),
        start: monthStart,
        end: monthEnd,
      });
      monthStart = new Date(monthStart.getFullYear(), monthStart.getMonth() + 1, 1);
    }
  }

  return ranges.map((range) => {
    const startStr = toDateOnlyString(range.start);
    const endStr = toDateOnlyString(range.end);
    let amount = 0;
    for (const tx of transactions) {
      if (tx.date >= startStr && tx.date <= endStr) {
        amount += Math.abs(convert(tx.amount, tx.currency).amount);
      }
    }
    return { label: range.label, amount };
  });
}

/**
 * Where a recurring day-of-month payment due date falls along a 0-1
 * fraction of `year`/`month` — same "project the recurring pattern onto a
 * timeline" idea as renewalDayOfYearFraction, just month-scoped instead of
 * year-scoped. Doesn't predict whether that date has already passed; a due
 * day beyond the month's real length (e.g. 31 in February) clamps to the
 * month's last day, same overflow handling as nextPaymentDueDate.
 */
export function dueDayFractionOfMonth(paymentDueDay: number, year: number, month: number): number {
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const clampedDay = Math.min(Math.max(paymentDueDay, 1), daysInMonth);
  return (clampedDay - 1) / daysInMonth;
}
