import { matchCategoryRule } from '@/lib/csvImport';
import type { CategoryRuleRow, TransactionRow } from '@/types/database';

export type TransactionCategoryFilterValue = 'all' | 'uncategorized' | string;

/** Same fallback TransactionRow uses to badge a transaction — a merchant-matched rule counts as that category for filtering too, not just for display. */
export function effectiveCategoryId(
  tx: Pick<TransactionRow, 'category_id' | 'merchant'>,
  rules: CategoryRuleRow[]
): string | null {
  return tx.category_id ?? matchCategoryRule(tx.merchant ?? '', rules);
}

export function filterByCategory<T extends Pick<TransactionRow, 'category_id' | 'merchant'>>(
  transactions: T[],
  rules: CategoryRuleRow[],
  value: TransactionCategoryFilterValue
): T[] {
  if (value === 'all') return transactions;
  if (value === 'uncategorized') return transactions.filter((tx) => effectiveCategoryId(tx, rules) === null);
  return transactions.filter((tx) => effectiveCategoryId(tx, rules) === value);
}
