import { useRouter } from 'expo-router';
import { useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput } from 'react-native';

import { PasswordInput } from '@/components/password-input';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { supabase } from '@/lib/supabase';

const TINT = Colors.light.tint;

export default function ChangeEmailScreen() {
  const router = useRouter();
  const { session } = useAuth();

  const [currentPassword, setCurrentPassword] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sentTo, setSentTo] = useState<string | null>(null);

  async function handleSave() {
    setSentTo(null);
    const trimmedEmail = newEmail.trim();
    if (!currentPassword || !trimmedEmail) {
      setError('Fill in both fields.');
      return;
    }
    if (!session?.user.email) {
      setError('No signed-in user.');
      return;
    }
    if (trimmedEmail.toLowerCase() === session.user.email.toLowerCase()) {
      setError("That's already your current email.");
      return;
    }

    setError(null);
    setIsSaving(true);

    // Same re-authentication pattern as Change Password — Supabase has no
    // separate "verify this password" call, and updateUser() alone would
    // accept any live session without checking it.
    const { error: verifyError } = await supabase.auth.signInWithPassword({
      email: session.user.email,
      password: currentPassword,
    });
    if (verifyError) {
      setIsSaving(false);
      setError('Current password is incorrect.');
      return;
    }

    // Doesn't take effect immediately — Supabase emails a confirmation
    // link to the new address (and, if "secure email change" is on for
    // this project, to the old address too) before the change is applied.
    // session.user.email stays the old value until that link is clicked.
    const { error: updateError } = await supabase.auth.updateUser({ email: trimmedEmail });
    setIsSaving(false);

    if (updateError) {
      setError(updateError.message);
      return;
    }

    setCurrentPassword('');
    setSentTo(trimmedEmail);
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: TINT }}>
            Change Email
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText style={styles.hint}>Current: {session?.user.email}</ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
        {sentTo ? (
          <ThemedText style={styles.success}>
            Confirmation link sent to {sentTo}. Your email won&apos;t change until you click it.
          </ThemedText>
        ) : null}

        <ThemedText type="defaultSemiBold" style={styles.fieldSpacing}>
          Current password
        </ThemedText>
        <PasswordInput
          value={currentPassword}
          onChangeText={setCurrentPassword}
          placeholder="Current password"
          accentColor={TINT}
          style={styles.input}
        />

        <ThemedText type="defaultSemiBold">New email</ThemedText>
        <TextInput
          value={newEmail}
          onChangeText={setNewEmail}
          keyboardType="email-address"
          autoCapitalize="none"
          autoCorrect={false}
          placeholder="you@example.com"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: TINT }]}
        />

        <Pressable onPress={handleSave} disabled={isSaving} style={[styles.button, { backgroundColor: TINT }]}>
          {isSaving ? (
            <ActivityIndicator color={Colors.light.backgroundSolid} />
          ) : (
            <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>
              Send confirmation
            </ThemedText>
          )}
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  fieldSpacing: {
    marginTop: 16,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
  success: {
    color: Colors.light.positive,
  },
});
