import { useLocalSearchParams, useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, Switch, TextInput } from 'react-native';

import { CityAutocompleteInput } from '@/components/city-autocomplete-input';
import { DateInput } from '@/components/date-input';
import { SelectModal, type SelectOption } from '@/components/select-modal';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { TimeInput } from '@/components/time-input';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useCurrency, LOCAL_CURRENCY } from '@/contexts/currency-context';
import { showAlert } from '@/lib/alert';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import type { CountryVisitedRow, TripSegmentMode } from '@/types/database';

const ACCENT = ModuleAccents.countries;

const MODE_OPTIONS: SelectOption[] = [
  { value: 'flight', label: 'Flight' },
  { value: 'train', label: 'Train' },
  { value: 'car', label: 'Car' },
  { value: 'bus', label: 'Bus' },
  { value: 'ferry', label: 'Ferry' },
  { value: 'other', label: 'Other' },
];

export default function TripSegmentFormScreen() {
  const {
    id,
    tripId: tripIdParam,
    minDepartDate,
    maxArriveDate,
    defaultDepartDate,
  } = useLocalSearchParams<{
    id: string;
    tripId?: string;
    minDepartDate?: string;
    maxArriveDate?: string;
    /** The last date already in the itinerary (a stop or another leg) — just a starting point for the pickers below, not a floor; see minDepartDate for the actual enforced bound. */
    defaultDepartDate?: string;
  }>();
  const isNew = id === 'new';
  const router = useRouter();
  const { displayCurrency, availableCurrencies, currencyNames } = useCurrency();
  const tripMinDate = minDepartDate ? parseDateOnly(minDepartDate) : null;
  const tripMaxDate = maxArriveDate ? parseDateOnly(maxArriveDate) : null;
  const defaultDepartDateValue = defaultDepartDate ? parseDateOnly(defaultDepartDate) : null;

  const [isLoading, setIsLoading] = useState(!isNew);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [tripId, setTripId] = useState(tripIdParam ?? '');
  const [mode, setMode] = useState<TripSegmentMode>('flight');
  const [showModePicker, setShowModePicker] = useState(false);
  const [showCostCurrencyPicker, setShowCostCurrencyPicker] = useState(false);
  const [carrier, setCarrier] = useState('');
  const [confirmationNumber, setConfirmationNumber] = useState('');
  const [fromLabel, setFromLabel] = useState('');
  const [toLabel, setToLabel] = useState('');
  // Set only when a CityAutocompleteInput suggestion was actually picked
  // (see that component) — null after free typing, which is still allowed
  // but carries no coordinates. A segment's from/to is trip LOGISTICS (how
  // you got there), not a stay, so these must never feed into the trip's
  // own country list or day-count anywhere else in the app — only into
  // the route map's waypoints (lib/tripRoute.ts). tripStops (the trip's
  // actual countries_visited rows, fetched below) is what the depart-date
  // check further down matches against — deliberately never these picks.
  const [fromCoords, setFromCoords] = useState<{ lat: number; lon: number } | null>(null);
  const [toCoords, setToCoords] = useState<{ lat: number; lon: number } | null>(null);
  const [tripStops, setTripStops] = useState<CountryVisitedRow[]>([]);
  const [departDate, setDepartDate] = useState(defaultDepartDateValue ?? new Date());
  const [departTime, setDepartTime] = useState<string | null>(null);
  const [arriveDate, setArriveDate] = useState(defaultDepartDateValue ?? new Date());
  const [arriveTime, setArriveTime] = useState<string | null>(null);
  const [notes, setNotes] = useState('');
  const [costAmount, setCostAmount] = useState('');
  const [costCurrency, setCostCurrency] = useState(displayCurrency === LOCAL_CURRENCY ? 'USD' : displayCurrency);
  const [jointGroupId, setJointGroupId] = useState<string | null>(null);
  const [shareStatus, setShareStatus] = useState<{ user_id: string; display_name: string; is_included: boolean }[]>(
    []
  );
  const [togglingUserId, setTogglingUserId] = useState<string | null>(null);

  async function loadShareStatus() {
    const { data } = await supabase.rpc('segment_share_status', { p_segment_id: id });
    setShareStatus(data ?? []);
  }

  useEffect(() => {
    if (isNew) return;

    let cancelled = false;
    supabase
      .from('trip_segments')
      .select('*')
      .eq('id', id)
      .single()
      .then(({ data, error: fetchError }) => {
        if (cancelled) return;
        if (fetchError) {
          setError(fetchError.message);
        } else if (data) {
          setTripId(data.trip_id);
          setMode(data.mode);
          setCarrier(data.carrier ?? '');
          setConfirmationNumber(data.confirmation_number ?? '');
          setFromLabel(data.from_label);
          setToLabel(data.to_label);
          setFromCoords(data.from_lat != null && data.from_lon != null ? { lat: data.from_lat, lon: data.from_lon } : null);
          setToCoords(data.to_lat != null && data.to_lon != null ? { lat: data.to_lat, lon: data.to_lon } : null);
          setDepartDate(parseDateOnly(data.depart_date));
          setDepartTime(data.depart_time);
          setArriveDate(parseDateOnly(data.arrive_date));
          setArriveTime(data.arrive_time);
          setNotes(data.notes ?? '');
          setCostAmount(data.cost != null ? String(data.cost) : '');
          if (data.cost_currency) setCostCurrency(data.cost_currency);
          setJointGroupId(data.joint_group_id);
          if (data.joint_group_id) {
            loadShareStatus();
          }
        }
        setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, isNew]);

  // The trip's own stops — used only to check this segment's depart date
  // against the stay it's departing from (see handleSave below), never to
  // constrain the from/to city pickers themselves (a connecting flight can
  // depart from a city that was never actually a stop on this trip).
  useEffect(() => {
    if (!tripId) return;
    let cancelled = false;
    supabase
      .from('countries_visited')
      .select('*')
      .eq('trip_id', tripId)
      .then(({ data }) => {
        if (!cancelled) setTripStops(data ?? []);
      });
    return () => {
      cancelled = true;
    };
  }, [tripId]);

  async function handleToggleShare(targetUserId: string, nextIncluded: boolean) {
    setTogglingUserId(targetUserId);
    const { error: toggleError } = await supabase.rpc('set_segment_share_exclusion', {
      p_segment_id: id,
      p_excluded_user_id: targetUserId,
      p_excluded: !nextIncluded,
    });
    if (toggleError) {
      setError(toggleError.message);
    } else {
      await loadShareStatus();
    }
    setTogglingUserId(null);
  }

  async function handleSave() {
    if (!fromLabel.trim() || !toLabel.trim()) {
      setError('From and To are required.');
      return;
    }
    if (!tripId) {
      setError('Missing trip.');
      return;
    }
    if (arriveDate < departDate) {
      setError('Arrival date must be on or after the departure date.');
      return;
    }
    if (tripMinDate && departDate < tripMinDate) {
      setError("Departure can't be before the trip starts.");
      return;
    }
    if (tripMaxDate && arriveDate > tripMaxDate) {
      setError("Arrival can't be after the trip ends.");
      return;
    }
    // Can't depart a city before you've actually arrived there — matched
    // by city name against the trip's own stops (never the segment's own
    // from/to picks, which are just logistics, not stays; see the
    // fromCountry/toCountry comment above). A same-day hop (departing on
    // the same date the stay there began) is fine and not flagged.
    const departDateStr = toDateOnlyString(departDate);
    const fromStop = tripStops.find((s) => s.city?.trim().toLowerCase() === fromLabel.trim().toLowerCase());
    if (fromStop && departDateStr < fromStop.entry_date) {
      setError(
        `This departs from ${fromLabel.trim()} on ${formatDateDisplay(departDateStr)}, but your stay there doesn't start until ${formatDateDisplay(fromStop.entry_date)}.`
      );
      return;
    }
    const trimmedCost = costAmount.trim();
    const parsedCost = trimmedCost ? Number(trimmedCost) : null;
    if (trimmedCost && (Number.isNaN(parsedCost) || parsedCost! < 0)) {
      setError('Planned cost must be a positive number.');
      return;
    }

    setError(null);
    setIsSaving(true);

    const payload = {
      trip_id: tripId,
      mode,
      carrier: carrier.trim() || null,
      confirmation_number: confirmationNumber.trim() || null,
      from_label: fromLabel.trim(),
      to_label: toLabel.trim(),
      from_lat: fromCoords?.lat ?? null,
      from_lon: fromCoords?.lon ?? null,
      to_lat: toCoords?.lat ?? null,
      to_lon: toCoords?.lon ?? null,
      depart_date: toDateOnlyString(departDate),
      depart_time: departTime,
      arrive_date: toDateOnlyString(arriveDate),
      arrive_time: arriveTime,
      notes: notes.trim() || null,
      cost: parsedCost,
      cost_currency: parsedCost != null ? costCurrency.trim().toUpperCase() : null,
    };

    const { error: saveError } = isNew
      ? await supabase.from('trip_segments').insert(payload)
      : await supabase.from('trip_segments').update(payload).eq('id', id);

    setIsSaving(false);
    if (saveError) {
      setError(saveError.message);
      return;
    }
    router.back();
  }

  function handleDelete() {
    showAlert('Delete travel', 'This cannot be undone.', [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Delete',
        style: 'destructive',
        onPress: async () => {
          setIsSaving(true);
          const { error: deleteError } = await supabase.from('trip_segments').delete().eq('id', id);
          setIsSaving(false);
          if (deleteError) {
            setError(deleteError.message);
            return;
          }
          router.back();
        },
      },
    ]);
  }

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  const modeLabel = MODE_OPTIONS.find((o) => o.value === mode)?.label ?? 'Flight';

  // Falls back to the bare code if the name hasn't been populated yet, same as components/top-bar.tsx's own currency picker.
  function currencyLabel(code: string): string {
    const currencyName = currencyNames[code];
    return currencyName ? `${currencyName} (${code})` : code;
  }
  const costCurrencyOptions: SelectOption[] = availableCurrencies.map((code) => ({
    value: code,
    label: currencyLabel(code),
  }));

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            {isNew ? 'Add Travel' : 'Edit Travel'}
          </ThemedText>
          {!isNew ? (
            <Pressable onPress={handleDelete} hitSlop={12}>
              <IconSymbol name="trash" size={22} color={Colors.light.negative} />
            </Pressable>
          ) : null}
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {jointGroupId && shareStatus.length > 0 ? (
          <ThemedView style={styles.shareSection}>
            <ThemedText type="defaultSemiBold">Shared with</ThemedText>
            <ThemedText style={styles.muted}>
              This trip is shared by default. Turn someone off here to keep just this leg private from them.
            </ThemedText>
            {shareStatus.map((participant) => (
              <ThemedView key={participant.user_id} style={styles.shareRow}>
                <ThemedText numberOfLines={1} style={styles.shareRowLabel}>
                  {participant.display_name}
                </ThemedText>
                <Switch
                  value={participant.is_included}
                  onValueChange={(next) => handleToggleShare(participant.user_id, next)}
                  disabled={togglingUserId === participant.user_id}
                  trackColor={{ true: ACCENT }}
                />
              </ThemedView>
            ))}
          </ThemedView>
        ) : null}

        <ThemedText type="defaultSemiBold">Mode</ThemedText>
        <Pressable onPress={() => setShowModePicker(true)} style={[styles.input, { borderColor: ACCENT }]}>
          <ThemedText>{modeLabel}</ThemedText>
        </Pressable>
        <SelectModal
          visible={showModePicker}
          onClose={() => setShowModePicker(false)}
          options={MODE_OPTIONS}
          selectedValue={mode}
          onSelect={(value) => setMode(value as TripSegmentMode)}
        />

        <ThemedText type="defaultSemiBold">From</ThemedText>
        <CityAutocompleteInput
          value={fromLabel}
          onChangeText={(text) => {
            setFromLabel(text);
            setFromCoords(null);
          }}
          onSelectPlace={(place) => {
            setFromLabel(place.name);
            setFromCoords({ lat: place.lat, lon: place.lon });
          }}
          placeholder="e.g. Frankfurt"
          accentColor={ACCENT}
        />

        <ThemedText type="defaultSemiBold">To</ThemedText>
        <CityAutocompleteInput
          value={toLabel}
          onChangeText={(text) => {
            setToLabel(text);
            setToCoords(null);
          }}
          onSelectPlace={(place) => {
            setToLabel(place.name);
            setToCoords({ lat: place.lat, lon: place.lon });
          }}
          placeholder="e.g. Delhi"
          accentColor={ACCENT}
        />

        <ThemedText type="defaultSemiBold">Depart</ThemedText>
        {tripMinDate ? (
          <ThemedText style={styles.muted}>
            Can&apos;t be before the trip starts ({formatDateDisplay(toDateOnlyString(tripMinDate))}).
          </ThemedText>
        ) : null}
        <ThemedView style={styles.row}>
          <ThemedView style={styles.half}>
            <DateInput
              value={departDate}
              onChange={(date) => {
                setDepartDate(date);
                if (arriveDate < date) setArriveDate(date);
              }}
              accentColor={ACCENT}
              minimumDate={tripMinDate ?? undefined}
            />
          </ThemedView>
          <ThemedView style={styles.half}>
            <TimeInput value={departTime} onChange={setDepartTime} accentColor={ACCENT} />
          </ThemedView>
        </ThemedView>

        <ThemedText type="defaultSemiBold">Arrive</ThemedText>
        {tripMaxDate ? (
          <ThemedText style={styles.muted}>
            Can&apos;t be after the trip ends ({formatDateDisplay(toDateOnlyString(tripMaxDate))}).
          </ThemedText>
        ) : null}
        <ThemedView style={styles.row}>
          <ThemedView style={styles.half}>
            <DateInput
              value={arriveDate}
              onChange={setArriveDate}
              accentColor={ACCENT}
              minimumDate={departDate}
              maximumDate={tripMaxDate ?? undefined}
            />
          </ThemedView>
          <ThemedView style={styles.half}>
            <TimeInput value={arriveTime} onChange={setArriveTime} accentColor={ACCENT} />
          </ThemedView>
        </ThemedView>

        <ThemedText type="defaultSemiBold">Carrier (optional)</ThemedText>
        <TextInput
          value={carrier}
          onChangeText={setCarrier}
          placeholder="e.g. IndiGo"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <ThemedText type="defaultSemiBold">Confirmation number (optional)</ThemedText>
        <TextInput
          value={confirmationNumber}
          onChangeText={setConfirmationNumber}
          placeholder="e.g. ABC123"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <ThemedText type="defaultSemiBold">Planned cost (optional)</ThemedText>
        <ThemedText style={styles.hint}>
          A budgeted figure for this leg, shown alongside any actual expense you link to it on the Cost Graph.
        </ThemedText>
        <ThemedView style={styles.row}>
          <TextInput
            value={costAmount}
            onChangeText={setCostAmount}
            placeholder="0.00"
            keyboardType="decimal-pad"
            placeholderTextColor={Colors.light.textMuted}
            style={[styles.input, styles.flexShrink, { color: Colors.light.text, borderColor: ACCENT }]}
          />
          <Pressable
            onPress={() => setShowCostCurrencyPicker(true)}
            style={[styles.input, styles.costCurrencyInput, { borderColor: ACCENT }]}>
            <ThemedText numberOfLines={1}>{costCurrency || 'Select'}</ThemedText>
          </Pressable>
        </ThemedView>
        <SelectModal
          visible={showCostCurrencyPicker}
          onClose={() => setShowCostCurrencyPicker(false)}
          options={costCurrencyOptions}
          selectedValue={costCurrency || null}
          onSelect={(value) => {
            setCostCurrency(value);
            setShowCostCurrencyPicker(false);
          }}
        />

        <ThemedText type="defaultSemiBold">Notes</ThemedText>
        <TextInput
          value={notes}
          onChangeText={setNotes}
          placeholder="Optional"
          placeholderTextColor={Colors.light.textMuted}
          multiline
          numberOfLines={4}
          style={[styles.input, styles.notesInput, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <Pressable onPress={handleSave} disabled={isSaving} style={[styles.button, { backgroundColor: ACCENT }]}>
          {isSaving ? (
            <ActivityIndicator color={ModuleAccentOnColor.countries} />
          ) : (
            <ThemedText style={{ color: ModuleAccentOnColor.countries, fontWeight: '600' }}>Save</ThemedText>
          )}
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

function parseDateOnly(dateString: string): Date {
  const [year, month, day] = dateString.split('-').map(Number);
  return new Date(year, month - 1, day);
}

