import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { CountryAutocompleteInput } from '@/components/country-autocomplete-input';
import { CountryFlag } from '@/components/country-flag';
import { DateInput } from '@/components/date-input';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useCurrency } from '@/contexts/currency-context';
import { flagCodeForCountry } from '@/lib/countries';
import { toDateOnlyString } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import type { UserCitizenshipRow, UserVisaRow } from '@/types/database';

const TINT = Colors.light.tint;

function parseDateOnly(dateString: string): Date {
  const [year, month, day] = dateString.split('-').map(Number);
  return new Date(year, month - 1, day);
}

export default function CitizenshipScreen() {
  const router = useRouter();
  const { session } = useAuth();
  const { hiddenFlagCountries } = useCurrency();

  const [citizenships, setCitizenships] = useState<UserCitizenshipRow[]>([]);
  const [visas, setVisas] = useState<UserVisaRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [primaryDraft, setPrimaryDraft] = useState('');
  const [addCitizenshipInput, setAddCitizenshipInput] = useState('');
  const [addVisaInput, setAddVisaInput] = useState('');

  const load = useCallback(async () => {
    if (!session) return;
    setError(null);
    const [citizenshipsResult, visasResult] = await Promise.all([
      supabase.from('user_citizenships').select('*').order('created_at'),
      supabase.from('user_visas').select('*').order('created_at'),
    ]);
    if (citizenshipsResult.error) {
      setError(citizenshipsResult.error.message);
    } else {
      setCitizenships(citizenshipsResult.data ?? []);
    }
    if (visasResult.error) {
      setError(visasResult.error.message);
    } else {
      setVisas(visasResult.data ?? []);
    }
    setIsLoading(false);
  }, [session]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const primary = citizenships.find((c) => c.is_primary) ?? null;
  const others = citizenships.filter((c) => !c.is_primary);

  // Draft is a free-typed copy of primary?.country, same reasoning as
  // app/account/index.tsx's home-country draft — setPrimary shouldn't fire
  // on every keystroke, only on an actual selection or a valid exact match
  // on blur.
  useEffect(() => {
    setPrimaryDraft(primary?.country ?? '');
  }, [primary?.country]);

  function handlePrimaryBlur() {
    const trimmed = primaryDraft.trim();
    if (trimmed && trimmed !== primary?.country && flagCodeForCountry(trimmed)) {
      setPrimary(trimmed);
    } else {
      setPrimaryDraft(primary?.country ?? '');
    }
  }

  async function setPrimary(country: string) {
    if (!session) return;
    setError(null);
    const myId = session.user.id;
    const existing = citizenships.find((c) => c.country === country);

    // Not atomic (two sequential calls, no cross-row transaction available
    // from the client) — acceptable here since a brief window with either
    // zero or two rows marked primary self-heals on the next load/toggle,
    // and RLS already scopes both calls to this user's own rows.
    const { error: clearError } = await supabase
      .from('user_citizenships')
      .update({ is_primary: false })
      .eq('user_id', myId)
      .eq('is_primary', true);
    if (clearError) {
      setError(clearError.message);
      return;
    }

    if (existing) {
      const { error: promoteError } = await supabase
        .from('user_citizenships')
        .update({ is_primary: true })
        .eq('id', existing.id);
      if (promoteError) {
        setError(promoteError.message);
        return;
      }
    } else {
      const { error: insertError } = await supabase
        .from('user_citizenships')
        .insert({ user_id: myId, country, is_primary: true });
      if (insertError) {
        setError(insertError.message);
        return;
      }
    }
    await load();
  }

  async function addCitizenship(country: string) {
    if (!session) return;
    setError(null);
    if (citizenships.some((c) => c.country === country)) return;
    const { error: insertError } = await supabase
      .from('user_citizenships')
      .insert({ user_id: session.user.id, country, is_primary: citizenships.length === 0 });
    if (insertError) {
      setError(insertError.message);
      return;
    }
    await load();
  }

  async function removeCitizenship(id: string) {
    setError(null);
    const { error: deleteError } = await supabase.from('user_citizenships').delete().eq('id', id);
    if (deleteError) {
      setError(deleteError.message);
      return;
    }
    setCitizenships((prev) => prev.filter((c) => c.id !== id));
  }

  async function addVisa(country: string) {
    if (!session) return;
    setError(null);
    const { data, error: insertError } = await supabase
      .from('user_visas')
      .insert({ user_id: session.user.id, country })
      .select()
      .single();
    if (insertError) {
      setError(insertError.message);
      return;
    }
    if (data) setVisas((prev) => [...prev, data]);
  }

  async function removeVisa(id: string) {
    setError(null);
    const { error: deleteError } = await supabase.from('user_visas').delete().eq('id', id);
    if (deleteError) {
      setError(deleteError.message);
      return;
    }
    setVisas((prev) => prev.filter((v) => v.id !== id));
  }

  async function setVisaExpiry(id: string, date: Date) {
    setError(null);
    const expiry_date = toDateOnlyString(date);
    const { error: updateError } = await supabase.from('user_visas').update({ expiry_date }).eq('id', id);
    if (updateError) {
      setError(updateError.message);
      return;
    }
    setVisas((prev) => prev.map((v) => (v.id === id ? { ...v, expiry_date } : v)));
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: TINT }}>
            Citizenship
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText style={styles.hint}>Separate from your home country. Supports holding more than one.</ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {isLoading ? (
          <ActivityIndicator color={TINT} />
        ) : (
          <>
            <ThemedText type="defaultSemiBold" style={styles.fieldLabel}>
              Primary
            </ThemedText>
            <CountryAutocompleteInput
              value={primaryDraft}
              onChangeText={setPrimaryDraft}
              onSelectCountry={setPrimary}
              onBlur={handlePrimaryBlur}
              hiddenFlagCountries={hiddenFlagCountries}
              accentColor={TINT}
              placeholder="Not set"
            />

            <ThemedText type="defaultSemiBold" style={styles.fieldLabel}>
              Other citizenships
            </ThemedText>
            {others.length === 0 ? <ThemedText style={styles.hint}>None added.</ThemedText> : null}
            {others.map((c) => (
              <Surface key={c.id} accentColor={TINT} style={styles.row}>
                <ThemedView style={styles.inputRow}>
                  <CountryFlag countryName={c.country} hiddenFlagCountries={hiddenFlagCountries} size={18} />
                  <ThemedText>{c.country}</ThemedText>
                </ThemedView>
                <Pressable onPress={() => removeCitizenship(c.id)} hitSlop={12}>
                  <IconSymbol name="trash" size={18} color={Colors.light.negative} />
                </Pressable>
              </Surface>
            ))}
            <CountryAutocompleteInput
              value={addCitizenshipInput}
              onChangeText={setAddCitizenshipInput}
              onSelectCountry={(country) => {
                addCitizenship(country);
                setAddCitizenshipInput('');
              }}
              hiddenFlagCountries={hiddenFlagCountries}
              accentColor={TINT}
              placeholder="+ Add citizenship"
            />

            <ThemedText type="defaultSemiBold" style={styles.fieldLabel}>
              Visas
            </ThemedText>
            <ThemedText style={styles.hint}>
              Used by the travel checklist to flag when a destination needs a visa you don&apos;t have yet.
            </ThemedText>
            {visas.length === 0 ? <ThemedText style={styles.hint}>None added.</ThemedText> : null}
            {visas.map((v) => (
              <Surface key={v.id} accentColor={TINT} style={styles.visaRow}>
                <ThemedView style={styles.visaInfo}>
                  <ThemedView style={styles.inputRow}>
                    <CountryFlag countryName={v.country} hiddenFlagCountries={hiddenFlagCountries} size={18} />
                    <ThemedText>{v.country}</ThemedText>
                  </ThemedView>
                  <DateInput
                    value={v.expiry_date ? parseDateOnly(v.expiry_date) : null}
                    onChange={(date) => setVisaExpiry(v.id, date)}
                    accentColor={TINT}
                    placeholder="Set expiry date"
                  />
                </ThemedView>
                <Pressable onPress={() => removeVisa(v.id)} hitSlop={12}>
                  <IconSymbol name="trash" size={18} color={Colors.light.negative} />
                </Pressable>
              </Surface>
            ))}
            <CountryAutocompleteInput
              value={addVisaInput}
              onChangeText={setAddVisaInput}
              onSelectCountry={(country) => {
                addVisa(country);
                setAddVisaInput('');
              }}
              hiddenFlagCountries={hiddenFlagCountries}
              accentColor={TINT}
              placeholder="+ Add visa"
            />
          </>
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  fieldLabel: {
    marginTop: 8,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
  },
  inputRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  visaRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  visaInfo: {
    gap: 2,
  },
  addRow: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingVertical: 12,
    alignItems: 'center',
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
