import { toDateOnlyString } from '@/lib/format';
import { residencyRuleFor, type ResidencyWindow } from '@/lib/residencyRules';
import type { CountryVisitedRow } from '@/types/database';

const MS_PER_DAY = 24 * 60 * 60 * 1000;

function parseDateOnly(dateString: string): Date {
  const [year, month, day] = dateString.split('-').map(Number);
  return new Date(year, month - 1, day);
}

function clampDays(days: number): number {
  return Math.max(0, days);
}

/** Inclusive day count between two date-only Dates (same day = 1). */
function daysBetweenInclusive(start: Date, end: Date): number {
  return Math.floor((end.getTime() - start.getTime()) / MS_PER_DAY) + 1;
}

// Stands in for "no exit date yet" (still ongoing) when comparing ranges —
// far enough out that any dated range will compare as ending before it.
const FAR_FUTURE = new Date(9999, 0, 1);

export type DateConflict = { country: string; entryDate: string; exitDate: string | null };

/** A past residency (see app/account/prior-residencies.tsx) — the home country for its own [start_date, end_date] window, same as the current home country is for now. */
export type PriorResidencyLike = { country: string; start_date: string; end_date: string };

/**
 * Whether `country` should be treated as home-equivalent on `dateStr` — the
 * current home country always is; a past residency's own country is too,
 * but only within its own dates, so an old US residency doesn't exempt a
 * trip to the US logged decades later or earlier.
 */
function isHomeCountryOn(country: string, dateStr: string, homeCountry: string | null, priorResidencies: PriorResidencyLike[]): boolean {
  if (country === homeCountry) return true;
  return priorResidencies.some((r) => r.country === country && dateStr >= r.start_date && dateStr <= r.end_date);
}

/**
 * The inverse of isHomeCountryOn: given a date, which single country counts
 * as home on it — a prior residency covering that date, or else the
 * current home country. Residency-by-year screens use this with December
 * 31 of the year in question ("wherever you lived at year-end is the flag
 * for that year," per explicit product decision), not the current home
 * country for every year regardless of when it was actually set — that was
 * the bug: a 2022 US residency showing as UK days once the home country
 * setting was later updated to UK.
 */
export function effectiveHomeCountryFor(
  dateStr: string,
  homeCountry: string | null,
  priorResidencies: PriorResidencyLike[]
): string | null {
  const match = priorResidencies.find((r) => dateStr >= r.start_date && dateStr <= r.end_date);
  return match ? match.country : homeCountry;
}

/** Whether a logged visit falls (at least partly) inside a home-equivalent window for its own country — see isHomeCountryOn. */
function isExemptVisit(
  visit: Pick<CountryVisitedRow, 'country' | 'entry_date' | 'exit_date'>,
  homeCountry: string | null,
  priorResidencies: PriorResidencyLike[]
): boolean {
  if (visit.country === homeCountry) return true;
  const visitEnd = visit.exit_date ?? '9999-12-31';
  return priorResidencies.some(
    (r) => r.country === visit.country && visit.entry_date <= r.end_date && visitEnd >= r.start_date
  );
}

/**
 * The first OTHER non-home visit whose date range overlaps
 * [entryDate, exitDate], inclusive on both ends — you can't be recorded in
 * two places on the same day. Returns null for a home-country candidate
 * (exempt per product decision: home is the default/baseline, not a
 * trip that blocks other trips) and never matches an existing home-country
 * row either — "home" here includes any prior residency active on the
 * candidate's own entry date (see isHomeCountryOn), so a past residency
 * doesn't need a fake trip logged just to keep other dates free.
 * excludeVisitId skips the row being edited; excludeTripId skips
 * sibling stops of the same trip, since their own back-to-back sequencing is
 * already handled by the "can't start before the previous stop ends" rule
 * (which deliberately allows one stop's exit date to equal the next one's
 * entry date — a same-day handoff, not a double-booking).
 */
export function findDateConflict(
  visits: Pick<CountryVisitedRow, 'id' | 'country' | 'entry_date' | 'exit_date' | 'trip_id'>[],
  homeCountry: string | null,
  candidateCountry: string,
  entryDate: Date,
  exitDate: Date | null,
  excludeVisitId?: string | null,
  excludeTripId?: string | null,
  priorResidencies: PriorResidencyLike[] = []
): DateConflict | null {
  if (!candidateCountry || isHomeCountryOn(candidateCountry, toDateOnlyString(entryDate), homeCountry, priorResidencies)) return null;
  const newEnd = exitDate ?? FAR_FUTURE;
  for (const visit of visits) {
    if (isExemptVisit(visit, homeCountry, priorResidencies)) continue;
    if (excludeVisitId && visit.id === excludeVisitId) continue;
    if (excludeTripId && visit.trip_id === excludeTripId) continue;
    const otherStart = parseDateOnly(visit.entry_date);
    const otherEnd = visit.exit_date ? parseDateOnly(visit.exit_date) : FAR_FUTURE;
    // Strict inequalities — a new stay starting exactly the day another one
    // ends (or ending exactly the day another one starts) is a same-day
    // transition (check out of one place in the morning, into the next
    // that evening), not a double-booking. Only a date genuinely claimed by
    // BOTH stays — not just a shared boundary day — is a real conflict.
    if (entryDate < otherEnd && newEnd > otherStart) {
      return { country: visit.country, entryDate: visit.entry_date, exitDate: visit.exit_date };
    }
  }
  return null;
}

/**
 * Every calendar day claimed by an OTHER non-home visit, as "YYYY-MM-DD"
 * range pairs — feeds DateInput's disabledRanges so those days simply
 * can't be picked in the first place. Same exclusion rules as
 * findDateConflict, and the same same-day-transition allowance: each
 * range is narrowed by one day on both ends, so the visit's own entry/exit
 * dates themselves stay pickable (a new stay can start exactly when
 * another one ends, or end exactly when another one starts) while every
 * day strictly inside the stay stays blocked.
 */
export function blockedDateRanges(
  visits: Pick<CountryVisitedRow, 'id' | 'country' | 'entry_date' | 'exit_date' | 'trip_id'>[],
  homeCountry: string | null,
  excludeVisitId?: string | null,
  excludeTripId?: string | null,
  priorResidencies: PriorResidencyLike[] = []
): { start: string; end: string }[] {
  const farFutureStr = '9999-01-01';
  return visits
    .filter((v) => !isExemptVisit(v, homeCountry, priorResidencies))
    .filter((v) => !excludeVisitId || v.id !== excludeVisitId)
    .filter((v) => !excludeTripId || v.trip_id !== excludeTripId)
    .map((v) => {
      const start = parseDateOnly(v.entry_date);
      start.setDate(start.getDate() + 1);
      let end: Date | null = null;
      if (v.exit_date) {
        end = parseDateOnly(v.exit_date);
        end.setDate(end.getDate() - 1);
      }
      return { start, end };
    })
    // A stay of 2 days or fewer has no interior day left to block at all
    // once both ends are narrowed — nothing to disable, not an inverted
    // range.
    .filter(({ start, end }) => !end || start <= end)
    .map(({ start, end }) => ({ start: toDateOnlyString(start), end: end ? toDateOnlyString(end) : farFutureStr }));
}

export type CountrySummary = {
  country: string;
  daysUsed: number;
  daysRemaining: number;
  /** True once daysUsed has reached the country's trigger (>=, see lib/residencyRules.ts). */
  overLimit: boolean;
  thresholdDays: number;
  windowLabel: string;
  /** This country has no rule of its own modeled yet — the generic 183/rolling-12-months default is in use. */
  ruleIsDefault: boolean;
};

type VisitLike = Pick<CountryVisitedRow, 'country' | 'entry_date' | 'exit_date'>;

/**
 * Distinct calendar days covered by these visits within [rangeStart,
 * rangeEnd]. A Set of day keys (same technique as awayFromHomeDaySet et al.
 * below) rather than summing each row's length — a duplicate or overlapping
 * entry for the same dates then contributes no extra days instead of
 * double-counting against the threshold. An open-ended visit runs through
 * `openEndedThrough` (today for live tallies).
 */
function countDistinctDays(visits: VisitLike[], rangeStart: Date, rangeEnd: Date, openEndedThrough: Date): number {
  const days = new Set<string>();
  for (const visit of visits) {
    const visitStart = parseDateOnly(visit.entry_date);
    const visitEnd = visit.exit_date ? parseDateOnly(visit.exit_date) : openEndedThrough;
    const start = visitStart > rangeStart ? visitStart : rangeStart;
    const end = visitEnd < rangeEnd ? visitEnd : rangeEnd;
    if (start > end) continue;
    for (const d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
      days.add(toDateOnlyKey(d));
    }
  }
  return days.size;
}

/**
 * Same union-of-days technique as countDistinctDays, for a caller (e.g.
 * lib/schengen.ts) that needs the actual Set of days, not just its size —
 * to find the oldest day currently inside a rolling window, for instance.
 * Keys are toDateOnlyString's zero-padded YYYY-MM-DD, specifically so a
 * plain lexicographic sort on the Set's contents is also a chronological
 * one — countDistinctDays's own internal toDateOnlyKey (unpadded, 0-based
 * month) does NOT sort correctly and is deliberately not reused here.
 */
export function countDistinctDaysInWindow(
  visits: VisitLike[],
  rangeStart: Date,
  rangeEnd: Date,
  openEndedThrough: Date
): { count: number; days: Set<string> } {
  const days = new Set<string>();
  for (const visit of visits) {
    const visitStart = parseDateOnly(visit.entry_date);
    const visitEnd = visit.exit_date ? parseDateOnly(visit.exit_date) : openEndedThrough;
    const start = visitStart > rangeStart ? visitStart : rangeStart;
    const end = visitEnd < rangeEnd ? visitEnd : rangeEnd;
    if (start > end) continue;
    for (const d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
      days.add(toDateOnlyString(d));
    }
  }
  return { count: days.size, days };
}

/** Days used toward a country's own residency window, ending today. */
function daysUsedInWindow(visits: VisitLike[], window: ResidencyWindow, todayOnly: Date): number {
  const year = todayOnly.getFullYear();
  switch (window.kind) {
    case 'rolling': {
      const start = new Date(todayOnly);
      start.setDate(start.getDate() - (window.days - 1));
      return countDistinctDays(visits, start, todayOnly, todayOnly);
    }
    case 'calendar-year':
      return countDistinctDays(visits, new Date(year, 0, 1), todayOnly, todayOnly);
    case 'tax-year': {
      const thisYearStart = new Date(year, window.startMonth - 1, window.startDay);
      const start = thisYearStart <= todayOnly ? thisYearStart : new Date(year - 1, window.startMonth - 1, window.startDay);
      return countDistinctDays(visits, start, todayOnly, todayOnly);
    }
    case 'us-substantial-presence': {
      const current = countDistinctDays(visits, new Date(year, 0, 1), todayOnly, todayOnly);
      // The IRS test has TWO independent requirements, not one: the 3-year
      // weighted total below, AND at least 31 days of actual presence in
      // the CURRENT year — 26 U.S.C. § 7701(b)(3)(A)(i). Skipping this gate
      // was a real bug, not just an edge case: someone who lived in the US
      // last year and has since moved away would otherwise keep reading as
      // "215 days used" indefinitely, purely from the prior-year carryover,
      // even with zero days there this year. Below the 31-day floor, the
      // test simply doesn't apply this year — daysUsed is just this year's
      // actual count (always < 31, so never near a 183 threshold), not the
      // weighted figure.
      if (current < 31) return current;
      // IRS counts the prior years' fractions exactly; rounding only the
      // final total keeps the display an integer without drifting.
      const previous = countDistinctDays(visits, new Date(year - 1, 0, 1), new Date(year - 1, 11, 31), todayOnly);
      const twoBack = countDistinctDays(visits, new Date(year - 2, 0, 1), new Date(year - 2, 11, 31), todayOnly);
      return Math.round(current + previous / 3 + twoBack / 6);
    }
  }
}

/**
 * Days used per country against THAT country's own residency day-count
 * rule (lib/residencyRules.ts) — its threshold and its window (rolling 12
 * months, calendar year, an offset tax year like the UK's 6 April, or the
 * US weighted three-year test). Countries without a modeled rule fall back
 * to 183 days in a rolling 12 months and are flagged as such.
 */
export function summarizeCountries(visits: VisitLike[], today: Date = new Date()): CountrySummary[] {
  const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());

  const visitsByCountry = new Map<string, VisitLike[]>();
  for (const visit of visits) {
    const list = visitsByCountry.get(visit.country) ?? [];
    list.push(visit);
    visitsByCountry.set(visit.country, list);
  }

  return Array.from(visitsByCountry.entries())
    .map(([country, countryVisits]) => {
      const rule = residencyRuleFor(country);
      const daysUsed = daysUsedInWindow(countryVisits, rule.window, todayOnly);
      return {
        country,
        daysUsed,
        daysRemaining: clampDays(rule.thresholdDays - daysUsed),
        overLimit: daysUsed >= rule.thresholdDays,
        thresholdDays: rule.thresholdDays,
        windowLabel: rule.label,
        ruleIsDefault: rule.isDefault,
      };
    })
    .filter((summary) => summary.daysUsed > 0)
    .sort((a, b) => b.daysUsed - a.daysUsed);
}

/**
 * Actual days spent in `country` within one calendar year — capped at today
 * for the current year (so a still-ongoing or future-dated stay doesn't
 * inflate an "actual so far" figure the way projectedDaysInCountryByYearEnd
 * deliberately does), and the full Jan 1 - Dec 31 range for a past year.
 * Drives the per-country/per-year day count on the country detail screen's
 * year chips and the country calendar screen — NOT the live rolling/tax-
 * year residency-rule tally summarizeCountries gives, which stays anchored
 * to "as of today" regardless of which year someone is browsing.
 */
export function daysInCountryForYear(
  visits: Pick<CountryVisitedRow, 'country' | 'entry_date' | 'exit_date'>[],
  country: string,
  year: number,
  today: Date = new Date()
): number {
  const yearStart = new Date(year, 0, 1);
  const naturalYearEnd = new Date(year, 11, 31);
  const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const yearEnd = todayOnly < naturalYearEnd ? todayOnly : naturalYearEnd;
  if (yearEnd < yearStart) return 0;
  const countryVisits = visits.filter((v) => v.country === country);
  return summarizeCountriesInRange(countryVisits, yearStart, yearEnd)[0]?.daysUsed ?? 0;
}

export type CountryRangeSummary = { country: string; daysUsed: number };

/**
 * Days spent per country within an arbitrary [rangeStart, rangeEnd] window —
 * NOT the rolling-365-day threshold view summarizeCountries gives (that's
 * always anchored to "today"; this is for a specific historical range
 * someone picked, e.g. a date-scoped export). An open-ended visit (no
 * exit_date) is treated as running through rangeEnd, not today, since a
 * still-ongoing stay should still be capped at whatever window was asked
 * for. Same Set-based day-union technique as summarizeCountries, so a
 * duplicate/overlapping entry still can't double-count.
 */
export function summarizeCountriesInRange(
  visits: Pick<CountryVisitedRow, 'country' | 'entry_date' | 'exit_date'>[],
  rangeStart: Date,
  rangeEnd: Date
): CountryRangeSummary[] {
  const daysByCountry = new Map<string, Set<string>>();

  for (const visit of visits) {
    const visitStart = parseDateOnly(visit.entry_date);
    const visitEnd = visit.exit_date ? parseDateOnly(visit.exit_date) : rangeEnd;
    const start = visitStart > rangeStart ? visitStart : rangeStart;
    const end = visitEnd < rangeEnd ? visitEnd : rangeEnd;
    if (start > end) continue;
    let days = daysByCountry.get(visit.country);
    if (!days) {
      days = new Set<string>();
      daysByCountry.set(visit.country, days);
    }
    for (const d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
      days.add(toDateOnlyKey(d));
    }
  }

  return Array.from(daysByCountry.entries())
    .map(([country, days]) => ({ country, daysUsed: days.size }))
    .sort((a, b) => b.daysUsed - a.daysUsed);
}

// Well before any real logged visit could exist — used as the lifetime
// range's start so summarizeCountriesInRange's Set-based day union picks up
// every visit ever logged, regardless of how far back it goes.
const LIFETIME_EPOCH = new Date(1900, 0, 1);

/**
 * Genuine lifetime total: every distinct calendar day ever logged in
 * `country`, from the very first visit through today — NOT
 * summarizeCountries's live rolling/tax-year residency-test tally, which is
 * deliberately scoped to a specific compliance window (e.g. trailing 365
 * days) and excludes anything outside it. That distinction is exactly what
 * "All-time" showing a country's days as lower than the sum of its
 * individual year totals turned out to mean — confusing rather than useful,
 * per explicit product feedback. Drives the "All-time" option on the
 * country detail and Countries-hub screens instead.
 */
export function lifetimeDaysInCountry(
  visits: Pick<CountryVisitedRow, 'country' | 'entry_date' | 'exit_date'>[],
  country: string,
  today: Date = new Date()
): number {
  const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const countryVisits = visits.filter((v) => v.country === country);
  return summarizeCountriesInRange(countryVisits, LIFETIME_EPOCH, todayOnly)[0]?.daysUsed ?? 0;
}

/** Same idea as lifetimeDaysInCountry, for every country at once — drives the Countries-hub "All-time" list. */
export function lifetimeCountrySummaries(
  visits: Pick<CountryVisitedRow, 'country' | 'entry_date' | 'exit_date'>[],
  today: Date = new Date()
): CountryRangeSummary[] {
  const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  return summarizeCountriesInRange(visits, LIFETIME_EPOCH, todayOnly);
}

/** Days used for a single visit entry (for display on the detail screen). */
export function visitDayCount(entryDate: string, exitDate: string | null, today: Date = new Date()): number {
  const start = parseDateOnly(entryDate);
  const end = exitDate ? parseDateOnly(exitDate) : new Date(today.getFullYear(), today.getMonth(), today.getDate());
  if (end < start) return 0;
  return daysBetweenInclusive(start, end);
}

/** Calendar days elapsed this year, Jan 1 through today inclusive. */
export function daysElapsedInYear(today: Date = new Date()): number {
  const yearStart = new Date(today.getFullYear(), 0, 1);
  const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  return daysBetweenInclusive(yearStart, todayOnly);
}

export function daysInYear(year: number): number {
  const isLeapYear = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  return isLeapYear ? 366 : 365;
}

/** Calendar days left in the current year, after today. */
export function daysRemainingInYear(today: Date = new Date()): number {
  return daysInYear(today.getFullYear()) - daysElapsedInYear(today);
}

function toDateOnlyKey(date: Date): string {
  return `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;
}

/**
 * Union of calendar days this year covered by any visit to a country other
 * than `homeCountry` — a Set dedupes overlapping trips so no day is counted
 * twice. Ongoing visits (no exit_date) count through today.
 */
function awayFromHomeDaySet(visits: CountryVisitedRow[], homeCountry: string, today: Date): Set<string> {
  const yearStart = new Date(today.getFullYear(), 0, 1);
  const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const away = new Set<string>();

  for (const visit of visits) {
    if (visit.country === homeCountry) continue;
    const visitStart = parseDateOnly(visit.entry_date);
    const visitEnd = visit.exit_date ? parseDateOnly(visit.exit_date) : todayOnly;
    const start = visitStart > yearStart ? visitStart : yearStart;
    const end = visitEnd < todayOnly ? visitEnd : todayOnly;
    if (start > end) continue;
    for (const d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
      away.add(toDateOnlyKey(d));
    }
  }

  return away;
}

/**
 * Days attributed to the home country so far this year — never stored
 * directly, always derived: calendar days elapsed this year minus days
 * covered by any logged trip to another country (deduped, so overlapping
 * trips don't double-subtract).
 */
export function homeCountryDaysThisYear(
  visits: CountryVisitedRow[],
  homeCountry: string,
  today: Date = new Date()
): number {
  const elapsed = daysElapsedInYear(today);
  const away = awayFromHomeDaySet(visits, homeCountry, today).size;
  return clampDays(elapsed - away);
}

/**
 * Same idea as homeCountryDaysThisYear, but for an arbitrary calendar year,
 * not just the current one — capped at today only when `year` IS the
 * current year (so a past year always gets its full Jan 1 - Dec 31 tally).
 * Drives the country detail screen's year chips for the home country, same
 * as daysInCountryForYear does for everywhere else.
 */
export function homeCountryDaysForYear(
  visits: CountryVisitedRow[],
  homeCountry: string,
  year: number,
  today: Date = new Date()
): number {
  const yearStart = new Date(year, 0, 1);
  const naturalYearEnd = new Date(year, 11, 31);
  const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const yearEnd = todayOnly < naturalYearEnd ? todayOnly : naturalYearEnd;
  if (yearEnd < yearStart) return 0;
  const elapsed = daysBetweenInclusive(yearStart, yearEnd);
  const away = new Set<string>();
  for (const visit of visits) {
    if (visit.country === homeCountry) continue;
    const visitStart = parseDateOnly(visit.entry_date);
    const visitEnd = visit.exit_date ? parseDateOnly(visit.exit_date) : yearEnd;
    const start = visitStart > yearStart ? visitStart : yearStart;
    const end = visitEnd < yearEnd ? visitEnd : yearEnd;
    if (start > end) continue;
    for (const d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
      away.add(toDateOnlyKey(d));
    }
  }
  return clampDays(elapsed - away.size);
}

/**
 * Day-by-day version of homeCountryDaysForYear, for the calendar screen's
 * bars: the actual set of dates (as "YYYY-MM-DD" strings, matching
 * lib/format.ts's toDateOnlyString) attributed to the home country in
 * `year` — every day in range minus any day covered by another country's
 * visit. Unlike every other country, home-country presence is never logged
 * as its own countries_visited row, so it can't be read off visit rows the
 * way daysInCountryForYear's bars can — it has to be derived the same way
 * the stat above it is.
 */
export function homeCountryDaySetForYear(
  visits: CountryVisitedRow[],
  homeCountry: string,
  year: number,
  today: Date = new Date()
): Set<string> {
  const yearStart = new Date(year, 0, 1);
  const naturalYearEnd = new Date(year, 11, 31);
  const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const yearEnd = todayOnly < naturalYearEnd ? todayOnly : naturalYearEnd;
  if (yearEnd < yearStart) return new Set();

  const away = new Set<string>();
  for (const visit of visits) {
    if (visit.country === homeCountry) continue;
    const visitStart = parseDateOnly(visit.entry_date);
    const visitEnd = visit.exit_date ? parseDateOnly(visit.exit_date) : yearEnd;
    const start = visitStart > yearStart ? visitStart : yearStart;
    const end = visitEnd < yearEnd ? visitEnd : yearEnd;
    if (start > end) continue;
    for (const d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
      away.add(toDateOnlyString(d));
    }
  }

  const home = new Set<string>();
  for (const d = new Date(yearStart); d <= yearEnd; d.setDate(d.getDate() + 1)) {
    const key = toDateOnlyString(d);
    if (!away.has(key)) home.add(key);
  }
  return home;
}

/**
 * Same union-of-days technique as awayFromHomeDaySet, but for the FULL
 * calendar year (Jan 1 - Dec 31) rather than Jan 1 - today — this is what
 * lets projections see future-dated trips already logged, not just past
 * ones. An ongoing visit with no exit_date is assumed, for projection
 * purposes only, to run through year-end.
 */
function awayFromHomeDaySetForYear(visits: CountryVisitedRow[], homeCountry: string, today: Date): Set<string> {
  const yearStart = new Date(today.getFullYear(), 0, 1);
  const yearEnd = new Date(today.getFullYear(), 11, 31);
  const away = new Set<string>();

  for (const visit of visits) {
    if (visit.country === homeCountry) continue;
    const visitStart = parseDateOnly(visit.entry_date);
    const visitEnd = visit.exit_date ? parseDateOnly(visit.exit_date) : yearEnd;
    const start = visitStart > yearStart ? visitStart : yearStart;
    const end = visitEnd < yearEnd ? visitEnd : yearEnd;
    if (start > end) continue;
    for (const d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
      away.add(toDateOnlyKey(d));
    }
  }

  return away;
}

/**
 * Projected days spent away from homeCountry by year-end, counting every
 * trip logged this year — past and future. This is the figure the Summary
 * page's tax-residency flag and the Countries dashboard's year-end
 * projection are both built from.
 */
export function projectedDaysAwayFromHomeByYearEnd(
  visits: CountryVisitedRow[],
  homeCountry: string,
  today: Date = new Date()
): number {
  return awayFromHomeDaySetForYear(visits, homeCountry, today).size;
}

/**
 * Projected days in homeCountry by year-end — days in the year minus
 * projected days away (never stored directly, always derived), based on
 * every trip currently logged, including future-dated ones.
 */
export function projectedHomeCountryDaysByYearEnd(
  visits: CountryVisitedRow[],
  homeCountry: string,
  today: Date = new Date()
): number {
  const away = projectedDaysAwayFromHomeByYearEnd(visits, homeCountry, today);
  return clampDays(daysInYear(today.getFullYear()) - away);
}

/**
 * Same union-of-days technique as awayFromHomeDaySetForYear, but matching
 * one specific country's own visits instead of "everywhere but home" — a
 * Set still dedupes overlapping/duplicate-logged trips to the same country.
 */
function inCountryDaySetForYear(visits: CountryVisitedRow[], country: string, today: Date): Set<string> {
  const yearStart = new Date(today.getFullYear(), 0, 1);
  const yearEnd = new Date(today.getFullYear(), 11, 31);
  const inCountry = new Set<string>();

  for (const visit of visits) {
    if (visit.country !== country) continue;
    const visitStart = parseDateOnly(visit.entry_date);
    const visitEnd = visit.exit_date ? parseDateOnly(visit.exit_date) : yearEnd;
    const start = visitStart > yearStart ? visitStart : yearStart;
    const end = visitEnd < yearEnd ? visitEnd : yearEnd;
    if (start > end) continue;
    for (const d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
      inCountry.add(toDateOnlyKey(d));
    }
  }

  return inCountry;
}

/**
 * Projected days spent in a specific (non-home) country by year-end,
 * counting every trip logged this year to that country — past and future.
 * Same "including planned future trips" idea as
 * projectedDaysAwayFromHomeByYearEnd, just scoped to one country instead of
 * "everywhere but home."
 */
export function projectedDaysInCountryByYearEnd(
  visits: CountryVisitedRow[],
  country: string,
  today: Date = new Date()
): number {
  return inCountryDaySetForYear(visits, country, today).size;
}

export type ProjectedResidencyCountry = { country: string; daysIn: number; daysOut: number; thresholdDays: number };

/**
 * The country — home or foreign — a day-count residency test would
 * actually flag: projected to reach ITS OWN threshold (lib/residencyRules.ts)
 * in the calendar year, home country included (a year spent mostly at home
 * should say so, not just skip straight to "no foreign country is close").
 * Thresholds differ per country now (Thailand 180, Switzerland 90…), so
 * more than one could qualify in the same year; the one with the most
 * projected days wins. Null when nothing is on track to cross a line.
 *
 * The projection itself stays calendar-year based even for countries whose
 * real window is rolling or an offset tax year — it's a "how is this year
 * shaping up" figure, not the live tally summarizeCountries gives.
 */
export function projectedResidencyCountryByYearEnd(
  visits: CountryVisitedRow[],
  homeCountry: string,
  today: Date = new Date()
): ProjectedResidencyCountry | null {
  const countries = new Set<string>([homeCountry, ...visits.map((v) => v.country)]);
  const totalDaysInYear = daysInYear(today.getFullYear());

  let flagged: ProjectedResidencyCountry | null = null;
  for (const country of countries) {
    const daysIn =
      country === homeCountry
        ? projectedHomeCountryDaysByYearEnd(visits, homeCountry, today)
        : projectedDaysInCountryByYearEnd(visits, country, today);
    const thresholdDays = residencyRuleFor(country).thresholdDays;
    if (daysIn >= thresholdDays && (!flagged || daysIn > flagged.daysIn)) {
      flagged = { country, daysIn, daysOut: clampDays(totalDaysInYear - daysIn), thresholdDays };
    }
  }
  return flagged;
}

/**
 * Most days you can be projected to spend away from home this year before
 * home's own residency test is no longer met — its threshold subtracted
 * from the days in the year. Summary's "tax residency projection" and the
 * matching notice both compare projectedDaysAwayFromHomeByYearEnd against
 * this instead of a flat 183.
 */
export function allowedDaysAwayFromHome(homeCountry: string, today: Date = new Date()): number {
  return clampDays(daysInYear(today.getFullYear()) - residencyRuleFor(homeCountry).thresholdDays);
}
