import { flagCodeForCountry } from '@/lib/countries';
import { VISA_REQUIREMENTS } from '@/lib/visaRequirementsData';

export type VisaRequirementStatus = 'visa_free' | 'visa_on_arrival' | 'eta' | 'e_visa' | 'visa_required' | 'no_admission';

export type VisaRequirementResult = {
  status: VisaRequirementStatus;
  /** Only meaningful for visa_free — the allowed stay length, when the source data specifies one (some visa-free regimes, e.g. EU freedom of movement, don't cap it). */
  visaFreeDays: number | null;
  /** Always 'static' today (see lib/visaRequirementsData.ts) — kept so a caller can eventually distinguish a live-looked-up answer from this fallback, once a real API is wired in behind this same function. */
  source: 'static';
};

export const VISA_STATUS_LABELS: Record<VisaRequirementStatus, string> = {
  visa_free: 'Visa-free',
  visa_on_arrival: 'Visa on arrival',
  eta: 'Electronic travel authorization (ETA)',
  e_visa: 'e-Visa required',
  visa_required: 'Visa required',
  no_admission: 'Entry not permitted',
};

function decode(code: string): VisaRequirementResult {
  const letter = code[0];
  if (letter === 'A') return { status: 'visa_on_arrival', visaFreeDays: null, source: 'static' };
  if (letter === 'T') return { status: 'eta', visaFreeDays: null, source: 'static' };
  if (letter === 'E') return { status: 'e_visa', visaFreeDays: null, source: 'static' };
  if (letter === 'R') return { status: 'visa_required', visaFreeDays: null, source: 'static' };
  if (letter === 'N') return { status: 'no_admission', visaFreeDays: null, source: 'static' };
  // 'F' or 'F<days>'
  const days = code.slice(1);
  return { status: 'visa_free', visaFreeDays: days ? Number(days) : null, source: 'static' };
}

/**
 * Best-effort "does a [citizenshipCountry] passport need a visa for
 * [destinationCountry]" lookup — approximate reference data, NOT a
 * guarantee, and callers must present it that way (see
 * components/travel-checklist.tsx's own disclaimer). Backed today by a
 * static snapshot (lib/visaRequirementsData.ts, generated once from an
 * open MIT-licensed dataset); deliberately async even though that lookup
 * is instant, so swapping this out for a real visa-requirement API later —
 * if this feature earns that — only changes what happens inside this one
 * function, not any of its call sites.
 *
 * Real visa rules also depend on trip length and purpose in ways this
 * dataset can't capture (e.g. "visa-free for 90 days, required beyond
 * that") — visaFreeDays surfaces the day cap where the data has one, but
 * there's no attempt here to compare it against an actual planned trip.
 *
 * Returns null when either country isn't one this app recognizes (see
 * lib/countries.ts) or the dataset simply has no row for that exact pair.
 */
export async function visaRequirementFor(
  citizenshipCountry: string,
  destinationCountry: string
): Promise<VisaRequirementResult | null> {
  const fromCode = flagCodeForCountry(citizenshipCountry)?.split('-')[0];
  const toCode = flagCodeForCountry(destinationCountry)?.split('-')[0];
  if (!fromCode || !toCode || fromCode === toCode) return null;
  const code = VISA_REQUIREMENTS[fromCode]?.[toCode];
  if (!code) return null;
  return decode(code);
}
