import { countDistinctDaysInWindow } from '@/lib/days';
import { toDateOnlyString } from '@/lib/format';
import type { CountryVisitedRow } from '@/types/database';

/**
 * The Schengen Area's 90/180 rule applies as ONE pooled limit across every
 * member state combined, not per country — a trip split 40 days in France
 * and 40 in Germany uses 80 of the 90, even though neither country alone
 * looks close. That's a fundamentally different shape from
 * lib/residencyRules.ts's per-country tests, so it isn't modeled there.
 *
 * Names match lib/countries.ts's exact strings (free-text convention also
 * used in countries_visited.country). Cyprus and Ireland are EU members but
 * NOT in Schengen; the UK, Switzerland's non-EU neighbors aside, is not
 * either. Source: https://schengendoc.com/blog/which-countries-are-in-the-schengen-area
 * (29 members as of 2026 — Bulgaria and Romania completed accession,
 * including land borders, 1 January 2025).
 */
export const SCHENGEN_COUNTRIES: readonly string[] = [
  'Austria',
  'Belgium',
  'Bulgaria',
  'Croatia',
  'Czech Republic',
  'Denmark',
  'Estonia',
  'Finland',
  'France',
  'Germany',
  'Greece',
  'Hungary',
  'Iceland',
  'Italy',
  'Latvia',
  'Liechtenstein',
  'Lithuania',
  'Luxembourg',
  'Malta',
  'Netherlands',
  'Norway',
  'Poland',
  'Portugal',
  'Romania',
  'Slovakia',
  'Slovenia',
  'Spain',
  'Sweden',
  'Switzerland',
];

const SCHENGEN_SET = new Set(SCHENGEN_COUNTRIES);

export function isSchengenCountry(country: string): boolean {
  return SCHENGEN_SET.has(country);
}

/**
 * The 90/180 rule only restricts visa-exempt THIRD-COUNTRY nationals —
 * someone with EU/EEA/Swiss free-movement rights isn't a short-stay
 * visitor there at all, so it never applies to them in the first place.
 * SCHENGEN_COUNTRIES already covers every Schengen member's own
 * citizenship (including the non-EU EEA/EFTA ones with the same
 * free-movement rights by treaty: Iceland, Liechtenstein, Norway,
 * Switzerland); the only additions needed are Cyprus and Ireland — EU
 * members with the same rights, but not themselves in Schengen. A citizen
 * of any of these doesn't get a muted version of the tracker — the rule
 * isn't theirs to track at all.
 */
export const SCHENGEN_EXEMPT_CITIZENSHIPS: readonly string[] = [
  ...SCHENGEN_COUNTRIES,
  'Cyprus',
  'Ireland',
];

const SCHENGEN_EXEMPT_SET = new Set(SCHENGEN_EXEMPT_CITIZENSHIPS);

/** True if ANY of the given citizenships grants EU/EEA/Swiss free-movement rights, exempting the 90/180 rule entirely. */
export function isExemptFromSchengenRule(citizenshipCountries: string[]): boolean {
  return citizenshipCountries.some((c) => SCHENGEN_EXEMPT_SET.has(c));
}

export const SCHENGEN_WINDOW_DAYS = 180;
export const SCHENGEN_LIMIT_DAYS = 90;
/** Flag once this many of the 90 are used — a 10-day heads-up, same spirit as the fixed windows in lib/notices.ts (RENEWAL_NOTICE_WINDOW_DAYS et al). */
export const SCHENGEN_WARNING_THRESHOLD_DAYS = 80;

export type SchengenStatus = {
  /** Distinct days spent in any Schengen member country within the rolling 180-day window ending today. */
  daysUsed: number;
  daysRemaining: number;
  /** True at or past the 90-day limit itself. */
  overLimit: boolean;
  /** True from SCHENGEN_WARNING_THRESHOLD_DAYS up to (not including) the limit — overLimit implies this is no longer the relevant state, the UI should show the over-limit treatment instead. */
  nearLimit: boolean;
  /** The earliest date on/after which the oldest day currently inside the window rolls out of it — i.e. the next date daysUsed can only go down, never up, on its own. Null when daysUsed is 0 (nothing to roll off). */
  nextDayFreesUp: string | null;
};

/**
 * Current Schengen 90/180 status, pooled across every member country at
 * once. `visits` should be the user's full countries_visited rows — this
 * filters to Schengen members itself, so callers don't need to pre-filter
 * (and can't accidentally forget to).
 */
export function schengenStatus(visits: Pick<CountryVisitedRow, 'country' | 'entry_date' | 'exit_date'>[], today: Date = new Date()): SchengenStatus {
  const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const schengenVisits = visits.filter((v) => isSchengenCountry(v.country));
  const windowStart = new Date(todayOnly);
  windowStart.setDate(windowStart.getDate() - (SCHENGEN_WINDOW_DAYS - 1));

  const { count: daysUsed, days } = countDistinctDaysInWindow(schengenVisits, windowStart, todayOnly, todayOnly);

  const overLimit = daysUsed >= SCHENGEN_LIMIT_DAYS;
  const nearLimit = !overLimit && daysUsed >= SCHENGEN_WARNING_THRESHOLD_DAYS;

  // The window itself slides forward one day at a time, so the single
  // oldest day currently counted is the first to age out — once it does,
  // daysUsed can only have gone down by (at least) one, never up, unless a
  // new day inside the new window gets logged in the meantime. That oldest
  // day plus SCHENGEN_WINDOW_DAYS is the first date it's no longer inside
  // any 180-day window ending on or after today. Set entries are
  // toDateOnlyString's zero-padded YYYY-MM-DD, so a plain lexicographic
  // sort is also a chronological one.
  let nextDayFreesUp: string | null = null;
  if (days.size > 0) {
    const oldest = Array.from(days).sort()[0];
    const [y, m, d] = oldest.split('-').map(Number);
    const freeDate = new Date(y, m - 1, d);
    freeDate.setDate(freeDate.getDate() + SCHENGEN_WINDOW_DAYS);
    nextDayFreesUp = toDateOnlyString(freeDate);
  }

  return {
    daysUsed,
    daysRemaining: Math.max(0, SCHENGEN_LIMIT_DAYS - daysUsed),
    overLimit,
    nearLimit,
    nextDayFreesUp,
  };
}
