import { useLocalSearchParams, useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, Switch, TextInput } from 'react-native';

import { OwnershipPicker } from '@/components/ownership-picker';
import { SelectModal, type SelectOption } from '@/components/select-modal';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useCurrency } from '@/contexts/currency-context';
import { useScope } from '@/contexts/scope-context';
import { showAlert } from '@/lib/alert';
import { supabase } from '@/lib/supabase';
import type { AccountRow } from '@/types/database';

const ACCENT = ModuleAccents.accounts;

const ACCOUNT_TYPES: { value: AccountRow['account_type']; label: string }[] = [
  { value: 'asset', label: 'Asset' },
  { value: 'liability', label: 'Liability' },
];

const TRACKING_METHODS: { value: AccountRow['tracking_method']; label: string }[] = [
  { value: 'transaction_based', label: 'Transaction-based' },
  { value: 'balance_based', label: 'Balance-based' },
];

const ASSET_CATEGORIES: { value: AccountRow['asset_category']; label: string }[] = [
  { value: 'cash', label: 'Cash' },
  { value: 'investment', label: 'Investment' },
  { value: 'real_estate', label: 'Real Estate' },
];

export default function AccountFormScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const isNew = id === 'new';
  const router = useRouter();
  const { session } = useAuth();
  const { refresh: refreshScope } = useScope();
  const { availableCurrencies, currencyNames } = useCurrency();

  const [isLoading, setIsLoading] = useState(!isNew);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [name, setName] = useState('');
  const [institution, setInstitution] = useState('');
  const [currency, setCurrency] = useState('USD');
  const [showCurrencyPicker, setShowCurrencyPicker] = useState(false);
  const [accountType, setAccountType] = useState<AccountRow['account_type']>('asset');
  const [trackingMethod, setTrackingMethod] = useState<AccountRow['tracking_method']>('transaction_based');
  const [assetCategory, setAssetCategory] = useState<AccountRow['asset_category']>('cash');
  const [ownership, setOwnership] = useState<AccountRow['ownership']>('personal');
  const [isActive, setIsActive] = useState(true);
  const [excludedFromCountryTracking, setExcludedFromCountryTracking] = useState(false);
  const [interestRate, setInterestRate] = useState('');

  useEffect(() => {
    if (isNew) return;

    let cancelled = false;
    supabase
      .from('accounts')
      .select('*')
      .eq('id', id)
      .single()
      .then(({ data, error: fetchError }) => {
        if (cancelled) return;
        if (fetchError) {
          setError(fetchError.message);
        } else if (data) {
          setName(data.name);
          setInstitution(data.institution ?? '');
          setCurrency(data.currency);
          setAccountType(data.account_type);
          setTrackingMethod(data.tracking_method);
          setAssetCategory(data.asset_category);
          setOwnership(data.ownership);
          setIsActive(data.is_active);
          setExcludedFromCountryTracking(data.excluded_from_country_tracking);
          setInterestRate(data.interest_rate != null ? String(data.interest_rate) : '');
        }
        setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [id, isNew]);

  async function handleSave() {
    if (!name.trim()) {
      setError('Account name is required.');
      return;
    }
    if (!currency.trim()) {
      setError('Currency is required.');
      return;
    }
    const trimmedRate = interestRate.trim();
    const parsedRate = trimmedRate ? Number(trimmedRate) : null;
    if (trimmedRate && (Number.isNaN(parsedRate) || parsedRate! < 0)) {
      setError('Interest rate must be a positive number.');
      return;
    }
    if (!session) {
      setError('You must be signed in.');
      return;
    }

    setError(null);
    setIsSaving(true);

    const payload = {
      name: name.trim(),
      institution: institution.trim() || null,
      currency: currency.trim().toUpperCase(),
      account_type: accountType,
      tracking_method: trackingMethod,
      asset_category: assetCategory,
      ownership,
      is_active: isActive,
      excluded_from_country_tracking: excludedFromCountryTracking,
      interest_rate: accountType === 'asset' && assetCategory === 'cash' ? parsedRate : null,
    };

    const { error: saveError } = isNew
      ? await supabase.from('accounts').insert({ ...payload, user_id: session.user.id })
      : await supabase.from('accounts').update(payload).eq('id', id);

    setIsSaving(false);

    if (saveError) {
      setError(saveError.message);
      return;
    }

    // The scope switch's ownership map is refreshed on demand, not
    // subscribed — this is the moment a tag can change.
    refreshScope();
    router.back();
  }

  function handleDelete() {
    showAlert('Delete account', 'This will also delete its transactions and balance history. This cannot be undone.', [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Delete',
        style: 'destructive',
        onPress: async () => {
          setIsSaving(true);
          const { error: deleteError } = await supabase.from('accounts').delete().eq('id', id);
          setIsSaving(false);
          if (deleteError) {
            setError(deleteError.message);
            return;
          }
          router.back();
        },
      },
    ]);
  }

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  // Falls back to the bare code if the name hasn't been populated yet, same as components/top-bar.tsx's own currency picker.
  function currencyLabel(code: string): string {
    const currencyName = currencyNames[code];
    return currencyName ? `${currencyName} (${code})` : code;
  }
  const currencyOptions: SelectOption[] = availableCurrencies.map((code) => ({
    value: code,
    label: currencyLabel(code),
  }));

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            {isNew ? 'Add Account' : 'Edit Account'}
          </ThemedText>
          {!isNew ? (
            <Pressable onPress={handleDelete} hitSlop={12}>
              <IconSymbol name="trash" size={22} color={Colors.light.negative} />
            </Pressable>
          ) : null}
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedText type="defaultSemiBold">Name</ThemedText>
        <TextInput
          value={name}
          onChangeText={setName}
          placeholder="e.g. Main Checking"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <ThemedText type="defaultSemiBold">Institution (optional)</ThemedText>
        <TextInput
          value={institution}
          onChangeText={setInstitution}
          placeholder="e.g. Chase"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <ThemedText type="defaultSemiBold">Currency</ThemedText>
        <Pressable onPress={() => setShowCurrencyPicker(true)} style={[styles.input, { borderColor: ACCENT }]}>
          <ThemedText>{currency ? currencyLabel(currency) : 'Select a currency'}</ThemedText>
        </Pressable>
        <SelectModal
          visible={showCurrencyPicker}
          onClose={() => setShowCurrencyPicker(false)}
          options={currencyOptions}
          selectedValue={currency || null}
          onSelect={(value) => {
            setCurrency(value);
            setShowCurrencyPicker(false);
          }}
        />

        <ThemedText type="defaultSemiBold">Type</ThemedText>
        <ThemedView style={styles.chipRow}>
          {ACCOUNT_TYPES.map((option) => {
            const isSelected = option.value === accountType;
            return (
              <Pressable
                key={option.value}
                onPress={() => setAccountType(option.value)}
                style={[
                  styles.chip,
                  { borderColor: ACCENT, backgroundColor: isSelected ? ACCENT : 'transparent' },
                ]}>
                <ThemedText style={isSelected ? { color: ModuleAccentOnColor.accounts } : undefined}>
                  {option.label}
                </ThemedText>
              </Pressable>
            );
          })}
        </ThemedView>

        {accountType === 'asset' ? (
          <>
            <ThemedText type="defaultSemiBold" style={styles.fieldSpacing}>
              Category
            </ThemedText>
            <ThemedText style={styles.hint}>
              Drives the home screen&apos;s Cash vs Investments tiles (Real Estate counts toward Investments). Real
              Estate is also excluded from FBAR/T1135/UK foreign-balance tracking, since directly-held property
              isn&apos;t a reportable financial account.
            </ThemedText>
            <ThemedView style={styles.chipRow}>
              {ASSET_CATEGORIES.map((option) => {
                const isSelected = option.value === assetCategory;
                return (
                  <Pressable
                    key={option.value}
                    onPress={() => setAssetCategory(option.value)}
                    style={[
                      styles.chip,
                      { borderColor: ACCENT, backgroundColor: isSelected ? ACCENT : 'transparent' },
                    ]}>
                    <ThemedText style={isSelected ? { color: ModuleAccentOnColor.accounts } : undefined}>
                      {option.label}
                    </ThemedText>
                  </Pressable>
                );
              })}
            </ThemedView>

            {assetCategory === 'cash' ? (
              <>
                <ThemedText type="defaultSemiBold" style={styles.fieldSpacing}>
                  Interest rate (APY, optional)
                </ThemedText>
                <ThemedText style={styles.hint}>
                  Used only by the &quot;pay bills from&quot; float recommendation, to weigh which cash account is
                  most valuable to leave untouched.
                </ThemedText>
                <TextInput
                  value={interestRate}
                  onChangeText={setInterestRate}
                  placeholder="e.g. 4.5"
                  keyboardType="decimal-pad"
                  placeholderTextColor={Colors.light.textMuted}
                  style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
                />
              </>
            ) : null}

            <ThemedView style={[styles.row, styles.fieldSpacing]}>
              <ThemedView style={styles.toggleLabelColumn}>
                <ThemedText type="defaultSemiBold">Exclude from country spend tracking</ThemedText>
                <ThemedText style={styles.hint}>
                  This account&apos;s transactions always attribute to your home country instead of wherever you
                  were traveling. Useful for an account like an investment, where a trade made abroad shouldn&apos;t
                  read as spend in that country. Doesn&apos;t affect FBAR/T1135/UK overseas-asset tracking.
                </ThemedText>
              </ThemedView>
              <Switch
                value={excludedFromCountryTracking}
                onValueChange={setExcludedFromCountryTracking}
                trackColor={{ true: ACCENT }}
              />
            </ThemedView>
          </>
        ) : (
          <ThemedView style={[styles.row, styles.fieldSpacing]}>
            <ThemedView style={styles.toggleLabelColumn}>
              <ThemedText type="defaultSemiBold">Secured against real estate</ThemedText>
              <ThemedText style={styles.hint}>E.g. a mortgage. Not used in any calculation yet.</ThemedText>
            </ThemedView>
            <Switch
              value={assetCategory === 'real_estate'}
              onValueChange={(value) => setAssetCategory(value ? 'real_estate' : 'cash')}
              trackColor={{ true: ACCENT }}
            />
          </ThemedView>
        )}

        <ThemedText type="defaultSemiBold" style={styles.fieldSpacing}>
          Tracking method
        </ThemedText>
        <ThemedView style={styles.chipRow}>
          {TRACKING_METHODS.map((option) => {
            const isSelected = option.value === trackingMethod;
            return (
              <Pressable
                key={option.value}
                onPress={() => setTrackingMethod(option.value)}
                style={[
                  styles.chip,
                  { borderColor: ACCENT, backgroundColor: isSelected ? ACCENT : 'transparent' },
                ]}>
                <ThemedText style={isSelected ? { color: ModuleAccentOnColor.accounts } : undefined}>
                  {option.label}
                </ThemedText>
              </Pressable>
            );
          })}
        </ThemedView>

        <OwnershipPicker value={ownership} onChange={setOwnership} accent={ACCENT} onColor={ModuleAccentOnColor.accounts} />

        <ThemedView style={[styles.row, styles.fieldSpacing]}>
          <ThemedText type="defaultSemiBold">Active</ThemedText>
          <Switch value={isActive} onValueChange={setIsActive} trackColor={{ true: ACCENT }} />
        </ThemedView>

        <Pressable onPress={handleSave} disabled={isSaving} style={[styles.button, { backgroundColor: ACCENT }]}>
          {isSaving ? (
            <ActivityIndicator color={ModuleAccentOnColor.accounts} />
          ) : (
            <ThemedText style={{ color: ModuleAccentOnColor.accounts, fontWeight: '600' }}>Save</ThemedText>
          )}
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  centered: { alignItems: 'center', justifyContent: 'center' },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  chipRow: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
    marginBottom: 8,
  },
  chip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 16,
    paddingHorizontal: 12,
    paddingVertical: 8,
  },
  fieldSpacing: {
    marginTop: 8,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 4,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  toggleLabelColumn: {
    flex: 1,
    gap: 2,
    marginRight: 12,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  error: {
    color: Colors.light.negative,
  },
});
