import type { AccountRow } from '@/types/database';

export type CurrencyExposureEntry = {
  currency: string;
  /** Sum of native-currency balances — accounts contribute positively, card debt (a liability) contributes negatively. Never converted; this is the actual amount held/owed in that currency. */
  nativeAmount: number;
  /** nativeAmount converted to the reference currency, used only to compute percentage share — never displayed directly. */
  referenceAmount: number;
  /** Share of total net worth (converted to the reference currency) held in this currency, 0-100. */
  percentage: number;
};

/**
 * Groups accounts' raw balances (already in each account's own currency,
 * same as app/accounts/index.tsx computes) and cards' raw per-currency debt
 * totals by currency, then converts only the per-currency subtotal (not
 * each individual balance) to `referenceCurrency` to compute percentage
 * share of total net worth. Reuses summarizeCardBalances for the per-card
 * grouping — pass an identity convert function there (not the real one) so
 * it returns native, unconverted per-currency totals rather than collapsing
 * everything into one currency.
 *
 * Same sign convention as lib/wealthSeries.ts's net worth calculation:
 * a liability's stored balance is always a positive magnitude ("amount
 * owed"), so it must be SUBTRACTED here, not added — this previously just
 * summed every account's raw balance regardless of asset/liability type,
 * which double-counted debt as a positive holding instead of netting it
 * out (assets - liabilities), same bug class the wealth chart already
 * solved via netWorthSign.
 */
export function computeCurrencyExposure(
  accounts: Pick<AccountRow, 'id' | 'currency' | 'account_type'>[],
  accountBalances: Map<string, number>,
  cardDebtByCurrency: { currency: string; amount: number }[],
  convertToReference: (amount: number, fromCurrency: string) => number
): CurrencyExposureEntry[] {
  const nativeByCurrency = new Map<string, number>();

  for (const account of accounts) {
    const balance = accountBalances.get(account.id) ?? 0;
    const signed = account.account_type === 'liability' ? -balance : balance;
    nativeByCurrency.set(account.currency, (nativeByCurrency.get(account.currency) ?? 0) + signed);
  }

  for (const debt of cardDebtByCurrency) {
    nativeByCurrency.set(debt.currency, (nativeByCurrency.get(debt.currency) ?? 0) - debt.amount);
  }

  const withReference = Array.from(nativeByCurrency.entries()).map(([currency, nativeAmount]) => ({
    currency,
    nativeAmount,
    referenceAmount: convertToReference(nativeAmount, currency),
  }));

  const total = withReference.reduce((sum, e) => sum + e.referenceAmount, 0);

  return withReference
    .map((e) => ({ ...e, percentage: total !== 0 ? (e.referenceAmount / total) * 100 : 0 }))
    .sort((a, b) => Math.abs(b.referenceAmount) - Math.abs(a.referenceAmount));
}
