import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useMemo, useState } from 'react';
import { Pressable, ScrollView, StyleSheet } from 'react-native';

import { CountryFlag } from '@/components/country-flag';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { ca4Status, CA4_COUNTRIES, CA4_LIMIT_DAYS } from '@/lib/ca4';
import { supabase } from '@/lib/supabase';
import type { CountryVisitedRow } from '@/types/database';

const ACCENT = ModuleAccents.countries;

export default function Ca4Screen() {
  const router = useRouter();
  const { hiddenFlagCountries } = useCurrency();
  const [visits, setVisits] = useState<CountryVisitedRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const loadVisits = useCallback(async () => {
    setIsLoading(true);
    const { data } = await supabase.from('countries_visited').select('*');
    setVisits(data ?? []);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      loadVisits();
    }, [loadVisits])
  );

  const today = useMemo(() => new Date(), []);
  const status = useMemo(() => ca4Status(visits, today), [visits, today]);

  const progressFraction = status.isCurrentlyInZone ? Math.min(1, status.daysUsed / CA4_LIMIT_DAYS) : 0;
  const statusColor = status.overLimit ? Colors.light.negative : status.nearLimit ? '#B8860B' : ACCENT;

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            CA-4 Tracker
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText style={styles.hint}>
          The CA-4 Border Control Agreement — Guatemala, El Salvador, Honduras, and Nicaragua — treats visa-exempt
          visitors as one combined territory: up to {CA4_LIMIT_DAYS} continuous days across all four, crossing
          between them doesn&apos;t restart the count. Unlike Schengen, there&apos;s no rolling look-back — leaving
          the zone entirely normally resets it on your next entry. Informational only, not visa advice.
        </ThemedText>

        {isLoading ? null : !status.isCurrentlyInZone ? (
          <Surface accentColor={ACCENT} style={styles.statCard}>
            <ThemedText style={styles.statusMessage}>
              Not currently in the CA-4 zone — nothing logged for today in Guatemala, El Salvador, Honduras, or
              Nicaragua. The 90-day count starts fresh from your next entry.
            </ThemedText>
          </Surface>
        ) : (
          <Surface accentColor={statusColor} style={styles.statCard}>
            <ThemedText type="mono" style={[styles.bigNumber, { color: statusColor }]}>
              {status.daysUsed} / {CA4_LIMIT_DAYS}
            </ThemedText>
            <ThemedText style={styles.muted}>continuous days in the zone, this stay</ThemedText>

            <ThemedView style={styles.progressTrack}>
              <ThemedView style={[styles.progressFill, { width: `${progressFraction * 100}%`, backgroundColor: statusColor }]} />
            </ThemedView>

            {status.overLimit ? (
              <ThemedText style={[styles.statusMessage, { color: Colors.light.negative }]}>
                Over the 90-day limit. Leaving the CA-4 zone resets the count on your next entry.
              </ThemedText>
            ) : status.nearLimit ? (
              <ThemedText style={[styles.statusMessage, { color: '#B8860B' }]}>
                Getting close — {status.daysRemaining} day{status.daysRemaining === 1 ? '' : 's'} left before hitting the
                limit.
              </ThemedText>
            ) : (
              <ThemedText style={styles.statusMessage}>{status.daysRemaining} days remaining before the limit.</ThemedText>
            )}
          </Surface>
        )}

        <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
          Member countries
        </ThemedText>
        {CA4_COUNTRIES.map((country) => (
          <ThemedView key={country} style={styles.countryRow}>
            <CountryFlag countryName={country} hiddenFlagCountries={hiddenFlagCountries} size={22} />
            <ThemedText style={styles.countryName}>{country}</ThemedText>
          </ThemedView>
        ))}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  hint: {
    fontSize: 13,
    opacity: 0.7,
    marginBottom: 8,
  },
  muted: {
    fontSize: 13,
    opacity: 0.7,
  },
  statCard: {
    alignItems: 'center',
    gap: 6,
    paddingVertical: 20,
  },
  bigNumber: {
    fontSize: 36,
    fontWeight: '700',
  },
  progressTrack: {
    width: '100%',
    height: 8,
    borderRadius: 4,
    backgroundColor: Colors.light.cardBorder,
    overflow: 'hidden',
    marginTop: 8,
  },
  progressFill: {
    height: '100%',
    borderRadius: 4,
  },
  statusMessage: {
    marginTop: 6,
    textAlign: 'center',
    fontSize: 14,
  },
  sectionSpacing: {
    marginTop: 12,
  },
  countryRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
    paddingVertical: 6,
  },
  countryName: {
    flex: 1,
  },
});
