import { useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput } from 'react-native';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useCurrency } from '@/contexts/currency-context';

const TINT = Colors.light.tint;

export default function AccountDetailsScreen() {
  const router = useRouter();
  const { session } = useAuth();
  const { fullName: savedFullName, setFullName: saveFullName, settingsError } = useCurrency();

  const [fullName, setFullName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    setFullName(savedFullName ?? '');
  }, [savedFullName]);

  async function handleSaveName() {
    setSuccess(false);
    setIsSaving(true);
    await saveFullName(fullName.trim() || null);
    setIsSaving(false);
    setSuccess(true);
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: TINT }}>
            Account Details
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {settingsError ? <ThemedText style={styles.error}>{settingsError}</ThemedText> : null}
        {success ? <ThemedText style={styles.success}>Saved.</ThemedText> : null}

        <ThemedText type="defaultSemiBold">Name</ThemedText>
        <TextInput
          value={fullName}
          onChangeText={setFullName}
          placeholder="Your name"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: TINT }]}
        />
        <Pressable onPress={handleSaveName} disabled={isSaving} style={[styles.button, { backgroundColor: TINT }]}>
          {isSaving ? (
            <ActivityIndicator color={Colors.light.backgroundSolid} />
          ) : (
            <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Save name</ThemedText>
          )}
        </Pressable>

        <ThemedText type="defaultSemiBold" style={styles.fieldSpacing}>
          Email
        </ThemedText>
        <Pressable onPress={() => router.push('/account/email')}>
          <Surface accentColor={TINT} style={styles.row}>
            <ThemedView>
              <ThemedText type="mono">{session?.user.email}</ThemedText>
              <ThemedText style={styles.hint}>Tap to change</ThemedText>
            </ThemedView>
            <IconSymbol name="chevron.right" size={18} color={TINT} />
          </Surface>
        </Pressable>

        <ThemedText type="defaultSemiBold" style={styles.fieldSpacing}>
          Password
        </ThemedText>
        <Pressable onPress={() => router.push('/account/password')}>
          <Surface accentColor={TINT} style={styles.row}>
            <ThemedText>Change password</ThemedText>
            <IconSymbol name="chevron.right" size={18} color={TINT} />
          </Surface>
        </Pressable>

        <ThemedText type="defaultSemiBold" style={styles.fieldSpacing}>
          Security
        </ThemedText>
        <Pressable onPress={() => router.push('/account/mfa')}>
          <Surface accentColor={TINT} style={styles.row}>
            <ThemedText>Two-factor authentication</ThemedText>
            <IconSymbol name="chevron.right" size={18} color={TINT} />
          </Surface>
        </Pressable>

        <ThemedText type="defaultSemiBold" style={styles.fieldSpacing}>
          Address
        </ThemedText>
        <Pressable onPress={() => router.push('/account/address')}>
          <Surface accentColor={TINT} style={styles.row}>
            <ThemedText>Edit address</ThemedText>
            <IconSymbol name="chevron.right" size={18} color={TINT} />
          </Surface>
        </Pressable>

        <ThemedText type="defaultSemiBold" style={styles.fieldSpacing}>
          Prior residencies
        </ThemedText>
        <Pressable onPress={() => router.push('/account/prior-residencies')}>
          <Surface accentColor={TINT} style={styles.row}>
            <ThemedText>Countries you used to live in</ThemedText>
            <IconSymbol name="chevron.right" size={18} color={TINT} />
          </Surface>
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  fieldSpacing: {
    marginTop: 16,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
  success: {
    color: Colors.light.positive,
  },
});
