import { useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput } from 'react-native';

import { CountryAutocompleteInput } from '@/components/country-autocomplete-input';
import { SelectModal, type SelectOption } from '@/components/select-modal';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { LOCAL_CURRENCY, useCurrency } from '@/contexts/currency-context';
import { supabase } from '@/lib/supabase';
import type { CategoryRow } from '@/types/database';

const ACCENT = ModuleAccents.spend;

type Scope = 'category' | 'country';

export default function NewBudgetScreen() {
  const router = useRouter();
  const { displayCurrency, hiddenFlagCountries, availableCurrencies, currencyNames } = useCurrency();

  const [scope, setScope] = useState<Scope>('category');
  const [categories, setCategories] = useState<CategoryRow[]>([]);
  const [categoryId, setCategoryId] = useState<string | null>(null);
  const [country, setCountry] = useState('');
  const [showPicker, setShowPicker] = useState(false);
  const [showCurrencyPicker, setShowCurrencyPicker] = useState(false);
  const [amount, setAmount] = useState('');
  const [currency, setCurrency] = useState(displayCurrency === LOCAL_CURRENCY ? 'USD' : displayCurrency);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    supabase
      .from('categories')
      .select('*')
      .eq('is_hidden', false)
      .order('name')
      .then(({ data }) => setCategories(data ?? []));
  }, []);

  const categoryOptions = categories.map((c) => ({ value: c.id, label: c.name }));
  const selectedValue = scope === 'category' ? categoryId : country;

  async function handleSave() {
    const parsedAmount = Number(amount);
    if (!amount.trim() || Number.isNaN(parsedAmount) || parsedAmount <= 0) {
      setError('Enter a valid amount.');
      return;
    }
    if (!selectedValue) {
      setError(scope === 'category' ? 'Choose a category.' : 'Choose a country.');
      return;
    }
    if (!currency.trim()) {
      setError('Enter a currency.');
      return;
    }

    setError(null);
    setIsSaving(true);

    const { data: userData } = await supabase.auth.getUser();
    const userId = userData.user?.id;
    if (!userId) {
      setError('Not signed in.');
      setIsSaving(false);
      return;
    }

    const { error: saveError } = await supabase.from('budgets').insert({
      user_id: userId,
      category_id: scope === 'category' ? categoryId : null,
      country: scope === 'country' ? country.trim() || null : null,
      amount: parsedAmount,
      currency: currency.trim().toUpperCase(),
    });

    setIsSaving(false);

    if (saveError) {
      // A duplicate scope (already have a budget for this exact category/country)
      // hits the partial unique index — surfaced as-is rather than a generic message,
      // since the fix (edit the existing one instead) is specific to this case.
      setError(saveError.message);
      return;
    }

    router.back();
  }

  // Falls back to the bare code if the name hasn't been populated yet, same as components/top-bar.tsx's own currency picker.
  function currencyLabel(code: string): string {
    const currencyName = currencyNames[code];
    return currencyName ? `${currencyName} (${code})` : code;
  }
  const currencyOptions: SelectOption[] = availableCurrencies.map((code) => ({
    value: code,
    label: currencyLabel(code),
  }));

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedText type="title" style={{ color: ACCENT }}>
          New Budget
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedText type="defaultSemiBold">Scope</ThemedText>
        <ThemedView style={styles.chipRow}>
          {(['category', 'country'] as Scope[]).map((option) => {
            const isSelected = option === scope;
            return (
              <Pressable
                key={option}
                onPress={() => {
                  setScope(option);
                  setCategoryId(null);
                  setCountry('');
                }}
                style={[styles.chip, { borderColor: ACCENT, backgroundColor: isSelected ? ACCENT : 'transparent' }]}>
                <ThemedText style={isSelected ? { color: ModuleAccentOnColor.spend } : undefined}>
                  {option === 'category' ? 'Category' : 'Country'}
                </ThemedText>
              </Pressable>
            );
          })}
        </ThemedView>

        <ThemedText type="defaultSemiBold">{scope === 'category' ? 'Category' : 'Country'}</ThemedText>
        {scope === 'category' ? (
          <>
            <Pressable onPress={() => setShowPicker(true)} style={[styles.input, styles.pickerTrigger, { borderColor: ACCENT }]}>
              <ThemedText>{categories.find((c) => c.id === categoryId)?.name ?? 'Choose a category'}</ThemedText>
            </Pressable>
            <SelectModal
              visible={showPicker}
              onClose={() => setShowPicker(false)}
              options={categoryOptions}
              selectedValue={selectedValue}
              onSelect={setCategoryId}
            />
          </>
        ) : (
          <CountryAutocompleteInput
            value={country}
            onChangeText={setCountry}
            onSelectCountry={setCountry}
            hiddenFlagCountries={hiddenFlagCountries}
            accentColor={ACCENT}
          />
        )}

        <ThemedText type="defaultSemiBold">Monthly limit</ThemedText>
        <TextInput
          value={amount}
          onChangeText={setAmount}
          placeholder="0.00"
          keyboardType="decimal-pad"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <ThemedText type="defaultSemiBold">Currency</ThemedText>
        <Pressable onPress={() => setShowCurrencyPicker(true)} style={[styles.input, { borderColor: ACCENT }]}>
          <ThemedText>{currency ? currencyLabel(currency) : 'Select a currency'}</ThemedText>
        </Pressable>
        <SelectModal
          visible={showCurrencyPicker}
          onClose={() => setShowCurrencyPicker(false)}
          options={currencyOptions}
          selectedValue={currency || null}
          onSelect={(value) => {
            setCurrency(value);
            setShowCurrencyPicker(false);
          }}
        />

        <Pressable onPress={handleSave} disabled={isSaving} style={[styles.button, { backgroundColor: ACCENT }]}>
          {isSaving ? (
            <ActivityIndicator color={ModuleAccentOnColor.spend} />
          ) : (
            <ThemedText style={{ color: ModuleAccentOnColor.spend, fontWeight: '600' }}>Save</ThemedText>
          )}
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  chipRow: {
    flexDirection: 'row',
    gap: 8,
  },
  chip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 16,
    paddingHorizontal: 16,
    paddingVertical: 8,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  pickerTrigger: {
    justifyContent: 'center',
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  error: {
    color: Colors.light.negative,
  },
});
