// Fallback for using MaterialIcons on Android and web.

import MaterialCommunityIcons from '@expo/vector-icons/MaterialCommunityIcons';
import MaterialIcons from '@expo/vector-icons/MaterialIcons';
import { SymbolWeight, SymbolViewProps } from 'expo-symbols';
import { ComponentProps } from 'react';
import { OpaqueColorValue, type StyleProp, type TextStyle } from 'react-native';

type MaterialIconName = ComponentProps<typeof MaterialIcons>['name'];
type CommunityIconName = ComponentProps<typeof MaterialCommunityIcons>['name'];
// Most icons map to a plain MaterialIcons name; a few (no MaterialIcons
// equivalent, e.g. a literal money bag) map to a MaterialCommunityIcons name instead.
type MappedIcon = MaterialIconName | { family: 'community'; name: CommunityIconName };
type IconMapping = Record<SymbolViewProps['name'], MappedIcon>;
export type IconSymbolName = keyof typeof MAPPING;

/**
 * Add your SF Symbols to Material Icons mappings here.
 * - see Material Icons in the [Icons Directory](https://icons.expo.fyi).
 * - see SF Symbols in the [SF Symbols](https://developer.apple.com/sf-symbols/) app.
 */
const MAPPING = {
  'house.fill': 'home',
  'paperplane.fill': 'send',
  'chevron.left.forwardslash.chevron.right': 'code',
  'chevron.right': 'chevron-right',
  'chevron.left': 'chevron-left',
  'chevron.up': 'keyboard-arrow-up',
  'chevron.down': 'keyboard-arrow-down',
  plus: 'add',
  trash: 'delete',
  creditcard: 'credit-card',
  exclamationmark: 'priority-high',
  'person.crop.circle': 'account-circle',
  'banknote.fill': { family: 'community', name: 'sack' },
  airplane: 'flight',
  cart: 'shopping-cart',
  scalemass: 'balance',
  'chart.line.uptrend.xyaxis': 'trending-up',
  'folder.fill': 'folder',
  'gearshape.fill': 'settings',
  'mappin.and.ellipse': 'place',
  calendar: 'event',
  'checkmark.circle.fill': 'check-circle',
  circle: 'radio-button-unchecked',
  'info.circle': 'info',
  'arrow.up.left.and.arrow.down.right': 'fullscreen',
  'arrow.down.right.and.arrow.up.left': 'fullscreen-exit',
  paperclip: 'attach-file',
  pencil: 'edit',
  magnifyingglass: 'search',
  eye: 'visibility',
  'eye.slash': 'visibility-off',
} as IconMapping;

/**
 * An icon component that uses native SF Symbols on iOS, and Material Icons on Android and web.
 * This ensures a consistent look across platforms, and optimal resource usage.
 * Icon `name`s are based on SF Symbols and require manual mapping to Material Icons.
 */
export function IconSymbol({
  name,
  size = 24,
  color,
  style,
}: {
  name: IconSymbolName;
  size?: number;
  color: string | OpaqueColorValue;
  style?: StyleProp<TextStyle>;
  weight?: SymbolWeight;
}) {
  const mapped = MAPPING[name];
  if (typeof mapped === 'object') {
    return <MaterialCommunityIcons color={color} size={size} name={mapped.name} style={style} />;
  }
  return <MaterialIcons color={color} size={size} name={mapped} style={style} />;
}
