/**
 * Turns the positioned text pdf.js pulls out of a text-based bank/card
 * statement (via the pdf-extract-text Edge Function) into the same
 * `string[][]` rows the CSV importer already works with, so the existing
 * column-mapping → parse → dedup → import flow is reused unchanged. Pure
 * geometry + regex, no network, no AI, no dependencies — this file is
 * deliberately import-free so it can be exercised directly under Node.
 *
 * The core idea: a transaction row is a line that starts with a date and
 * contains at least one money amount. Columns are found by clustering
 * where cells sit horizontally across all such lines — right edges for
 * amounts (banks right-align numbers), left edges for everything else — so
 * Debit / Credit / Balance land in separate cells rather than one mushed
 * string. Lines with no date sitting directly under a transaction are
 * treated as its wrapped description.
 */

export type PdfTextItem = { page: number; x: number; y: number; w: number; h: number; text: string };
export type PdfPage = { width: number; height: number };
export type PdfExtractResult = { items: PdfTextItem[]; pages: PdfPage[] };

export type PdfTableResult = {
  rows: string[][];
  headerRow: string[] | null;
  /** Human-readable notes about what the heuristics had to guess (e.g. an inferred year). */
  notes: string[];
};

type CellKind = 'date' | 'amount' | 'text';
type Cell = { x0: number; x1: number; h: number; text: string; kind: CellKind };
type Line = { page: number; y: number; cells: Cell[] };

const MONTHS: Record<string, number> = {
  jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, sept: 9, oct: 10, nov: 11, dec: 12,
  january: 1, february: 2, march: 3, april: 4, june: 6, july: 7, august: 8, september: 9, october: 10, november: 11, december: 12,
};

const NUMERIC_DATE = /^(\d{1,2})[/.-](\d{1,2})(?:[/.-](\d{2}|\d{4}))?$/;
const ISO_DATE = /^(\d{4})-(\d{1,2})-(\d{1,2})$/;
const DAY_MONTH = /^(\d{1,2})\s+([A-Za-z]{3,9})\.?,?(?:\s+(\d{2}|\d{4}))?$/;
const MONTH_DAY = /^([A-Za-z]{3,9})\.?\s+(\d{1,2}),?(?:\s+(\d{2}|\d{4}))?$/;
// Requires a decimal part so years, account numbers and reference codes never read as money.
const AMOUNT = /^[-−+]?\(?\s*[$€£¥₹]?\s*\d{1,3}(?:[,.\s]\d{3})*[.,]\d{2}\s*\)?\s*(?:CR|DR|Cr|Dr|cr|dr)?\s*[-−]?$/;
const HEADER_WORDS =
  /\b(date|description|details|particulars|narrative|transaction|merchant|payee|amount|debit|credit|withdrawal|deposit|balance|money\s*(in|out)|paid\s*(in|out))\b/i;

function isDateText(text: string): boolean {
  const t = text.trim();
  if (ISO_DATE.test(t)) return true;
  const numeric = t.match(NUMERIC_DATE);
  if (numeric) {
    // "45.99" or "23.40" also fit the DD.MM shape — only accept it as a
    // date if the two parts could actually be a day and a month.
    const a = Number(numeric[1]);
    const b = Number(numeric[2]);
    return a >= 1 && b >= 1 && a <= 31 && b <= 31 && (a <= 12 || b <= 12);
  }
  const dm = t.match(DAY_MONTH);
  if (dm && MONTHS[dm[2].toLowerCase()]) return true;
  const md = t.match(MONTH_DAY);
  if (md && MONTHS[md[1].toLowerCase()]) return true;
  return false;
}

function isAmountText(text: string): boolean {
  return AMOUNT.test(text.trim());
}

/**
 * Position breaks the remaining ambiguity ("4.20" is 4 April in a date
 * column and four pounds twenty in an amount column): statements put their
 * dates in the first column or two, so only there does a date reading win;
 * further right, anything shaped like money is money.
 */
function classifyCell(text: string, indexInLine: number): CellKind {
  const dateLike = isDateText(text);
  if (dateLike && indexInLine <= 1) return 'date';
  if (isAmountText(text)) return 'amount';
  if (dateLike) return 'date';
  return 'text';
}

function median(values: number[]): number {
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

/** Groups text fragments into visual lines (same page, same baseline within tolerance), each sorted left→right. */
function buildLines(items: PdfTextItem[]): Line[] {
  const sorted = [...items].sort((a, b) => a.page - b.page || a.y - b.y || a.x - b.x);
  const lines: Line[] = [];
  for (const item of sorted) {
    const last = lines[lines.length - 1];
    const tolerance = Math.max(2, item.h * 0.5);
    const cell: Cell = { x0: item.x, x1: item.x + item.w, h: item.h, text: item.text, kind: 'text' };
    if (last && last.page === item.page && Math.abs(last.y - item.y) <= tolerance) {
      last.cells.push(cell);
    } else {
      lines.push({ page: item.page, y: item.y, cells: [cell] });
    }
  }
  for (const line of lines) {
    line.cells.sort((a, b) => a.x0 - b.x0);
    line.cells = mergeFragments(line.cells).map((cell, index) => ({ ...cell, kind: classifyCell(cell.text, index) }));
  }
  return lines;
}

/**
 * pdf.js frequently splits one visual run of text into several fragments
 * (per word, per kerning change). Fragments separated by roughly a word
 * space or less belong to the same cell; a clearly larger gap is a column
 * boundary. Threshold scales with font size so it holds for 8pt statements
 * and 12pt ones alike.
 */
function mergeFragments(cells: Cell[]): Cell[] {
  const merged: Cell[] = [];
  for (const cell of cells) {
    const last = merged[merged.length - 1];
    if (!last) {
      merged.push({ ...cell });
      continue;
    }
    const gap = cell.x0 - last.x1;
    const threshold = Math.max(2.5, Math.max(last.h, cell.h) * 0.75);
    if (gap <= threshold) {
      const needsSpace = gap > Math.max(last.h, cell.h) * 0.12 && !/\s$/.test(last.text) && !/^\s/.test(cell.text);
      last.text = `${last.text}${needsSpace ? ' ' : ''}${cell.text}`;
      last.x1 = Math.max(last.x1, cell.x1);
      last.h = Math.max(last.h, cell.h);
    } else {
      merged.push({ ...cell });
    }
  }
  for (const cell of merged) cell.text = cell.text.replace(/\s+/g, ' ').trim();
  return merged.filter((c) => c.text.length > 0);
}

/** A date in the first column or two, plus at least one amount somewhere on the line. */
function isTransactionLine(line: Line): boolean {
  if (line.cells.length < 2) return false;
  if (!line.cells.slice(0, 2).some((c) => c.kind === 'date')) return false;
  return line.cells.some((c) => c.kind === 'amount');
}

/**
 * One-dimensional clustering on a per-cell anchor: right edge for amounts
 * (right-aligned), left edge for dates and text (left-aligned). Two anchors
 * within ~1.5 line-heights belong to the same column.
 */
type Column = { anchors: number[]; x0: number; x1: number };

function anchorOf(cell: Cell): number {
  return cell.kind === 'amount' ? cell.x1 : cell.x0;
}

function clusterColumns(cells: Cell[]): Column[] {
  const columns: Column[] = [];
  const sorted = [...cells].sort((a, b) => anchorOf(a) - anchorOf(b));
  for (const cell of sorted) {
    const anchor = anchorOf(cell);
    const tolerance = Math.max(6, cell.h * 1.5);
    const existing = columns.find((col) => Math.abs(median(col.anchors) - anchor) <= tolerance);
    if (existing) {
      existing.anchors.push(anchor);
      existing.x0 = Math.min(existing.x0, cell.x0);
      existing.x1 = Math.max(existing.x1, cell.x1);
    } else {
      columns.push({ anchors: [anchor], x0: cell.x0, x1: cell.x1 });
    }
  }
  return columns.sort((a, b) => median(a.anchors) - median(b.anchors));
}

function columnIndexFor(cell: Cell, columns: Column[]): number {
  const anchor = anchorOf(cell);
  let best = 0;
  let bestDistance = Infinity;
  columns.forEach((col, index) => {
    const distance = Math.abs(median(col.anchors) - anchor);
    if (distance < bestDistance) {
      bestDistance = distance;
      best = index;
    }
  });
  return best;
}

/** Best column for a header label: the one whose horizontal span overlaps it most, falling back to nearest anchor. */
function headerColumnIndexFor(cell: Cell, columns: Column[]): number {
  let best = -1;
  let bestOverlap = 0;
  columns.forEach((col, index) => {
    const overlap = Math.min(cell.x1, col.x1) - Math.max(cell.x0, col.x0);
    if (overlap > bestOverlap) {
      bestOverlap = overlap;
      best = index;
    }
  });
  if (best >= 0) return best;
  const center = (cell.x0 + cell.x1) / 2;
  let nearest = 0;
  let nearestDistance = Infinity;
  columns.forEach((col, index) => {
    const distance = Math.abs((col.x0 + col.x1) / 2 - center);
    if (distance < nearestDistance) {
      nearestDistance = distance;
      nearest = index;
    }
  });
  return nearest;
}

/**
 * Which calendar year a date without one belongs to. Statements almost
 * always print the year somewhere (period, closing date, footer); the most
 * common 4-digit year in the document is the answer, except when the
 * document mentions two consecutive years — a statement spanning New Year —
 * where November/December dates take the earlier one.
 */
export function inferYear(allText: string[], month: number): { year: number; inferred: boolean } {
  const counts = new Map<number, number>();
  for (const text of allText) {
    for (const match of text.matchAll(/\b(20\d{2})\b/g)) {
      const year = Number(match[1]);
      counts.set(year, (counts.get(year) ?? 0) + 1);
    }
  }
  if (counts.size === 0) return { year: new Date().getFullYear(), inferred: true };
  const years = [...counts.keys()].sort((a, b) => a - b);
  const latest = years[years.length - 1];
  if (years.includes(latest - 1) && month >= 11) return { year: latest - 1, inferred: true };
  const mode = [...counts.entries()].sort((a, b) => b[1] - a[1] || b[0] - a[0])[0][0];
  return { year: mode, inferred: true };
}

function expandYear(raw: string | undefined, allText: string[], month: number, usedInference: { value: boolean }): number {
  if (raw && raw.length === 4) return Number(raw);
  if (raw && raw.length === 2) return 2000 + Number(raw);
  usedInference.value = true;
  return inferYear(allText, month).year;
}

/**
 * Normalises a date cell to something lib/csvImport.ts's parseDateFlexible
 * accepts: month-name dates become unambiguous ISO; numeric slash dates
 * keep their day/month order (the importer's MDY/DMY toggle decides) but
 * gain a 4-digit year if the statement omitted one.
 */
function normalizeDate(text: string, allText: string[], usedInference: { value: boolean }): string {
  const t = text.trim();
  if (ISO_DATE.test(t)) return t;

  const numeric = t.match(NUMERIC_DATE);
  if (numeric) {
    const [, first, second, rawYear] = numeric;
    // Month for rollover purposes is ambiguous here (could be MDY or DMY);
    // whichever part is ≤ 12 and larger is the safer guess for "is this
    // Nov/Dec" — only matters for statements spanning New Year.
    const a = Number(first);
    const b = Number(second);
    const monthGuess = a > 12 ? b : b > 12 ? a : Math.max(a, b);
    const year = expandYear(rawYear, allText, monthGuess, usedInference);
    return `${first}/${second}/${year}`;
  }

  const dayMonth = t.match(DAY_MONTH);
  if (dayMonth && MONTHS[dayMonth[2].toLowerCase()]) {
    const month = MONTHS[dayMonth[2].toLowerCase()];
    const year = expandYear(dayMonth[3], allText, month, usedInference);
    return `${year}-${String(month).padStart(2, '0')}-${dayMonth[1].padStart(2, '0')}`;
  }

  const monthDay = t.match(MONTH_DAY);
  if (monthDay && MONTHS[monthDay[1].toLowerCase()]) {
    const month = MONTHS[monthDay[1].toLowerCase()];
    const year = expandYear(monthDay[3], allText, month, usedInference);
    return `${year}-${String(month).padStart(2, '0')}-${monthDay[2].padStart(2, '0')}`;
  }

  return t;
}

/**
 * Normalises a money cell to what parseAmount accepts: strips currency
 * symbols, turns a trailing minus / DR marker into a leading minus, drops a
 * CR marker (credit = money in = positive in this app's convention), and
 * converts European "1.234,56" to "1234.56". Parentheses are left alone —
 * parseAmount already reads them as negative.
 */
export function normalizeAmount(text: string): string {
  let t = text.trim().replace(/[$€£¥₹]/g, '').replace(/−/g, '-').replace(/\s+/g, '');
  let negative = false;
  if (/DR$/i.test(t)) {
    negative = true;
    t = t.replace(/DR$/i, '');
  } else if (/CR$/i.test(t)) {
    t = t.replace(/CR$/i, '');
  }
  if (t.endsWith('-')) {
    negative = true;
    t = t.slice(0, -1);
  }
  if (t.startsWith('-')) {
    negative = true;
    t = t.slice(1);
  }
  if (/^\d{1,3}(\.\d{3})+,\d{2}$/.test(t)) {
    t = t.replace(/\./g, '').replace(',', '.');
  } else if (/^\d{1,3}(\s\d{3})+[.,]\d{2}$/.test(t)) {
    t = t.replace(/\s/g, '').replace(',', '.');
  }
  return negative ? `-${t}` : t;
}

/**
 * Some single-column statements mark credits with "CR" and print debits
 * as plain positive numbers. When a column shows that pattern — some CR
 * markers, but never an explicit negative or DR — the unmarked cells are
 * spend and get negated so the sign convention (spend negative, income
 * positive) holds without the user having to think about it.
 */
function applyImpliedDebitSign(rows: string[][], amountColumns: Set<number>, rawByCell: Map<string, string>): string[] {
  const notes: string[] = [];
  for (const col of amountColumns) {
    let hasCr = false;
    let hasExplicitNegative = false;
    for (let r = 0; r < rows.length; r++) {
      const raw = rawByCell.get(`${r}:${col}`);
      if (!raw) continue;
      if (/CR$/i.test(raw.trim())) hasCr = true;
      if (/DR$/i.test(raw.trim()) || /^[-−(]/.test(raw.trim()) || /[-−]$/.test(raw.trim())) hasExplicitNegative = true;
    }
    if (hasCr && !hasExplicitNegative) {
      for (let r = 0; r < rows.length; r++) {
        const raw = rawByCell.get(`${r}:${col}`);
        if (raw && !/CR$/i.test(raw.trim()) && rows[r][col]) rows[r][col] = `-${rows[r][col]}`;
      }
      notes.push('Amounts without a "CR" marker were treated as spending (negative).');
    }
  }
  return notes;
}

export function buildRowsFromPdf(extract: PdfExtractResult): PdfTableResult {
  const notes: string[] = [];
  if (extract.items.length === 0) {
    return { rows: [], headerRow: null, notes: ['No text found in this PDF. Scanned or photographed statements need a text-based export instead.'] };
  }

  const lines = buildLines(extract.items);
  const allText = extract.items.map((i) => i.text);
  const transactionFlags = lines.map(isTransactionLine);
  const transactionLines = lines.filter((_, i) => transactionFlags[i]);
  if (transactionLines.length === 0) {
    return { rows: [], headerRow: null, notes: ["Couldn't find any lines that start with a date and contain an amount."] };
  }

  const columns = clusterColumns(transactionLines.flatMap((l) => l.cells));
  const columnCount = columns.length;
  const amountColumns = new Set<number>();
  const usedInference = { value: false };
  const rawByCell = new Map<string, string>();
  const rows: string[][] = [];
  const continuationLineIndexes = new Set<number>();
  // Which column indexes a given row's description text lives in — where
  // a following no-date line has to sit to count as a wrapped description.
  const descriptionColumnsByRow: Set<number>[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (transactionFlags[i]) {
      const row: string[] = new Array<string>(columnCount).fill('');
      const descriptionColumns = new Set<number>();
      for (const cell of line.cells) {
        const col = columnIndexFor(cell, columns);
        let value = cell.text;
        if (cell.kind === 'date') {
          value = normalizeDate(cell.text, allText, usedInference);
        } else if (cell.kind === 'amount') {
          value = normalizeAmount(cell.text);
          amountColumns.add(col);
          rawByCell.set(`${rows.length}:${col}`, cell.text);
        } else {
          descriptionColumns.add(col);
        }
        row[col] = row[col] ? `${row[col]} ${value}` : value;
      }
      rows.push(row);
      descriptionColumnsByRow.push(descriptionColumns);
      continue;
    }

    // Wrapped description: a no-date, no-amount line directly beneath a
    // transaction on the same page, whose text sits in that transaction's
    // own description column(s). Anything else (headers, footers, totals,
    // "Page 1 of 2") is dropped.
    const previous = rows.length - 1;
    if (previous < 0) continue;
    const previousLineIndex = i - 1;
    if (previousLineIndex < 0 || lines[previousLineIndex].page !== line.page) continue;
    const previousWasRowOrContinuation = transactionFlags[previousLineIndex] || continuationLineIndexes.has(previousLineIndex);
    if (!previousWasRowOrContinuation) continue;
    if (line.cells.some((c) => c.kind !== 'text')) continue;
    if (HEADER_WORDS.test(line.cells.map((c) => c.text).join(' ')) && line.cells.length > 1) continue;
    const targets = line.cells.map((c) => columnIndexFor(c, columns));
    if (!targets.every((col) => descriptionColumnsByRow[previous].has(col))) continue;
    line.cells.forEach((cell, index) => {
      const col = targets[index];
      rows[previous][col] = rows[previous][col] ? `${rows[previous][col]} ${cell.text}` : cell.text;
    });
    continuationLineIndexes.add(i);
  }

  // Header: the nearest line above the first transaction that reads like
  // column titles — its labels are placed by horizontal overlap so the
  // importer's mapping step can pre-select Date/Description/Amount.
  let headerRow: string[] | null = null;
  const firstTransactionIndex = transactionFlags.indexOf(true);
  for (let i = firstTransactionIndex - 1; i >= 0 && i >= firstTransactionIndex - 8; i--) {
    const line = lines[i];
    if (line.page !== lines[firstTransactionIndex].page) break;
    const headerish = line.cells.filter((c) => HEADER_WORDS.test(c.text)).length;
    if (headerish >= 2 || (headerish >= 1 && line.cells.length >= 3)) {
      headerRow = new Array<string>(columnCount).fill('');
      for (const cell of line.cells) {
        const col = headerColumnIndexFor(cell, columns);
        headerRow[col] = headerRow[col] ? `${headerRow[col]} ${cell.text}` : cell.text;
      }
      break;
    }
  }

  notes.push(...applyImpliedDebitSign(rows, amountColumns, rawByCell));
  if (usedInference.value) {
    notes.push('Dates in this statement had no year. The year was taken from the statement period printed on it.');
  }
  return { rows, headerRow, notes };
}
