import { StyleSheet, View, useWindowDimensions } from 'react-native';
import Svg, { Circle } from 'react-native-svg';

import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { formatMoney } from '@/lib/currency';

export type PieSlice = { label: string; amount: number; currency: string };

// A general-purpose categorical palette, cycled if there are more slices
// than colors — not run through the colorblind-adjacency validator given
// the category count here is open-ended and user-defined, unlike the fixed
// 2-3 slice charts elsewhere in the app.
const PALETTE = [
  '#3B6FA0',
  '#C99A3B',
  '#A83A4A',
  '#7A5FA0',
  '#6E7A78',
  '#5AA469',
  '#D9822B',
  '#4A90D9',
  '#B24C9C',
  '#8E6ACF',
];

export function CategoryPieChart({ slices }: { slices: PieSlice[] }) {
  const { width: windowWidth } = useWindowDimensions();
  const total = slices.reduce((sum, s) => sum + s.amount, 0);
  const size = Math.min(windowWidth - 64, 220);
  const center = size / 2;
  const radius = size / 2 - 12;
  const strokeWidth = radius * 0.55;
  const ringRadius = radius - strokeWidth / 2;
  const circumference = 2 * Math.PI * ringRadius;

  if (total <= 0 || slices.length === 0) {
    return <ThemedText style={styles.muted}>No spend to chart yet.</ThemedText>;
  }

  let cumulativeDegrees = 0;

  return (
    <ThemedView style={styles.container}>
      <View style={{ width: size, height: size }}>
        <Svg width={size} height={size}>
          {slices.map((slice, index) => {
            const sliceDegrees = (slice.amount / total) * 360;
            const arcLength = circumference * (sliceDegrees / 360);
            const rotation = cumulativeDegrees - 90;
            cumulativeDegrees += sliceDegrees;
            return (
              <Circle
                key={slice.label}
                cx={center}
                cy={center}
                r={ringRadius}
                fill="transparent"
                stroke={PALETTE[index % PALETTE.length]}
                strokeWidth={strokeWidth}
                strokeDasharray={`${arcLength} ${circumference - arcLength}`}
                rotation={rotation}
                origin={`${center}, ${center}`}
              />
            );
          })}
        </Svg>
      </View>

      <ThemedView style={styles.legend}>
        {slices.map((slice, index) => (
          <ThemedView key={slice.label} style={styles.legendRow}>
            <View style={[styles.swatch, { backgroundColor: PALETTE[index % PALETTE.length] }]} />
            <ThemedText style={styles.legendLabel} numberOfLines={1}>
              {slice.label}: {formatMoney(slice.amount, slice.currency)}
            </ThemedText>
          </ThemedView>
        ))}
      </ThemedView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    gap: 16,
  },
  legend: {
    gap: 8,
    alignSelf: 'stretch',
  },
  legendRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  swatch: {
    width: 14,
    height: 14,
    borderRadius: 7,
  },
  legendLabel: {
    fontSize: 14,
    flexShrink: 1,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
    textAlign: 'center',
  },
});
