import { supabase } from '@/lib/supabase';
import type { ConnectionShareRequestRow, ShareModule, ShareRequestStatus } from '@/types/database';

// 'wishlist' deliberately excluded — unlike every module here, it has no
// request/accept step at all (see app/countries/wishlist/[id].tsx): the
// owner grants visibility to one connection for one city directly via
// wishlist_city_shares, with nothing to toggle on this settings screen.
export const SHARE_MODULES: ShareModule[] = ['countries', 'trips_planned', 'cards', 'accounts', 'documents'];

export const SHARE_MODULE_LABELS: Record<ShareModule, string> = {
  countries: 'Countries visited',
  trips_planned: 'Trips planned',
  cards: 'Credit cards',
  accounts: 'Accounts',
  documents: 'Documents',
  wishlist: 'Wishlist',
};

/** Which shared-view route a module's data lives on — countries and trips_planned are two toggles but one route (travel). */
export const SHARE_MODULE_ROUTE: Record<ShareModule, 'travel' | 'cards' | 'accounts' | 'documents' | 'wishlist'> = {
  countries: 'travel',
  trips_planned: 'travel',
  cards: 'cards',
  accounts: 'accounts',
  documents: 'documents',
  wishlist: 'wishlist',
};

/**
 * Turns sharing on for a module — upserts a request from me to them,
 * always resetting to 'pending' even if one already existed (declined or
 * previously accepted), since re-sharing should always require a fresh
 * accept rather than silently resuming. onConflict on
 * (connection_id, from_user_id, module) is exactly the request's identity,
 * so this is also how an existing request gets re-triggered.
 */
export async function sendShareRequest(
  connectionId: string,
  fromUserId: string,
  toUserId: string,
  module: ShareModule
): Promise<{ error: string | null }> {
  const { error } = await supabase.from('connection_share_requests').upsert(
    { connection_id: connectionId, from_user_id: fromUserId, to_user_id: toUserId, module, status: 'pending' },
    { onConflict: 'connection_id,from_user_id,module' }
  );
  return { error: error?.message ?? null };
}

/** Turns sharing off for a module — fully removes the request/grant, so turning it back on later requires a fresh accept. */
export async function revokeShareRequest(
  connectionId: string,
  fromUserId: string,
  module: ShareModule
): Promise<{ error: string | null }> {
  const { error } = await supabase
    .from('connection_share_requests')
    .delete()
    .eq('connection_id', connectionId)
    .eq('from_user_id', fromUserId)
    .eq('module', module);
  return { error: error?.message ?? null };
}

/**
 * The sharer opting an already-shared module (accounts/cards) into also
 * including the balance figure — updates their existing row in place, no
 * status reset. Only meaningful once that module is actually being shared
 * (the caller should only show this control then); a no-op if no row
 * exists yet for (connection, fromUserId, module).
 */
export async function setShareBalances(
  connectionId: string,
  fromUserId: string,
  module: ShareModule,
  includeBalances: boolean
): Promise<{ error: string | null }> {
  const { error } = await supabase
    .from('connection_share_requests')
    .update({ share_balances: includeBalances })
    .eq('connection_id', connectionId)
    .eq('from_user_id', fromUserId)
    .eq('module', module);
  return { error: error?.message ?? null };
}

/** The recipient accepting or declining a pending share request. */
export async function respondToShareRequest(
  requestId: string,
  status: Extract<ShareRequestStatus, 'accepted' | 'declined'>
): Promise<{ error: string | null }> {
  const { error } = await supabase.from('connection_share_requests').update({ status }).eq('id', requestId);
  return { error: error?.message ?? null };
}

/** Every request tied to a connection, both directions — the settings screen splits this into "what I'm sharing" vs "what they're sharing" itself. */
export async function fetchConnectionShareRequests(
  connectionId: string
): Promise<{ data: ConnectionShareRequestRow[]; error: string | null }> {
  const { data, error } = await supabase.from('connection_share_requests').select('*').eq('connection_id', connectionId);
  return { data: data ?? [], error: error?.message ?? null };
}

export type PendingIncomingShareRequest = ConnectionShareRequestRow & { fromDisplayName: string };
