import { useLocalSearchParams, useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, Switch, TextInput } from 'react-native';

import { CategoryPicker } from '@/components/category-picker';
import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { DateInput } from '@/components/date-input';
import { SelectModal, type SelectOption } from '@/components/select-modal';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { NOT_LINKED_VALUE, TripStopPicker, type TripLinkValue } from '@/components/trip-stop-picker';
import { Colors, Fonts } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { showAlert } from '@/lib/alert';
import { matchCategoryRule } from '@/lib/csvImport';
import { toDateOnlyString } from '@/lib/format';
import { attributedLocationForTransaction, type TripLinkMaps } from '@/lib/spend';
import { supabase } from '@/lib/supabase';
import { computeTripSummaries } from '@/lib/trips';
import type {
  AccountRow,
  CategoryRow,
  CategoryRuleRow,
  CountryVisitedRow,
  CreditCardRow,
  TransactionRow,
  TripRow,
  TripSegmentRow,
} from '@/types/database';

function parseDateOnly(dateString: string): Date {
  const [year, month, day] = dateString.split('-').map(Number);
  return new Date(year, month - 1, day);
}

export default function EditTransactionScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();
  const { availableCurrencies, currencyNames } = useCurrency();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const [transaction, setTransaction] = useState<TransactionRow | null>(null);
  const [account, setAccount] = useState<AccountRow | null>(null);
  const [card, setCard] = useState<CreditCardRow | null>(null);
  const [categories, setCategories] = useState<CategoryRow[]>([]);
  const [categoryRules, setCategoryRules] = useState<CategoryRuleRow[]>([]);
  const [visits, setVisits] = useState<CountryVisitedRow[]>([]);
  const [homeCountry, setHomeCountry] = useState<string | null>(null);
  const [trips, setTrips] = useState<TripRow[]>([]);
  const [tripSegments, setTripSegments] = useState<TripSegmentRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showCategoryPicker, setShowCategoryPicker] = useState(false);
  const [showTripPicker, setShowTripPicker] = useState(false);
  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);

  const [amount, setAmount] = useState('');
  const [currency, setCurrency] = useState('USD');
  const [showCurrencyPicker, setShowCurrencyPicker] = useState(false);
  const [date, setDate] = useState(new Date());
  const [merchant, setMerchant] = useState('');
  const [notes, setNotes] = useState('');
  const [isInternalTransfer, setIsInternalTransfer] = useState(false);

  const [tripLinkValue, setTripLinkValue] = useState<TripLinkValue>(NOT_LINKED_VALUE);

  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    Promise.all([
      supabase.from('transactions').select('*').eq('id', id).single(),
      supabase.from('categories').select('*').eq('is_hidden', false).order('name'),
      supabase.from('category_rules').select('*'),
      supabase.from('countries_visited').select('*'),
      supabase.from('trips').select('*'),
      supabase.from('trip_segments').select('*'),
    ]).then(async ([txResult, categoriesResult, rulesResult, visitsResult, tripsResult, segmentsResult]) => {
      if (cancelled) return;
      if (txResult.error) {
        setError(txResult.error.message);
        setIsLoading(false);
        return;
      }

      const tx = txResult.data;
      setTransaction(tx);
      setAmount(String(tx.amount));
      setCurrency(tx.currency);
      setDate(parseDateOnly(tx.date));
      setMerchant(tx.merchant ?? '');
      setNotes(tx.notes ?? '');
      setIsInternalTransfer(tx.is_internal_transfer);
      setSelectedCategoryId(tx.category_id);
      setCategories(categoriesResult.data ?? []);
      setCategoryRules(rulesResult.data ?? []);
      setVisits(visitsResult.data ?? []);
      setTrips(tripsResult.data ?? []);
      setTripSegments(segmentsResult.data ?? []);
      setTripLinkValue(
        tx.trip_stop_id ? `stop:${tx.trip_stop_id}` : tx.trip_segment_id ? `segment:${tx.trip_segment_id}` : NOT_LINKED_VALUE
      );

      const { data: settingsRow } = await supabase
        .from('user_settings')
        .select('home_country')
        .eq('user_id', tx.user_id)
        .maybeSingle();
      if (!cancelled) setHomeCountry(settingsRow?.home_country ?? null);

      if (tx.account_id) {
        const { data } = await supabase.from('accounts').select('*').eq('id', tx.account_id).maybeSingle();
        if (!cancelled) setAccount(data ?? null);
      }
      if (tx.card_id) {
        const { data } = await supabase.from('credit_cards').select('*').eq('id', tx.card_id).maybeSingle();
        if (!cancelled) setCard(data ?? null);
      }

      setIsLoading(false);
    });

    return () => {
      cancelled = true;
    };
  }, [id]);

  const selectedCategory = categories.find((c) => c.id === selectedCategoryId);

  // Only suggests a category when there isn't one already — editing the
  // merchant on an already-categorized transaction should never silently
  // change its category out from under whoever set it.
  function handleMerchantBlur() {
    if (selectedCategoryId) return;
    const trimmed = merchant.trim();
    if (!trimmed) return;
    const matchedCategoryId = matchCategoryRule(trimmed, categoryRules);
    if (matchedCategoryId) setSelectedCategoryId(matchedCategoryId);
  }

  const parsedStopId = tripLinkValue.startsWith('stop:') ? tripLinkValue.slice(5) : null;
  const parsedSegmentId = tripLinkValue.startsWith('segment:') ? tripLinkValue.slice(8) : null;
  const isLinked = parsedStopId !== null || parsedSegmentId !== null;
  const tripSummaries = computeTripSummaries(trips, visits, tripSegments);
  const links: TripLinkMaps = {
    stopsById: new Map(visits.map((v) => [v.id, { country: v.country, city: v.city }])),
    segmentCountryById: new Map(
      tripSegments.map((s) => [
        s.id,
        tripSummaries.find((t) => t.id === s.trip_id)?.countries[0] ?? homeCountry ?? 'Unknown',
      ])
    ),
  };
  const resolvedLocation = attributedLocationForTransaction(
    { date: toDateOnlyString(date), trip_stop_id: parsedStopId, trip_segment_id: parsedSegmentId },
    visits,
    homeCountry,
    false,
    links
  );
  const linkedTripName = parsedStopId
    ? tripSummaries.find((t) => t.stops.some((s) => s.id === parsedStopId))?.displayName
    : parsedSegmentId
      ? tripSummaries.find((t) => t.id === tripSegments.find((s) => s.id === parsedSegmentId)?.trip_id)?.displayName
      : null;
  const locationLabel = resolvedLocation.city ? `${resolvedLocation.city}, ${resolvedLocation.country}` : resolvedLocation.country;
  const tripFieldLabel = isLinked
    ? `Linked: ${locationLabel}${linkedTripName ? ` (${linkedTripName})` : ''}`
    : `Automatic: ${locationLabel}`;

  async function handleSave() {
    const parsedAmount = Number(amount);
    if (!amount.trim() || Number.isNaN(parsedAmount)) {
      setError('Enter a valid amount.');
      return;
    }
    if (!currency.trim()) {
      setError('Currency is required.');
      return;
    }

    setError(null);
    setIsSaving(true);

    const { error: saveError } = await supabase
      .from('transactions')
      .update({
        date: toDateOnlyString(date),
        amount: parsedAmount,
        currency: currency.trim().toUpperCase(),
        category_id: selectedCategoryId,
        merchant: merchant.trim() || null,
        notes: notes.trim() || null,
        is_internal_transfer: isInternalTransfer,
        trip_stop_id: tripLinkValue.startsWith('stop:') ? tripLinkValue.slice(5) : null,
        trip_segment_id: tripLinkValue.startsWith('segment:') ? tripLinkValue.slice(8) : null,
      })
      .eq('id', id);

    setIsSaving(false);

    if (saveError) {
      setError(saveError.message);
      return;
    }

    router.back();
  }

  function handleDelete() {
    showAlert('Delete transaction', 'This cannot be undone.', [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Delete',
        style: 'destructive',
        onPress: async () => {
          setIsDeleting(true);
          const { error: deleteError } = await supabase.from('transactions').delete().eq('id', id);
          setIsDeleting(false);
          if (deleteError) {
            setError(deleteError.message);
            return;
          }
          router.back();
        },
      },
    ]);
  }

  if (isLoading || !transaction) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={Colors.light.tint} />
      </ThemedView>
    );
  }

  // Falls back to the bare code if the name hasn't been populated yet, same as components/top-bar.tsx's own currency picker.
  function currencyLabel(code: string): string {
    const currencyName = currencyNames[code];
    return currencyName ? `${currencyName} (${code})` : code;
  }
  const currencyOptions: SelectOption[] = availableCurrencies.map((code) => ({
    value: code,
    label: currencyLabel(code),
  }));

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={Colors.light.tint}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title">Edit Transaction</ThemedText>
          <Pressable onPress={handleDelete} hitSlop={12} disabled={isDeleting}>
            {isDeleting ? (
              <ActivityIndicator color={Colors.light.negative} />
            ) : (
              <ThemedText style={{ color: Colors.light.negative }}>Delete</ThemedText>
            )}
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedText style={styles.hint}>
          {account ? `On ${account.name}` : card ? `On ${card.issuer} · ${card.name}` : 'Not linked to an account or card'}
        </ThemedText>

        <ThemedText type="defaultSemiBold">Amount</ThemedText>
        <TextInput
          value={amount}
          onChangeText={setAmount}
          placeholder="0.00"
          keyboardType="decimal-pad"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, styles.monoInput, { color: Colors.light.text, borderColor: Colors.light.tint }]}
        />

        <ThemedText type="defaultSemiBold">Currency</ThemedText>
        <Pressable onPress={() => setShowCurrencyPicker(true)} style={[styles.input, { borderColor: Colors.light.tint }]}>
          <ThemedText>{currency ? currencyLabel(currency) : 'Select a currency'}</ThemedText>
        </Pressable>
        <SelectModal
          visible={showCurrencyPicker}
          onClose={() => setShowCurrencyPicker(false)}
          options={currencyOptions}
          selectedValue={currency || null}
          onSelect={(value) => {
            setCurrency(value);
            setShowCurrencyPicker(false);
          }}
        />

        <ThemedText type="defaultSemiBold">Date</ThemedText>
        <DateInput value={date} onChange={setDate} accentColor={Colors.light.tint} />

        <ThemedText type="defaultSemiBold">Merchant</ThemedText>
        <TextInput
          value={merchant}
          onChangeText={setMerchant}
          onBlur={handleMerchantBlur}
          placeholder="Optional"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: Colors.light.tint }]}
        />

        <ThemedText type="defaultSemiBold">Category</ThemedText>
        <Pressable
          onPress={() => setShowCategoryPicker(true)}
          style={[styles.input, { borderColor: Colors.light.tint }]}>
          <ThemedText>{selectedCategory ? selectedCategory.name : 'Uncategorized'}</ThemedText>
        </Pressable>
        <CategoryPicker
          visible={showCategoryPicker}
          onClose={() => setShowCategoryPicker(false)}
          categories={categories}
          selectedCategoryId={selectedCategoryId}
          onSelect={setSelectedCategoryId}
          onCategoryCreated={(category) => setCategories((prev) => [...prev, category])}
          accentColor={Colors.light.tint}
        />
        {selectedCategory && merchant.trim() ? (
          <Pressable
            onPress={() =>
              router.push(
                `/spend/rules/new?merchant=${encodeURIComponent(merchant.trim())}&categoryId=${selectedCategory.id}`
              )
            }
            hitSlop={4}>
            <ThemedText type="link" style={styles.ruleLink}>
              Always categorize &quot;{merchant.trim()}&quot; as {selectedCategory.name} →
            </ThemedText>
          </Pressable>
        ) : null}

        <ThemedText type="defaultSemiBold">Trip</ThemedText>
        <Pressable onPress={() => setShowTripPicker(true)} style={[styles.input, { borderColor: Colors.light.tint }]}>
          <ThemedText>{tripFieldLabel}</ThemedText>
        </Pressable>
        <TripStopPicker
          visible={showTripPicker}
          onClose={() => setShowTripPicker(false)}
          trips={trips}
          stops={visits}
          segments={tripSegments}
          selectedValue={tripLinkValue}
          onSelect={(value) => {
            setShowTripPicker(false);
            setTripLinkValue(value);
          }}
        />

        <ThemedText type="defaultSemiBold">Notes</ThemedText>
        <TextInput
          value={notes}
          onChangeText={setNotes}
          placeholder="Optional"
          multiline
          numberOfLines={3}
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, styles.notesInput, { color: Colors.light.text, borderColor: Colors.light.tint }]}
        />

        <ThemedView style={styles.row}>
          <ThemedText type="defaultSemiBold">Internal transfer</ThemedText>
          <Switch value={isInternalTransfer} onValueChange={setIsInternalTransfer} trackColor={{ true: Colors.light.tint }} />
        </ThemedView>

        <Pressable
          onPress={handleSave}
          disabled={isSaving}
          style={[styles.button, { backgroundColor: Colors.light.tint }]}>
          {isSaving ? (
            <ActivityIndicator color={Colors.light.backgroundSolid} />
          ) : (
            <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Save</ThemedText>
          )}
        </Pressable>
      </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  centered: { alignItems: 'center', justifyContent: 'center' },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 4,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 8,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  monoInput: {
    fontFamily: Fonts.mono,
  },
  notesInput: {
    minHeight: 80,
    textAlignVertical: 'top',
  },
  ruleLink: {
    fontSize: 13,
    marginBottom: 8,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  error: {
    color: Colors.light.negative,
  },
});
