import * as DocumentPicker from 'expo-document-picker';
import { File as ExpoFile } from 'expo-file-system';
import * as LegacyFileSystem from 'expo-file-system/legacy';
import { useRouter } from 'expo-router';
import { useEffect, useRef, useState } from 'react';
import { ActivityIndicator, Platform, Pressable, ScrollView, StyleSheet } from 'react-native';

import { SelectModal, type SelectOption } from '@/components/select-modal';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, Fonts, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useCurrency } from '@/contexts/currency-context';
import {
  columnLabels,
  importFileKind,
  isLikelyDuplicate,
  matchCategoryRule,
  parseAmount,
  parseCsv,
  parseDateFlexible,
  sanitizeCell,
  splitHeaderAndRows,
  validateImportFile,
  type DateFormat,
  type ImportCandidate,
} from '@/lib/csvImport';
import { formatDateDisplay } from '@/lib/format';
import { buildRowsFromPdf, type PdfExtractResult } from '@/lib/pdfImport';
import { supabase } from '@/lib/supabase';
import type { AccountRow, CategoryRuleRow, CreditCardRow, TransactionRow } from '@/types/database';

const ACCENT = ModuleAccents.spend;

const DATE_FORMAT_OPTIONS: { value: DateFormat; label: string }[] = [
  { value: 'MDY', label: 'MM/DD/YYYY' },
  { value: 'DMY', label: 'DD/MM/YYYY' },
];

type Step = 'upload' | 'mapping' | 'summary' | 'done';
type Target = { type: 'account' | 'card'; id: string } | null;
type AmountMode = 'single' | 'split';

type ReadyCandidate = ImportCandidate & { categoryId: string | null; isDuplicate: boolean };
type LoadedRows = { rows: string[][]; headerRow: string[] | null; notes: string[] };

/** supabase.functions.invoke surfaces a non-2xx as a bare FunctionsHttpError — the server's own message is in the response body. */
async function functionErrorMessage(error: unknown): Promise<string> {
  const context = (error as { context?: Response }).context;
  if (context && typeof context.json === 'function') {
    try {
      const body = (await context.json()) as { error?: string };
      if (body?.error) return body.error;
    } catch {
      // Body wasn't JSON — fall through to the generic message.
    }
  }
  return error instanceof Error ? error.message : String(error);
}

export default function ImportTransactionsScreen() {
  const router = useRouter();
  const { session } = useAuth();
  const { availableCurrencies } = useCurrency();

  const [step, setStep] = useState<Step>('upload');
  const [error, setError] = useState<string | null>(null);

  // Upload step
  const [accounts, setAccounts] = useState<AccountRow[]>([]);
  const [cards, setCards] = useState<CreditCardRow[]>([]);
  const [target, setTarget] = useState<Target>(null);
  const [showTargetPicker, setShowTargetPicker] = useState(false);
  const [currency, setCurrency] = useState('USD');
  const [showCurrencyPicker, setShowCurrencyPicker] = useState(false);
  const [isPicking, setIsPicking] = useState(false);
  const [fileName, setFileName] = useState<string | null>(null);
  const [fileContent, setFileContent] = useState<string | null>(null);
  // A PDF is uploaded to the csv-imports bucket up front (the Edge Function
  // reads it from there), so at confirm time that path is reused instead of
  // re-uploading. committedRef tells the unmount cleanup whether the file
  // became part of import history or is an orphan to delete.
  const [pdfStoragePath, setPdfStoragePath] = useState<string | null>(null);
  const [importNotes, setImportNotes] = useState<string[]>([]);
  const pdfPathRef = useRef<string | null>(null);
  const committedRef = useRef(false);
  const [dataRows, setDataRows] = useState<string[][]>([]);
  const [headerRow, setHeaderRow] = useState<string[] | null>(null);

  // Mapping step
  const [dateColumn, setDateColumn] = useState<number | null>(null);
  const [dateFormat, setDateFormat] = useState<DateFormat>('MDY');
  const [merchantColumn, setMerchantColumn] = useState<number | null>(null);
  const [amountMode, setAmountMode] = useState<AmountMode>('single');
  const [amountColumn, setAmountColumn] = useState<number | null>(null);
  const [debitColumn, setDebitColumn] = useState<number | null>(null);
  const [creditColumn, setCreditColumn] = useState<number | null>(null);
  const [showColumnPicker, setShowColumnPicker] = useState<
    'date' | 'merchant' | 'amount' | 'debit' | 'credit' | null
  >(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // Summary step
  const [readyCandidates, setReadyCandidates] = useState<ReadyCandidate[]>([]);
  const [duplicateCount, setDuplicateCount] = useState(0);
  const [unparseableCount, setUnparseableCount] = useState(0);
  const [isImporting, setIsImporting] = useState(false);
  const [importedCount, setImportedCount] = useState(0);

  useEffect(() => {
    Promise.all([
      supabase.from('accounts').select('*').eq('is_active', true).order('name'),
      supabase.from('credit_cards').select('*').eq('is_active', true).order('name'),
    ]).then(([accountsResult, cardsResult]) => {
      setAccounts(accountsResult.data ?? []);
      setCards(cardsResult.data ?? []);
    });
  }, []);

  useEffect(
    () => () => {
      if (pdfPathRef.current && !committedRef.current) {
        supabase.storage.from('csv-imports').remove([pdfPathRef.current]);
      }
    },
    []
  );

  const targetOptions: SelectOption[] = [
    ...accounts.map((a) => ({ value: `account:${a.id}`, label: a.name })),
    ...cards.map((c) => ({ value: `card:${c.id}`, label: `${c.issuer} · ${c.name}` })),
  ];
  const targetLabel = target
    ? (targetOptions.find((o) => o.value === `${target.type}:${target.id}`)?.label ?? 'Selected')
    : 'Select an account or card';

  const columns = columnLabels(headerRow, dataRows[0]?.length ?? 0);
  const columnOptions: SelectOption[] = columns.map((label, i) => ({ value: String(i), label }));
  const currencyOptions: SelectOption[] = availableCurrencies.map((c) => ({ value: c, label: c }));

  async function handlePickFile() {
    setError(null);
    const result = await DocumentPicker.getDocumentAsync({ type: '*/*', copyToCacheDirectory: true });
    if (result.canceled || !result.assets[0]) return;

    const asset = result.assets[0];
    const sizeError = validateImportFile(asset.name, asset.size);
    if (sizeError) {
      setError(sizeError);
      return;
    }

    setIsPicking(true);
    try {
      await discardPendingPdf();
      const loaded = importFileKind(asset.name) === 'pdf' ? await loadPdfRows(asset) : await loadCsvRows(asset);
      if (!loaded) return;
      setDataRows(loaded.rows);
      setHeaderRow(loaded.headerRow);
      setFileName(asset.name);
      setImportNotes(loaded.notes);
      applyMappingDefaults(loaded.headerRow);
      setStep('mapping');
    } catch (err) {
      // Surfaces the real underlying error, same as documents/new.tsx and
      // the avatar upload's own catch blocks — a canned message here was
      // actively hiding what's actually going wrong.
      setError(
        `Could not read that file: ${err instanceof Error ? err.message : String(err)}`
      );
    } finally {
      setIsPicking(false);
    }
  }

  async function loadCsvRows(asset: DocumentPicker.DocumentPickerAsset): Promise<LoadedRows | null> {
    // Web and native need two different reads here. On web,
    // expo-file-system (both the new File class and the /legacy
    // readAsStringAsync API) doesn't back onto real filesystem access at
    // all, so both throw ("validatePath is not a function" / "not
    // available on web") for anything picked via DocumentPicker's
    // unrestricted type: '*/*'. DocumentPickerAsset carries the actual
    // browser File object at asset.file on web (parity with the Web File
    // API), which has its own native .text() and needs no
    // expo-file-system involvement. Native keeps using
    // expo-file-system/legacy's readAsStringAsync, the older, more
    // battle-tested API for "read whatever content:// URI a document
    // picker handed back."
    const content =
      Platform.OS === 'web' && asset.file
        ? await asset.file.text()
        : await LegacyFileSystem.readAsStringAsync(asset.uri, { encoding: 'utf8' });
    const allRows = parseCsv(content);
    if (allRows.length === 0) {
      setError('No data rows found in this file.');
      return null;
    }
    const { rows, headerRow: detectedHeader } = splitHeaderAndRows(allRows);
    if (rows.length === 0) {
      setError('This file only has a header row. No transactions to import.');
      return null;
    }
    setFileContent(content);
    setPdfStoragePath(null);
    return { rows, headerRow: detectedHeader, notes: [] };
  }

  /**
   * Text-based PDF statements: the file goes to the caller's own folder in
   * the csv-imports bucket, the pdf-extract-text Edge Function reads it
   * back and returns every text fragment with its position, and
   * lib/pdfImport.ts turns those into the same rows a CSV would give. The
   * upload is reused at confirm time as the import-history copy.
   */
  async function loadPdfRows(asset: DocumentPicker.DocumentPickerAsset): Promise<LoadedRows | null> {
    if (!session) return null;
    // Same web/native split as the CSV read, but as bytes: the browser File
    // is a valid upload body as-is; natively the new expo-file-system File
    // class reads raw bytes (the approach documents/new.tsx already uses).
    const body: Blob | Uint8Array =
      Platform.OS === 'web' && asset.file ? asset.file : await new ExpoFile(asset.uri).bytes();
    const sanitizedName = asset.name.replace(/[^a-zA-Z0-9._-]/g, '_');
    const storagePath = `${session.user.id}/${Date.now()}-${sanitizedName}`;
    const { error: uploadError } = await supabase.storage
      .from('csv-imports')
      .upload(storagePath, body, { contentType: 'application/pdf' });
    if (uploadError) {
      setError(`Couldn't upload the PDF: ${uploadError.message}`);
      return null;
    }
    pdfPathRef.current = storagePath;
    committedRef.current = false;

    const { data, error: extractError } = await supabase.functions.invoke<PdfExtractResult>('pdf-extract-text', {
      body: { storage_path: storagePath },
    });
    if (extractError || !data) {
      await discardPendingPdf();
      setError(`Couldn't read the PDF: ${extractError ? await functionErrorMessage(extractError) : 'empty response'}`);
      return null;
    }

    const table = buildRowsFromPdf(data);
    if (table.rows.length === 0) {
      await discardPendingPdf();
      setError(table.notes.join(' ') || 'No transactions found in this PDF.');
      return null;
    }
    setFileContent(null);
    setPdfStoragePath(storagePath);
    return table;
  }

  /** Removes a PDF uploaded for a previous pick that never made it into import history. */
  async function discardPendingPdf() {
    if (pdfPathRef.current && !committedRef.current) {
      await supabase.storage.from('csv-imports').remove([pdfPathRef.current]);
    }
    pdfPathRef.current = null;
    setPdfStoragePath(null);
  }

  // Reasonable defaults so the mapping step isn't blank: header text often
  // names the column outright. A statement with separate Money Out / Money
  // In (or Debit / Credit) columns and no single Amount column flips the
  // amount mode to split automatically.
  function applyMappingDefaults(header: string[] | null) {
    const find = (pattern: RegExp): number | null => {
      const index = header?.findIndex((h) => pattern.test(h)) ?? -1;
      return index >= 0 ? index : null;
    };
    const amount = find(/amount/i);
    const debit = find(/(debit|money\s*out|paid\s*out|withdrawal)/i);
    const credit = find(/(credit|money\s*in|paid\s*in|deposit)/i);
    setDateColumn(find(/date/i) ?? -1);
    setMerchantColumn(find(/(description|details|particulars|narrative|merchant|payee|memo)/i) ?? -1);
    if (amount === null && (debit !== null || credit !== null)) {
      setAmountMode('split');
      setDebitColumn(debit);
      setCreditColumn(credit);
      setAmountColumn(-1);
    } else {
      setAmountMode('single');
      setAmountColumn(amount ?? -1);
      setDebitColumn(null);
      setCreditColumn(null);
    }
  }

  function buildCandidates(): { candidates: ImportCandidate[]; unparseable: number } {
    const candidates: ImportCandidate[] = [];
    let unparseable = 0;

    for (const row of dataRows) {
      const rawDate = dateColumn !== null ? (row[dateColumn] ?? '') : '';
      const rawMerchant = merchantColumn !== null ? (row[merchantColumn] ?? '') : '';
      const date = parseDateFlexible(rawDate, dateFormat);
      const merchant = sanitizeCell(rawMerchant);

      let amount: number | null;
      if (amountMode === 'single') {
        amount = amountColumn !== null ? parseAmount(row[amountColumn] ?? '') : null;
      } else {
        const debit = debitColumn !== null ? (parseAmount(row[debitColumn] ?? '') ?? 0) : 0;
        const credit = creditColumn !== null ? (parseAmount(row[creditColumn] ?? '') ?? 0) : 0;
        amount = credit - debit;
      }

      if (!date || amount === null || !merchant) {
        unparseable += 1;
        continue;
      }
      candidates.push({ date, amount, merchant });
    }

    return { candidates, unparseable };
  }

  async function handleContinueFromMapping() {
    if (dateColumn === null || dateColumn < 0 || merchantColumn === null || merchantColumn < 0) {
      setError('Pick a column for both Date and Merchant.');
      return;
    }
    if (amountMode === 'single' && (amountColumn === null || amountColumn < 0)) {
      setError('Pick a column for Amount.');
      return;
    }
    if (amountMode === 'split' && debitColumn === null && creditColumn === null) {
      setError('Pick at least one of Debit or Credit.');
      return;
    }
    if (!target) {
      setError('Pick an account or card for this import.');
      return;
    }

    setError(null);
    setIsProcessing(true);

    const { candidates, unparseable } = buildCandidates();
    if (candidates.length === 0) {
      setIsProcessing(false);
      setError('No rows could be parsed with this column mapping. Double check your selections.');
      return;
    }

    const dates = candidates.map((c) => c.date).sort();
    const minDate = dates[0];
    const maxDate = dates[dates.length - 1];

    const targetColumn = target.type === 'account' ? 'account_id' : 'card_id';
    const [existingResult, rulesResult] = await Promise.all([
      supabase
        .from('transactions')
        .select('*')
        .eq(targetColumn, target.id)
        .gte('date', minDate)
        .lte('date', maxDate),
      supabase.from('category_rules').select('*'),
    ]);

    const existing: TransactionRow[] = existingResult.data ?? [];
    const rules: CategoryRuleRow[] = rulesResult.data ?? [];

    const ready: ReadyCandidate[] = candidates.map((candidate) => ({
      ...candidate,
      categoryId: matchCategoryRule(candidate.merchant, rules),
      isDuplicate: isLikelyDuplicate(candidate, existing),
    }));

    setReadyCandidates(ready);
    setDuplicateCount(ready.filter((r) => r.isDuplicate).length);
    setUnparseableCount(unparseable);
    setIsProcessing(false);
    setStep('summary');
  }

  async function handleConfirmImport() {
    if (!session || !target) return;
    const toInsert = readyCandidates.filter((c) => !c.isDuplicate);
    if (toInsert.length === 0) {
      setStep('done');
      return;
    }

    setIsImporting(true);
    setError(null);

    // Keep the source file in the csv-imports repository (transactions/imports.tsx)
    // so an incorrectly-posted statement can be deleted after the fact —
    // deleting the csv_imports row cascades to every transaction it
    // created via transactions.csv_import_id's own "on delete cascade", so
    // there's no separate cleanup step needed here beyond tagging the rows.
    // Uploads the already-decoded text directly rather than re-reading the
    // original file/URI a second time — a plain string is a valid upload
    // body on every platform, sidestepping the same web/native File-class
    // inconsistency that broke the initial CSV read.
    let csvImportId: string | null = null;
    let repositoryWarning: string | null = null;
    if (fileName && (fileContent || pdfStoragePath)) {
      // A PDF is already sitting in the bucket from the extraction step;
      // a CSV gets uploaded now.
      let storagePath = pdfStoragePath;
      if (!storagePath && fileContent) {
        const sanitizedName = fileName.replace(/[^a-zA-Z0-9._-]/g, '_');
        storagePath = `${session.user.id}/${Date.now()}-${sanitizedName}`;
        const { error: uploadError } = await supabase.storage
          .from('csv-imports')
          .upload(storagePath, fileContent, { contentType: 'text/csv' });
        if (uploadError) {
          repositoryWarning = `Import will proceed, but the file couldn't be saved to your import history: ${uploadError.message}`;
          storagePath = null;
        }
      }

      if (storagePath) {
        const { data: importRow, error: importInsertError } = await supabase
          .from('csv_imports')
          .insert({
            user_id: session.user.id,
            file_name: fileName,
            storage_path: storagePath,
            target_type: target.type,
            target_id: target.id,
            row_count: toInsert.length,
          })
          .select()
          .single();

        if (importInsertError) {
          await supabase.storage.from('csv-imports').remove([storagePath]);
          pdfPathRef.current = null;
          repositoryWarning = `Import will proceed, but couldn't be recorded in your import history: ${importInsertError.message}`;
        } else {
          csvImportId = importRow.id;
          committedRef.current = true;
        }
      }
    }

    const rows = toInsert.map((c) => ({
      user_id: session.user.id,
      account_id: target.type === 'account' ? target.id : null,
      card_id: target.type === 'card' ? target.id : null,
      date: c.date,
      time: null,
      amount: c.amount,
      currency: currency.trim().toUpperCase() || 'USD',
      merchant: c.merchant,
      category_id: c.categoryId,
      notes: null,
      attributed_country_id: null,
      csv_import_id: csvImportId,
    }));

    const { error: insertError } = await supabase.from('transactions').insert(rows);

    setIsImporting(false);

    if (insertError) {
      setError(insertError.message);
      return;
    }

    if (repositoryWarning) setError(repositoryWarning);
    setImportedCount(toInsert.length);
    setStep('done');
  }

  function openColumnPicker(field: 'date' | 'merchant' | 'amount' | 'debit' | 'credit') {
    setShowColumnPicker(field);
  }

  function handleColumnSelect(value: string) {
    const index = Number(value);
    switch (showColumnPicker) {
      case 'date':
        setDateColumn(index);
        break;
      case 'merchant':
        setMerchantColumn(index);
        break;
      case 'amount':
        setAmountColumn(index);
        break;
      case 'debit':
        setDebitColumn(index);
        break;
      case 'credit':
        setCreditColumn(index);
        break;
    }
    setShowColumnPicker(null);
  }

  const currentColumnValue =
    showColumnPicker === 'date'
      ? dateColumn
      : showColumnPicker === 'merchant'
        ? merchantColumn
        : showColumnPicker === 'amount'
          ? amountColumn
          : showColumnPicker === 'debit'
            ? debitColumn
            : creditColumn;

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedText type="title" style={{ color: ACCENT }}>
          Import Transactions
        </ThemedText>
        {step === 'upload' ? (
          <Pressable onPress={() => router.push('/transactions/imports')} hitSlop={8}>
            <ThemedText type="link">View import history</ThemedText>
          </Pressable>
        ) : null}
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {step === 'upload' ? (
          <>
            <ThemedText type="defaultSemiBold">Account or card</ThemedText>
            <Pressable
              onPress={() => setShowTargetPicker(true)}
              style={[styles.input, { borderColor: ACCENT }]}>
              <ThemedText>{targetLabel}</ThemedText>
            </Pressable>
            <SelectModal
              visible={showTargetPicker}
              onClose={() => setShowTargetPicker(false)}
              options={targetOptions}
              selectedValue={target ? `${target.type}:${target.id}` : null}
              onSelect={(value) => {
                const [type, id] = value.split(':');
                setTarget({ type: type as 'account' | 'card', id });
              }}
            />

            <ThemedText type="defaultSemiBold">Currency</ThemedText>
            <Pressable
              onPress={() => setShowCurrencyPicker(true)}
              style={[styles.input, { borderColor: ACCENT }]}>
              <ThemedText type="mono">{currency}</ThemedText>
            </Pressable>
            <SelectModal
              visible={showCurrencyPicker}
              onClose={() => setShowCurrencyPicker(false)}
              options={currencyOptions}
              selectedValue={currency}
              onSelect={setCurrency}
            />
            <ThemedText style={styles.hint}>Applied to every transaction in this import.</ThemedText>

            <Pressable
              onPress={handlePickFile}
              disabled={isPicking}
              style={[styles.button, { backgroundColor: ACCENT, marginTop: 16 }]}>
              {isPicking ? (
                <ActivityIndicator color={ModuleAccentOnColor.spend} />
              ) : (
                <ThemedText style={{ color: ModuleAccentOnColor.spend, fontWeight: '600' }}>
                  Choose CSV or PDF file
                </ThemedText>
              )}
            </Pressable>
            <ThemedText style={styles.hint}>
              CSV exports, or the PDF statement your bank lets you download. Scanned or photographed PDFs
              can&apos;t be read, only text-based ones. Excel (.xlsx) isn&apos;t supported.
            </ThemedText>
          </>
        ) : null}

        {step === 'mapping' ? (
          <>
            <ThemedText style={styles.hint}>{fileName} · {dataRows.length} rows</ThemedText>
            {importNotes.map((note) => (
              <ThemedText key={note} style={styles.hint}>
                {note}
              </ThemedText>
            ))}

            <ThemedView style={styles.previewBox}>
              <ScrollView horizontal>
                <ThemedView>
                  {dataRows.slice(0, 5).map((row, rowIndex) => (
                    <ThemedView key={rowIndex} style={styles.previewRow}>
                      {row.map((cell, cellIndex) => (
                        <ThemedText key={cellIndex} style={styles.previewCell} numberOfLines={1}>
                          {cell || '-'}
                        </ThemedText>
                      ))}
                    </ThemedView>
                  ))}
                </ThemedView>
              </ScrollView>
            </ThemedView>

            <ThemedText type="defaultSemiBold">Date column</ThemedText>
            <Pressable onPress={() => openColumnPicker('date')} style={[styles.input, { borderColor: ACCENT }]}>
              <ThemedText>{dateColumn !== null && dateColumn >= 0 ? columns[dateColumn] : 'Select a column'}</ThemedText>
            </Pressable>

            <ThemedText type="defaultSemiBold">Date format</ThemedText>
            <ThemedView style={styles.chipRow}>
              {DATE_FORMAT_OPTIONS.map((option) => (
                <Pressable
                  key={option.value}
                  onPress={() => setDateFormat(option.value)}
                  style={[
                    styles.chip,
                    { borderColor: ACCENT, backgroundColor: dateFormat === option.value ? ACCENT : 'transparent' },
                  ]}>
                  <ThemedText style={dateFormat === option.value ? { color: ModuleAccentOnColor.spend } : undefined}>
                    {option.label}
                  </ThemedText>
                </Pressable>
              ))}
            </ThemedView>
            <ThemedText style={styles.hint}>Only matters for slash-separated dates (ISO dates like 2026-01-31 are unambiguous).</ThemedText>

            <ThemedText type="defaultSemiBold">Merchant column</ThemedText>
            <Pressable onPress={() => openColumnPicker('merchant')} style={[styles.input, { borderColor: ACCENT }]}>
              <ThemedText>
                {merchantColumn !== null && merchantColumn >= 0 ? columns[merchantColumn] : 'Select a column'}
              </ThemedText>
            </Pressable>

            <ThemedText type="defaultSemiBold">Amount format</ThemedText>
            <ThemedView style={styles.chipRow}>
              {(['single', 'split'] as AmountMode[]).map((mode) => (
                <Pressable
                  key={mode}
                  onPress={() => setAmountMode(mode)}
                  style={[
                    styles.chip,
                    { borderColor: ACCENT, backgroundColor: amountMode === mode ? ACCENT : 'transparent' },
                  ]}>
                  <ThemedText style={amountMode === mode ? { color: ModuleAccentOnColor.spend } : undefined}>
                    {mode === 'single' ? 'One amount column' : 'Separate debit/credit'}
                  </ThemedText>
                </Pressable>
              ))}
            </ThemedView>

            {amountMode === 'single' ? (
              <>
                <ThemedText type="defaultSemiBold">Amount column</ThemedText>
                <Pressable onPress={() => openColumnPicker('amount')} style={[styles.input, { borderColor: ACCENT }]}>
                  <ThemedText>
                    {amountColumn !== null && amountColumn >= 0 ? columns[amountColumn] : 'Select a column'}
                  </ThemedText>
                </Pressable>
              </>
            ) : (
              <>
                <ThemedText type="defaultSemiBold">Debit column</ThemedText>
                <Pressable onPress={() => openColumnPicker('debit')} style={[styles.input, { borderColor: ACCENT }]}>
                  <ThemedText>{debitColumn !== null ? columns[debitColumn] : 'Select a column'}</ThemedText>
                </Pressable>

                <ThemedText type="defaultSemiBold">Credit column</ThemedText>
                <Pressable onPress={() => openColumnPicker('credit')} style={[styles.input, { borderColor: ACCENT }]}>
                  <ThemedText>{creditColumn !== null ? columns[creditColumn] : 'Select a column'}</ThemedText>
                </Pressable>
              </>
            )}

            <SelectModal
              visible={showColumnPicker !== null}
              onClose={() => setShowColumnPicker(null)}
              options={columnOptions}
              selectedValue={currentColumnValue !== null && currentColumnValue >= 0 ? String(currentColumnValue) : null}
              onSelect={handleColumnSelect}
            />

            <Pressable
              onPress={handleContinueFromMapping}
              disabled={isProcessing}
              style={[styles.button, { backgroundColor: ACCENT, marginTop: 16 }]}>
              {isProcessing ? (
                <ActivityIndicator color={ModuleAccentOnColor.spend} />
              ) : (
                <ThemedText style={{ color: ModuleAccentOnColor.spend, fontWeight: '600' }}>Continue</ThemedText>
              )}
            </Pressable>
          </>
        ) : null}

        {step === 'summary' ? (
          <>
            <Surface accentColor={ACCENT}>
              <ThemedText type="defaultSemiBold">
                {readyCandidates.length - duplicateCount} new transactions
              </ThemedText>
              <ThemedText style={styles.muted}>{duplicateCount} likely duplicates skipped</ThemedText>
              {unparseableCount > 0 ? (
                <ThemedText style={styles.muted}>{unparseableCount} rows skipped (couldn&apos;t be parsed)</ThemedText>
              ) : null}
              {readyCandidates.length > 0 ? (
                <ThemedText type="mono" style={styles.muted}>
                  {formatDateDisplay([...readyCandidates].sort((a, b) => (a.date < b.date ? -1 : 1))[0].date)} &rarr;{' '}
                  {formatDateDisplay(
                    [...readyCandidates].sort((a, b) => (a.date < b.date ? 1 : -1))[0].date
                  )}
                </ThemedText>
              ) : null}
            </Surface>

            <Pressable
              onPress={handleConfirmImport}
              disabled={isImporting}
              style={[styles.button, { backgroundColor: ACCENT, marginTop: 16 }]}>
              {isImporting ? (
                <ActivityIndicator color={ModuleAccentOnColor.spend} />
              ) : (
                <ThemedText style={{ color: ModuleAccentOnColor.spend, fontWeight: '600' }}>
                  Confirm import
                </ThemedText>
              )}
            </Pressable>
          </>
        ) : null}

        {step === 'done' ? (
          <>
            <Surface accentColor={ACCENT}>
              <ThemedText type="defaultSemiBold">{importedCount} transactions imported</ThemedText>
              <ThemedText style={styles.muted}>You can categorize any leftovers from the Spend screen.</ThemedText>
            </Surface>
            <Pressable onPress={() => router.back()} style={[styles.button, { backgroundColor: ACCENT, marginTop: 16 }]}>
              <ThemedText style={{ color: ModuleAccentOnColor.spend, fontWeight: '600' }}>Done</ThemedText>
            </Pressable>
          </>
        ) : null}
      </ScrollView>
    </ThemedView>
  );
}

