import { StyleSheet, View, useWindowDimensions } from 'react-native';
import Svg, { Circle } from 'react-native-svg';

import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';

export type SunburstAccount = { id: string; label: string; amount: number };

type Arc = { key: string; label: string; startDegrees: number; degrees: number; opacity: number };

/** Builds one arc per account, confined to [startDegrees, startDegrees + spanDegrees) and sized by its share of groupTotal — the account "ring" nested inside its parent category's angular slice. */
function buildAccountArcs(items: SunburstAccount[], startDegrees: number, spanDegrees: number, groupTotal: number): Arc[] {
  let cursor = startDegrees;
  return items.map((item, index) => {
    const degrees = groupTotal > 0 ? (item.amount / groupTotal) * spanDegrees : 0;
    const arc: Arc = { key: item.id, label: item.label, startDegrees: cursor, degrees, opacity: 1 - (index % 4) * 0.15 };
    cursor += degrees;
    return arc;
  });
}

/**
 * Hand-rolled (no charting library, matching the rest of the app's charts —
 * see CategoryPieChart/TripPieChart) two-ring sunburst: an inner ring with
 * exactly 2 arcs (Assets, Liabilities, sized by total magnitude) and an
 * outer ring with one arc per account, each confined to its parent
 * category's angular span. Same stroke-arc technique as CategoryPieChart,
 * just two concentric rings instead of one.
 */
export function AssetLiabilitySunburst({
  assets,
  liabilities,
  assetsColor,
  liabilitiesColor,
}: {
  assets: SunburstAccount[];
  liabilities: SunburstAccount[];
  assetsColor: string;
  liabilitiesColor: string;
}) {
  const { width: windowWidth } = useWindowDimensions();
  const assetsTotal = assets.reduce((sum, a) => sum + a.amount, 0);
  const liabilitiesTotal = liabilities.reduce((sum, a) => sum + a.amount, 0);
  const grandTotal = assetsTotal + liabilitiesTotal;

  const size = Math.min(windowWidth - 64, 240);
  const center = size / 2;
  const radius = size / 2 - 8;

  const categoryRingWidth = radius * 0.28;
  const categoryRingRadius = categoryRingWidth / 2 + 2;
  const categoryCircumference = 2 * Math.PI * categoryRingRadius;

  const accountRingWidth = radius * 0.3;
  const accountRingRadius = categoryRingRadius + categoryRingWidth / 2 + 4 + accountRingWidth / 2;
  const accountCircumference = 2 * Math.PI * accountRingRadius;

  if (grandTotal <= 0) {
    return <ThemedText style={styles.muted}>Nothing to chart yet.</ThemedText>;
  }

  const assetsDegrees = (assetsTotal / grandTotal) * 360;
  const liabilitiesDegrees = 360 - assetsDegrees;

  const assetArcs = buildAccountArcs(assets, 0, assetsDegrees, assetsTotal);
  const liabilityArcs = buildAccountArcs(liabilities, assetsDegrees, liabilitiesDegrees, liabilitiesTotal);

  function categoryArc(color: string, startDegrees: number, degrees: number) {
    const arcLength = categoryCircumference * (degrees / 360);
    return (
      <Circle
        cx={center}
        cy={center}
        r={categoryRingRadius}
        fill="transparent"
        stroke={color}
        strokeWidth={categoryRingWidth}
        strokeDasharray={`${arcLength} ${categoryCircumference - arcLength}`}
        rotation={startDegrees - 90}
        origin={`${center}, ${center}`}
      />
    );
  }

  function accountArc(arc: Arc, color: string) {
    if (arc.degrees <= 0) return null;
    // Leave a hairline gap between adjacent account slices so they read as
    // distinct wedges, not one solid ring — same 2px-gap idea used for the
    // wheel's segments elsewhere in the app.
    const gapDegrees = Math.min(1, arc.degrees * 0.08);
    const drawnDegrees = Math.max(0, arc.degrees - gapDegrees);
    const arcLength = accountCircumference * (drawnDegrees / 360);
    return (
      <Circle
        key={arc.key}
        cx={center}
        cy={center}
        r={accountRingRadius}
        fill="transparent"
        stroke={color}
        strokeOpacity={arc.opacity}
        strokeWidth={accountRingWidth}
        strokeDasharray={`${arcLength} ${accountCircumference - arcLength}`}
        rotation={arc.startDegrees - 90}
        origin={`${center}, ${center}`}
      />
    );
  }

  return (
    <ThemedView style={styles.container}>
      <View style={{ width: size, height: size }}>
        <Svg width={size} height={size}>
          {categoryArc(assetsColor, 0, assetsDegrees)}
          {categoryArc(liabilitiesColor, assetsDegrees, liabilitiesDegrees)}
          {assetArcs.map((arc) => accountArc(arc, assetsColor))}
          {liabilityArcs.map((arc) => accountArc(arc, liabilitiesColor))}
        </Svg>
      </View>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
    textAlign: 'center',
  },
});
