import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import * as WebBrowser from 'expo-web-browser';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { SharedModuleNav } from '@/components/shared-module-nav';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useConnectionDisplay } from '@/hooks/use-connection-display';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { formatDateDisplay } from '@/lib/format';
import { supabase } from '@/lib/supabase';

const ACCENT = ModuleAccents.documents;
const SIGNED_URL_EXPIRY_SECONDS = 300;

type SharedDocument = { user_id: string; name: string; doc_type: string; expiry_date: string | null; file_ref: string };

export default function SharedDocumentsScreen() {
  const { connectionId } = useLocalSearchParams<{ connectionId: string }>();
  const router = useRouter();
  const display = useConnectionDisplay(connectionId);
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const [documents, setDocuments] = useState<SharedDocument[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [openingFileRef, setOpeningFileRef] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const { data, error: fetchError } = await supabase.rpc('shared_documents', { p_connection_id: connectionId });
    if (fetchError) {
      setError(fetchError.message);
    } else {
      setDocuments(data ?? []);
    }
    setIsLoading(false);
  }, [connectionId]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  async function handleOpenDocument(fileRef: string) {
    setError(null);
    setOpeningFileRef(fileRef);
    const { data, error: signError } = await supabase.storage
      .from('documents')
      .createSignedUrl(fileRef, SIGNED_URL_EXPIRY_SECONDS);
    setOpeningFileRef(null);
    if (signError || !data) {
      setError(signError?.message ?? "Couldn't open that file.");
      return;
    }
    await WebBrowser.openBrowserAsync(data.signedUrl);
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel
        connections={swipeConnections}
        isLoading={isConnectionsLoading}
        accentColor={ACCENT}
        activeConnectionId={connectionId}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }} numberOfLines={1} adjustsFontSizeToFit>
            {display.displayName}&apos;s Documents
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <SharedModuleNav connectionId={connectionId} accentColor={ACCENT} active="documents" />
        <ScrollView
          contentContainerStyle={styles.content}
          refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
          {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
          <ThemedText style={styles.hint}>Tap a document to open the actual file.</ThemedText>

          {isLoading ? (
            <ActivityIndicator color={ACCENT} />
          ) : documents.length === 0 ? (
            <ThemedText style={styles.muted}>Nothing shared yet.</ThemedText>
          ) : (
            documents.map((doc, index) => (
              <Pressable
                key={index}
                onPress={() => handleOpenDocument(doc.file_ref)}
                disabled={openingFileRef === doc.file_ref}>
                <Surface accentColor={ACCENT} style={styles.row}>
                  <ThemedView style={styles.rowText}>
                    <ThemedText type="defaultSemiBold">{doc.name}</ThemedText>
                    <ThemedText style={styles.muted}>
                      {doc.doc_type}
                      {doc.expiry_date ? ` · Expires ${formatDateDisplay(doc.expiry_date)}` : ''}
                    </ThemedText>
                  </ThemedView>
                  {openingFileRef === doc.file_ref ? (
                    <ActivityIndicator color={ACCENT} />
                  ) : (
                    <IconSymbol name="chevron.right" size={18} color={ACCENT} />
                  )}
                </Surface>
              </Pressable>
            ))
          )}
        </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: 16,
    paddingBottom: 8,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  rowText: {
    flex: 1,
    gap: 2,
    marginRight: 12,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
