import { Pressable, StyleSheet } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import type { TransactionSortDirection, TransactionSortField } from '@/lib/transactionSort';

/**
 * Tapping the already-active field flips its direction; tapping the other
 * field switches to it with a sensible default (newest-first for date,
 * biggest-first for amount) — no separate direction control needed.
 */
export function TransactionSortControl({
  sortField,
  sortDirection,
  onChange,
  accentColor,
}: {
  sortField: TransactionSortField;
  sortDirection: TransactionSortDirection;
  onChange: (field: TransactionSortField, direction: TransactionSortDirection) => void;
  accentColor: string;
}) {
  function handlePress(field: TransactionSortField) {
    if (field === sortField) {
      onChange(field, sortDirection === 'asc' ? 'desc' : 'asc');
    } else {
      onChange(field, 'desc');
    }
  }

  const arrow = sortDirection === 'asc' ? '↑' : '↓';

  return (
    <ThemedView style={styles.row}>
      <ThemedText style={styles.label}>Sort</ThemedText>
      {(['date', 'amount'] as const).map((field) => {
        const isSelected = field === sortField;
        return (
          <Pressable
            key={field}
            onPress={() => handlePress(field)}
            style={[
              styles.chip,
              { borderColor: accentColor, backgroundColor: isSelected ? accentColor : 'transparent' },
            ]}>
            <ThemedText style={isSelected ? { color: Colors.light.backgroundSolid } : undefined}>
              {field === 'date' ? 'Date' : 'Amount'}
              {isSelected ? ` ${arrow}` : ''}
            </ThemedText>
          </Pressable>
        );
      })}
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  label: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  chip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 14,
    paddingHorizontal: 12,
    paddingVertical: 5,
  },
});
