export type DemoAccount = {
  name: string;
  institution: string;
  balance: number;
  currency: string;
  liquid: boolean;
};

export const DEMO_ACCOUNTS: DemoAccount[] = [
  { name: 'Everyday Checking', institution: 'Chase', balance: 12400, currency: 'USD', liquid: true },
  { name: 'Brokerage', institution: 'Fidelity', balance: 85000, currency: 'USD', liquid: false },
  { name: 'Flat in Paris', institution: 'Real estate', balance: 550000, currency: 'USD', liquid: false },
  { name: 'Mortgage', institution: 'Real estate loan', balance: -430000, currency: 'USD', liquid: false },
];

export function demoLiquidNetWorth(): number {
  return DEMO_ACCOUNTS.filter((a) => a.liquid).reduce((sum, a) => sum + a.balance, 0);
}

export function demoIlliquidNetWorth(): number {
  return DEMO_ACCOUNTS.filter((a) => !a.liquid).reduce((sum, a) => sum + a.balance, 0);
}
