import { View } from 'react-native';
import { SvgXml } from 'react-native-svg';

import { FLAG_SVGS } from '@/lib/flagSvgs';

/**
 * Renders a single flag from bundled SVG source (lib/flagSvgs.ts) via
 * react-native-svg's SvgXml — see that file for why (Windows web can't
 * render the Unicode flag-emoji this used to use). Pure lookup: takes the
 * raw code directly rather than a country name, so it can be used both by
 * components/country-flag.tsx (which adds the hidden-country/neutral-icon
 * logic on top) and directly by SelectModal's per-row rendering.
 */
export function FlagIcon({ code, size = 24 }: { code: string; size?: number }) {
  const xml = FLAG_SVGS[code];
  if (!xml) return null;
  return (
    <View style={{ width: size * 1.5, height: size, borderRadius: 2, overflow: 'hidden' }}>
      <SvgXml xml={xml} width="100%" height="100%" />
    </View>
  );
}
