import { useLocalSearchParams, useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput } from 'react-native';

import { DateInput } from '@/components/date-input';
import { SelectModal, type SelectOption } from '@/components/select-modal';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, Fonts, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { showAlert } from '@/lib/alert';
import { toDateOnlyString } from '@/lib/format';
import { defaultProgramType, PROGRAM_TYPE_OPTIONS, type LoyaltyProgramType } from '@/lib/loyalty';
import { supabase } from '@/lib/supabase';
import type { CreditCardRow, PointsProgramRateRow } from '@/types/database';

const ACCENT = ModuleAccents.cards;
const NO_CARD_VALUE = '__none__';
const OTHER_PROGRAM_VALUE = '__other__';

function parseDateOnly(value: string): Date {
  const [y, m, d] = value.split('-').map(Number);
  return new Date(y, m - 1, d);
}

/**
 * Add/edit one loyalty account — a card's points program, or a hotel /
 * airline / rail account with no card behind it. Reached from the Points &
 * Loyalty hub (any kind) or a card's own detail screen (pre-linked to that
 * card via ?cardId=).
 */
export default function LoyaltyAccountFormScreen() {
  const { id, cardId: presetCardId } = useLocalSearchParams<{ id: string; cardId?: string }>();
  const isNew = id === 'new';
  const router = useRouter();
  const { session } = useAuth();

  const [isLoading, setIsLoading] = useState(!isNew);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [program, setProgram] = useState('');
  const [programType, setProgramType] = useState<LoyaltyProgramType>('card');
  const [balance, setBalance] = useState('0');
  const [cardId, setCardId] = useState<string | null>(presetCardId ?? null);
  const [memberNumber, setMemberNumber] = useState('');
  const [expiryDate, setExpiryDate] = useState<Date | null>(null);
  const [notes, setNotes] = useState('');

  const [cards, setCards] = useState<CreditCardRow[]>([]);
  const [knownPrograms, setKnownPrograms] = useState<PointsProgramRateRow[]>([]);
  const [showProgramPicker, setShowProgramPicker] = useState(false);
  const [showCardPicker, setShowCardPicker] = useState(false);

  useEffect(() => {
    Promise.all([
      supabase.from('credit_cards').select('*').eq('is_active', true).order('name'),
      supabase.from('points_program_rates').select('*').order('program'),
    ]).then(([cardsResult, ratesResult]) => {
      setCards(cardsResult.data ?? []);
      setKnownPrograms(ratesResult.data ?? []);
    });
  }, []);

  useEffect(() => {
    if (isNew) return;
    let cancelled = false;
    supabase
      .from('loyalty_accounts')
      .select('*')
      .eq('id', id)
      .single()
      .then(({ data, error: fetchError }) => {
        if (cancelled) return;
        if (fetchError) {
          setError(fetchError.message);
        } else if (data) {
          setProgram(data.program);
          setProgramType(data.program_type);
          setBalance(String(data.balance));
          setCardId(data.card_id);
          setMemberNumber(data.member_number ?? '');
          setExpiryDate(data.expiry_date ? parseDateOnly(data.expiry_date) : null);
          setNotes(data.notes ?? '');
        }
        setIsLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [id, isNew]);

  const programOptions: SelectOption[] = [
    ...knownPrograms.map((r) => ({ value: r.program, label: r.program })),
    { value: OTHER_PROGRAM_VALUE, label: 'Something else…', dividerBefore: true },
  ];
  const cardOptions: SelectOption[] = [
    { value: NO_CARD_VALUE, label: 'Not earned through a card' },
    ...cards.map((c) => ({ value: c.id, label: `${c.issuer} · ${c.name}`, dividerBefore: false })),
  ];
  const linkedCard = cards.find((c) => c.id === cardId) ?? null;

  async function handleSave() {
    if (!session) return;
    if (!program.trim()) {
      setError('Program name is required.');
      return;
    }
    const parsedBalance = Number(balance.replace(/,/g, ''));
    if (Number.isNaN(parsedBalance)) {
      setError('Balance must be a number.');
      return;
    }

    setError(null);
    setIsSaving(true);
    const payload = {
      program: program.trim(),
      program_type: programType,
      balance: parsedBalance,
      card_id: cardId,
      member_number: memberNumber.trim() || null,
      expiry_date: expiryDate ? toDateOnlyString(expiryDate) : null,
      notes: notes.trim() || null,
      last_updated: new Date().toISOString(),
    };
    const { error: saveError } = isNew
      ? await supabase.from('loyalty_accounts').insert({ ...payload, user_id: session.user.id })
      : await supabase.from('loyalty_accounts').update(payload).eq('id', id);
    setIsSaving(false);
    if (saveError) {
      setError(saveError.message);
      return;
    }
    router.back();
  }

  function handleDelete() {
    showAlert('Delete program', 'This removes the balance and its expiry reminder. This cannot be undone.', [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Delete',
        style: 'destructive',
        onPress: async () => {
          setIsSaving(true);
          const { error: deleteError } = await supabase.from('loyalty_accounts').delete().eq('id', id);
          setIsSaving(false);
          if (deleteError) {
            setError(deleteError.message);
            return;
          }
          router.back();
        },
      },
    ]);
  }

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            {isNew ? 'Add Program' : 'Edit Program'}
          </ThemedText>
          {!isNew ? (
            <Pressable onPress={handleDelete} hitSlop={12}>
              <IconSymbol name="trash" size={22} color={Colors.light.negative} />
            </Pressable>
          ) : null}
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedText type="defaultSemiBold">Program</ThemedText>
        <TextInput
          value={program}
          onChangeText={setProgram}
          placeholder="e.g. Marriott Bonvoy"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
        />
        <Pressable onPress={() => setShowProgramPicker(true)} hitSlop={8}>
          <ThemedText type="link" style={styles.pickLink}>
            Choose from known programs
          </ThemedText>
        </Pressable>
        <SelectModal
          visible={showProgramPicker}
          onClose={() => setShowProgramPicker(false)}
          options={programOptions}
          selectedValue={knownPrograms.some((r) => r.program === program) ? program : null}
          onSelect={(value) => {
            if (value === OTHER_PROGRAM_VALUE) {
              setProgram('');
              return;
            }
            setProgram(value);
            setProgramType(defaultProgramType(value));
          }}
        />

        <ThemedText type="defaultSemiBold">Type</ThemedText>
        <ThemedView style={styles.chipRow}>
          {PROGRAM_TYPE_OPTIONS.map((option) => {
            const isSelected = option.value === programType;
            return (
              <Pressable
                key={option.value}
                onPress={() => setProgramType(option.value)}
                style={[styles.chip, { borderColor: ACCENT, backgroundColor: isSelected ? ACCENT : 'transparent' }]}>
                <ThemedText style={isSelected ? { color: ModuleAccentOnColor.cards } : undefined}>{option.label}</ThemedText>
              </Pressable>
            );
          })}
        </ThemedView>

        <ThemedText type="defaultSemiBold">Balance</ThemedText>
        <TextInput
          value={balance}
          onChangeText={setBalance}
          placeholder="0"
          keyboardType="decimal-pad"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT, fontFamily: Fonts.mono }]}
        />

        <ThemedText type="defaultSemiBold">Earned through</ThemedText>
        <Pressable onPress={() => setShowCardPicker(true)} style={[styles.input, { borderColor: ACCENT }]}>
          <ThemedText>{linkedCard ? `${linkedCard.issuer} · ${linkedCard.name}` : 'Not earned through a card'}</ThemedText>
        </Pressable>
        <ThemedText style={styles.hint}>
          Link a card so its points show on that card&apos;s page. Hotel and airline accounts you hold directly
          can stay unlinked.
        </ThemedText>
        <SelectModal
          visible={showCardPicker}
          onClose={() => setShowCardPicker(false)}
          options={cardOptions}
          selectedValue={cardId ?? NO_CARD_VALUE}
          onSelect={(value) => setCardId(value === NO_CARD_VALUE ? null : value)}
        />

        <ThemedText type="defaultSemiBold">Member number (optional)</ThemedText>
        <TextInput
          value={memberNumber}
          onChangeText={setMemberNumber}
          placeholder="Loyalty / frequent flyer number"
          autoCapitalize="characters"
          autoCorrect={false}
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT, fontFamily: Fonts.mono }]}
        />

        <ThemedText type="defaultSemiBold">Points expire (optional)</ThemedText>
        <ThemedText style={styles.hint}>
          The date they lapse, or the inactivity deadline that would lapse them. You&apos;ll get a notice 60 days
          out. Usually one small earn or redemption resets the clock.
        </ThemedText>
        <ThemedView style={styles.dateRow}>
          <ThemedView style={styles.dateInput}>
            <DateInput value={expiryDate} onChange={setExpiryDate} accentColor={ACCENT} placeholder="Not set" />
          </ThemedView>
          {expiryDate ? (
            <Pressable onPress={() => setExpiryDate(null)} hitSlop={8}>
              <ThemedText style={{ color: Colors.light.negative }}>Clear</ThemedText>
            </Pressable>
          ) : null}
        </ThemedView>

        <ThemedText type="defaultSemiBold">Notes</ThemedText>
        <TextInput
          value={notes}
          onChangeText={setNotes}
          placeholder="e.g. Gold status through 2027"
          placeholderTextColor={Colors.light.textMuted}
          multiline
          numberOfLines={3}
          style={[styles.input, styles.notesInput, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <Pressable onPress={handleSave} disabled={isSaving} style={[styles.button, { backgroundColor: ACCENT }]}>
          {isSaving ? (
            <ActivityIndicator color={ModuleAccentOnColor.cards} />
          ) : (
            <ThemedText style={{ color: ModuleAccentOnColor.cards, fontWeight: '600' }}>Save</ThemedText>
          )}
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  centered: { alignItems: 'center', justifyContent: 'center' },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  notesInput: {
    minHeight: 72,
    textAlignVertical: 'top',
  },
  pickLink: {
    fontSize: 13,
    marginTop: -4,
    marginBottom: 8,
  },
  chipRow: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
    marginBottom: 8,
  },
  chip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 16,
    paddingHorizontal: 12,
    paddingVertical: 8,
  },
  dateRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
    marginBottom: 8,
  },
  dateInput: {
    flex: 1,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  error: {
    color: Colors.light.negative,
  },
});
