import { daysUntilRenewal } from '@/lib/renewal';
import type { LoyaltyAccountRow } from '@/types/database';

export type LoyaltyProgramType = LoyaltyAccountRow['program_type'];

export const PROGRAM_TYPE_OPTIONS: { value: LoyaltyProgramType; label: string }[] = [
  { value: 'card', label: 'Card' },
  { value: 'hotel', label: 'Hotel' },
  { value: 'airline', label: 'Airline' },
  { value: 'rail', label: 'Rail' },
  { value: 'other', label: 'Other' },
];

export function programTypeLabel(type: LoyaltyProgramType): string {
  return PROGRAM_TYPE_OPTIONS.find((o) => o.value === type)?.label ?? 'Other';
}

/** Same lead time as document expiry — points lapsing is the same "act before a date" problem. */
export const LOYALTY_EXPIRY_NOTICE_WINDOW_DAYS = 60;

/**
 * Best-guess program type from a known program name, so picking "Hilton
 * Honors" from the suggestions doesn't also require choosing "Hotel".
 * Unknown names default to card — historically the only kind tracked.
 */
export function defaultProgramType(program: string): LoyaltyProgramType {
  const p = program.toLowerCase();
  if (/(bonvoy|marriott|hilton|hyatt|ihg|accor|wyndham|choice|best western|radisson|hotel)/.test(p)) return 'hotel';
  if (/(amtrak|eurostar|rail|trenitalia|renfe|sncf|db bahn)/.test(p)) return 'rail';
  if (
    /(miles|skymiles|mileageplus|aadvantage|rapid rewards|flying blue|avios|skywards|etihad|krisflyer|asia miles|aeroplan|trueblue|flying club|air |airways|airline|maharaja|lufthansa|turkish|qantas|ana |jal )/.test(
      p
    )
  ) {
    return 'airline';
  }
  return 'card';
}

/** Accounts whose points lapse within the notice window (already-lapsed ones included), soonest first. */
export function expiringLoyaltyAccounts<T extends Pick<LoyaltyAccountRow, 'expiry_date'>>(rows: T[], today = new Date()): T[] {
  return rows
    .filter((r) => r.expiry_date && daysUntilRenewal(r.expiry_date, today) <= LOYALTY_EXPIRY_NOTICE_WINDOW_DAYS)
    .sort((a, b) => (a.expiry_date! < b.expiry_date! ? -1 : 1));
}
