export const UPCOMING_RENEWAL_WINDOW_DAYS = 30;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

function parseDateOnly(dateString: string): Date {
  const [year, month, day] = dateString.split('-').map(Number);
  return new Date(year, month - 1, day);
}

export type RenewalStatus = 'overdue' | 'upcoming' | 'normal';

export function daysUntilRenewal(renewalDate: string, today: Date = new Date()): number {
  const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const renewal = parseDateOnly(renewalDate);
  return Math.round((renewal.getTime() - todayOnly.getTime()) / MS_PER_DAY);
}

export function renewalStatus(renewalDate: string, today: Date = new Date()): RenewalStatus {
  const days = daysUntilRenewal(renewalDate, today);
  if (days < 0) return 'overdue';
  if (days <= UPCOMING_RENEWAL_WINDOW_DAYS) return 'upcoming';
  return 'normal';
}

/**
 * The next actual due date from a recurring day-of-month: if this month's
 * occurrence hasn't happened yet, that's the next due date; if it already
 * has, roll to next month. A day value beyond a short month's length (e.g.
 * 31 in February) overflows naturally via the Date constructor into the
 * following month — the same "due on the 31st" handling most billing
 * systems use for short months.
 */
export function nextPaymentDueDate(paymentDueDay: number, today: Date = new Date()): Date {
  const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const thisMonthDue = new Date(todayOnly.getFullYear(), todayOnly.getMonth(), paymentDueDay);
  if (thisMonthDue >= todayOnly) return thisMonthDue;
  return new Date(todayOnly.getFullYear(), todayOnly.getMonth() + 1, paymentDueDay);
}

/**
 * Projects a renewal_date's month/day onto `year`'s calendar (ignoring its
 * own year) and returns how far through that year it falls — 0 for Jan 1,
 * just under 1 for Dec 31. Used to position a card's marker along a year
 * timeline regardless of which absolute year the stored date happens to be,
 * since renewal dates recur annually.
 */
export function renewalDayOfYearFraction(renewalDate: string, year: number): number {
  const renewal = parseDateOnly(renewalDate);
  const projected = new Date(year, renewal.getMonth(), renewal.getDate());
  const yearStart = new Date(year, 0, 1);
  const isLeapYear = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const totalDays = isLeapYear ? 366 : 365;
  const dayIndex = Math.round((projected.getTime() - yearStart.getTime()) / MS_PER_DAY);
  return Math.min(Math.max(dayIndex, 0), totalDays - 1) / totalDays;
}
