import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { Pressable, RefreshControl, ScrollView, StyleSheet, View, useWindowDimensions } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { ScopeSwitch } from '@/components/scope-switch';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useScope } from '@/contexts/scope-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { summarizeCardBalances, type CardBalance } from '@/lib/cardBalance';
import { formatMoney } from '@/lib/currency';
import { fetchAllRows } from '@/lib/fetchAll';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import { nextPaymentDueDate, renewalDayOfYearFraction } from '@/lib/renewal';
import { supabase } from '@/lib/supabase';
import type { CreditCardRow, LoyaltyAccountRow, TransactionRow } from '@/types/database';

const ACCENT = ModuleAccents.cards;
const MARKER_SIZE = 22;

function formatTotals(totals: CardBalance[]): string {
  if (totals.length === 0) return formatMoney(0, 'USD');
  return totals.map((t) => formatMoney(t.amount, t.currency)).join(' · ');
}

export default function CardsScreen() {
  const router = useRouter();
  const { convert } = useCurrency();
  const { width: windowWidth } = useWindowDimensions();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const { filterCards, filterTransactions } = useScope();
  const [allCards, setCards] = useState<CreditCardRow[]>([]);
  const [allTransactions, setTransactions] = useState<TransactionRow[]>([]);
  const cards = filterCards(allCards);
  const transactions = filterTransactions(allTransactions);
  const [pointsBalances, setPointsBalances] = useState<LoyaltyAccountRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [cardsResult, transactionsResult, pointsResult] = await Promise.all([
      supabase.from('credit_cards').select('*').order('renewal_date', { ascending: true }),
      fetchAllRows<TransactionRow>((from, to) =>
        supabase.from('transactions').select('*').not('card_id', 'is', null).order('date').order('id').range(from, to)
      ),
      supabase.from('loyalty_accounts').select('*'),
    ]);

    if (cardsResult.error) {
      setError(cardsResult.error.message);
      setIsLoading(false);
      return;
    }

    setCards(cardsResult.data ?? []);
    setTransactions(transactionsResult.data);
    setPointsBalances(pointsResult.data ?? []);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const currentYear = new Date().getFullYear();
  const trackWidth = windowWidth - 32 - MARKER_SIZE;

  const cardBalances = summarizeCardBalances(transactions, convert);

  const totalDebtByCurrency = new Map<string, number>();
  for (const totals of cardBalances.values()) {
    for (const t of totals) {
      totalDebtByCurrency.set(t.currency, (totalDebtByCurrency.get(t.currency) ?? 0) + t.amount);
    }
  }
  const totalDebt = Array.from(totalDebtByCurrency.entries()).map(([currency, amount]) => ({ currency, amount }));

  const pointsByProgram = new Map<string, number>();
  for (const p of pointsBalances) {
    pointsByProgram.set(p.program, (pointsByProgram.get(p.program) ?? 0) + p.balance);
  }
  const programTotals = Array.from(pointsByProgram.entries()).sort((a, b) => b[1] - a[1]);

  function pointsForCard(cardId: string): number {
    return pointsBalances.filter((p) => p.card_id === cardId).reduce((sum, p) => sum + p.balance, 0);
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel
        connections={swipeConnections}
        isLoading={isConnectionsLoading}
        accentColor={ACCENT}
        destinationModule="cards">
      <ScrollView
        contentContainerStyle={styles.content}
        refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
        <ScopeSwitch accent={ACCENT} onColor={ModuleAccentOnColor.cards} />
        <ThemedText type="title" style={{ color: ACCENT }}>
          Credit Cards
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {cards.length === 0 && !isLoading ? (
          <ThemedText style={styles.muted}>No cards yet. Add your first one below.</ThemedText>
        ) : null}

        {cards.length > 0 ? (
          <Surface accentColor={ACCENT}>
            <ThemedText style={styles.muted}>{currentYear} renewals</ThemedText>
            <View style={[styles.timelineTrack, { marginHorizontal: MARKER_SIZE / 2 }]}>
              <View style={styles.timelineLine} />
              {cards.map((card) => {
                const fraction = renewalDayOfYearFraction(card.renewal_date, currentYear);
                return (
                  <Pressable
                    key={card.id}
                    onPress={() => router.push(`/cards/${card.id}`)}
                    hitSlop={8}
                    style={[styles.timelineMarker, { left: fraction * trackWidth }]}>
                    <IconSymbol name="creditcard" size={14} color={ModuleAccentOnColor.cards} />
                  </Pressable>
                );
              })}
            </View>
            <ThemedView style={styles.timelineLabels}>
              <ThemedText style={styles.timelineLabel}>Jan</ThemedText>
              <ThemedText style={styles.timelineLabel}>Apr</ThemedText>
              <ThemedText style={styles.timelineLabel}>Jul</ThemedText>
              <ThemedText style={styles.timelineLabel}>Oct</ThemedText>
            </ThemedView>
          </Surface>
        ) : null}

        <ThemedView style={styles.tierTwoRow}>
          <Pressable style={styles.tierTwoTile} onPress={() => router.push('/cards/points')}>
            <Surface accentColor={ACCENT}>
              <ThemedText style={styles.muted}>Total Points</ThemedText>
              {programTotals.length === 0 ? (
                <ThemedText type="mono" style={styles.tierTwoValue}>
                  0
                </ThemedText>
              ) : programTotals.length === 1 ? (
                <ThemedText type="mono" style={styles.tierTwoValue} numberOfLines={1} adjustsFontSizeToFit>
                  {programTotals[0][1].toLocaleString()}
                </ThemedText>
              ) : (
                programTotals.map(([program, balance]) => (
                  <ThemedView key={program} style={styles.programRow}>
                    <ThemedText style={styles.programName} numberOfLines={1}>
                      {program}
                    </ThemedText>
                    <ThemedText type="mono" style={styles.programValue}>
                      {balance.toLocaleString()}
                    </ThemedText>
                  </ThemedView>
                ))
              )}
            </Surface>
          </Pressable>

          <Pressable style={styles.tierTwoTile} onPress={() => router.push('/cards/spend?view=transactions')}>
            <Surface accentColor={ACCENT}>
              <ThemedText style={styles.muted}>Current Debt</ThemedText>
              <ThemedText type="mono" style={styles.tierTwoValue} numberOfLines={1} adjustsFontSizeToFit>
                {formatTotals(totalDebt)}
              </ThemedText>
            </Surface>
          </Pressable>
        </ThemedView>

        {cards.length > 0 ? (
          <Pressable onPress={() => router.push('/cards/float')}>
            <Surface accentColor={ACCENT} style={styles.cardRow}>
              <ThemedView style={styles.cardInfo}>
                <ThemedText type="defaultSemiBold">Pay Bills From</ThemedText>
                <ThemedText style={styles.muted}>Which account to pay each card from, to leverage float.</ThemedText>
              </ThemedView>
            </Surface>
          </Pressable>
        ) : null}

        <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
          Your cards
        </ThemedText>
        {cards.map((card) => {
          const balance = cardBalances.get(card.id) ?? [];
          const dueDate = card.payment_due_day ? nextPaymentDueDate(card.payment_due_day) : null;
          const points = pointsForCard(card.id);
          return (
            <Pressable key={card.id} onPress={() => router.push(`/cards/${card.id}`)}>
              <Surface accentColor={ACCENT} style={styles.cardRow}>
                <ThemedView style={[styles.cardIconBox, { backgroundColor: ACCENT }]}>
                  <IconSymbol name="creditcard" size={22} color={ModuleAccentOnColor.cards} />
                </ThemedView>
                <ThemedView style={styles.cardInfo}>
                  <ThemedText type="defaultSemiBold" numberOfLines={1}>
                    {card.issuer} · {card.name}
                  </ThemedText>
                  <ThemedText type="mono" style={styles.muted}>
                    {formatTotals(balance)} owed
                  </ThemedText>
                  <ThemedText type="mono" style={styles.muted}>
                    {dueDate ? `Due ${formatDateDisplay(toDateOnlyString(dueDate))}` : 'Payment due day not set'}
                  </ThemedText>
                  <ThemedText type="mono" style={styles.muted}>
                    {points.toLocaleString()} points
                  </ThemedText>
                </ThemedView>
              </Surface>
            </Pressable>
          );
        })}
      </ScrollView>

      <Pressable onPress={() => router.push('/cards/new/edit')} style={[styles.fab, { backgroundColor: ACCENT }]}>
        <IconSymbol name="plus" size={28} color={ModuleAccentOnColor.cards} />
      </Pressable>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 96,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  timelineTrack: {
    height: MARKER_SIZE,
    justifyContent: 'center',
    marginTop: 8,
    marginBottom: 4,
  },
  timelineLine: {
    position: 'absolute',
    left: 0,
    right: 0,
    height: StyleSheet.hairlineWidth * 2,
    backgroundColor: Colors.light.tint,
  },
  timelineMarker: {
    position: 'absolute',
    width: MARKER_SIZE,
    height: MARKER_SIZE,
    borderRadius: MARKER_SIZE / 2,
    backgroundColor: ACCENT,
    alignItems: 'center',
    justifyContent: 'center',
  },
  timelineLabels: {
    flexDirection: 'row',
    justifyContent: 'space-between',
  },
  timelineLabel: {
    fontSize: 11,
    opacity: 0.6,
    color: Colors.light.textMuted,
  },
  tierTwoRow: {
    flexDirection: 'row',
    gap: 8,
  },
  tierTwoTile: {
    flex: 1,
    gap: 4,
  },
  tierTwoValue: {
    fontSize: 20,
  },
  programRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    gap: 8,
  },
  programName: {
    flex: 1,
    fontSize: 13,
    opacity: 0.7,
    color: Colors.light.textMuted,
  },
  programValue: {
    fontSize: 13,
  },
  cardRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
  },
  cardIconBox: {
    width: 48,
    height: 48,
    borderRadius: 10,
    alignItems: 'center',
    justifyContent: 'center',
  },
  cardInfo: {
    flex: 1,
    gap: 2,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
  fab: {
    position: 'absolute',
    right: 20,
    bottom: 28,
    width: 56,
    height: 56,
    borderRadius: 28,
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: '#000',
    shadowOpacity: 0.2,
    shadowRadius: 6,
    shadowOffset: { width: 0, height: 3 },
    elevation: 4,
  },
});
