import { Platform, StyleSheet, View, type ViewProps } from 'react-native';
import { KeyboardAvoidingView } from 'react-native-keyboard-controller';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { GradientBackground } from '@/components/gradient-background';
import { useThemeColor } from '@/hooks/use-theme-color';

export type ThemedViewProps = ViewProps & {
  lightColor?: string;
  darkColor?: string;
  /** 'screen' renders the shared gradient backdrop behind this view — use for a screen's root container only, never nested layout wrappers. */
  variant?: 'screen' | 'plain';
  /**
   * Set false to skip the built-in KeyboardAvoidingView wrapper on the
   * 'screen' variant — for screens that handle keyboard avoidance
   * themselves with a more targeted tool (e.g. KeyboardStickyView around
   * just a composer bar), where the generic whole-screen shrink would
   * double up with it. Defaults to true.
   */
  keyboardAvoiding?: boolean;
};

export function ThemedView({
  style,
  lightColor,
  darkColor,
  variant = 'plain',
  keyboardAvoiding = true,
  children,
  ...otherProps
}: ThemedViewProps) {
  const backgroundColor = useThemeColor({ light: lightColor, dark: darkColor }, 'background');
  const insets = useSafeAreaInsets();

  if (variant === 'screen') {
    return (
      <View style={styles.screen}>
        <GradientBackground />
        {/* insets.bottom on this OUTER box (never touched by a caller's own
            style) keeps it independent of the KeyboardAvoidingView below —
            a static safe-area floor so bottom-pinned content (FABs, the
            last item in a ScrollView) clears the system nav bar/gesture
            pill, and — per the user's report — an Android "taskbar" some
            phones let you pin across every app, which eats into the same
            bottom inset space. Applied here rather than per-screen since
            nearly every screen already roots on this variant. */}
        <View style={[styles.screenContent, { paddingBottom: insets.bottom }]}>
          {/* Keyboard avoidance was previously bolted on ad hoc per-screen
              (only 2 of dozens of form screens had it) — centralizing here
              means every TextInput in the app now gets out from under the
              keyboard for free. RN core's KeyboardAvoidingView never worked
              reliably here (this app's edge-to-edge Android config is a
              documented weak spot for it), so this is
              react-native-keyboard-controller's version instead, backed by
              the KeyboardProvider in app/_layout.tsx. Screens with a more
              specific need (a composer bar stuck to the keyboard, e.g.)
              should set keyboardAvoiding={false} here and use that
              library's KeyboardStickyView directly instead — layering both
              risks double-compensating for the same keyboard event. */}
          {keyboardAvoiding ? (
            <KeyboardAvoidingView
              style={[styles.screenContent, style]}
              behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
              {...otherProps}>
              {children}
            </KeyboardAvoidingView>
          ) : (
            <View style={[styles.screenContent, style]} {...otherProps}>
              {children}
            </View>
          )}
        </View>
      </View>
    );
  }

  return (
    <View style={[{ backgroundColor }, style]} {...otherProps}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1 },
  screenContent: { flex: 1 },
});
