import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, TextInput } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { supabase } from '@/lib/supabase';

const TINT = Colors.light.tint;

/**
 * Shown instead of the protected app when a session exists at aal1 but the
 * account has a verified TOTP factor requiring aal2 (app/_layout.tsx's
 * mfaRequired guard) — the step-up prompt for the code from the user's
 * authenticator app. Not reachable for accounts with no MFA factor
 * enrolled, since mfaRequired is false for them from the moment they sign
 * in (see contexts/auth-context.tsx's refreshMfaStatus).
 */
export default function MfaChallengeScreen() {
  const { signOut, refreshMfaStatus } = useAuth();
  const [factorId, setFactorId] = useState<string | null>(null);
  const [code, setCode] = useState('');
  const [isVerifying, setIsVerifying] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    supabase.auth.mfa.listFactors().then(({ data, error: listError }) => {
      if (listError) {
        setError(listError.message);
        return;
      }
      const verifiedTotp = data?.totp[0];
      if (!verifiedTotp) {
        // Shouldn't happen — mfaRequired is only true when a verified
        // factor exists — but fail safe with a clear message rather than a
        // stuck spinner if it somehow does.
        setError('No verified authenticator found for this account.');
        return;
      }
      setFactorId(verifiedTotp.id);
    });
  }, []);

  async function handleVerify() {
    if (!factorId || code.trim().length !== 6) {
      setError('Enter the 6-digit code from your authenticator app.');
      return;
    }
    setError(null);
    setIsVerifying(true);
    const { error: verifyError } = await supabase.auth.mfa.challengeAndVerify({ factorId, code: code.trim() });
    setIsVerifying(false);
    if (verifyError) {
      setError(verifyError.message);
      return;
    }
    await refreshMfaStatus();
  }

  return (
    <ThemedView variant="screen" style={styles.container}>
      <ThemedText type="title" style={{ color: TINT }}>
        Two-Factor Verification
      </ThemedText>
      <ThemedText style={styles.muted}>Enter the 6-digit code from your authenticator app.</ThemedText>
      {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

      <TextInput
        value={code}
        onChangeText={(text) => setCode(text.replace(/\D/g, '').slice(0, 6))}
        placeholder="123456"
        placeholderTextColor={Colors.light.textMuted}
        keyboardType="number-pad"
        maxLength={6}
        autoFocus
        style={[styles.input, { color: Colors.light.text, borderColor: TINT }]}
      />

      <Pressable onPress={handleVerify} disabled={isVerifying || !factorId} style={[styles.button, { backgroundColor: TINT }]}>
        {isVerifying ? (
          <ActivityIndicator color={Colors.light.backgroundSolid} />
        ) : (
          <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Verify</ThemedText>
        )}
      </Pressable>

      <Pressable onPress={() => signOut()} hitSlop={12} style={styles.signOutLink}>
        <ThemedText type="link">Sign out instead</ThemedText>
      </Pressable>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    padding: 24,
    gap: 12,
  },
  muted: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 8,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 14,
    fontSize: 22,
    letterSpacing: 6,
    textAlign: 'center',
    marginBottom: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
  },
  signOutLink: {
    marginTop: 16,
    alignItems: 'center',
  },
  error: {
    color: Colors.light.negative,
  },
});
