import { useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, Share, StyleSheet } from 'react-native';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { supabase } from '@/lib/supabase';

const TINT = Colors.light.tint;

// Excludes visually ambiguous characters (0/O, 1/I/L) so a code is easy to
// read back over a phone call or a screenshot.
const CODE_CHARSET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';

function generateReferralCode(length = 8): string {
  let code = '';
  for (let i = 0; i < length; i++) {
    code += CODE_CHARSET[Math.floor(Math.random() * CODE_CHARSET.length)];
  }
  return code;
}

export default function ReferralsScreen() {
  const router = useRouter();
  const { session } = useAuth();

  const [referralCode, setReferralCode] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!session) return;
    let cancelled = false;

    async function ensureReferralCode() {
      const { data, error: fetchError } = await supabase
        .from('user_settings')
        .select('referral_code')
        .eq('user_id', session!.user.id)
        .maybeSingle();

      if (cancelled) return;
      if (fetchError) {
        setError(fetchError.message);
        setIsLoading(false);
        return;
      }
      if (data?.referral_code) {
        setReferralCode(data.referral_code);
        setIsLoading(false);
        return;
      }

      // No code yet — generate one and store it, retrying on the rare
      // collision against another user's code (referral_code is unique).
      for (let attempt = 0; attempt < 5; attempt++) {
        const candidate = generateReferralCode();
        const { error: upsertError } = await supabase
          .from('user_settings')
          .upsert({ user_id: session!.user.id, referral_code: candidate }, { onConflict: 'user_id' });

        if (cancelled) return;
        if (!upsertError) {
          setReferralCode(candidate);
          setIsLoading(false);
          return;
        }
        if (upsertError.code !== '23505') {
          setError(upsertError.message);
          setIsLoading(false);
          return;
        }
      }
      setError('Could not generate a unique referral code. Try again.');
      setIsLoading(false);
    }

    ensureReferralCode();
    return () => {
      cancelled = true;
    };
  }, [session]);

  async function handleShare() {
    if (!referralCode) return;
    try {
      await Share.share({
        message: `Join me on Cluster! Use my referral code ${referralCode} when you sign up.`,
      });
    } catch (shareError) {
      setError(shareError instanceof Error ? shareError.message : 'Could not open share sheet.');
    }
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ThemedView style={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: TINT }}>
            Referrals
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {isLoading ? (
          <ActivityIndicator color={TINT} />
        ) : referralCode ? (
          <>
            <Surface accentColor={TINT} style={styles.codeCard}>
              <ThemedText style={styles.muted}>Your referral code</ThemedText>
              <ThemedText type="title" style={styles.code}>
                {referralCode}
              </ThemedText>
            </Surface>

            <Pressable onPress={handleShare} style={[styles.button, { backgroundColor: TINT }]}>
              <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Share</ThemedText>
            </Pressable>
          </>
        ) : null}
      </ThemedView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 12,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  codeCard: {
    alignItems: 'center',
    gap: 4,
  },
  code: {
    letterSpacing: 4,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
