import type { StyleSpecification } from '@maplibre/maplibre-gl-style-spec';
import { Camera, GeoJSONSource, Layer, Map as MapLibreMap } from '@maplibre/maplibre-react-native';
import { useEffect, useMemo, useState } from 'react';
import { StyleSheet, View, type NativeSyntheticEvent, type StyleProp, type ViewStyle } from 'react-native';

import { countryNameForMapId, type visitedMapIds } from '@/lib/worldMapData';
import { countryLabelPoints, statusTaggedBoundaries } from '@/lib/worldBoundaries';
import { countryFillColorExpression, FILL_INSERT_BEFORE_LAYER_ID, loadMapStyle, PAINTED_COUNTRY_FILTER } from '@/lib/worldMapStyle';

const MAP_HEIGHT = 420;

/**
 * The passport map's Countries/Cities tabs — a real MapLibre Native map
 * (OpenFreeMap's free "Positron" vector tiles, see lib/worldMapStyle.ts)
 * with genuine pan/zoom/detail, not a flat SVG scale transform. Country
 * shapes are our own accurate boundary data (lib/worldBoundaries.ts),
 * colored per visited/pending/unvisited status via a data-driven fill
 * layer, with a symbol layer drawing each country's name from this app's
 * own English names (never the basemap's own, locally-languaged place
 * labels) — MapLibre's own built-in label collision detection keeps
 * these from overlapping, so unlike the flat map's labels this needed no
 * hand-rolled collision-avoidance pass at all.
 *
 * This is the one component in the app that needs a native module
 * (@maplibre/maplibre-react-native) rather than pure JS — see
 * app.config.js's own comment on why that means a fresh EAS build to
 * reach a device, not just an OTA push.
 */
export function WorldPassportMap({
  visitedIds,
  pendingIds,
  accentColor,
  pendingColor,
  onSelectCountry,
  style,
  height = MAP_HEIGHT,
  interactive = true,
}: {
  visitedIds: ReturnType<typeof visitedMapIds>;
  pendingIds: ReturnType<typeof visitedMapIds>;
  accentColor: string;
  pendingColor: string;
  onSelectCountry: (countryName: string) => void;
  style?: StyleProp<ViewStyle>;
  height?: number;
  /** False for the embedded card on app/countries/passport.tsx's regular
   * (non-fullscreen) layout — that card sits inside the screen's own
   * outer ScrollView, where its drag-to-pan gesture competes with the
   * ScrollView's own scroll gesture (confirmed directly: a real user
   * report of not being able to pan the embedded map at all). The
   * fullscreen modal view isn't inside a competing ScrollView, so it
   * stays fully interactive — same "glance and tap, open fullscreen
   * for the real thing" split multi-trip-route-map.tsx already uses
   * unconditionally for its own always-a-card presentation. */
  interactive?: boolean;
}) {
  // statusTaggedBoundaries re-maps all 196 countries' full geometry (now
  // ~85,000 points, ~7MB — raised from 18,000 this same session, once
  // react-native-maps' native Polygon renderer was replaced by MapLibre).
  // Rebuilding and reassigning that whole object on every render — as a
  // plain `const` here previously did — meant the native GeoJSONSource
  // below got a brand-new `data` reference, and therefore re-sent the
  // entire multi-megabyte payload across the native bridge, on literally
  // any re-render of this component: a parent state change, a tab
  // switch, the initial data load resolving, anything. Cheap on web (same
  // JS context, a fast desktop CPU in every headless-browser check this
  // session) but a real freeze on an actual Android device, where
  // repeatedly re-serializing ~7MB across the bridge blocks the UI
  // thread. Memoizing on the actual visited/pending Sets means this only
  // recomputes when a country's status genuinely changes.
  const data = useMemo(() => statusTaggedBoundaries(visitedIds, pendingIds), [visitedIds, pendingIds]);
  const labelData = useMemo(() => countryLabelPoints(), []);
  // Pre-built (English labels forced, basemap's own country-name layers
  // stripped) — see lib/worldMapStyle.ts's loadMapStyle for why this has
  // to happen before the map ever sees the style, not after loading it
  // from a plain URL the way the map's own onDidFinishLoadingStyle event
  // might suggest (MapLibre Native's React component exposes no
  // imperative way to reach into an already-loaded style and patch
  // individual layers the way web's maplibre-gl does).
  const [mapStyle, setMapStyle] = useState<StyleSpecification | null>(null);
  useEffect(() => {
    let cancelled = false;
    loadMapStyle().then((loaded) => {
      if (!cancelled) setMapStyle(loaded);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  function handlePress(event: NativeSyntheticEvent<{ features: GeoJSON.Feature[] }>) {
    const code = event.nativeEvent.features[0]?.properties?.code as string | undefined;
    const countryName = code ? countryNameForMapId(code) : null;
    if (countryName) onSelectCountry(countryName);
  }

  if (!mapStyle) {
    return <View style={[styles.container, { height }, style]} />;
  }

  // @maplibre/maplibre-react-native has a documented native crash (both
  // iOS and Android — github.com/maplibre/maplibre-react-native#1293)
  // when some <Layer>s in the same map have a beforeId/afterId prop and
  // others don't — exactly what countries-fill/countries-line (beforeId,
  // added for the fill-under-roads-and-labels fix) vs. countries-label
  // (previously neither) were doing. Giving the label layer an explicit
  // afterId pointing at the style's own last layer keeps it in the exact
  // same visual position it already had (appended on top of everything,
  // which is what no prop at all also does) while satisfying the "every
  // layer needs the prop" workaround the issue describes.
  const lastBaseLayerId = mapStyle.layers[mapStyle.layers.length - 1]?.id;

  return (
    <View style={[styles.container, { height }, style]}>
      <MapLibreMap
        style={styles.map}
        mapStyle={mapStyle}
        compass={false}
        scaleBar={false}
        logo={false}
        dragPan={interactive}
        touchZoom={interactive}
        touchRotate={interactive}
        touchPitch={interactive}>
        <Camera initialViewState={{ center: [0, 20], zoom: 1.2 }} minZoom={1} maxZoom={14} />
        {/* Only visited/pending countries get drawn at all — see
            lib/worldMapStyle.ts's PAINTED_COUNTRY_FILTER comment on why an
            unvisited country shows nothing but the clean basemap
            underneath, rather than a gray tint over the whole rest of the
            world. */}
        <GeoJSONSource id="countries" data={data} onPress={handlePress}>
          <Layer
            id="countries-fill"
            type="fill"
            filter={PAINTED_COUNTRY_FILTER}
            beforeId={FILL_INSERT_BEFORE_LAYER_ID}
            paint={{
              'fill-color': countryFillColorExpression(accentColor, pendingColor),
              'fill-opacity': 0.75,
            }}
          />
          <Layer
            id="countries-line"
            type="line"
            filter={PAINTED_COUNTRY_FILTER}
            beforeId={FILL_INSERT_BEFORE_LAYER_ID}
            paint={{ 'line-color': countryFillColorExpression(accentColor, pendingColor), 'line-width': 1 }}
          />
        </GeoJSONSource>
        {/* A separate point source, not the polygon boundaries above — one
            label per country at its largest landmass's centroid (see
            lib/worldBoundaries.ts's countryLabelPoints), rather than one
            label per polygon PART, which repeated a sprawling
            archipelago's name six-plus times across the map (confirmed
            against a real render). */}
        <GeoJSONSource id="country-labels" data={labelData}>
          <Layer
            id="countries-label"
            type="symbol"
            afterId={lastBaseLayerId}
            layout={{
              'text-field': ['get', 'name'],
              'text-size': 12,
              'text-font': ['Noto Sans Regular'],
            }}
            paint={{ 'text-color': '#1A241F', 'text-halo-color': '#FBFBF9', 'text-halo-width': 1.2 }}
          />
        </GeoJSONSource>
      </MapLibreMap>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 12,
    overflow: 'hidden',
  },
  map: {
    flex: 1,
  },
});
