import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet } from 'react-native';

import { CategoryPieChart } from '@/components/category-pie-chart';
import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { ScopeSwitch } from '@/components/scope-switch';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useScope } from '@/contexts/scope-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { latestSnapshotByAccount, transactionSumByAccount } from '@/lib/accountBalance';
import { summarizeCardBalances } from '@/lib/cardBalance';
import { formatMoney } from '@/lib/currency';
import { computeCurrencyExposure } from '@/lib/currencyExposure';
import { fetchAllRows } from '@/lib/fetchAll';
import { supabase } from '@/lib/supabase';
import { resolveWealthCurrency } from '@/lib/wealthCurrency';
import type { AccountRow, BalanceSnapshotRow, TransactionRow } from '@/types/database';

const ACCENT = ModuleAccents.wealth;

// Passed to summarizeCardBalances instead of the real convert() so it
// returns native, unconverted per-currency totals rather than collapsing
// everything into one currency — this screen needs to know exactly how
// much is held/owed in each currency, not a blended total.
function identityConvert(amount: number, currency: string) {
  return { amount, currency };
}

export default function CurrencyExposureScreen() {
  const router = useRouter();
  const { displayCurrency, homeCountry, availableCurrencies, convertToCurrency } = useCurrency();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const { filterAccounts, filterSnapshots, filterTransactions, filterAccountLinked } = useScope();
  const [allAccounts, setAccounts] = useState<AccountRow[]>([]);
  const [allSnapshots, setSnapshots] = useState<BalanceSnapshotRow[]>([]);
  const [allAccountTx, setAccountTx] = useState<{ account_id: string | null; amount: number }[]>([]);
  const [allCardTx, setCardTx] = useState<TransactionRow[]>([]);
  const accounts = filterAccounts(allAccounts);
  const snapshots = filterSnapshots(allSnapshots);
  const accountTx = filterAccountLinked(allAccountTx);
  const cardTx = filterTransactions(allCardTx);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [accountsResult, snapshotsResult, accountTxResult, cardTxResult] = await Promise.all([
      supabase.from('accounts').select('*'),
      fetchAllRows<BalanceSnapshotRow>((from, to) =>
        supabase.from('balance_snapshots').select('*').order('date', { ascending: false }).order('id').range(from, to)
      ),
      fetchAllRows<{ account_id: string | null; amount: number }>((from, to) =>
        supabase
          .from('transactions')
          .select('account_id, amount')
          .not('account_id', 'is', null)
          .order('date')
          .order('id')
          .range(from, to)
      ),
      fetchAllRows<TransactionRow>((from, to) =>
        supabase.from('transactions').select('*').not('card_id', 'is', null).order('date').order('id').range(from, to)
      ),
    ]);

    if (accountsResult.error) {
      setError(accountsResult.error.message);
      setIsLoading(false);
      return;
    }

    setAccounts(accountsResult.data ?? []);
    setSnapshots(snapshotsResult.data);
    setAccountTx(accountTxResult.data);
    setCardTx(cardTxResult.data);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  // Same "Local isn't coherent for a blended calculation" reasoning as the
  // wealth chart — percentages need one real reference currency to compute in.
  const referenceCurrency = resolveWealthCurrency(displayCurrency, homeCountry, availableCurrencies);

  const latestSnapshots = latestSnapshotByAccount(snapshots);
  const txSums = transactionSumByAccount(accountTx);
  const accountBalances = new Map<string, number>();
  for (const account of accounts) {
    if (account.tracking_method === 'balance_based') {
      accountBalances.set(account.id, latestSnapshots.get(account.id)?.balance ?? 0);
    } else {
      accountBalances.set(account.id, txSums.get(account.id) ?? 0);
    }
  }

  const cardDebtByCurrencyMap = summarizeCardBalances(cardTx, identityConvert);
  const cardDebtByCurrency: { currency: string; amount: number }[] = [];
  for (const totals of cardDebtByCurrencyMap.values()) {
    for (const t of totals) {
      const existing = cardDebtByCurrency.find((c) => c.currency === t.currency);
      if (existing) existing.amount += t.amount;
      else cardDebtByCurrency.push({ ...t });
    }
  }

  const exposure = computeCurrencyExposure(accounts, accountBalances, cardDebtByCurrency, (amount, from) =>
    convertToCurrency(amount, from, referenceCurrency.currency)
  );

  const pieSlices = exposure
    .filter((e) => e.referenceAmount > 0)
    .map((e) => ({ label: e.currency, amount: e.referenceAmount, currency: referenceCurrency.currency }));

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView
        contentContainerStyle={styles.content}
        refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
        <ScopeSwitch accent={ACCENT} />
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Currency Exposure
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
        <ThemedText style={styles.hint}>
          Share of total net worth (accounts minus card debt) held in each currency, valued in{' '}
          {referenceCurrency.currency}.
        </ThemedText>

        {exposure.length === 0 ? (
          <ThemedText style={styles.muted}>No accounts or cards yet.</ThemedText>
        ) : (
          <>
            <CategoryPieChart slices={pieSlices} />

            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              By currency
            </ThemedText>
            {exposure.map((entry) => (
              <Surface key={entry.currency} accentColor={ACCENT}>
                <ThemedView style={styles.rowBetween}>
                  <ThemedText type="defaultSemiBold">{entry.currency}</ThemedText>
                  <ThemedText type="mono" style={entry.nativeAmount < 0 ? styles.negative : undefined}>
                    {formatMoney(entry.nativeAmount, entry.currency)}
                  </ThemedText>
                </ThemedView>
                <ThemedText style={entry.percentage < 0 ? styles.negative : styles.muted}>
                  {entry.percentage.toFixed(1)}% of net worth
                </ThemedText>
              </Surface>
            ))}
          </>
        )}
      </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  centered: { alignItems: 'center', justifyContent: 'center' },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  rowBetween: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 4,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  negative: {
    color: Colors.light.negative,
  },
  error: {
    color: Colors.light.negative,
  },
});
