import type { SwipeConnection } from '@/components/connections-swipe-panel';
import { formatMoney } from '@/lib/currency';
import { documentTypeLabel } from '@/lib/documents';
import { formatDateDisplay } from '@/lib/format';
import { supabase } from '@/lib/supabase';

export type SearchResultItem = { id: string; title: string; subtitle: string; href: string };
export type SearchResultSection = { key: string; label: string; items: SearchResultItem[] };

const RESULTS_PER_CATEGORY = 8;

function dedupeById<T extends { id: string }>(...lists: T[][]): T[] {
  const seen = new Map<string, T>();
  for (const list of lists) {
    for (const item of list) {
      if (!seen.has(item.id)) seen.set(item.id, item);
    }
  }
  return Array.from(seen.values());
}

/**
 * Cross-module search — one plain .ilike() query per searched column,
 * rather than a single .or() filter string. PostgREST's or= syntax is its
 * own mini-DSL where commas and parens are meaningful; embedding a raw user
 * query into that string would both break on ordinary search terms
 * containing those characters and, in principle, let a crafted query
 * smuggle in extra filter clauses. Per-column matches are merged and
 * de-duped client-side instead — RLS still scopes every query to the
 * caller's own rows regardless.
 */
export async function runGlobalSearch(query: string, connections: SwipeConnection[]): Promise<SearchResultSection[]> {
  const pattern = `%${query}%`;

  const [
    txByMerchant,
    txByNotes,
    docsByName,
    visitsByCountry,
    visitsByCity,
    cardsByIssuer,
    cardsByName,
    accountsByName,
    accountsByInstitution,
  ] = await Promise.all([
    supabase
      .from('transactions')
      .select('id, merchant, notes, date, amount, currency')
      .ilike('merchant', pattern)
      .limit(RESULTS_PER_CATEGORY),
    supabase
      .from('transactions')
      .select('id, merchant, notes, date, amount, currency')
      .ilike('notes', pattern)
      .limit(RESULTS_PER_CATEGORY),
    supabase.from('documents').select('id, name, doc_type').ilike('name', pattern).limit(RESULTS_PER_CATEGORY),
    supabase
      .from('countries_visited')
      .select('id, trip_id, country, city, entry_date')
      .ilike('country', pattern)
      .limit(RESULTS_PER_CATEGORY),
    supabase
      .from('countries_visited')
      .select('id, trip_id, country, city, entry_date')
      .ilike('city', pattern)
      .limit(RESULTS_PER_CATEGORY),
    supabase.from('credit_cards').select('id, issuer, name').ilike('issuer', pattern).limit(RESULTS_PER_CATEGORY),
    supabase.from('credit_cards').select('id, issuer, name').ilike('name', pattern).limit(RESULTS_PER_CATEGORY),
    supabase.from('accounts').select('id, name, institution').ilike('name', pattern).limit(RESULTS_PER_CATEGORY),
    supabase
      .from('accounts')
      .select('id, name, institution')
      .ilike('institution', pattern)
      .limit(RESULTS_PER_CATEGORY),
  ]);

  const txItems: SearchResultItem[] = dedupeById(txByMerchant.data ?? [], txByNotes.data ?? [])
    .slice(0, RESULTS_PER_CATEGORY)
    .map((t) => ({
      id: t.id,
      title: t.merchant?.trim() || 'Transaction',
      subtitle: `${formatDateDisplay(t.date)} · ${formatMoney(t.amount, t.currency)}`,
      href: `/transactions/${t.id}`,
    }));

  const docItems: SearchResultItem[] = (docsByName.data ?? []).map((d) => ({
    id: d.id,
    title: d.name,
    subtitle: documentTypeLabel(d.doc_type),
    href: `/documents/${d.id}`,
  }));

  // Trips and standalone (ungrouped) visits share the same underlying
  // countries_visited rows — a match navigates to the trip if this stop
  // belongs to one, otherwise straight to the visit itself.
  const travelItems: SearchResultItem[] = dedupeById(visitsByCountry.data ?? [], visitsByCity.data ?? [])
    .slice(0, RESULTS_PER_CATEGORY)
    .map((v) => ({
      id: v.id,
      title: v.city?.trim() || v.country,
      subtitle: v.city?.trim() ? v.country : formatDateDisplay(v.entry_date),
      href: v.trip_id ? `/countries/trips/${v.trip_id}` : `/countries/visit/${v.id}`,
    }));

  const cardItems: SearchResultItem[] = dedupeById(cardsByIssuer.data ?? [], cardsByName.data ?? [])
    .slice(0, RESULTS_PER_CATEGORY)
    .map((c) => ({
      id: c.id,
      title: `${c.issuer} ${c.name}`.trim(),
      subtitle: 'Credit card',
      href: `/cards/${c.id}`,
    }));

  const accountItems: SearchResultItem[] = dedupeById(accountsByName.data ?? [], accountsByInstitution.data ?? [])
    .slice(0, RESULTS_PER_CATEGORY)
    .map((a) => ({
      id: a.id,
      title: a.name,
      subtitle: a.institution?.trim() || 'Account',
      href: `/accounts/${a.id}`,
    }));

  // No searchable name column on connections server-side (display names are
  // resolved client-side from profile + override data) — filtering the
  // already-loaded, small accepted-connections list is simpler and cheap
  // enough than adding a dedicated RPC just for this.
  const lowerQuery = query.toLowerCase();
  const connectionItems: SearchResultItem[] = connections
    .filter((c) => c.displayName.toLowerCase().includes(lowerQuery))
    .slice(0, RESULTS_PER_CATEGORY)
    .map((c) => ({
      id: c.id,
      title: c.displayName,
      subtitle: 'Connection',
      href: `/connections/${c.id}/travel`,
    }));

  return [
    { key: 'transactions', label: 'Transactions', items: txItems },
    { key: 'documents', label: 'Documents', items: docItems },
    { key: 'travel', label: 'Travel', items: travelItems },
    { key: 'cards', label: 'Cards', items: cardItems },
    { key: 'accounts', label: 'Accounts', items: accountItems },
    { key: 'connections', label: 'Connections', items: connectionItems },
  ].filter((section) => section.items.length > 0);
}
