import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { CountryFlag } from '@/components/country-flag';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { formatMoney } from '@/lib/currency';
import { formatDateDisplay } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import { computeTripBudget } from '@/lib/tripBudget';
import { computeTripSummaries } from '@/lib/trips';
import type { CountryVisitedRow, TransactionRow, TripRow, TripSegmentRow } from '@/types/database';

const ACCENT = ModuleAccents.countries;
const STAIRCASE_STEP = 14;
const MAX_STAIRCASE_STEPS = 5;

function formatTotals(totals: { currency: string; amount: number }[]): string | null {
  if (totals.length === 0) return null;
  return totals.map((t) => formatMoney(t.amount, t.currency)).join(' · ');
}

export default function TripGraphScreen() {
  const { tripId } = useLocalSearchParams<{ tripId: string }>();
  const router = useRouter();
  const { hiddenFlagCountries, convert } = useCurrency();

  const [trip, setTrip] = useState<TripRow | null>(null);
  const [stops, setStops] = useState<CountryVisitedRow[]>([]);
  const [segments, setSegments] = useState<TripSegmentRow[]>([]);
  const [linkedExpenses, setLinkedExpenses] = useState<TransactionRow[]>([]);
  const [isCollaboratorView, setIsCollaboratorView] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [tripResult, stopsResult, segmentsResult, expensesResult] = await Promise.all([
      supabase.from('trips').select('*').eq('id', tripId).single(),
      supabase.from('countries_visited').select('*').eq('trip_id', tripId).order('entry_date'),
      supabase.from('trip_segments').select('*').eq('trip_id', tripId),
      // Same "fetch everything linked, filter by this trip's own stop/segment
      // ids client-side" approach as app/countries/trips/[id].tsx, rather
      // than an .in() query that has to guard against an empty id list.
      supabase.from('transactions').select('*').or('trip_stop_id.not.is.null,trip_segment_id.not.is.null'),
    ]);
    if (!tripResult.error) {
      // I own this trip directly — the normal, fast path.
      setTrip(tripResult.data);
      setStops(stopsResult.data ?? []);
      setSegments(segmentsResult.data ?? []);
      setLinkedExpenses(expensesResult.data ?? []);
      setIsCollaboratorView(false);
      setIsLoading(false);
      return;
    }

    // Not my own trip — RLS blocked the direct query above. Fall back to the
    // collaboration RPCs, which work for a contributor or a full
    // collaborator viewing this via the owner's trip_id (can_view_trip_
    // collaboration resolves either). Linked-expense totals stay empty here
    // deliberately — transactions remain fully owner-only, no RPC exposes
    // them to a collaborator, so the staircase just shows no cost figures.
    const [collabTripResult, collabStopsResult, collabSegmentsResult] = await Promise.all([
      supabase.rpc('trip_collaboration_trip', { p_trip_id: tripId }),
      supabase.rpc('trip_collaboration_stops', { p_trip_id: tripId }),
      supabase.rpc('trip_collaboration_segments', { p_trip_id: tripId }),
    ]);
    if (collabTripResult.error || !collabTripResult.data?.[0]) {
      setError(collabTripResult.error?.message ?? tripResult.error.message);
    } else {
      setTrip(collabTripResult.data[0] as TripRow);
      setStops(collabStopsResult.data ?? []);
      setSegments(collabSegmentsResult.data ?? []);
      setLinkedExpenses([]);
      setIsCollaboratorView(true);
    }
    setIsLoading(false);
  }, [tripId]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  if (isLoading || !trip) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  const [summary] = computeTripSummaries([trip], stops, segments);
  const stopIds = new Set(stops.map((s) => s.id));
  const segmentIds = new Set(segments.map((s) => s.id));
  const tripLinkedExpenses = linkedExpenses.filter(
    (tx) => (tx.trip_stop_id && stopIds.has(tx.trip_stop_id)) || (tx.trip_segment_id && segmentIds.has(tx.trip_segment_id))
  );
  const budget = computeTripBudget(stops, segments, tripLinkedExpenses, convert);
  const grandTotalLabel = formatTotals(budget.grandTotal);
  const plannedGrandTotalLabel = formatTotals(budget.plannedGrandTotal);

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">‹ {summary?.displayName ?? 'Trip'}</ThemedText>
          </Pressable>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText type="title" style={{ color: ACCENT }}>
          Cost Graph
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {summary ? (
          <ThemedView style={styles.metaRow}>
            <ThemedView style={styles.flagRow}>
              {summary.countries.map((country) => (
                <CountryFlag key={country} countryName={country} hiddenFlagCountries={hiddenFlagCountries} size={18} />
              ))}
            </ThemedView>
            <ThemedText style={styles.muted}>
              {formatDateDisplay(summary.startDate)} → {formatDateDisplay(summary.endDate)}
            </ThemedText>
          </ThemedView>
        ) : null}

        {isCollaboratorView ? (
          <ThemedText style={[styles.muted, styles.sectionSpacing]}>
            Itinerary only. Cost figures come from the trip owner&apos;s own transactions, which stay private to
            them.
          </ThemedText>
        ) : budget.legs.every((leg) => leg.expenses.length === 0 && !leg.plannedTotal) ? (
          <ThemedText style={[styles.muted, styles.sectionSpacing]}>
            No costs yet. Set a planned cost on a stop or leg, or link an actual expense, to see it appear here.
          </ThemedText>
        ) : null}

        <ThemedView style={styles.staircase}>
          {budget.legs.map((leg, index) => {
            const total = formatTotals(leg.totals);
            const planned = leg.plannedTotal ? formatMoney(leg.plannedTotal.amount, leg.plannedTotal.currency) : null;
            const indent = Math.min(index, MAX_STAIRCASE_STEPS) * STAIRCASE_STEP;
            return (
              <ThemedView
                key={leg.kind === 'stop' ? leg.stop.id : leg.segment.id}
                style={[styles.legWrap, { marginLeft: indent }]}>
                <Surface accentColor={ACCENT} style={styles.legCard}>
                  <ThemedView style={styles.legTop}>
                    <ThemedText type="defaultSemiBold" numberOfLines={1} style={styles.flexShrink}>
                      {leg.label}
                    </ThemedText>
                    <ThemedText type="mono" style={total ? styles.legTotal : styles.muted}>
                      {total ?? '-'}
                    </ThemedText>
                  </ThemedView>
                  <ThemedView style={styles.legBottom}>
                    <ThemedText type="mono" style={styles.muted}>
                      {formatDateDisplay(leg.date)}
                    </ThemedText>
                    {planned ? <ThemedText style={styles.plannedLabel}>Planned {planned}</ThemedText> : null}
                  </ThemedView>
                </Surface>
              </ThemedView>
            );
          })}
        </ThemedView>

        {budget.categories.length > 0 ? (
          <>
            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              Cost summary
            </ThemedText>
            <ThemedView style={styles.categoryGrid}>
              {budget.categories.map((category) => (
                <Surface key={category.label} accentColor={ACCENT} style={styles.categoryTile}>
                  <ThemedText style={styles.muted}>{category.label}</ThemedText>
                  <ThemedText type="mono" style={styles.categoryTotal} numberOfLines={1} adjustsFontSizeToFit>
                    {formatTotals(category.totals)}
                  </ThemedText>
                </Surface>
              ))}
            </ThemedView>
          </>
        ) : null}

        {plannedGrandTotalLabel ? (
          <ThemedView style={styles.plannedTotalRow}>
            <ThemedText type="defaultSemiBold">Planned budget</ThemedText>
            <ThemedText type="mono" style={styles.plannedTotalValue}>
              {plannedGrandTotalLabel}
            </ThemedText>
          </ThemedView>
        ) : null}

        {grandTotalLabel ? (
          <ThemedView style={[styles.grandTotalRow, { backgroundColor: ACCENT }]}>
            <ThemedText style={{ color: ModuleAccentOnColor.countries, fontWeight: '600' }}>Actual spend</ThemedText>
            <ThemedText type="mono" style={[styles.grandTotalValue, { color: ModuleAccentOnColor.countries }]}>
              {grandTotalLabel}
            </ThemedText>
          </ThemedView>
        ) : null}
      </ScrollView>
    </ThemedView>
  );
}

