import { useLocalSearchParams, useRouter } from 'expo-router';
import { useEffect, useRef, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { PasswordInput } from '@/components/password-input';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { supabase } from '@/lib/supabase';

const TINT = Colors.light.tint;

/**
 * Reached three ways: via a password-recovery email link (?code=...&type=
 * recovery), a signup-confirmation link (?code=...&type=signup — see
 * contexts/auth-context.tsx's signUp for why that lands HERE and not on /),
 * or by navigating here directly with no code/session at all — the last one
 * just shows a dead-end message pointing back at requesting a fresh link.
 *
 * The code param is exchanged for a session by hand below rather than
 * relying on Supabase's detectSessionInUrl, which only works on web (see
 * lib/supabase.ts). A signup confirmation redirects on into / once that
 * exchange succeeds; a recovery link stays here to show the set-password
 * form.
 */
export default function ResetPasswordScreen() {
  const router = useRouter();
  const { code, type } = useLocalSearchParams<{ code?: string; type?: string }>();
  const { session, isLoading: isAuthLoading } = useAuth();

  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);
  const [isExchanging, setIsExchanging] = useState(!!code);
  const [exchangeFailed, setExchangeFailed] = useState(false);
  const hasExchangedRef = useRef(false);

  useEffect(() => {
    if (!code || hasExchangedRef.current) return;
    hasExchangedRef.current = true;
    supabase.auth.exchangeCodeForSession(code).then(({ error: exchangeError }) => {
      setIsExchanging(false);
      if (exchangeError) {
        // "Link Expired" below doesn't say why — logged so the real reason
        // (expired code, already-used code, mismatched PKCE verifier from a
        // different browser/device, etc.) is visible in dev tools instead
        // of being a dead end.
        console.error('exchangeCodeForSession failed:', exchangeError.message, exchangeError);
        setExchangeFailed(true);
      }
      // On success, the onAuthStateChange listener in contexts/auth-
      // context.tsx picks up the new session on its own — nothing else to
      // do here.
    });
  }, [code]);

  useEffect(() => {
    if (type === 'signup' && session) {
      router.replace('/');
    }
  }, [type, session, router]);

  async function handleSave() {
    setSuccess(false);
    if (!newPassword || !confirmPassword) {
      setError('Fill in both fields.');
      return;
    }
    if (newPassword !== confirmPassword) {
      setError('Passwords do not match.');
      return;
    }
    if (newPassword.length < 6) {
      setError('Password must be at least 6 characters.');
      return;
    }

    setError(null);
    setIsSaving(true);
    const { error: updateError } = await supabase.auth.updateUser({ password: newPassword });
    setIsSaving(false);

    if (updateError) {
      setError(updateError.message);
      return;
    }

    setSuccess(true);
  }

  if (isAuthLoading || isExchanging) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={TINT} />
      </ThemedView>
    );
  }

  if (!session) {
    // A code was present and its exchange didn't outright fail — session
    // just hasn't propagated from the onAuthStateChange listener into
    // context yet. Keep showing the spinner rather than flashing "expired"
    // for what's normally a near-instant gap.
    if (code && !exchangeFailed) {
      return (
        <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
          <ActivityIndicator color={TINT} />
        </ThemedView>
      );
    }
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered, styles.padded]}>
        <ThemedText type="title" style={{ color: TINT }}>
          Link Expired
        </ThemedText>
        <ThemedText style={styles.body}>
          This reset link is invalid or has expired. Request a new one from the sign-in screen.
        </ThemedText>
        <Pressable onPress={() => router.replace('/login')} hitSlop={12}>
          <ThemedText type="link">Back to sign in</ThemedText>
        </Pressable>
      </ThemedView>
    );
  }

  if (type === 'signup') {
    // Session now exists — the redirect effect above sends this on into /
    // momentarily. Avoid flashing the password form in the meantime.
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={TINT} />
      </ThemedView>
    );
  }

  if (success) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered, styles.padded]}>
        <ThemedText type="title" style={{ color: TINT }}>
          Password Updated
        </ThemedText>
        <ThemedText style={styles.body}>You&apos;re signed in with your new password.</ThemedText>
        <Pressable onPress={() => router.replace('/')} hitSlop={12}>
          <ThemedText type="link">Continue to Cluster</ThemedText>
        </Pressable>
      </ThemedView>
    );
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedText type="title" style={{ color: TINT }}>
          Set a New Password
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedText type="defaultSemiBold">New password</ThemedText>
        <PasswordInput
          value={newPassword}
          onChangeText={setNewPassword}
          autoComplete="new-password"
          placeholder="At least 6 characters"
          accentColor={TINT}
          style={styles.input}
        />

        <ThemedText type="defaultSemiBold">Confirm new password</ThemedText>
        <PasswordInput
          value={confirmPassword}
          onChangeText={setConfirmPassword}
          autoComplete="new-password"
          placeholder="Repeat new password"
          accentColor={TINT}
          style={styles.input}
        />

        <Pressable onPress={handleSave} disabled={isSaving} style={[styles.button, { backgroundColor: TINT }]}>
          {isSaving ? (
            <ActivityIndicator color={Colors.light.backgroundSolid} />
          ) : (
            <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Save password</ThemedText>
          )}
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  centered: { alignItems: 'center', justifyContent: 'center', gap: 12 },
  padded: { padding: 24 },
  content: {
    padding: 24,
    gap: 8,
    paddingBottom: 48,
  },
  body: {
    fontSize: 15,
    lineHeight: 22,
    textAlign: 'center',
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  error: {
    color: Colors.light.negative,
  },
});
