import { useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';
import Svg, { Circle, Line, Polyline } from 'react-native-svg';

import { ThemedText } from '@/components/themed-text';
import { Colors } from '@/constants/theme';
import { axisUnitFor, formatAxisTick, niceTicks } from '@/lib/chartScale';

const CHART_HEIGHT = 200;
// Left gutter reserved for the Y-axis value labels — the line/points draw
// in the remaining width to the right of it, same treatment as
// components/candlestick-chart.tsx.
const AXIS_GUTTER = 52;
const TICK_COUNT = 4;

export type LinePoint = { label: string; value: number };

/**
 * A single-series line chart with an optional horizontal threshold
 * reference line (dashed) — built for the FBAR balance-over-time drill-down,
 * generic enough to reuse elsewhere. Only one series, so no categorical
 * palette/colorblind concerns the way a multi-series chart would need.
 */
export function LineChart({
  points,
  color,
  currency,
  threshold,
  thresholdLabel,
}: {
  points: LinePoint[];
  color: string;
  /** Y-axis value labels are formatted in this currency. */
  currency: string;
  threshold?: number;
  thresholdLabel?: string;
}) {
  const [width, setWidth] = useState(0);

  if (points.length === 0) {
    return <ThemedText style={{ opacity: 0.7, fontSize: 13, color: Colors.light.textMuted }}>No data yet.</ThemedText>;
  }

  if (width === 0) {
    return <View onLayout={(e) => setWidth(e.nativeEvent.layout.width)} style={{ height: CHART_HEIGHT }} />;
  }

  const values = points.map((p) => p.value).concat(threshold != null ? [threshold] : []);
  const max = Math.max(...values, 0);
  const min = Math.min(...values, 0);
  const range = max - min || Math.abs(max) || 1;
  const padding = range * 0.1;
  const domainMax = max + padding;
  const domainMin = min - padding;
  const domainRange = domainMax - domainMin || 1;

  const ticks = niceTicks(domainMin, domainMax, TICK_COUNT).filter((t) => t >= domainMin && t <= domainMax);
  const axisUnit = axisUnitFor(ticks);
  const topTick = ticks[ticks.length - 1];
  const plotWidth = Math.max(width - AXIS_GUTTER, 0);

  function toY(value: number): number {
    return CHART_HEIGHT - ((value - domainMin) / domainRange) * CHART_HEIGHT;
  }
  function toX(index: number): number {
    return AXIS_GUTTER + (points.length === 1 ? plotWidth / 2 : (index / (points.length - 1)) * plotWidth);
  }

  const svgPoints = points.map((p, i) => `${toX(i)},${toY(p.value)}`).join(' ');
  const lastPoint = points[points.length - 1];

  return (
    <View style={{ gap: 4 }}>
      <View style={{ height: CHART_HEIGHT }}>
        {ticks.map((tick) => (
          <Text
            key={tick}
            numberOfLines={1}
            style={[styles.axisLabel, { top: Math.min(Math.max(toY(tick) - 7, 0), CHART_HEIGHT - 14) }]}>
            {formatAxisTick(tick, currency, axisUnit, tick === topTick)}
          </Text>
        ))}
        <Svg width={width} height={CHART_HEIGHT} style={StyleSheet.absoluteFillObject}>
          {/* Recessive gridlines — a visual reference for the labels, not a focal element. */}
          {ticks.map((tick) => (
            <Line
              key={tick}
              x1={AXIS_GUTTER}
              x2={width}
              y1={toY(tick)}
              y2={toY(tick)}
              stroke={Colors.light.cardBorder}
              strokeWidth={1}
              opacity={0.35}
            />
          ))}
          {threshold != null ? (
            <Line
              x1={AXIS_GUTTER}
              y1={toY(threshold)}
              x2={width}
              y2={toY(threshold)}
              stroke={Colors.light.negative}
              strokeWidth={1}
              strokeDasharray="4,4"
            />
          ) : null}
          <Polyline points={svgPoints} fill="none" stroke={color} strokeWidth={2} />
          {points.map((p, i) => (
            <Circle key={i} cx={toX(i)} cy={toY(p.value)} r={2.5} fill={color} />
          ))}
        </Svg>
      </View>
      <View style={{ flexDirection: 'row', justifyContent: 'space-between', paddingLeft: AXIS_GUTTER }}>
        <ThemedText style={{ opacity: 0.7, fontSize: 11, color: Colors.light.textMuted }}>
          {points[0].label}
        </ThemedText>
        <ThemedText style={{ opacity: 0.7, fontSize: 11, color: Colors.light.textMuted }}>{lastPoint.label}</ThemedText>
      </View>
      {threshold != null && thresholdLabel ? (
        <ThemedText style={{ opacity: 0.7, fontSize: 11, color: Colors.light.negative, paddingLeft: AXIS_GUTTER }}>
          {thresholdLabel}
        </ThemedText>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  axisLabel: {
    position: 'absolute',
    left: 0,
    width: AXIS_GUTTER - 8,
    fontSize: 10,
    lineHeight: 14,
    textAlign: 'right',
    color: Colors.light.textMuted,
    opacity: 0.8,
  },
});
