import { StyleSheet, useWindowDimensions } from 'react-native';
import Svg, { Defs, RadialGradient, Rect, Stop } from 'react-native-svg';

import { BackgroundGradient } from '@/constants/theme';

/**
 * Full-bleed radial gradient screen backdrop. Uses userSpaceOnUse (absolute
 * pixel) coordinates rather than the SVG default objectBoundingBox, because
 * bounding-box-relative radial gradients scale x/y independently to the
 * element's own width/height — on a tall phone screen that stretches the
 * glint into a vertical ellipse instead of staying circular.
 */
export function GradientBackground() {
  const { width, height } = useWindowDimensions();
  const cx = width * BackgroundGradient.focalXFraction;
  const cy = height * BackgroundGradient.focalYFraction;
  // Reaching the literal farthest corner (the old formula, no multiplier)
  // meant the 100% stop only exists at one exact pixel, and the screen
  // CENTER — where most content actually sits — was only ~35% of the way
  // through the gradient. Everything visible lived in the early, closest-
  // to-white stops; the more distinct hues were pushed out into a corner
  // nothing renders on top of, which is why this kept reading as "one flat
  // color" no matter how the stop colors themselves were tuned. Pulling
  // the radius in to 65% of that distance moves the full color journey
  // into the actually-visible viewport instead of past its edges.
  const radius = 0.65 * Math.sqrt(Math.max(cx, width - cx) ** 2 + Math.max(cy, height - cy) ** 2);

  return (
    <Svg width={width} height={height} style={StyleSheet.absoluteFillObject} pointerEvents="none">
      <Defs>
        <RadialGradient id="screenBg" cx={cx} cy={cy} r={radius} fx={cx} fy={cy} gradientUnits="userSpaceOnUse">
          {BackgroundGradient.stops.map((stop) => (
            <Stop key={stop.offset} offset={stop.offset} stopColor={stop.color} />
          ))}
        </RadialGradient>
      </Defs>
      <Rect x={0} y={0} width={width} height={height} fill="url(#screenBg)" />
    </Svg>
  );
}
