import { useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput } from 'react-native';

import { CountryAutocompleteInput } from '@/components/country-autocomplete-input';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { supabase } from '@/lib/supabase';

const TINT = Colors.light.tint;

export default function AddressScreen() {
  const router = useRouter();
  const { session } = useAuth();

  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  const [street, setStreet] = useState('');
  const [city, setCity] = useState('');
  const [postalCode, setPostalCode] = useState('');
  const [country, setCountry] = useState('');

  useEffect(() => {
    if (!session) return;
    let cancelled = false;

    supabase
      .from('user_settings')
      .select('address_street, address_city, address_postal_code, address_country')
      .eq('user_id', session.user.id)
      .maybeSingle()
      .then(({ data, error: fetchError }) => {
        if (cancelled) return;
        if (fetchError) {
          setError(fetchError.message);
        } else if (data) {
          setStreet(data.address_street ?? '');
          setCity(data.address_city ?? '');
          setPostalCode(data.address_postal_code ?? '');
          setCountry(data.address_country ?? '');
        }
        setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [session]);

  async function handleSave() {
    if (!session) return;
    setError(null);
    setSuccess(false);
    setIsSaving(true);

    const { error: saveError } = await supabase.from('user_settings').upsert(
      {
        user_id: session.user.id,
        address_street: street.trim() || null,
        address_city: city.trim() || null,
        address_postal_code: postalCode.trim() || null,
        address_country: country,
      },
      { onConflict: 'user_id' }
    );

    setIsSaving(false);

    if (saveError) {
      setError(saveError.message);
      return;
    }

    setSuccess(true);
  }

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={TINT} />
      </ThemedView>
    );
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: TINT }}>
            Address
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
        {success ? <ThemedText style={styles.success}>Saved.</ThemedText> : null}
        <ThemedText style={styles.hint}>
          Stored profile information only. Not used in any calculation yet.
        </ThemedText>

        <ThemedText type="defaultSemiBold">Street</ThemedText>
        <TextInput
          value={street}
          onChangeText={setStreet}
          placeholder="123 Main St"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: TINT }]}
        />

        <ThemedText type="defaultSemiBold">City</ThemedText>
        <TextInput
          value={city}
          onChangeText={setCity}
          placeholder="City"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: TINT }]}
        />

        <ThemedText type="defaultSemiBold">Postal code</ThemedText>
        <TextInput
          value={postalCode}
          onChangeText={setPostalCode}
          placeholder="Postal code"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: TINT }]}
        />

        <ThemedText type="defaultSemiBold">Country</ThemedText>
        <CountryAutocompleteInput value={country} onChangeText={setCountry} onSelectCountry={setCountry} accentColor={TINT} />

        <Pressable onPress={handleSave} disabled={isSaving} style={[styles.button, { backgroundColor: TINT }]}>
          {isSaving ? (
            <ActivityIndicator color={Colors.light.backgroundSolid} />
          ) : (
            <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Save</ThemedText>
          )}
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  centered: { alignItems: 'center', justifyContent: 'center' },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 8,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  error: {
    color: Colors.light.negative,
  },
  success: {
    color: Colors.light.positive,
  },
});
