import { useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet } from 'react-native';
import { createPlaidLinkSession } from 'react-native-plaid-link-sdk';

import { ThemedText } from '@/components/themed-text';
import { Colors } from '@/constants/theme';
import { supabase } from '@/lib/supabase';

/**
 * Native-only — kept out of app/accounts/plaid.tsx directly because
 * react-native-plaid-link-sdk calls into expo-modules-core's native view
 * manager at import time, which crashes the entire web bundle the moment
 * this file is imported (same failure mode as expo-print earlier this
 * project: an unused import is fatal, not just calling it). Metro's
 * platform-extension resolution picks this file on iOS/Android and
 * plaid-connect-button.web.tsx on web, so the route file itself never
 * imports the SDK.
 */
export function PlaidConnectButton({
  accentColor,
  onConnected,
  onError,
}: {
  accentColor: string;
  onConnected: () => void;
  onError: (message: string) => void;
}) {
  const [isConnecting, setIsConnecting] = useState(false);

  async function handleConnect() {
    onError('');
    setIsConnecting(true);
    try {
      const { data: tokenData, error: tokenError } = await supabase.functions.invoke<{ link_token: string }>(
        'plaid-create-link-token'
      );
      if (tokenError || !tokenData) {
        throw new Error(tokenError?.message ?? 'Could not start Plaid Link.');
      }

      const session = await createPlaidLinkSession({
        token: tokenData.link_token,
        onSuccess: async (success) => {
          const { error: exchangeError } = await supabase.functions.invoke('plaid-exchange-token', {
            body: {
              public_token: success.publicToken,
              institution_name: success.metadata.institution?.name ?? null,
            },
          });
          setIsConnecting(false);
          if (exchangeError) {
            onError(exchangeError.message);
            return;
          }
          onConnected();
        },
        onExit: (exit) => {
          setIsConnecting(false);
          if (exit.error) onError(exit.error.errorMessage ?? 'Plaid Link was closed before finishing.');
        },
        onEvent: () => {},
      });
      await session.open();
    } catch (e) {
      setIsConnecting(false);
      onError(e instanceof Error ? e.message : 'Could not start Plaid Link.');
    }
  }

  return (
    <Pressable onPress={handleConnect} disabled={isConnecting} style={[styles.button, { backgroundColor: accentColor }]}>
      {isConnecting ? (
        <ActivityIndicator color={Colors.light.backgroundSolid} />
      ) : (
        <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Connect a test bank</ThemedText>
      )}
    </Pressable>
  );
}

const styles = StyleSheet.create({
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
});
