import { useRouter } from 'expo-router';
import type { PropsWithChildren } from 'react';
import { useState } from 'react';
import { Pressable, StyleSheet, View } from 'react-native';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';
import Animated, { runOnJS, useAnimatedStyle, useSharedValue, withTiming } from 'react-native-reanimated';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors } from '@/constants/theme';
import { useTour } from '@/contexts/tour-context';

// 300, not the original 260 — that width was sized for 2 top icon buttons
// (Settings/Map); a 3rd (Calendar) made each one too narrow for its label
// to fit on one line, wrapping mid-word ("Settin" / "gs").
const PANEL_WIDTH = 300;
const EDGE_ZONE_WIDTH = 24;

export type SwipeConnection = { id: string; displayName: string };

/**
 * Swipe-right FROM THE LEFT SCREEN EDGE reveals a panel of the viewer's
 * shared connections — a quick switcher reachable both from the Countries
 * dashboard and from within a connection's own shared pages, so moving
 * between connections doesn't require backing out each time. Tapping one
 * closes the panel and navigates straight to that connection's travel page
 * (not the sub-wheel — the wheel is a secondary settings/overview stop,
 * reachable from within the travel page or account/share instead).
 *
 * Deliberately edge-scoped (a narrow absolutely-positioned strip), not a
 * gesture wrapping the whole screen: an earlier version wrapped `children`
 * directly in the pan gesture's GestureDetector, which fought the screen's
 * own ScrollView for vertical drags (broke scrolling) and, because the
 * panel's Pressable rows were nested inside that same ancestor
 * GestureDetector, could swallow taps meant for them (row taps did
 * nothing). Scoping the open-gesture to a thin edge strip fixed the first
 * problem, but the panel itself was still wrapped in its own GestureDetector
 * (for swipe-to-close) — same class of bug, still swallowing row taps.
 * Removed that gesture entirely: the panel closes via tapping the backdrop
 * (a plain Pressable, no GestureDetector involved) or tapping a row, both
 * fully reliable. Swipe only opens now; nothing swipes it closed.
 */
export function ConnectionsSwipePanel({
  connections,
  isLoading,
  accentColor,
  activeConnectionId,
  destinationModule = 'travel',
  children,
}: PropsWithChildren<{
  connections: SwipeConnection[];
  isLoading: boolean;
  accentColor: string;
  /** When this panel is shown from within a specific connection's own page, highlights that entry in the list so it's clear which one you're on. */
  activeConnectionId?: string;
  /** Which shared sub-page tapping a connection navigates to — 'travel' from Countries/the travel page itself, 'cards' from the Cards dashboard, etc. */
  destinationModule?: 'travel' | 'cards' | 'accounts' | 'documents';
}>) {
  const router = useRouter();
  const { step, reportTap } = useTour();
  const isSwipeHighlighted = step?.highlightAnchor === 'connections-swipe';
  const isSettingsHighlighted = step?.highlightAnchor === 'swipe-panel-settings';
  const translateX = useSharedValue(-PANEL_WIDTH);
  const isOpen = useSharedValue(false);
  // Mirrors isOpen on the JS thread — used to actually unmount the backdrop
  // Pressable when closed, not just hide it visually. A full-screen
  // Pressable that only looks invisible (opacity 0) still intercepts every
  // touch meant for the page underneath; only removing it from the tree
  // (or setting pointerEvents="none") stops that.
  const [panelOpenState, setPanelOpenState] = useState(false);

  function closePanel() {
    translateX.value = withTiming(-PANEL_WIDTH, { duration: 220 });
    isOpen.value = false;
    setPanelOpenState(false);
  }

  const edgeOpenGesture = Gesture.Pan()
    .activeOffsetX([15, 999999])
    .failOffsetY([-15, 15])
    .onUpdate((event) => {
      translateX.value = Math.min(0, Math.max(-PANEL_WIDTH, -PANEL_WIDTH + event.translationX));
    })
    .onEnd(() => {
      if (translateX.value > -PANEL_WIDTH / 2) {
        translateX.value = withTiming(0, { duration: 200 });
        isOpen.value = true;
        runOnJS(setPanelOpenState)(true);
        runOnJS(reportTap)('connections-swipe');
      } else {
        translateX.value = withTiming(-PANEL_WIDTH, { duration: 200 });
        isOpen.value = false;
        runOnJS(setPanelOpenState)(false);
      }
    });

  const panelStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: translateX.value }],
  }));
  const backdropStyle = useAnimatedStyle(() => ({
    opacity: Math.max(0, Math.min(1, (translateX.value + PANEL_WIDTH) / PANEL_WIDTH)) * 0.4,
  }));

  return (
    <View style={styles.flex}>
      <View style={[styles.flex, isSwipeHighlighted ? styles.tourDimmed : null]}>{children}</View>

      {!panelOpenState ? (
        <GestureDetector gesture={edgeOpenGesture}>
          <View style={styles.edgeZone} />
        </GestureDetector>
      ) : null}

      {/* Visible only during the walkthrough — day to day this edge stays
          a deliberately invisible hit zone (see the file-level note above),
          but an invisible gesture zone is undiscoverable without a hint the
          first time. pointerEvents="none" so it never competes with the
          real edgeZone's own gesture handling above. */}
      {isSwipeHighlighted && !panelOpenState ? (
        <View style={styles.swipeHint} pointerEvents="none">
          <IconSymbol name="chevron.right" size={18} color={Colors.light.backgroundSolid} />
        </View>
      ) : null}

      {panelOpenState ? (
        <Animated.View style={[styles.backdrop, backdropStyle]} pointerEvents="box-none">
          <Pressable style={StyleSheet.absoluteFill} onPress={closePanel} />
        </Animated.View>
      ) : null}

      <Animated.View
        style={[styles.panel, { width: PANEL_WIDTH, backgroundColor: Colors.light.backgroundSolid }, panelStyle]}>
        <ThemedText type="subtitle" style={[styles.panelTitle, { color: accentColor }]}>
          Shared with
        </ThemedText>
        <View style={styles.topIconRow}>
          <Pressable
            style={styles.flexOne}
            onPress={() => {
              reportTap('swipe-panel-settings');
              closePanel();
              router.push(activeConnectionId ? `/account/share/${activeConnectionId}` : '/account/share');
            }}>
            <Surface
              accentColor={accentColor}
              style={[styles.topIconButton, isSettingsHighlighted ? styles.tourHighlighted : null]}>
              <IconSymbol name="gearshape.fill" size={20} color={accentColor} />
              <ThemedText style={styles.topIconLabel} numberOfLines={1} adjustsFontSizeToFit>
                Settings
              </ThemedText>
            </Surface>
          </Pressable>
          {!isLoading && connections.length > 0 ? (
            <Pressable
              style={[styles.flexOne, isSettingsHighlighted ? styles.tourDimmed : null]}
              onPress={() => {
                closePanel();
                router.push('/connections/map');
              }}>
              <Surface accentColor={accentColor} style={styles.topIconButton}>
                <IconSymbol name="mappin.and.ellipse" size={20} color={accentColor} />
                <ThemedText style={styles.topIconLabel} numberOfLines={1} adjustsFontSizeToFit>
                  Map
                </ThemedText>
              </Surface>
            </Pressable>
          ) : null}
          {!isLoading && connections.length > 0 ? (
            <Pressable
              style={[styles.flexOne, isSettingsHighlighted ? styles.tourDimmed : null]}
              onPress={() => {
                closePanel();
                router.push('/connections/calendar');
              }}>
              <Surface accentColor={accentColor} style={styles.topIconButton}>
                <IconSymbol name="calendar" size={20} color={accentColor} />
                <ThemedText style={styles.topIconLabel} numberOfLines={1} adjustsFontSizeToFit>
                  Calendar
                </ThemedText>
              </Surface>
            </Pressable>
          ) : null}
        </View>
        <View style={isSettingsHighlighted ? styles.tourDimmed : undefined}>
          {isLoading ? null : connections.length === 0 ? (
            <ThemedText style={styles.emptyText}>
              No connections yet. Tap Settings above to add someone.
            </ThemedText>
          ) : (
            connections.map((connection) => {
              const isActive = connection.id === activeConnectionId;
              return (
                <Pressable
                  key={connection.id}
                  onPress={() => {
                    closePanel();
                    if (!isActive) router.push(`/connections/${connection.id}/${destinationModule}`);
                  }}>
                  <Surface
                    accentColor={isActive ? accentColor : 'rgba(245, 247, 246, 0.1)'}
                    style={styles.connectionRow}>
                    <ThemedText type="defaultSemiBold" numberOfLines={1}>
                      {connection.displayName}
                    </ThemedText>
                    {isActive ? (
                      <ThemedText style={[styles.currentLabel, { color: accentColor }]}>Current</ThemedText>
                    ) : null}
                  </Surface>
                </Pressable>
              );
            })
          )}
        </View>
      </Animated.View>
    </View>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  edgeZone: {
    position: 'absolute',
    left: 0,
    top: 0,
    bottom: 0,
    width: EDGE_ZONE_WIDTH,
  },
  backdrop: {
    ...StyleSheet.absoluteFillObject,
    backgroundColor: '#000000',
  },
  panel: {
    position: 'absolute',
    left: 0,
    top: 0,
    bottom: 0,
    padding: 16,
    gap: 8,
    borderRightWidth: StyleSheet.hairlineWidth,
    borderRightColor: Colors.light.icon,
  },
  panelTitle: {
    marginBottom: 4,
  },
  emptyText: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  connectionRow: {
    marginBottom: 4,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  topIconRow: {
    flexDirection: 'row',
    gap: 8,
    marginBottom: 4,
  },
  flexOne: {
    flex: 1,
  },
  topIconButton: {
    alignItems: 'center',
    gap: 4,
    paddingVertical: 10,
  },
  topIconLabel: {
    fontSize: 12,
    fontWeight: '600',
  },
  currentLabel: {
    fontSize: 12,
    fontWeight: '600',
  },
  // Applied to everything OTHER than the tour's currently-highlighted
  // element, when there is one — see app/index.tsx's own copy of this
  // style for why plain opacity on a wrapper beats a separately-positioned
  // overlay trying to track the element's screen position.
  tourDimmed: {
    opacity: 0.3,
  },
  tourHighlighted: {
    borderWidth: 3,
    borderColor: Colors.light.tint,
  },
  swipeHint: {
    position: 'absolute',
    left: 4,
    top: '50%',
    marginTop: -18,
    width: 36,
    height: 36,
    borderRadius: 18,
    backgroundColor: Colors.light.tint,
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: '#000000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.3,
    shadowRadius: 6,
    elevation: 6,
  },
});
