import { useEffect, useRef, useState } from 'react';
import { Platform, StyleSheet, View } from 'react-native';
import MapView, { Marker, Polyline, PROVIDER_DEFAULT, PROVIDER_GOOGLE, type Region } from 'react-native-maps';

import { Colors, ModuleAccents } from '@/constants/theme';
import { dotIcon } from '@/lib/mapMarkerIcons';
import { catmullRomLegPath, type RoutePoint, type TripLeg } from '@/lib/tripRoute';

const MAP_HEIGHT = 260;
const REGION_PADDING_FACTOR = 1.6;
const MIN_DELTA = 4;
const FIT_EDGE_PADDING = { top: 40, right: 40, bottom: 40, left: 40 };
// A leg with no real trip_segment behind it — just a manual mode tag, or
// nothing at all — draws dashed rather than solid, so a fully logged leg
// (with its own dates/carrier/cost) stays visually distinct from a light
// label on the map. See TripLeg.hasSegment.
const DASH_PATTERN = [8, 6];

function computeRegion(points: RoutePoint[]): Region {
  if (points.length === 0) {
    return { latitude: 20, longitude: 0, latitudeDelta: 100, longitudeDelta: 100 };
  }
  const lats = points.map((p) => p.lat);
  const lons = points.map((p) => p.lon);
  const minLat = Math.min(...lats);
  const maxLat = Math.max(...lats);
  const minLon = Math.min(...lons);
  const maxLon = Math.max(...lons);
  return {
    latitude: (minLat + maxLat) / 2,
    longitude: (minLon + maxLon) / 2,
    latitudeDelta: Math.max((maxLat - minLat) * REGION_PADDING_FACTOR, MIN_DELTA),
    longitudeDelta: Math.max((maxLon - minLon) * REGION_PADDING_FACTOR, MIN_DELTA),
  };
}

/**
 * Real map (Apple Maps on iOS, Google Maps on Android via react-native-maps
 * — same as components/connections-map.tsx) showing a trip's stops
 * connected by straight lines, one Polyline per leg so each can carry its
 * own color (see lib/tripRoute.ts). Tapping a leg calls onSelectLeg; web
 * uses trip-route-map.web.tsx instead (react-native-maps has no web
 * support), via Metro's platform extension resolution.
 */
export function TripRouteMap({
  points,
  legs,
  onSelectLeg,
  height = MAP_HEIGHT,
}: {
  points: RoutePoint[];
  legs: TripLeg[];
  onSelectLeg: (legId: string) => void;
  /** Overrides the default compact height — the fullscreen expand view passes a taller one. */
  height?: number;
}) {
  const mapRef = useRef<MapView>(null);
  // react-native-maps' native MapView, unlike a plain RN view, is backed
  // by a real platform view the bridge has to size explicitly — on
  // Android specifically, leaving it to size itself purely via flex:1
  // inside nested ScrollView/flex ancestors (as this did before) let it
  // measure before the JS layout pass had actually resolved the true
  // parent width, so it rendered at the WINDOW's width instead of its own
  // card's — confirmed directly against a real device (the map visibly
  // bled past its card into the screen edge, while every sibling element
  // correctly respected the same padding). Measuring this container's own
  // width via onLayout and passing it explicitly to both the wrapper and
  // the MapView (same pattern world-passport-map.tsx already uses for its
  // SVG) sidesteps that entirely — same fix WorldPassportMap already
  // needed for this exact reason.
  const [measuredWidth, setMeasuredWidth] = useState(0);
  // A stable key of the actual coordinate values, not the points array's
  // object identity (computeTripRoute builds a fresh array every render) —
  // otherwise the effect below would re-fit on every unrelated re-render
  // instead of only when a coordinate genuinely changes.
  const pointsKey = points.map((p) => `${p.id}:${p.lat}:${p.lon}`).join('|');

  // initialRegion only ever applies once, at mount — a trip whose stops
  // arrive gradually (older stops get their real coordinates backfilled
  // asynchronously, see app/countries/trips/[id].tsx) would otherwise stay
  // framed on wherever the FIRST render's points happened to be, forcing a
  // manual zoom-out once the rest resolve. Re-fitting explicitly whenever
  // the actual point set changes keeps the view honest.
  useEffect(() => {
    if (points.length === 0) return;
    if (points.length === 1) {
      mapRef.current?.animateToRegion({ latitude: points[0].lat, longitude: points[0].lon, latitudeDelta: MIN_DELTA, longitudeDelta: MIN_DELTA }, 300);
      return;
    }
    mapRef.current?.fitToCoordinates(
      points.map((p) => ({ latitude: p.lat, longitude: p.lon })),
      { edgePadding: FIT_EDGE_PADDING, animated: true }
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pointsKey]);

  return (
    <View style={[styles.container, { height }]} onLayout={(e) => setMeasuredWidth(e.nativeEvent.layout.width)}>
      {measuredWidth > 0 ? (
      <MapView
        ref={mapRef}
        style={[styles.map, { width: measuredWidth }]}
        initialRegion={computeRegion(points)}
        provider={Platform.OS === 'android' ? PROVIDER_GOOGLE : PROVIDER_DEFAULT}>
        {legs.map((leg, index) => (
          <Polyline
            key={leg.id}
            coordinates={catmullRomLegPath(points, index).map((p) => ({ latitude: p.lat, longitude: p.lon }))}
            strokeColor={leg.color}
            strokeWidth={5}
            lineCap="round"
            lineJoin="round"
            lineDashPattern={leg.hasSegment || leg.mode ? undefined : DASH_PATTERN}
            tappable
            onPress={() => onSelectLeg(leg.id)}
          />
        ))}
        {points.map((point, index) => (
          <Marker
            key={point.id}
            coordinate={{ latitude: point.lat, longitude: point.lon }}
            anchor={{ x: 0.5, y: 0.5 }}
            image={dotIcon(index === 0 ? ModuleAccents.wealth : index === points.length - 1 ? Colors.light.negative : ModuleAccents.countries)}
          />
        ))}
      </MapView>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 12,
    overflow: 'hidden',
  },
  map: {
    flex: 1,
  },
});
