import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useMemo, useState } from 'react';
import { Pressable, ScrollView, StyleSheet } from 'react-native';

import { CountryFlag } from '@/components/country-flag';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { summarizeCountriesInRange } from '@/lib/days';
import { formatDateDisplay } from '@/lib/format';
import { isExemptFromSchengenRule, isSchengenCountry, schengenStatus, SCHENGEN_LIMIT_DAYS, SCHENGEN_WINDOW_DAYS } from '@/lib/schengen';
import { supabase } from '@/lib/supabase';
import type { CountryVisitedRow } from '@/types/database';

const ACCENT = ModuleAccents.countries;

export default function SchengenScreen() {
  const router = useRouter();
  const { hiddenFlagCountries } = useCurrency();
  const [visits, setVisits] = useState<CountryVisitedRow[]>([]);
  const [citizenshipCountries, setCitizenshipCountries] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const loadVisits = useCallback(async () => {
    setIsLoading(true);
    const [visitsResult, citizenshipsResult] = await Promise.all([
      supabase.from('countries_visited').select('*'),
      supabase.from('user_citizenships').select('country'),
    ]);
    setVisits(visitsResult.data ?? []);
    setCitizenshipCountries((citizenshipsResult.data ?? []).map((c) => c.country));
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      loadVisits();
    }, [loadVisits])
  );

  const today = useMemo(() => new Date(), []);
  const status = useMemo(() => schengenStatus(visits, today), [visits, today]);

  // Per-country breakdown within the exact same rolling window the headline
  // figure is computed over, so the list always adds up to daysUsed above
  // it — a separate "all-time" or "this year" cut would silently disagree.
  const windowStart = useMemo(() => {
    const d = new Date(today);
    d.setDate(d.getDate() - (SCHENGEN_WINDOW_DAYS - 1));
    return d;
  }, [today]);

  const perCountry = useMemo(() => {
    const schengenVisits = visits.filter((v) => isSchengenCountry(v.country));
    return summarizeCountriesInRange(schengenVisits, windowStart, today);
  }, [visits, windowStart, today]);

  const progressFraction = Math.min(1, status.daysUsed / SCHENGEN_LIMIT_DAYS);
  const statusColor = status.overLimit ? Colors.light.negative : status.nearLimit ? '#B8860B' : ACCENT;
  const isExempt = isExemptFromSchengenRule(citizenshipCountries);

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Schengen Tracker
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText style={styles.hint}>
          The Schengen Area&apos;s 90/180 rule: no more than {SCHENGEN_LIMIT_DAYS} days in any rolling{' '}
          {SCHENGEN_WINDOW_DAYS}-day window, pooled across every member country combined — not per country.
          Informational only, not visa advice.
        </ThemedText>

        {isLoading ? null : isExempt ? (
          <Surface accentColor={ACCENT} style={styles.statCard}>
            <ThemedText style={styles.statusMessage}>
              The 90/180 rule only restricts visa-exempt short-stay visitors. With EU, EEA, or Swiss citizenship on
              file, you have free-movement rights across the Schengen Area instead — this limit doesn&apos;t apply to
              you, so there&apos;s nothing to track here.
            </ThemedText>
          </Surface>
        ) : (
          <>
            <Surface accentColor={statusColor} style={styles.statCard}>
              <ThemedText type="mono" style={[styles.bigNumber, { color: statusColor }]}>
                {status.daysUsed} / {SCHENGEN_LIMIT_DAYS}
              </ThemedText>
              <ThemedText style={styles.muted}>days used in the trailing {SCHENGEN_WINDOW_DAYS} days</ThemedText>

              <ThemedView style={styles.progressTrack}>
                <ThemedView style={[styles.progressFill, { width: `${progressFraction * 100}%`, backgroundColor: statusColor }]} />
              </ThemedView>

              {status.overLimit ? (
                <ThemedText style={[styles.statusMessage, { color: Colors.light.negative }]}>
                  Over the 90-day limit. Entering a Schengen country now could be refused or flagged at the border.
                </ThemedText>
              ) : status.nearLimit ? (
                <ThemedText style={[styles.statusMessage, { color: '#B8860B' }]}>
                  Getting close — {status.daysRemaining} day{status.daysRemaining === 1 ? '' : 's'} left before hitting the
                  limit.
                </ThemedText>
              ) : (
                <ThemedText style={styles.statusMessage}>{status.daysRemaining} days remaining before the limit.</ThemedText>
              )}

              {status.nextDayFreesUp ? (
                <ThemedText style={styles.muted}>
                  Next day frees up on {formatDateDisplay(status.nextDayFreesUp)} — the count can only go up from a new
                  trip before then.
                </ThemedText>
              ) : null}
            </Surface>

            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              By country
            </ThemedText>
            {perCountry.length === 0 ? (
              <ThemedText style={styles.muted}>No Schengen days logged in the current window.</ThemedText>
            ) : (
              perCountry.map((c) => (
                <Surface key={c.country} accentColor={ACCENT} style={styles.countryRow}>
                  <CountryFlag countryName={c.country} hiddenFlagCountries={hiddenFlagCountries} size={22} />
                  <ThemedText style={styles.countryName}>{c.country}</ThemedText>
                  <ThemedText type="mono">{c.daysUsed}d</ThemedText>
                </Surface>
              ))
            )}
          </>
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  hint: {
    fontSize: 13,
    opacity: 0.7,
    marginBottom: 8,
  },
  muted: {
    fontSize: 13,
    opacity: 0.7,
  },
  statCard: {
    alignItems: 'center',
    gap: 6,
    paddingVertical: 20,
  },
  bigNumber: {
    fontSize: 36,
    fontWeight: '700',
  },
  progressTrack: {
    width: '100%',
    height: 8,
    borderRadius: 4,
    backgroundColor: Colors.light.cardBorder,
    overflow: 'hidden',
    marginTop: 8,
  },
  progressFill: {
    height: '100%',
    borderRadius: 4,
  },
  statusMessage: {
    marginTop: 6,
    textAlign: 'center',
    fontSize: 14,
  },
  sectionSpacing: {
    marginTop: 12,
  },
  countryRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
  },
  countryName: {
    flex: 1,
  },
});
