import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput } from 'react-native';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { formatMoney } from '@/lib/currency';
import { fetchAllRows } from '@/lib/fetchAll';
import { formatDateDisplay } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import type { AccountRow, CreditCardRow, TransactionRow } from '@/types/database';

const ACCENT = ModuleAccents.countries;

/** Picks an EXISTING transaction to link to a trip stop/leg — the reverse
 * direction of the picker in app/transactions/[id].tsx (there you pick a
 * stop for a transaction; here you pick a transaction for a stop). Both set
 * the same trip_stop_id/trip_segment_id columns. */
export default function LinkExpenseScreen() {
  const { stopId, segmentId } = useLocalSearchParams<{ stopId?: string; segmentId?: string }>();
  const router = useRouter();
  const { convert } = useCurrency();

  const [transactions, setTransactions] = useState<TransactionRow[]>([]);
  const [accounts, setAccounts] = useState<AccountRow[]>([]);
  const [cards, setCards] = useState<CreditCardRow[]>([]);
  const [search, setSearch] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [linkingId, setLinkingId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [txResult, accountsResult, cardsResult] = await Promise.all([
      fetchAllRows<TransactionRow>((from, to) =>
        supabase.from('transactions').select('*').order('date', { ascending: false }).order('id').range(from, to)
      ),
      supabase.from('accounts').select('*'),
      supabase.from('credit_cards').select('*'),
    ]);
    if (txResult.error) {
      setError(txResult.error.message);
      setIsLoading(false);
      return;
    }
    setTransactions(txResult.data.filter((tx) => !tx.is_internal_transfer && tx.amount < 0));
    setAccounts(accountsResult.data ?? []);
    setCards(cardsResult.data ?? []);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const accountNameById = new Map(accounts.map((a) => [a.id, a.name]));
  const cardNameById = new Map(cards.map((c) => [c.id, `${c.issuer} · ${c.name}`]));

  function sourceLabel(tx: TransactionRow): string {
    if (tx.account_id) return accountNameById.get(tx.account_id) ?? 'Account';
    if (tx.card_id) return cardNameById.get(tx.card_id) ?? 'Card';
    return 'Unknown source';
  }

  const filtered = search.trim()
    ? transactions.filter((tx) => (tx.merchant ?? '').toLowerCase().includes(search.trim().toLowerCase()))
    : transactions;

  async function handleLink(tx: TransactionRow) {
    setLinkingId(tx.id);
    const { error: linkError } = await supabase
      .from('transactions')
      .update({ trip_stop_id: stopId ?? null, trip_segment_id: segmentId ?? null })
      .eq('id', tx.id);
    setLinkingId(null);
    if (linkError) {
      setError(linkError.message);
      return;
    }
    router.back();
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Link Expense
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Cancel</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <TextInput
          value={search}
          onChangeText={setSearch}
          placeholder="Search by merchant"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        {isLoading ? (
          <ActivityIndicator color={ACCENT} style={styles.spinner} />
        ) : filtered.length === 0 ? (
          <ThemedText style={styles.muted}>No matching transactions.</ThemedText>
        ) : (
          filtered.map((tx) => {
            const converted = convert(tx.amount, tx.currency);
            return (
              <Pressable key={tx.id} disabled={linkingId !== null} onPress={() => handleLink(tx)}>
                <Surface accentColor={ACCENT} style={styles.row}>
                  <ThemedView style={styles.rowBetween}>
                    <ThemedText type="defaultSemiBold" style={styles.flexShrink} numberOfLines={1}>
                      {tx.merchant || 'Transaction'}
                    </ThemedText>
                    <ThemedText type="mono">{formatMoney(Math.abs(converted.amount), converted.currency)}</ThemedText>
                  </ThemedView>
                  <ThemedView style={styles.rowBetween}>
                    <ThemedText type="mono" style={styles.muted}>
                      {formatDateDisplay(tx.date)}
                    </ThemedText>
                    <ThemedText style={styles.muted} numberOfLines={1}>
                      {sourceLabel(tx)}
                    </ThemedText>
                  </ThemedView>
                </Surface>
              </Pressable>
            );
          })
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 4,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 4,
  },
  row: {
    gap: 6,
  },
  rowBetween: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 8,
  },
  flexShrink: {
    flexShrink: 1,
  },
  spinner: {
    marginTop: 24,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
