import { Fragment, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';
import Svg, { Line, Rect } from 'react-native-svg';

import { Colors } from '@/constants/theme';
import { axisUnitFor, formatAxisTick, niceTicks } from '@/lib/chartScale';
import type { Candle } from '@/lib/wealthSeries';

const CHART_HEIGHT = 220;
const CANDLE_GAP = 4;
// Left gutter reserved for the Y-axis value labels — candles draw in the
// remaining width to the right of it.
const AXIS_GUTTER = 52;
const TICK_COUNT = 4;
// Strip below the plot reserved for X-axis period labels — every graph in
// this app is time-based, so the period actually surveyed needs to be
// visible, not just the value scale.
const X_AXIS_HEIGHT = 18;
// Rough width a short date label ("Jun 5") needs — used to figure out how
// many candles can go between labels before they'd start overlapping.
const MIN_LABEL_SPACING = 40;

function compactDateLabel(dateStr: string): string {
  return new Date(dateStr).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}

export function CandlestickChart({
  candles,
  selectedIndex,
  onSelectCandle,
  currency,
}: {
  candles: Candle[];
  selectedIndex: number | null;
  onSelectCandle: (index: number) => void;
  currency: string;
}) {
  const [width, setWidth] = useState(0);

  if (candles.length === 0) {
    return null;
  }

  if (width === 0) {
    return (
      <View onLayout={(e) => setWidth(e.nativeEvent.layout.width)} style={{ height: CHART_HEIGHT + X_AXIS_HEIGHT }} />
    );
  }

  // The axis domain is built from open/close (the period's actual
  // start/end position) rather than high/low: a single period's
  // intra-period excursion (e.g. a mortgage draw landing a day before its
  // matching asset entry) can produce a wick far outside where every
  // period actually settled. Letting that one wick dictate the whole
  // chart's scale squashes every other candle into a sliver near zero —
  // so the wick is still drawn in full, just clipped to the visible plot
  // area instead of controlling the axis.
  const bodyValues = candles.flatMap((c) => [c.open, c.close]);
  const max = Math.max(...bodyValues);
  const min = Math.min(...bodyValues);
  const range = max - min || Math.abs(max) || 1;
  const padding = range * 0.15;
  const domainMax = max + padding;
  const domainMin = min - padding;
  const domainRange = domainMax - domainMin || 1;

  const ticks = niceTicks(domainMin, domainMax, TICK_COUNT).filter((t) => t >= domainMin && t <= domainMax);
  const axisUnit = axisUnitFor(ticks);
  const topTick = ticks[ticks.length - 1];

  const plotWidth = Math.max(width - AXIS_GUTTER, 0);
  const candleWidth = plotWidth / candles.length;
  const bodyWidth = Math.max(candleWidth - CANDLE_GAP, 2);
  // Every Nth candle gets a label rather than all of them — with a dozen
  // monthly candles in a narrow phone-width chart, one label per candle
  // would overlap into an unreadable smear. The first and last candle
  // always get one regardless of step, so the surveyed range's actual
  // boundaries are never the ones skipped.
  const labelStep = Math.max(1, Math.ceil(MIN_LABEL_SPACING / candleWidth));

  function yFor(value: number) {
    const y = CHART_HEIGHT - ((value - domainMin) / domainRange) * CHART_HEIGHT;
    return Math.min(Math.max(y, 0), CHART_HEIGHT);
  }
  function xFor(index: number) {
    return AXIS_GUTTER + index * candleWidth + candleWidth / 2;
  }

  return (
    <View onLayout={(e) => setWidth(e.nativeEvent.layout.width)} style={{ height: CHART_HEIGHT + X_AXIS_HEIGHT }}>
      {ticks.map((tick) => {
        const y = yFor(tick);
        return (
          <Text
            key={tick}
            numberOfLines={1}
            style={[styles.axisLabel, { top: Math.min(Math.max(y - 7, 0), CHART_HEIGHT - 14) }]}>
            {formatAxisTick(tick, currency, axisUnit, tick === topTick)}
          </Text>
        );
      })}
      <Svg width={width} height={CHART_HEIGHT} style={styles.plotSvg}>
        {/* Recessive gridlines — a visual reference for the labels, not a focal element. */}
        {ticks.map((tick) => (
          <Line
            key={tick}
            x1={AXIS_GUTTER}
            x2={width}
            y1={yFor(tick)}
            y2={yFor(tick)}
            stroke={Colors.light.cardBorder}
            strokeWidth={1}
            opacity={0.35}
          />
        ))}
        {candles.map((candle, index) => {
          const x = xFor(index);
          const isUp = candle.close >= candle.open;
          const color = isUp ? Colors.light.positive : Colors.light.negative;
          const bodyTop = yFor(Math.max(candle.open, candle.close));
          const bodyBottom = yFor(Math.min(candle.open, candle.close));
          const bodyHeight = Math.max(bodyBottom - bodyTop, 1.5);
          const isSelected = index === selectedIndex;

          return (
            <Fragment key={candle.periodStart}>
              <Line x1={x} x2={x} y1={yFor(candle.high)} y2={yFor(candle.low)} stroke={color} strokeWidth={1.5} />
              <Rect
                x={x - bodyWidth / 2}
                y={bodyTop}
                width={bodyWidth}
                height={bodyHeight}
                fill={color}
                opacity={isSelected ? 1 : 0.85}
                stroke={isSelected ? Colors.light.text : 'none'}
                strokeWidth={isSelected ? 1.5 : 0}
              />
              <Rect
                x={AXIS_GUTTER + index * candleWidth}
                y={0}
                width={candleWidth}
                height={CHART_HEIGHT}
                fill="transparent"
                onPress={() => onSelectCandle(index)}
              />
            </Fragment>
          );
        })}
      </Svg>
      {candles.map((candle, index) => {
        if (index % labelStep !== 0 && index !== candles.length - 1) return null;
        return (
          <Text
            key={candle.periodStart}
            numberOfLines={1}
            style={[styles.xAxisLabel, { left: xFor(index) - MIN_LABEL_SPACING / 2, width: MIN_LABEL_SPACING, top: CHART_HEIGHT + 2 }]}>
            {compactDateLabel(candle.periodStart)}
          </Text>
        );
      })}
    </View>
  );
}

const styles = StyleSheet.create({
  plotSvg: {
    position: 'absolute',
    top: 0,
    left: 0,
  },
  axisLabel: {
    position: 'absolute',
    left: 0,
    width: AXIS_GUTTER - 8,
    fontSize: 10,
    lineHeight: 14,
    textAlign: 'right',
    color: Colors.light.textMuted,
    opacity: 0.8,
  },
  xAxisLabel: {
    position: 'absolute',
    fontSize: 10,
    lineHeight: 14,
    textAlign: 'center',
    color: Colors.light.textMuted,
    opacity: 0.8,
  },
});
