import { toDateOnlyString } from '@/lib/format';

export type CityTripLike = { country: string; city: string | null; entry_date: string; exit_date: string | null };
export type CityOverlapRange = { start: string; end: string | null; isPast: boolean };
export type CityOverlap = { country: string; city: string; ranges: CityOverlapRange[] };

// Sorts after any real YYYY-MM-DD date — same sentinel trick as
// lib/tripCalendar.ts's country-level version, for an open-ended trip
// (no exit_date yet).
const OPEN_ENDED_SENTINEL = '9999-12-31';

/**
 * City-level counterpart to lib/tripCalendar.ts's computeSameCountryOverlaps
 * (which only ever compared country, never city, since it predates
 * per-visit city data being used this way) — same overlap-window math, but
 * additionally requires both sides' `city` to be set and match
 * (case-insensitive) within the same country. Trips with no city logged are
 * skipped entirely rather than treated as a match.
 */
/** Same interval-merge as lib/tripCalendar.ts's mergeOverlapRanges — collapses the O(my stops × partner stops) pairwise ranges below into the fewest spans that cover the same days. */
function mergeCityOverlapRanges(ranges: CityOverlapRange[]): CityOverlapRange[] {
  const today = toDateOnlyString(new Date());
  const sorted = [...ranges].sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0));

  const merged: { start: string; endSortable: string }[] = [];
  for (const range of sorted) {
    const endSortable = range.end ?? OPEN_ENDED_SENTINEL;
    const last = merged[merged.length - 1];
    if (last && range.start <= last.endSortable) {
      if (endSortable > last.endSortable) last.endSortable = endSortable;
    } else {
      merged.push({ start: range.start, endSortable });
    }
  }

  return merged.map((m) => ({
    start: m.start,
    end: m.endSortable === OPEN_ENDED_SENTINEL ? null : m.endSortable,
    isPast: m.start <= today,
  }));
}

export function computeSameCityOverlaps(myTrips: CityTripLike[], partnerTrips: CityTripLike[]): CityOverlap[] {
  const today = toDateOnlyString(new Date());
  const byCity = new Map<string, CityOverlapRange[]>();

  for (const mine of myTrips) {
    if (!mine.city?.trim()) continue;
    for (const partner of partnerTrips) {
      if (!partner.city?.trim()) continue;
      if (mine.country !== partner.country) continue;
      if (mine.city.trim().toLowerCase() !== partner.city.trim().toLowerCase()) continue;

      const myEndSortable = mine.exit_date ?? OPEN_ENDED_SENTINEL;
      const partnerEndSortable = partner.exit_date ?? OPEN_ENDED_SENTINEL;
      const overlapStart = mine.entry_date > partner.entry_date ? mine.entry_date : partner.entry_date;
      const overlapEndSortable = myEndSortable < partnerEndSortable ? myEndSortable : partnerEndSortable;
      if (overlapStart > overlapEndSortable) continue;

      const overlapEnd = overlapEndSortable === OPEN_ENDED_SENTINEL ? null : overlapEndSortable;
      const isPast = overlapStart <= today;

      const key = `${mine.country}|${mine.city.trim()}`;
      const existing = byCity.get(key) ?? [];
      existing.push({ start: overlapStart, end: overlapEnd, isPast });
      byCity.set(key, existing);
    }
  }

  return Array.from(byCity.entries())
    .map(([key, ranges]) => {
      const [country, city] = key.split('|');
      return { country, city, ranges: mergeCityOverlapRanges(ranges) };
    })
    .sort((a, b) => (a.city < b.city ? -1 : a.city > b.city ? 1 : 0));
}

export function filterCityOverlapsByTense(overlaps: CityOverlap[], tense: 'past' | 'future'): CityOverlap[] {
  return overlaps
    .map((overlap) => ({
      country: overlap.country,
      city: overlap.city,
      ranges: overlap.ranges.filter((r) => (tense === 'past' ? r.isPast : !r.isPast)),
    }))
    .filter((overlap) => overlap.ranges.length > 0);
}

/**
 * For "[connection] will be in your city" — NOT a mutual-overlap check
 * (the viewer doesn't need a trip logged too), just whether a connection
 * has a trip, current or upcoming, to the viewer's home city.
 */
export function findVisitsToCity(trips: CityTripLike[], targetCity: string): CityTripLike[] {
  const today = toDateOnlyString(new Date());
  const normalizedTarget = targetCity.trim().toLowerCase();
  return trips.filter(
    (t) => t.city?.trim().toLowerCase() === normalizedTarget && (!t.exit_date || t.exit_date >= today)
  );
}
