import { countDistinctDaysInWindow } from '@/lib/days';
import type { CountryVisitedRow } from '@/types/database';

/**
 * The CA-4 Border Control Agreement — Guatemala, El Salvador, Honduras and
 * Nicaragua treat visa-exempt visitors as being in ONE combined territory,
 * same pooling idea as Schengen's 90/180 rule but a genuinely different
 * mechanic: there's no rolling look-back window. The 90-day clock starts
 * on first entry to any of the four and counts continuously — crossing
 * between them doesn't reset it — until you leave the whole zone, at which
 * point a fresh entry normally gets a fresh 90 days (border officer's
 * discretion; no official minimum time outside is published).
 * Source: https://maprecap.com/ca4-calculator/ ,
 * https://www.rouletout.ch/ca4-countries
 */
export const CA4_COUNTRIES: readonly string[] = ['Guatemala', 'El Salvador', 'Honduras', 'Nicaragua'];

const CA4_SET = new Set(CA4_COUNTRIES);

export function isCa4Country(country: string): boolean {
  return CA4_SET.has(country);
}

export const CA4_LIMIT_DAYS = 90;
/** Flag once this many of the 90 are used — the heads-up point, same spirit as Schengen's own warning threshold. */
export const CA4_WARNING_THRESHOLD_DAYS = 85;

export type Ca4Status = {
  /** True only while today is actually inside a continuous CA-4 stay — once you've left the zone, this (and daysUsed) goes back to false/0, per the agreement's own reset-on-exit behavior. */
  isCurrentlyInZone: boolean;
  /** Continuous days in the zone, counting from the most recent entry after a gap, through today. 0 whenever isCurrentlyInZone is false. */
  daysUsed: number;
  daysRemaining: number;
  overLimit: boolean;
  nearLimit: boolean;
};

// Well before any real logged visit — the lower bound for pulling every
// CA-4 day ever logged, so the most recent continuous run is found
// regardless of how long ago it started.
const EPOCH = new Date(1900, 0, 1);

/**
 * Current CA-4 90-day status, pooled across all four member countries.
 * Unlike schengenStatus, this has nothing to report once you've actually
 * left the zone — the clock being reset on exit is the whole point of how
 * CA-4 works, not a limitation of this tracker.
 */
export function ca4Status(visits: Pick<CountryVisitedRow, 'country' | 'entry_date' | 'exit_date'>[], today: Date = new Date()): Ca4Status {
  const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const ca4Visits = visits.filter((v) => isCa4Country(v.country));
  const { days } = countDistinctDaysInWindow(ca4Visits, EPOCH, todayOnly, todayOnly);

  if (days.size === 0) {
    return { isCurrentlyInZone: false, daysUsed: 0, daysRemaining: CA4_LIMIT_DAYS, overLimit: false, nearLimit: false };
  }

  // Walk the sorted days to find the length of the run ending on the
  // LATEST day present — "latest" rather than "today" specifically,
  // since a visit that already ended isn't extended by this call's own
  // openEndedThrough=today (that only applies to visits with no
  // exit_date yet). If that latest day isn't actually today, the person
  // has already left the zone (their last logged stay ended before
  // today), so there's no current stay to report.
  const sortedDays = Array.from(days).sort();
  const latestDay = sortedDays[sortedDays.length - 1];
  const todayKey = toDateOnlyKey(todayOnly);
  if (latestDay !== todayKey) {
    return { isCurrentlyInZone: false, daysUsed: 0, daysRemaining: CA4_LIMIT_DAYS, overLimit: false, nearLimit: false };
  }

  let runLength = 1;
  for (let i = sortedDays.length - 2; i >= 0; i--) {
    const expectedPrev = addDaysKey(sortedDays[i + 1], -1);
    if (sortedDays[i] !== expectedPrev) break;
    runLength++;
  }

  const overLimit = runLength >= CA4_LIMIT_DAYS;
  const nearLimit = !overLimit && runLength >= CA4_WARNING_THRESHOLD_DAYS;

  return {
    isCurrentlyInZone: true,
    daysUsed: runLength,
    daysRemaining: Math.max(0, CA4_LIMIT_DAYS - runLength),
    overLimit,
    nearLimit,
  };
}

function toDateOnlyKey(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

function addDaysKey(dateKey: string, delta: number): string {
  const [y, m, d] = dateKey.split('-').map(Number);
  const date = new Date(y, m - 1, d);
  date.setDate(date.getDate() + delta);
  return toDateOnlyKey(date);
}
