export function currencyForCountry(countryName: string): string | null {
  return COUNTRIES.find((c) => c.name === countryName)?.currency ?? null;
}

/** Shown instead of a flag for any country the user has opted to hide — a neutral, non-political marker. Not curated by us: the user decides which countries this applies to, for whatever reason (contested regions, personal preference, etc). */
export const NEUTRAL_FLAG_ICON = '🌐';

/** The FLAG_SVGS lookup key (lib/flagSvgs.ts) for a country name from the list above, or null if the country isn't in the list at all. Callers combine this with the hidden-flags list themselves — see components/country-flag.tsx. */
export function flagCodeForCountry(countryName: string): string | null {
  return COUNTRIES.find((c) => c.name === countryName)?.code ?? null;
}

/** {value,label,icon?,flagCode?} options for SelectModal, shared by every country picker in the app — sorted A-Z by name. Hidden countries get the neutral text icon; visible ones get a flagCode for SelectModal to render via FlagIcon. */
export function buildCountrySelectOptions(hiddenFlagCountries: readonly string[] = []) {
  return COUNTRIES.map((c) => ({
    value: c.name,
    label: c.name,
    ...(hiddenFlagCountries.includes(c.name) ? { icon: NEUTRAL_FLAG_ICON } : { flagCode: c.code }),
  })).sort((a, b) => a.label.localeCompare(b.label));
}
