import Papa from 'papaparse';

import type { CategoryRuleRow, TransactionRow } from '@/types/database';

export const MAX_IMPORT_FILE_SIZE_BYTES = 5 * 1024 * 1024;

export type ImportFileKind = 'csv' | 'pdf';

export function importFileKind(name: string): ImportFileKind | null {
  const lower = name.toLowerCase();
  if (lower.endsWith('.csv')) return 'csv';
  if (lower.endsWith('.pdf')) return 'pdf';
  return null;
}

/** Rejects anything that isn't a .csv or .pdf by name, or is over the size cap — checked before we ever try to parse. */
export function validateImportFile(name: string, sizeBytes: number | undefined): string | null {
  if (!importFileKind(name)) {
    return "Please choose a .csv or .pdf file. Excel (.xlsx) import isn't supported yet. Export your statement as CSV or PDF first.";
  }
  if (sizeBytes !== undefined && sizeBytes > MAX_IMPORT_FILE_SIZE_BYTES) {
    return `File is too large (${(sizeBytes / (1024 * 1024)).toFixed(1)}MB). The limit is ${MAX_IMPORT_FILE_SIZE_BYTES / (1024 * 1024)}MB.`;
  }
  return null;
}

/** Parses raw CSV text into rows of cell strings — no header assumption, that's a separate step. */
export function parseCsv(content: string): string[][] {
  const result = Papa.parse<string[]>(content.trim(), { skipEmptyLines: true });
  return result.data.filter((row) => row.length > 0 && row.some((cell) => cell.trim() !== ''));
}

const HEADER_KEYWORDS = [
  'date',
  'amount',
  'debit',
  'credit',
  'description',
  'merchant',
  'payee',
  'memo',
  'balance',
  'transaction',
];

/** Heuristic: the first row is a header if any cell looks like a typical bank-export column name. Bank CSVs don't reliably have headers, so this isn't assumed. */
function looksLikeHeaderRow(row: string[]): boolean {
  return row.some((cell) => HEADER_KEYWORDS.some((keyword) => cell.toLowerCase().includes(keyword)));
}

export type SplitCsv = {
  /** Data rows only — the header row, if detected, is excluded. */
  rows: string[][];
  headerRow: string[] | null;
};

export function splitHeaderAndRows(allRows: string[][]): SplitCsv {
  if (allRows.length === 0) return { rows: [], headerRow: null };
  if (looksLikeHeaderRow(allRows[0])) {
    return { rows: allRows.slice(1), headerRow: allRows[0] };
  }
  return { rows: allRows, headerRow: null };
}

/** Labels for the column-mapping picker: the header cell text if we detected a header row, else "Column N". */
export function columnLabels(headerRow: string[] | null, columnCount: number): string[] {
  return Array.from({ length: columnCount }, (_, i) => headerRow?.[i]?.trim() || `Column ${i + 1}`);
}

/**
 * Guards against CSV/formula injection if this data is ever re-exported: a
 * cell starting with =, +, -, or @ can be interpreted as a formula by
 * spreadsheet software (e.g. Excel, Google Sheets) that opens the export.
 * Prefixing with a single quote is the standard mitigation — it keeps the
 * original text visible/recoverable while defusing the leading character.
 */
export function sanitizeCell(value: string): string {
  const trimmed = value.trim();
  return /^[=+\-@]/.test(trimmed) ? `'${trimmed}` : trimmed;
}

/** Parses a loosely-formatted money string: strips currency symbols/commas/whitespace, treats parenthesized values as negative. */
export function parseAmount(raw: string): number | null {
  const trimmed = raw.trim();
  if (!trimmed) return null;
  const isParenNegative = /^\(.*\)$/.test(trimmed);
  const cleaned = trimmed.replace(/[()$,\s]/g, '');
  if (!cleaned) return null;
  const value = Number(cleaned);
  if (Number.isNaN(value)) return null;
  return isParenNegative ? -Math.abs(value) : value;
}

function toIsoDate(year: number, month: number, day: number): string | null {
  if (month < 1 || month > 12 || day < 1 || day > 31) return null;
  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

export type DateFormat = 'MDY' | 'DMY';

/**
 * Parses ISO (YYYY-MM-DD) or slash-separated dates — the formats most bank
 * exports use. Slash-separated dates are genuinely ambiguous without a
 * locale hint (31/01/2026 aside, 03/04/2026 could be either), so the
 * importer asks up front which convention the source file uses and passes
 * it through here rather than guessing; defaults to MDY, matching how
 * dates are entered everywhere else in this app.
 */
export function parseDateFlexible(raw: string, dateFormat: DateFormat = 'MDY'): string | null {
  const trimmed = raw.trim();
  const isoMatch = trimmed.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (isoMatch) {
    const [, y, m, d] = isoMatch;
    return toIsoDate(Number(y), Number(m), Number(d));
  }
  const slashMatch = trimmed.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (slashMatch) {
    const [, first, second, y] = slashMatch;
    const [m, d] = dateFormat === 'DMY' ? [second, first] : [first, second];
    return toIsoDate(Number(y), Number(m), Number(d));
  }
  return null;
}

/** Lowercased, punctuation-stripped, whitespace-collapsed — used for both category-rule matching and duplicate detection. */
export function normalizeMerchant(raw: string): string {
  return raw
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Case-insensitive substring match against category_rules.merchant_pattern — first match wins. */
export function matchCategoryRule(merchant: string, rules: CategoryRuleRow[]): string | null {
  const normalizedMerchant = merchant.toLowerCase();
  const rule = rules.find((r) => normalizedMerchant.includes(r.merchant_pattern.toLowerCase()));
  return rule?.category_id ?? null;
}

/** Two merchant strings are "similar" for dedup purposes if, once normalized, one contains the other (handles suffixes like transaction IDs). */
function merchantsAreSimilar(a: string, b: string): boolean {
  const normA = normalizeMerchant(a);
  const normB = normalizeMerchant(b);
  if (!normA || !normB) return normA === normB;
  return normA === normB || normA.includes(normB) || normB.includes(normA);
}

export type ImportCandidate = {
  date: string;
  amount: number;
  merchant: string;
};

/** A candidate row is a likely duplicate if an existing transaction shares its date and exact amount, with a similar merchant string. */
export function isLikelyDuplicate(candidate: ImportCandidate, existing: TransactionRow[]): boolean {
  return existing.some(
    (tx) =>
      tx.date === candidate.date &&
      tx.amount === candidate.amount &&
      merchantsAreSimilar(tx.merchant ?? '', candidate.merchant)
  );
}
