import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { PlaidConnectButton } from '@/components/plaid-connect-button';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccents } from '@/constants/theme';
import { formatDateDisplay, toDateOnlyString } from '@/lib/format';
import { supabase } from '@/lib/supabase';

const ACCENT = ModuleAccents.accounts;

type PlaidConnection = { id: string; institution_name: string | null; created_at: string };

export default function PlaidConnectScreen() {
  const router = useRouter();
  const [connections, setConnections] = useState<PlaidConnection[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const { data, error: fetchError } = await supabase.rpc('my_plaid_connections');
    if (fetchError) {
      setError(fetchError.message);
    } else {
      setConnections(data ?? []);
    }
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Connect a Bank
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedText style={styles.hint}>
          Sandbox test mode, uses Plaid&apos;s fake test institutions and data, not a real bank connection. Nothing
          here pulls real account balances or transactions yet.
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <PlaidConnectButton accentColor={ACCENT} onConnected={load} onError={setError} />

        <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
          Connected
        </ThemedText>
        {isLoading ? (
          <ActivityIndicator color={ACCENT} />
        ) : connections.length === 0 ? (
          <ThemedText style={styles.muted}>Nothing connected yet.</ThemedText>
        ) : (
          connections.map((c) => (
            <Surface key={c.id} accentColor={ACCENT}>
              <ThemedText type="defaultSemiBold">{c.institution_name ?? 'Unknown institution'}</ThemedText>
              <ThemedText style={styles.muted}>Connected {formatDateDisplay(toDateOnlyString(new Date(c.created_at)))}</ThemedText>
            </Surface>
          ))
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 4,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    fontStyle: 'italic',
  },
  sectionSpacing: {
    marginTop: 16,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
