import type { BalanceSnapshotRow } from '@/types/database';

/** Assumes snapshots are already sorted by date descending. */
export function latestSnapshotByAccount(snapshots: BalanceSnapshotRow[]): Map<string, BalanceSnapshotRow> {
  const map = new Map<string, BalanceSnapshotRow>();
  for (const snapshot of snapshots) {
    if (!map.has(snapshot.account_id)) {
      map.set(snapshot.account_id, snapshot);
    }
  }
  return map;
}

export function transactionSumByAccount(
  transactions: { account_id: string | null; amount: number }[]
): Map<string, number> {
  const map = new Map<string, number>();
  for (const tx of transactions) {
    if (!tx.account_id) continue;
    map.set(tx.account_id, (map.get(tx.account_id) ?? 0) + tx.amount);
  }
  return map;
}
