import { useFocusEffect } from '@react-navigation/native';
import { useCallback, useState } from 'react';
import { Pressable, StyleSheet } from 'react-native';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import type { ChecklistItem } from '@/lib/countryChecklist';
import { supabase } from '@/lib/supabase';

/**
 * Self-contained: fetches and persists its own completion state (in
 * country_checklist_completions, shared across every checklist that uses
 * this component — item_key namespaces keep them from colliding, e.g.
 * MOVING_CHECKLIST_ITEMS's plain keys vs TRAVEL_CHECKLIST_ITEMS's
 * "travel_"-prefixed ones) for the given country, so it can be dropped into
 * any screen without that screen threading the fetch/toggle logic itself.
 * `items` is which checklist to render — this component doesn't know or
 * care which one it is.
 */
export function CountryChecklist({
  country,
  accentColor,
  items,
  onProgress,
}: {
  country: string;
  accentColor: string;
  items: ChecklistItem[];
  /** Called after every load/toggle with (checkedCount, totalCount) — lets a parent (e.g. Summary) know when a checklist is fully done without duplicating the fetch. */
  onProgress?: (checked: number, total: number) => void;
}) {
  const { session } = useAuth();
  const [checkedItems, setCheckedItems] = useState<Set<string>>(new Set());
  const [isLoading, setIsLoading] = useState(true);

  const load = useCallback(async () => {
    const { data } = await supabase.from('country_checklist_completions').select('item_key').eq('country', country);
    const relevantKeys = new Set(items.map((i) => i.key));
    const checked = new Set((data ?? []).map((row) => row.item_key).filter((key) => relevantKeys.has(key)));
    setCheckedItems(checked);
    setIsLoading(false);
    onProgress?.(checked.size, items.length);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [country, items]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  async function toggleChecklistItem(itemKey: string) {
    if (!session) return;
    const isChecked = checkedItems.has(itemKey);

    let next: Set<string> = checkedItems;
    setCheckedItems((prev) => {
      next = new Set(prev);
      if (isChecked) next.delete(itemKey);
      else next.add(itemKey);
      return next;
    });
    onProgress?.(next.size, items.length);

    if (isChecked) {
      await supabase
        .from('country_checklist_completions')
        .delete()
        .eq('user_id', session.user.id)
        .eq('country', country)
        .eq('item_key', itemKey);
    } else {
      await supabase
        .from('country_checklist_completions')
        .insert({ user_id: session.user.id, country, item_key: itemKey });
    }
  }

  if (isLoading) return null;

  return (
    <Surface accentColor={accentColor} style={styles.card}>
      {items.map((item) => {
        const isChecked = checkedItems.has(item.key);
        return (
          <Pressable key={item.key} onPress={() => toggleChecklistItem(item.key)} style={styles.row}>
            <IconSymbol
              name={isChecked ? 'checkmark.circle.fill' : 'circle'}
              size={22}
              color={isChecked ? accentColor : Colors.light.icon}
            />
            <ThemedText style={isChecked ? styles.labelDone : undefined}>{item.label}</ThemedText>
          </Pressable>
        );
      })}
    </Surface>
  );
}

const styles = StyleSheet.create({
  card: {
    gap: 10,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
  },
  labelDone: {
    textDecorationLine: 'line-through',
    opacity: 0.6,
  },
});
