import { LOCAL_CURRENCY } from '@/contexts/currency-context';
import { currencyForCountry } from '@/lib/countries';

export type WealthCurrencySource = 'display' | 'home-country' | 'default';

/**
 * The wealth chart blends amounts from multiple native currencies into one
 * number, so unlike per-transaction display, "Local" (no conversion) isn't a
 * coherent option here — it needs a single real currency to compute in.
 */
export function resolveWealthCurrency(
  displayCurrency: string,
  homeCountry: string | null,
  availableCurrencies: string[]
): { currency: string; source: WealthCurrencySource } {
  if (displayCurrency !== LOCAL_CURRENCY) {
    return { currency: displayCurrency, source: 'display' };
  }

  const countryCurrency = homeCountry ? currencyForCountry(homeCountry) : null;
  if (countryCurrency && availableCurrencies.includes(countryCurrency)) {
    return { currency: countryCurrency, source: 'home-country' };
  }

  return { currency: 'USD', source: 'default' };
}
