import * as DocumentPicker from 'expo-document-picker';
import { File } from 'expo-file-system';
import * as ImagePicker from 'expo-image-picker';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput } from 'react-native';

import { DateInput } from '@/components/date-input';
import { SelectModal } from '@/components/select-modal';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { NOT_LINKED_VALUE, TripStopPicker, type TripLinkValue } from '@/components/trip-stop-picker';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { DOCUMENT_TYPE_OPTIONS, MAX_DOCUMENT_FILE_SIZE_BYTES, SUPPORTED_DOCUMENT_MIME_TYPES } from '@/lib/documents';
import { toDateOnlyString } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import { computeTripSummaries } from '@/lib/trips';
import type { CountryVisitedRow, DocumentType, TripRow, TripSegmentRow } from '@/types/database';

const ACCENT = ModuleAccents.documents;

type PickedFile = { uri: string; name: string; mimeType: string; size: number | null };

function formatFileSize(bytes: number | null): string {
  if (bytes === null) return '';
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

export default function NewDocumentScreen() {
  const router = useRouter();
  const { session } = useAuth();
  // Arriving from a trip's own screen (mine, or one I'm a full/contributor
  // collaborator on) — trip data then comes from the collaboration RPCs
  // below instead of the "all my own trips" query, since a contributor has
  // no trips rows of their own to query directly.
  const { tripId } = useLocalSearchParams<{ tripId?: string }>();

  const [pickedFile, setPickedFile] = useState<PickedFile | null>(null);
  const [docType, setDocType] = useState<DocumentType>('other');
  const [showTypePicker, setShowTypePicker] = useState(false);
  const [name, setName] = useState('');
  const [issueDate, setIssueDate] = useState<Date | null>(null);
  const [expiryDate, setExpiryDate] = useState<Date | null>(null);
  const [notes, setNotes] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Only relevant once Type is set to "Proof of Travel" — loaded once,
  // lazily, on the first switch to that type rather than unconditionally
  // on mount, since most documents never need this.
  const [trips, setTrips] = useState<TripRow[]>([]);
  const [stops, setStops] = useState<CountryVisitedRow[]>([]);
  const [segments, setSegments] = useState<TripSegmentRow[]>([]);
  const [tripDataLoaded, setTripDataLoaded] = useState(false);
  const [tripLinkValue, setTripLinkValue] = useState<TripLinkValue>(NOT_LINKED_VALUE);
  const [showTripPicker, setShowTripPicker] = useState(false);

  useEffect(() => {
    if (tripDataLoaded) return;
    if (tripId) {
      setTripDataLoaded(true);
      Promise.all([
        supabase.rpc('trip_collaboration_trip', { p_trip_id: tripId }),
        supabase.rpc('trip_collaboration_stops', { p_trip_id: tripId }),
        supabase.rpc('trip_collaboration_segments', { p_trip_id: tripId }),
      ]).then(([tripResult, stopsResult, segmentsResult]) => {
        const loadedStops = stopsResult.data ?? [];
        const loadedSegments = segmentsResult.data ?? [];
        setTrips((tripResult.data ?? []) as TripRow[]);
        setStops(loadedStops);
        setSegments(loadedSegments);
        // Pre-select the first stop so the common case is one less tap —
        // a document added from a trip's own screen that ISN'T linked to
        // it would never show up there, which is the whole point.
        const first = loadedStops[0] ? `stop:${loadedStops[0].id}` : loadedSegments[0] ? `segment:${loadedSegments[0].id}` : null;
        if (first) setTripLinkValue((prev) => (prev === NOT_LINKED_VALUE ? first : prev));
      });
      return;
    }
    if (docType !== 'proof_of_travel') return;
    setTripDataLoaded(true);
    Promise.all([
      supabase.from('trips').select('*'),
      supabase.from('countries_visited').select('*'),
      supabase.from('trip_segments').select('*'),
    ]).then(([tripsResult, stopsResult, segmentsResult]) => {
      setTrips(tripsResult.data ?? []);
      setStops(stopsResult.data ?? []);
      setSegments(segmentsResult.data ?? []);
    });
  }, [docType, tripDataLoaded, tripId]);

  function rejectIfTooLarge(size: number | null): boolean {
    if (size && size > MAX_DOCUMENT_FILE_SIZE_BYTES) {
      setError('That file is larger than 10MB. Please choose a smaller one.');
      return true;
    }
    return false;
  }

  async function handlePickPhoto() {
    setError(null);
    const permission = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (!permission.granted) {
      setError('Photo library permission is required.');
      return;
    }

    const result = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], quality: 0.8 });
    if (result.canceled || !result.assets[0]) return;

    const asset = result.assets[0];
    if (rejectIfTooLarge(asset.fileSize ?? null)) return;

    const fileName = asset.fileName ?? `photo-${Date.now()}.jpg`;
    setPickedFile({ uri: asset.uri, name: fileName, mimeType: asset.mimeType ?? 'image/jpeg', size: asset.fileSize ?? null });
    setName((prev) => prev || fileName);
  }

  async function handlePickDocument() {
    setError(null);
    const result = await DocumentPicker.getDocumentAsync({
      type: SUPPORTED_DOCUMENT_MIME_TYPES,
      copyToCacheDirectory: true,
    });
    if (result.canceled || !result.assets[0]) return;

    const asset = result.assets[0];
    if (rejectIfTooLarge(asset.size ?? null)) return;

    setPickedFile({
      uri: asset.uri,
      name: asset.name,
      mimeType: asset.mimeType ?? 'application/octet-stream',
      size: asset.size ?? null,
    });
    setName((prev) => prev || asset.name);
  }

  async function handleSave() {
    if (!session || !pickedFile) return;
    if (!name.trim()) {
      setError('Name is required.');
      return;
    }
    if (tripId && tripLinkValue === NOT_LINKED_VALUE) {
      setError('Choose which stop or leg this document belongs to.');
      return;
    }

    setError(null);
    setIsSaving(true);

    try {
      // fetch(uri).blob() is unreliable for local file:// / content:// picker
      // URIs on device (the "network request failed" this was hitting isn't
      // a real connectivity issue) — read raw bytes via expo-file-system
      // instead, the same File-class approach already used for CSV import.
      const file = new File(pickedFile.uri);
      const bytes = await file.bytes();

      const sanitizedName = pickedFile.name.replace(/[^a-zA-Z0-9._-]/g, '_');
      const path = `${session.user.id}/${Date.now()}-${sanitizedName}`;

      const { error: uploadError } = await supabase.storage
        .from('documents')
        .upload(path, bytes, { contentType: pickedFile.mimeType });

      if (uploadError) {
        setError(uploadError.message);
        setIsSaving(false);
        return;
      }

      const { error: insertError } = await supabase.from('documents').insert({
        user_id: session.user.id,
        doc_type: docType,
        name: name.trim(),
        file_ref: path,
        issue_date: issueDate ? toDateOnlyString(issueDate) : null,
        expiry_date: expiryDate ? toDateOnlyString(expiryDate) : null,
        notes: notes.trim() || null,
        trip_stop_id: tripLinkValue.startsWith('stop:') ? tripLinkValue.slice(5) : null,
        trip_segment_id: tripLinkValue.startsWith('segment:') ? tripLinkValue.slice(8) : null,
      });

      if (insertError) {
        // Don't leave an orphaned file if the row itself couldn't be created.
        await supabase.storage.from('documents').remove([path]);
        setError(insertError.message);
        setIsSaving(false);
        return;
      }

      router.back();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Upload failed.');
      setIsSaving(false);
    }
  }

  const typeLabel = DOCUMENT_TYPE_OPTIONS.find((o) => o.value === docType)?.label ?? 'Other';

  const tripSummaries = computeTripSummaries(trips, stops, segments);
  let tripLinkLabel = 'Not linked';
  if (tripLinkValue.startsWith('stop:')) {
    const stop = stops.find((s) => s.id === tripLinkValue.slice(5));
    const summary = tripSummaries.find((t) => t.id === stop?.trip_id);
    if (stop) tripLinkLabel = `${summary?.displayName ?? 'Trip'}: ${stop.city?.trim() || stop.country}`;
  } else if (tripLinkValue.startsWith('segment:')) {
    const segment = segments.find((s) => s.id === tripLinkValue.slice(8));
    const summary = tripSummaries.find((t) => t.id === segment?.trip_id);
    if (segment) tripLinkLabel = `${summary?.displayName ?? 'Trip'}: ${segment.from_label} → ${segment.to_label}`;
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Add Document
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Cancel</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {!pickedFile ? (
          <>
            <ThemedText style={styles.hint}>Choose a photo of the document or pick a file (PDF or image).</ThemedText>
            <Pressable onPress={handlePickPhoto} style={[styles.button, { backgroundColor: ACCENT }]}>
              <ThemedText style={{ color: ModuleAccentOnColor.documents, fontWeight: '600' }}>
                Choose from Photo Library
              </ThemedText>
            </Pressable>
            <Pressable onPress={handlePickDocument} style={[styles.button, styles.buttonOutline, { borderColor: ACCENT }]}>
              <ThemedText style={{ color: ACCENT, fontWeight: '600' }}>Choose a File</ThemedText>
            </Pressable>
          </>
        ) : (
          <>
            <Surface accentColor={ACCENT} style={styles.fileCard}>
              <ThemedText type="defaultSemiBold" numberOfLines={1}>
                {pickedFile.name}
              </ThemedText>
              <ThemedText style={styles.muted}>{formatFileSize(pickedFile.size)}</ThemedText>
              <Pressable onPress={() => setPickedFile(null)}>
                <ThemedText type="link">Choose a different file</ThemedText>
              </Pressable>
            </Surface>

            <ThemedText type="defaultSemiBold">Type</ThemedText>
            <Pressable onPress={() => setShowTypePicker(true)} style={[styles.input, { borderColor: ACCENT }]}>
              <ThemedText>{typeLabel}</ThemedText>
            </Pressable>
            <SelectModal
              visible={showTypePicker}
              onClose={() => setShowTypePicker(false)}
              options={DOCUMENT_TYPE_OPTIONS}
              selectedValue={docType}
              onSelect={(value) => setDocType(value as DocumentType)}
            />

            {docType === 'proof_of_travel' || tripId ? (
              <>
                <ThemedText type="defaultSemiBold">{tripId ? 'Link to' : 'Proof for'}</ThemedText>
                <ThemedText style={styles.hint}>
                  {tripId
                    ? 'Ties this document to a specific stop or leg on this trip, shows up in its Documents list.'
                    : "Ties this document to a specific stop or leg, shows up as supporting evidence on that country's day-count."}
                </ThemedText>
                <Pressable onPress={() => setShowTripPicker(true)} style={[styles.input, { borderColor: ACCENT }]}>
                  <ThemedText>{tripLinkLabel}</ThemedText>
                </Pressable>
                <TripStopPicker
                  visible={showTripPicker}
                  onClose={() => setShowTripPicker(false)}
                  trips={trips}
                  stops={stops}
                  segments={segments}
                  selectedValue={tripLinkValue}
                  onSelect={(value) => {
                    setShowTripPicker(false);
                    setTripLinkValue(value);
                  }}
                />
              </>
            ) : null}

            <ThemedText type="defaultSemiBold">Name</ThemedText>
            <TextInput
              value={name}
              onChangeText={setName}
              placeholder="e.g. Passport"
              placeholderTextColor={Colors.light.textMuted}
              style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
            />

            <ThemedText type="defaultSemiBold">Issue date (optional)</ThemedText>
            <ThemedView style={styles.dateRow}>
              <ThemedView style={styles.dateInput}>
                <DateInput
                  value={issueDate}
                  onChange={(date) => {
                    setIssueDate(date);
                    if (expiryDate && expiryDate < date) setExpiryDate(date);
                  }}
                  accentColor={ACCENT}
                  placeholder="Not set"
                />
              </ThemedView>
              {issueDate ? (
                <Pressable onPress={() => setIssueDate(null)} hitSlop={8}>
                  <ThemedText style={{ color: Colors.light.negative }}>Clear</ThemedText>
                </Pressable>
              ) : null}
            </ThemedView>

            <ThemedText type="defaultSemiBold">Expiry date (optional)</ThemedText>
            <ThemedView style={styles.dateRow}>
              <ThemedView style={styles.dateInput}>
                <DateInput
                  value={expiryDate}
                  onChange={setExpiryDate}
                  accentColor={ACCENT}
                  minimumDate={issueDate ?? undefined}
                  placeholder="Not set"
                />
              </ThemedView>
              {expiryDate ? (
                <Pressable onPress={() => setExpiryDate(null)} hitSlop={8}>
                  <ThemedText style={{ color: Colors.light.negative }}>Clear</ThemedText>
                </Pressable>
              ) : null}
            </ThemedView>

            <ThemedText type="defaultSemiBold">Notes</ThemedText>
            <ThemedText style={styles.hint}>
              Keep this non-sensitive, a description like &quot;backup copy,&quot; not account or ID numbers.
            </ThemedText>
            <TextInput
              value={notes}
              onChangeText={setNotes}
              placeholder="Optional"
              placeholderTextColor={Colors.light.textMuted}
              multiline
              numberOfLines={3}
              style={[styles.input, styles.notesInput, { color: Colors.light.text, borderColor: ACCENT }]}
            />

            <Pressable onPress={handleSave} disabled={isSaving} style={[styles.button, { backgroundColor: ACCENT }]}>
              {isSaving ? (
                <ActivityIndicator color={ModuleAccentOnColor.documents} />
              ) : (
                <ThemedText style={{ color: ModuleAccentOnColor.documents, fontWeight: '600' }}>Upload</ThemedText>
              )}
            </Pressable>
          </>
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
    marginBottom: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  buttonOutline: {
    backgroundColor: 'transparent',
    borderWidth: StyleSheet.hairlineWidth,
  },
  fileCard: {
    gap: 4,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  dateRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
  },
  dateInput: {
    flex: 1,
  },
  notesInput: {
    minHeight: 80,
    textAlignVertical: 'top',
  },
  muted: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
