import { useMemo, useState } from 'react';
import { Pressable, StyleSheet, TextInput, View, type StyleProp, type TextStyle } from 'react-native';

import { CountryFlag } from '@/components/country-flag';
import { ThemedText } from '@/components/themed-text';
import { Colors } from '@/constants/theme';
import { COUNTRIES } from '@/lib/countries';

const MAX_RESULTS = 8;

/**
 * Type-and-filter replacement for the SelectModal country picker (tap to
 * open a modal, scroll/tap a list) — a faster path for anyone who already
 * knows the country name, which is the common case. Purely client-side:
 * COUNTRIES (lib/countries.ts) is a small static list, so unlike
 * CityAutocompleteInput there's no network round trip, no debounce, no
 * error state — just an instant filter on every keystroke.
 */
export function CountryAutocompleteInput({
  value,
  onChangeText,
  onSelectCountry,
  hiddenFlagCountries = [],
  placeholder = 'e.g. Portugal',
  accentColor,
  onBlur,
  inputStyle,
}: {
  value: string;
  onChangeText: (text: string) => void;
  onSelectCountry: (countryName: string) => void;
  hiddenFlagCountries?: readonly string[];
  placeholder?: string;
  accentColor: string;
  /** For a screen that needs to react once typing settles (e.g. account/index.tsx committing an exact-match home country, or reverting an invalid one) — fires alongside the internal focus-tracking blur handler below, doesn't replace it. */
  onBlur?: () => void;
  /** Extra styling layered onto the text input itself (e.g. the tour walkthrough's highlight border) — merged after the base/accent-color styles below. */
  inputStyle?: StyleProp<TextStyle>;
}) {
  const [isFocused, setIsFocused] = useState(false);

  const matches = useMemo(() => {
    const query = value.trim().toLowerCase();
    if (!query) return [];
    // Names starting with the query rank above names that merely contain
    // it (e.g. typing "united" surfaces "United States" and "United
    // Kingdom" before "United Arab Emirates" would otherwise tie-break
    // arbitrarily against them alphabetically).
    const starts: string[] = [];
    const contains: string[] = [];
    for (const c of COUNTRIES) {
      const name = c.name.toLowerCase();
      if (name.startsWith(query)) starts.push(c.name);
      else if (name.includes(query)) contains.push(c.name);
    }
    starts.sort((a, b) => a.localeCompare(b));
    contains.sort((a, b) => a.localeCompare(b));
    return [...starts, ...contains].slice(0, MAX_RESULTS);
  }, [value]);

  // Collapsing to nothing the instant a keystroke drops matches to zero
  // (as this used to) means whatever's below the field — the next form
  // field, in every real usage — snaps upward right under a still-moving
  // finger, which can land a tap meant for a dropdown row on that next
  // field instead: confirmed directly, a real user's report of typing in
  // a Country field and the keyboard ending up in the City field below it
  // traced to exactly this layout shift via a real device's touch/focus
  // event log, not a deliberate focus change anywhere in this app's code.
  // CityAutocompleteInput already avoids this by keeping its dropdown box
  // present (rendering "No matches." instead of nothing) whenever there's
  // enough text to search at all — matched here for the same reason.
  const showDropdown = isFocused && value.trim().length > 0;

  return (
    // Same zIndex-only-while-open pattern as CityAutocompleteInput — keeps
    // a later field's dropdown from painting over an earlier one's.
    <View style={[styles.container, showDropdown ? styles.containerOpen : null]}>
      <TextInput
        value={value}
        onChangeText={onChangeText}
        onFocus={() => setIsFocused(true)}
        onBlur={() => {
          onBlur?.();
          setTimeout(() => setIsFocused(false), 150);
        }}
        placeholder={placeholder}
        placeholderTextColor={Colors.light.textMuted}
        style={[styles.input, { color: Colors.light.text, borderColor: accentColor }, inputStyle]}
      />
      {showDropdown ? (
        <View collapsable={false} style={[styles.dropdown, { borderColor: accentColor }]}>
          {/* No ScrollView, confirmed by direct A/B testing on a real
              device: with it, a real tap stopped registering at all,
              twice, even with collapsable={false} in place too — this
              nesting is fundamentally unreliable for selection on native,
              not just missing one prop. MAX_RESULTS hard-caps this at 8
              rows, so styles.dropdown's maxHeight below is sized to fit
              all 8 without clipping instead: there is no scrolling left
              to need, rather than a scrolling mechanism that doesn't
              actually work. collapsable={false} stays regardless — real,
              separate fix for a tap/drag over this box reaching the City
              field behind it instead (Android can flatten a simple View
              into its parent, corrupting an absolutely-positioned box's
              touch-target boundary). */}
          {matches.length === 0 ? (
            <ThemedText style={styles.noMatches}>No matches.</ThemedText>
          ) : (
            matches.map((name, index) => (
              <Pressable
                key={name}
                collapsable={false}
                onPress={() => onSelectCountry(name)}
                style={[styles.row, index < matches.length - 1 ? styles.rowBorder : null]}>
                <CountryFlag countryName={name} hiddenFlagCountries={hiddenFlagCountries} size={18} />
                <ThemedText numberOfLines={1} style={styles.rowLabel}>
                  {name}
                </ThemedText>
              </Pressable>
            ))
          )}
        </View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    position: 'relative',
    zIndex: 10,
  },
  containerOpen: {
    zIndex: 100,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
  },
  dropdown: {
    position: 'absolute',
    top: '100%',
    left: 0,
    right: 0,
    marginTop: 4,
    backgroundColor: Colors.light.backgroundSolid,
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    // Fits all MAX_RESULTS=8 rows without clipping — see the comment
    // above the dropdown box itself for why there's no ScrollView to
    // handle an overflow this is sized to never have.
    maxHeight: 400,
    overflow: 'hidden',
    zIndex: 20,
    elevation: 6,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
    paddingHorizontal: 16,
    paddingVertical: 10,
  },
  rowBorder: {
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: Colors.light.cardBorder,
  },
  rowLabel: {
    flex: 1,
  },
  noMatches: {
    fontSize: 12,
    opacity: 0.6,
    color: Colors.light.textMuted,
    paddingHorizontal: 16,
    paddingVertical: 10,
  },
});
