import { useLocalSearchParams, useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, Switch, TextInput } from 'react-native';

import { DateInput } from '@/components/date-input';
import { OwnershipPicker } from '@/components/ownership-picker';
import { SelectModal, type SelectOption } from '@/components/select-modal';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, Fonts, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useCurrency } from '@/contexts/currency-context';
import { useScope } from '@/contexts/scope-context';
import { showAlert } from '@/lib/alert';
import { toDateOnlyString } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import type { AccountRow, CreditCardRow } from '@/types/database';

const ACCENT = ModuleAccents.cards;

export default function CardFormScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const isNew = id === 'new';
  const router = useRouter();
  const { session } = useAuth();
  const { availableCurrencies, currencyNames } = useCurrency();

  const [isLoading, setIsLoading] = useState(!isNew);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [issuer, setIssuer] = useState('');
  const [name, setName] = useState('');
  const [annualFee, setAnnualFee] = useState('0');
  const [feeCurrency, setFeeCurrency] = useState('USD');
  const [renewalDate, setRenewalDate] = useState(new Date());
  const [openedDate, setOpenedDate] = useState<Date | null>(null);
  const [pointsProgram, setPointsProgram] = useState('');
  const [paymentDueDay, setPaymentDueDay] = useState('');
  const [paymentAccountId, setPaymentAccountId] = useState<string | null>(null);
  const [accounts, setAccounts] = useState<AccountRow[]>([]);
  const [showAccountPicker, setShowAccountPicker] = useState(false);
  const [showFeeCurrencyPicker, setShowFeeCurrencyPicker] = useState(false);
  const [isActive, setIsActive] = useState(true);
  const [ownership, setOwnership] = useState<CreditCardRow['ownership']>('personal');
  const { refresh: refreshScope } = useScope();

  useEffect(() => {
    supabase
      .from('accounts')
      .select('*')
      .eq('is_active', true)
      .order('name')
      .then(({ data }) => setAccounts(data ?? []));
  }, []);

  useEffect(() => {
    if (isNew) return;

    let cancelled = false;
    supabase
      .from('credit_cards')
      .select('*')
      .eq('id', id)
      .single()
      .then(({ data, error: fetchError }) => {
        if (cancelled) return;
        if (fetchError) {
          setError(fetchError.message);
        } else if (data) {
          setIssuer(data.issuer);
          setName(data.name);
          setAnnualFee(String(data.annual_fee));
          setFeeCurrency(data.fee_currency);
          setRenewalDate(parseDateOnly(data.renewal_date));
          setOpenedDate(data.opened_date ? parseDateOnly(data.opened_date) : null);
          setPointsProgram(data.points_program ?? '');
          setPaymentDueDay(data.payment_due_day !== null ? String(data.payment_due_day) : '');
          setPaymentAccountId(data.payment_account_id);
          setOwnership(data.ownership);
          setIsActive(data.is_active);
        }
        setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [id, isNew]);

  const accountOptions: SelectOption[] = accounts.map((a) => ({
    value: a.id,
    label: `${a.name}${a.institution ? ` · ${a.institution}` : ''}`,
  }));
  const selectedAccount = accounts.find((a) => a.id === paymentAccountId) ?? null;

  // Falls back to the bare code if the name hasn't been populated yet, same as components/top-bar.tsx's own currency picker.
  function currencyLabel(code: string): string {
    const currencyName = currencyNames[code];
    return currencyName ? `${currencyName} (${code})` : code;
  }
  const feeCurrencyOptions: SelectOption[] = availableCurrencies.map((code) => ({
    value: code,
    label: currencyLabel(code),
  }));

  async function handleSave() {
    if (!issuer.trim() || !name.trim()) {
      setError('Issuer and card name are required.');
      return;
    }
    const parsedFee = Number(annualFee);
    if (Number.isNaN(parsedFee)) {
      setError('Annual fee must be a number.');
      return;
    }
    if (!feeCurrency.trim()) {
      setError('Fee currency is required.');
      return;
    }
    const parsedDueDay = paymentDueDay.trim() ? Number(paymentDueDay) : null;
    if (parsedDueDay !== null && (!Number.isInteger(parsedDueDay) || parsedDueDay < 1 || parsedDueDay > 31)) {
      setError('Payment due day must be a whole number between 1 and 31.');
      return;
    }
    if (!session) {
      setError('You must be signed in.');
      return;
    }

    setError(null);
    setIsSaving(true);

    const payload = {
      issuer: issuer.trim(),
      name: name.trim(),
      annual_fee: parsedFee,
      fee_currency: feeCurrency.trim().toUpperCase(),
      renewal_date: toDateOnlyString(renewalDate),
      opened_date: openedDate ? toDateOnlyString(openedDate) : null,
      points_program: pointsProgram.trim() || null,
      payment_due_day: parsedDueDay,
      payment_account_id: paymentAccountId,
      ownership,
      is_active: isActive,
    };

    const { error: saveError } = isNew
      ? await supabase.from('credit_cards').insert({ ...payload, user_id: session.user.id })
      : await supabase.from('credit_cards').update(payload).eq('id', id);

    setIsSaving(false);

    if (saveError) {
      setError(saveError.message);
      return;
    }

    // The scope switch's ownership map is refreshed on demand, not
    // subscribed — this is the moment a tag can change.
    refreshScope();

    router.back();
  }

  function handleDelete() {
    showAlert('Delete card', 'This will also delete its points balances and transactions. This cannot be undone.', [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Delete',
        style: 'destructive',
        onPress: async () => {
          setIsSaving(true);
          const { error: deleteError } = await supabase.from('credit_cards').delete().eq('id', id);
          setIsSaving(false);
          if (deleteError) {
            setError(deleteError.message);
            return;
          }
          router.back();
        },
      },
    ]);
  }

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            {isNew ? 'Add Card' : 'Edit Card'}
          </ThemedText>
          {!isNew ? (
            <Pressable onPress={handleDelete} hitSlop={12}>
              <IconSymbol name="trash" size={22} color={Colors.light.negative} />
            </Pressable>
          ) : null}
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedText type="defaultSemiBold">Issuer</ThemedText>
        <TextInput
          value={issuer}
          onChangeText={setIssuer}
          placeholder="e.g. Chase"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <ThemedText type="defaultSemiBold">Card name</ThemedText>
        <TextInput
          value={name}
          onChangeText={setName}
          placeholder="e.g. Sapphire Preferred"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <ThemedText type="defaultSemiBold">Annual fee</ThemedText>
        <TextInput
          value={annualFee}
          onChangeText={setAnnualFee}
          placeholder="0"
          keyboardType="decimal-pad"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, styles.monoInput, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <ThemedText type="defaultSemiBold">Fee currency</ThemedText>
        <Pressable onPress={() => setShowFeeCurrencyPicker(true)} style={[styles.input, { borderColor: ACCENT }]}>
          <ThemedText>{feeCurrency ? currencyLabel(feeCurrency) : 'Select a currency'}</ThemedText>
        </Pressable>
        <SelectModal
          visible={showFeeCurrencyPicker}
          onClose={() => setShowFeeCurrencyPicker(false)}
          options={feeCurrencyOptions}
          selectedValue={feeCurrency || null}
          onSelect={(value) => {
            setFeeCurrency(value);
            setShowFeeCurrencyPicker(false);
          }}
        />

        <ThemedText type="defaultSemiBold">Renewal date</ThemedText>
        <DateInput value={renewalDate} onChange={setRenewalDate} accentColor={ACCENT} />

        <ThemedText type="defaultSemiBold">Opened date (optional)</ThemedText>
        <DateInput value={openedDate} onChange={setOpenedDate} accentColor={ACCENT} placeholder="Not set" />

        <ThemedText type="defaultSemiBold">Points program (optional)</ThemedText>
        <TextInput
          value={pointsProgram}
          onChangeText={setPointsProgram}
          placeholder="e.g. Chase Ultimate Rewards"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <ThemedText type="defaultSemiBold">Payment due day (optional)</ThemedText>
        <TextInput
          value={paymentDueDay}
          onChangeText={setPaymentDueDay}
          placeholder="e.g. 15"
          keyboardType="number-pad"
          maxLength={2}
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, styles.monoInput, { color: Colors.light.text, borderColor: ACCENT }]}
        />
        <ThemedText style={styles.hint}>Day of the month payment is due (1-31).</ThemedText>

        <ThemedText type="defaultSemiBold">Paid from (optional)</ThemedText>
        <Pressable onPress={() => setShowAccountPicker(true)} style={[styles.input, { borderColor: ACCENT }]}>
          <ThemedText>{selectedAccount ? selectedAccount.name : 'Not set'}</ThemedText>
        </Pressable>
        <ThemedText style={styles.hint}>
          Which bank account this card&apos;s bill is paid from. Used to flag if that account can&apos;t cover the
          annual fee.
        </ThemedText>
        <SelectModal
          visible={showAccountPicker}
          onClose={() => setShowAccountPicker(false)}
          options={accountOptions}
          selectedValue={paymentAccountId}
          onSelect={(value) => {
            setPaymentAccountId(value);
            setShowAccountPicker(false);
          }}
        />

        <OwnershipPicker value={ownership} onChange={setOwnership} accent={ACCENT} onColor={ModuleAccentOnColor.cards} />

        <ThemedView style={styles.row}>
          <ThemedText type="defaultSemiBold">Active</ThemedText>
          <Switch value={isActive} onValueChange={setIsActive} trackColor={{ true: ACCENT }} />
        </ThemedView>

        <Pressable onPress={handleSave} disabled={isSaving} style={[styles.button, { backgroundColor: ACCENT }]}>
          {isSaving ? (
            <ActivityIndicator color={ModuleAccentOnColor.cards} />
          ) : (
            <ThemedText style={{ color: ModuleAccentOnColor.cards, fontWeight: '600' }}>Save</ThemedText>
          )}
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

function parseDateOnly(dateString: string): Date {
  const [year, month, day] = dateString.split('-').map(Number);
  return new Date(year, month - 1, day);
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  centered: { alignItems: 'center', justifyContent: 'center' },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  hint: {
    opacity: 0.7,
    fontSize: 13,
    marginBottom: 8,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  monoInput: {
    fontFamily: Fonts.mono,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  error: {
    color: Colors.light.negative,
  },
});
