/**
 * Day-count residency triggers per country — replaces the old global
 * "183 days in a rolling 365" placeholder. Keyed by the exact country name
 * strings in lib/countries.ts.
 *
 * `thresholdDays` is the count AT WHICH the test triggers (>=), so a rule
 * worded "more than 183 days" is stored as 184 and "183 days or more" as
 * 183 — one comparison everywhere, no per-country > vs >= special-casing.
 *
 * These are the day-count arms of each country's residency test only.
 * Nearly every country ALSO has home/family/economic-ties tests that can
 * make someone resident on far fewer days, and several (US, UK, Ireland,
 * Hong Kong, India…) have secondary multi-year formulas not modeled here.
 * The UI says so; this is a tracker, not tax advice.
 */

export type ResidencyWindow =
  /** Any trailing period of this many days ending today. */
  | { kind: 'rolling'; days: number }
  /** 1 Jan of the current year through today. */
  | { kind: 'calendar-year' }
  /** From the most recent tax-year start (1-based month/day) through today — e.g. the UK's 6 April. */
  | { kind: 'tax-year'; startMonth: number; startDay: number }
  /** US Substantial Presence Test: this calendar year + 1/3 of last year + 1/6 of the year before. */
  | { kind: 'us-substantial-presence' };

export type ResidencyRule = {
  thresholdDays: number;
  window: ResidencyWindow;
  /** Short factual description shown beside the day count. */
  label: string;
  /** True only for the generic fallback, so the UI can say this country's own test isn't modeled. */
  isDefault: boolean;
  /**
   * True only for a country that taxes its own citizens on worldwide
   * income regardless of where they live or how many days they spend
   * there (the US, and Eritrea, are the only real-world examples). For a
   * citizen of a country like this, the day-count test is moot: they owe
   * that country's taxes either way, so crossing the threshold isn't news.
   * This is NOT "any country I hold citizenship in" — most countries
   * (the UK included) tax by RESIDENCE, so a citizen who genuinely drops
   * under the day count really does stop being tax-resident there, and
   * the alarm should keep firing for them same as anyone else.
   */
  usesCitizenshipBasedTaxation?: boolean;
};

export const DEFAULT_RESIDENCY_RULE: ResidencyRule = {
  thresholdDays: 183,
  window: { kind: 'rolling', days: 365 },
  label: '183 days in any rolling 12 months',
  isDefault: true,
};

const rolling = (thresholdDays: number, label: string, days = 365): ResidencyRule => ({
  thresholdDays,
  window: { kind: 'rolling', days },
  label,
  isDefault: false,
});
const calendar = (thresholdDays: number, label: string): ResidencyRule => ({
  thresholdDays,
  window: { kind: 'calendar-year' },
  label,
  isDefault: false,
});
const taxYear = (thresholdDays: number, startMonth: number, startDay: number, label: string): ResidencyRule => ({
  thresholdDays,
  window: { kind: 'tax-year', startMonth, startDay },
  label,
  isDefault: false,
});

