export function residencyRuleFor(country: string): ResidencyRule {
  return RULES[country] ?? DEFAULT_RESIDENCY_RULE;
}

/**
 * True when crossing `country`'s day-count threshold isn't actually news
 * for this user: the country taxes its own citizens regardless of day
 * count (usesCitizenshipBasedTaxation), and they hold that citizenship.
 * Callers use this to skip the "alarm" treatment (a flagged notice, red
 * styling) for that country specifically, while the plain day count can
 * still be shown as information elsewhere. `citizenshipCountries` is a
 * plain country-name list, so callers can pass `user_citizenships` rows
 * mapped to `.country` without an extra step.
 */
export function isCitizenshipTaxed(country: string, citizenshipCountries: string[]): boolean {
  return !!residencyRuleFor(country).usesCitizenshipBasedTaxation && citizenshipCountries.includes(country);
}

/** Countries with their own modeled rule — for a "what's covered" list, if one is ever needed. */
export function modeledResidencyCountries(): string[] {
  return Object.keys(RULES).sort();
}
