import { Image } from 'expo-image';
import { StyleSheet, View } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { Fonts } from '@/constants/theme';
import { colorForId, initialsFromEmail } from '@/lib/avatar';

export function Avatar({
  userId,
  email,
  size = 28,
  photoUrl,
}: {
  userId: string;
  email: string;
  size?: number;
  photoUrl?: string | null;
}) {
  if (photoUrl) {
    return (
      <Image
        source={photoUrl}
        style={[styles.circle, { width: size, height: size, borderRadius: size / 2 }]}
        contentFit="cover"
      />
    );
  }

  return (
    <View
      style={[
        styles.circle,
        { width: size, height: size, borderRadius: size / 2, backgroundColor: colorForId(userId) },
      ]}>
      <ThemedText style={[styles.initials, { fontSize: size * 0.4 }]}>{initialsFromEmail(email)}</ThemedText>
    </View>
  );
}

const styles = StyleSheet.create({
  circle: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  initials: {
    color: '#fff',
    fontFamily: Fonts.bodySemiBold,
  },
});
