import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import * as WebBrowser from 'expo-web-browser';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { CountryFlag } from '@/components/country-flag';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { useCurrency } from '@/contexts/currency-context';
import { showAlert } from '@/lib/alert';
import { documentTypeLabel } from '@/lib/documents';
import { formatDateDisplay, formatTimeDisplay } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import { computeTripSummaries, computeTripTimeline } from '@/lib/trips';
import type { CountryVisitedRow, DocumentType, TripRow, TripSegmentRow } from '@/types/database';

const ACCENT = ModuleAccents.countries;
const SIGNED_URL_EXPIRY_SECONDS = 300;

const MODE_LABELS: Record<TripSegmentRow['mode'], string> = {
  flight: 'Flight',
  train: 'Train',
  car: 'Car',
  bus: 'Bus',
  ferry: 'Ferry',
  other: 'Travel',
};

type CollabDocument = {
  id: string;
  name: string;
  doc_type: string;
  file_ref: string;
  trip_stop_id: string | null;
  trip_segment_id: string | null;
  uploaded_by: string;
  uploaded_by_display_name: string;
};

/**
 * A CONTRIBUTOR's own view of someone else's trip — read-only itinerary,
 * with the ability to add documents (train tickets, confirmations, etc.).
 * A 'full' collaborator instead gets their own real trips row (via
 * accept_trip_collaboration's copy-creation) and just uses the normal
 * app/countries/trips/[id].tsx screen like any trip of their own — this
 * screen exists only for the no-own-copy 'contributor' role.
 */
export default function SharedTripScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();
  const { session } = useAuth();
  const { hiddenFlagCountries } = useCurrency();

  const [trip, setTrip] = useState<{ id: string; name: string | null } | null>(null);
  const [stops, setStops] = useState<CountryVisitedRow[]>([]);
  const [segments, setSegments] = useState<TripSegmentRow[]>([]);
  const [documents, setDocuments] = useState<CollabDocument[]>([]);
  const [myCollaborationId, setMyCollaborationId] = useState<string | null>(null);
  const [openingFileRef, setOpeningFileRef] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isLeaving, setIsLeaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [tripResult, stopsResult, segmentsResult, documentsResult, collaborationResult] = await Promise.all([
      supabase.rpc('trip_collaboration_trip', { p_trip_id: id }),
      supabase.rpc('trip_collaboration_stops', { p_trip_id: id }),
      supabase.rpc('trip_collaboration_segments', { p_trip_id: id }),
      supabase.rpc('trip_collaboration_documents', { p_trip_id: id }),
      // My own row, for the Leave action — RLS already scopes this to rows
      // I'm a party to, the collaborator filter just excludes the case of
      // the owner themselves landing on this URL.
      session
        ? supabase
            .from('trip_collaborators')
            .select('id')
            .eq('trip_id', id)
            .eq('collaborator_user_id', session.user.id)
            .eq('status', 'accepted')
            .maybeSingle()
        : Promise.resolve({ data: null, error: null }),
    ]);
    if (tripResult.error || !tripResult.data?.[0]) {
      setError(tripResult.error?.message ?? "This trip isn't available anymore.");
    } else {
      setTrip(tripResult.data[0]);
    }
    if (!stopsResult.error) setStops(stopsResult.data ?? []);
    if (!segmentsResult.error) setSegments(segmentsResult.data ?? []);
    if (!documentsResult.error) setDocuments(documentsResult.data ?? []);
    if (!collaborationResult.error) setMyCollaborationId(collaborationResult.data?.id ?? null);
    setIsLoading(false);
  }, [id, session]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  async function handleOpenDocument(fileRef: string) {
    setError(null);
    setOpeningFileRef(fileRef);
    const { data, error: signError } = await supabase.storage
      .from('documents')
      .createSignedUrl(fileRef, SIGNED_URL_EXPIRY_SECONDS);
    setOpeningFileRef(null);
    if (signError || !data) {
      setError(signError?.message ?? "Couldn't open that file.");
      return;
    }
    await WebBrowser.openBrowserAsync(data.signedUrl);
  }

  function handleLeave() {
    if (!myCollaborationId) return;
    showAlert(
      'Leave this trip',
      "You'll stop seeing this trip. Any documents you've already added stay with the trip.",
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Leave',
          style: 'destructive',
          onPress: async () => {
            setIsLeaving(true);
            const { error: leaveError } = await supabase.rpc('revoke_trip_collaboration', { p_id: myCollaborationId });
            setIsLeaving(false);
            if (leaveError) {
              setError(leaveError.message);
              return;
            }
            router.back();
          },
        },
      ]
    );
  }

  if (isLoading || !trip) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        {error ? (
          <>
            <ThemedText style={styles.error}>{error}</ThemedText>
            <Pressable onPress={() => router.back()} hitSlop={12}>
              <ThemedText type="link">‹ Back</ThemedText>
            </Pressable>
          </>
        ) : (
          <ActivityIndicator color={ACCENT} />
        )}
      </ThemedView>
    );
  }

  const [summary] = computeTripSummaries([{ id: trip.id, name: trip.name } as TripRow], stops, segments);
  const timeline = computeTripTimeline(summary?.stops ?? [], segments);

  function documentLinkLabel(doc: CollabDocument): string | null {
    if (doc.trip_stop_id) {
      const stop = stops.find((s) => s.id === doc.trip_stop_id);
      return stop ? stop.city?.trim() || stop.country : null;
    }
    if (doc.trip_segment_id) {
      const segment = segments.find((s) => s.id === doc.trip_segment_id);
      return segment ? `${segment.from_label} → ${segment.to_label}` : null;
    }
    return null;
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">‹ Back</ThemedText>
          </Pressable>
          <ThemedView style={styles.titleActions}>
            {myCollaborationId ? (
              <Pressable onPress={handleLeave} disabled={isLeaving} hitSlop={12}>
                <ThemedText style={{ color: Colors.light.negative }}>Leave</ThemedText>
              </Pressable>
            ) : null}
            <Pressable
              onPress={() => router.push(`/countries/trips/graph?tripId=${trip.id}`)}
              style={[styles.summaryTile, { borderColor: ACCENT }]}>
              <ThemedText style={[styles.summaryTileText, { color: ACCENT }]}>Summary</ThemedText>
            </Pressable>
          </ThemedView>
        </ThemedView>
        <ThemedText style={styles.muted}>You&apos;re helping with this trip. View the plan and add documents to it.</ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedText type="title" style={{ color: ACCENT }} numberOfLines={1} adjustsFontSizeToFit>
          {summary?.displayName ?? trip.name ?? 'Trip'}
        </ThemedText>
        {summary ? (
          <ThemedView style={styles.metaRow}>
            <ThemedView style={styles.flagRow}>
              {summary.countries.map((country) => (
                <CountryFlag key={country} countryName={country} hiddenFlagCountries={hiddenFlagCountries} size={18} />
              ))}
            </ThemedView>
            <ThemedText style={styles.muted}>
              {formatDateDisplay(summary.startDate)} → {formatDateDisplay(summary.endDate)}
            </ThemedText>
          </ThemedView>
        ) : null}

        <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
          Itinerary
        </ThemedText>
        {timeline.length === 0 ? <ThemedText style={styles.muted}>Nothing added yet.</ThemedText> : null}
        <ThemedView style={styles.itinerary}>
          {timeline.map((entry, index) => (
            <ThemedView key={entry.kind === 'stop' ? entry.stop.id : entry.segment.id} style={styles.stopRow}>
              <ThemedView style={styles.stopDotColumn}>
                <ThemedView style={[styles.stopDot, { borderColor: ACCENT }]} />
                {index < timeline.length - 1 ? (
                  <ThemedView style={[styles.stopLine, { backgroundColor: Colors.light.cardBorder }]} />
                ) : null}
              </ThemedView>
              <ThemedView style={styles.stopCardWrap}>
                <Surface accentColor={ACCENT} style={styles.stopCard}>
                  {entry.kind === 'stop' ? (
                    <>
                      <ThemedView style={styles.stopTop}>
                        <ThemedView style={styles.stopCity}>
                          <CountryFlag countryName={entry.stop.country} hiddenFlagCountries={hiddenFlagCountries} size={16} />
                          <ThemedText type="defaultSemiBold">{entry.stop.city?.trim() || entry.stop.country}</ThemedText>
                        </ThemedView>
                        <ThemedText type="mono" style={styles.muted}>
                          {formatDateDisplay(entry.stop.entry_date)} → {formatDateDisplay(entry.stop.exit_date)}
                        </ThemedText>
                      </ThemedView>
                      {entry.stop.accommodation ? (
                        <ThemedText style={styles.detailText} numberOfLines={1}>
                          {entry.stop.accommodation}
                        </ThemedText>
                      ) : null}
                    </>
                  ) : (
                    <>
                      <ThemedView style={styles.stopTop}>
                        <ThemedText type="defaultSemiBold">
                          {entry.segment.from_label} → {entry.segment.to_label}
                        </ThemedText>
                        <ThemedText style={styles.muted}>{MODE_LABELS[entry.segment.mode]}</ThemedText>
                      </ThemedView>
                      <ThemedText type="mono" style={styles.muted}>
                        {formatDateDisplay(entry.segment.depart_date)}
                        {formatTimeDisplay(entry.segment.depart_time) ? ` ${formatTimeDisplay(entry.segment.depart_time)}` : ''}
                        {' → '}
                        {formatDateDisplay(entry.segment.arrive_date)}
                        {formatTimeDisplay(entry.segment.arrive_time) ? ` ${formatTimeDisplay(entry.segment.arrive_time)}` : ''}
                      </ThemedText>
                      {entry.segment.carrier || entry.segment.confirmation_number ? (
                        <ThemedText style={styles.detailText} numberOfLines={1}>
                          {[entry.segment.carrier, entry.segment.confirmation_number].filter(Boolean).join(' · ')}
                        </ThemedText>
                      ) : null}
                    </>
                  )}
                </Surface>
              </ThemedView>
            </ThemedView>
          ))}
        </ThemedView>

        <ThemedView style={styles.sectionHeaderRow}>
          <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
            Documents
          </ThemedText>
          <Pressable onPress={() => router.push(`/documents/new?tripId=${trip.id}`)} hitSlop={8}>
            <ThemedText type="link">+ Add document</ThemedText>
          </Pressable>
        </ThemedView>
        {documents.length === 0 ? (
          <ThemedText style={styles.muted}>No documents linked to this trip yet.</ThemedText>
        ) : (
          documents.map((doc) => (
            <Pressable key={doc.id} onPress={() => handleOpenDocument(doc.file_ref)} disabled={openingFileRef === doc.file_ref}>
              <Surface accentColor={ACCENT} style={styles.docRow}>
                <ThemedView style={styles.docRowText}>
                  <ThemedText type="defaultSemiBold" numberOfLines={1}>
                    {doc.name}
                  </ThemedText>
                  <ThemedText style={styles.muted} numberOfLines={1}>
                    {[
                      documentTypeLabel(doc.doc_type as DocumentType),
                      documentLinkLabel(doc),
                      doc.uploaded_by !== session?.user.id ? `added by ${doc.uploaded_by_display_name}` : null,
                    ]
                      .filter(Boolean)
                      .join(' · ')}
                  </ThemedText>
                </ThemedView>
                {openingFileRef === doc.file_ref ? (
                  <ActivityIndicator color={ACCENT} />
                ) : (
                  <IconSymbol name="chevron.right" size={16} color={ACCENT} />
                )}
              </Surface>
            </Pressable>
          ))
        )}
      </ScrollView>
    </ThemedView>
  );
}

