import { supabase } from '@/lib/supabase';
import type { TripPlanRequestRow, TripPlanRequestStatus } from '@/types/database';

/**
 * Proposes (or re-proposes) planning a country together — upserts on
 * (connection_id, country), always resetting to 'pending' even if a row
 * already existed (declined or previously accepted), since re-planning
 * should always require a fresh accept rather than silently resuming. Same
 * reasoning as sendShareRequest (lib/shareRequests.ts).
 */
export async function proposeTripPlan(
  connectionId: string,
  country: string,
  requestedBy: string
): Promise<{ error: string | null }> {
  const { error } = await supabase
    .from('trip_plan_requests')
    .upsert({ connection_id: connectionId, country, requested_by: requestedBy, status: 'pending' }, { onConflict: 'connection_id,country' });
  return { error: error?.message ?? null };
}

/** Either party accepting or declining a pending plan-together request. */
export async function respondToTripPlan(
  requestId: string,
  status: Extract<TripPlanRequestStatus, 'accepted' | 'declined'>
): Promise<{ error: string | null }> {
  const { error } = await supabase.from('trip_plan_requests').update({ status }).eq('id', requestId);
  return { error: error?.message ?? null };
}

/** Fully removes the agreement, so re-planning later needs a fresh accept — matches revokeShareRequest's reasoning. */
export async function revokeTripPlan(connectionId: string, country: string): Promise<{ error: string | null }> {
  const { error } = await supabase
    .from('trip_plan_requests')
    .delete()
    .eq('connection_id', connectionId)
    .eq('country', country);
  return { error: error?.message ?? null };
}

/** Every plan-together request tied to a connection, every country. */
export async function fetchTripPlanRequests(
  connectionId: string
): Promise<{ data: TripPlanRequestRow[]; error: string | null }> {
  const { data, error } = await supabase.from('trip_plan_requests').select('*').eq('connection_id', connectionId);
  return { data: data ?? [], error: error?.message ?? null };
}
