import { useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, TextInput } from 'react-native';

import { PasswordInput } from '@/components/password-input';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { useAuth } from '@/contexts/auth-context';
import { Colors } from '@/constants/theme';

export default function LoginScreen() {
  const { signIn, signUp, resetPasswordForEmail } = useAuth();
  const [mode, setMode] = useState<'sign-in' | 'sign-up' | 'forgot-password'>('sign-in');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [inviteCode, setInviteCode] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [info, setInfo] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const isSignUp = mode === 'sign-up';
  const isForgotPassword = mode === 'forgot-password';

  async function handleSubmit() {
    if (isForgotPassword) {
      if (!email.trim()) {
        setError('Enter your email.');
        return;
      }
      setError(null);
      setInfo(null);
      setIsSubmitting(true);
      const result = await resetPasswordForEmail(email.trim());
      setIsSubmitting(false);

      if (result.error) {
        setError(result.error);
        return;
      }
      setInfo('If an account exists for that email, a reset link is on its way.');
      return;
    }

    if (!email.trim() || !password) {
      setError('Enter an email and password.');
      return;
    }
    if (isSignUp && !inviteCode.trim()) {
      setError('Enter your invite code.');
      return;
    }
    setError(null);
    setInfo(null);
    setIsSubmitting(true);
    const result = isSignUp
      ? await signUp(email.trim(), password, inviteCode.trim())
      : await signIn(email.trim(), password);
    setIsSubmitting(false);

    if (result.error) {
      setError(result.error);
      return;
    }

    if (isSignUp) {
      setInfo('Account created. Check your email if confirmation is required, then sign in.');
      setMode('sign-in');
    }
  }

  function switchMode(next: typeof mode) {
    setError(null);
    setInfo(null);
    setMode(next);
  }

  return (
    <ThemedView variant="screen" style={styles.container}>
        <ThemedText type="title">Cluster</ThemedText>
        <ThemedText type="subtitle" style={styles.subtitle}>
          {isForgotPassword ? 'Reset your password' : isSignUp ? 'Create an account' : 'Sign in'}
        </ThemedText>

        <TextInput
          value={email}
          onChangeText={setEmail}
          placeholder="Email"
          placeholderTextColor={Colors.light.textMuted}
          autoCapitalize="none"
          autoComplete="email"
          keyboardType="email-address"
          style={[styles.input, { color: Colors.light.text, borderColor: Colors.light.tint }]}
        />
        {!isForgotPassword ? (
          <PasswordInput
            value={password}
            onChangeText={setPassword}
            placeholder="Password"
            autoComplete={isSignUp ? 'new-password' : 'password'}
            accentColor={Colors.light.tint}
            style={styles.input}
          />
        ) : null}
        {isSignUp ? (
          <TextInput
            value={inviteCode}
            onChangeText={setInviteCode}
            placeholder="Invite code"
            placeholderTextColor={Colors.light.textMuted}
            autoCapitalize="characters"
            style={[styles.input, { color: Colors.light.text, borderColor: Colors.light.tint }]}
          />
        ) : null}

        {mode === 'sign-in' ? (
          <Pressable onPress={() => switchMode('forgot-password')} hitSlop={8} style={styles.forgotPasswordButton}>
            <ThemedText type="link" style={styles.forgotPasswordText}>
              Forgot password?
            </ThemedText>
          </Pressable>
        ) : null}

        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
        {info ? <ThemedText style={styles.info}>{info}</ThemedText> : null}

        <Pressable
          onPress={handleSubmit}
          disabled={isSubmitting}
          style={[styles.button, { backgroundColor: Colors.light.tint }]}>
          {isSubmitting ? (
            <ActivityIndicator color={Colors.light.backgroundSolid} />
          ) : (
            <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>
              {isForgotPassword ? 'Send reset link' : isSignUp ? 'Sign up' : 'Sign in'}
            </ThemedText>
          )}
        </Pressable>

        <Pressable
          onPress={() => switchMode(isForgotPassword ? 'sign-in' : isSignUp ? 'sign-in' : 'sign-up')}
          style={styles.switchModeButton}>
          <ThemedText type="link">
            {isForgotPassword
              ? 'Back to sign in'
              : isSignUp
                ? 'Already have an account? Sign in'
                : "Don't have an account? Sign up"}
          </ThemedText>
        </Pressable>
      </ThemedView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    padding: 24,
    gap: 12,
  },
  subtitle: {
    marginBottom: 12,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  switchModeButton: {
    alignItems: 'center',
    marginTop: 16,
  },
  forgotPasswordButton: {
    alignItems: 'flex-end',
  },
  forgotPasswordText: {
    fontSize: 14,
  },
  error: {
    color: Colors.light.negative,
  },
  info: {
    color: Colors.light.tint,
  },
});
