import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, View } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { ScopeSwitch } from '@/components/scope-switch';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useScope } from '@/contexts/scope-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { computeBudgetProgress, type BudgetProgress } from '@/lib/budgets';
import { formatMoney } from '@/lib/currency';
import { fetchAllRows } from '@/lib/fetchAll';
import { supabase } from '@/lib/supabase';
import type { AccountRow, BudgetRow, CategoryRow, CountryVisitedRow, TransactionRow } from '@/types/database';

const ACCENT = ModuleAccents.spend;

function progressColor(percentUsed: number): string {
  if (percentUsed >= 100) return Colors.light.negative;
  if (percentUsed >= 80) return ModuleAccents.cards;
  return Colors.light.positive;
}

export default function BudgetsScreen() {
  const router = useRouter();
  const { homeCountry, convertToCurrency } = useCurrency();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const { filterTransactions, filterAccounts } = useScope();
  const [budgets, setBudgets] = useState<BudgetRow[]>([]);
  const [allTransactions, setTransactions] = useState<TransactionRow[]>([]);
  const [categories, setCategories] = useState<CategoryRow[]>([]);
  const [visits, setVisits] = useState<CountryVisitedRow[]>([]);
  const [allAccounts, setAccounts] = useState<AccountRow[]>([]);
  const transactions = filterTransactions(allTransactions);
  const accounts = filterAccounts(allAccounts);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [budgetsResult, txResult, categoriesResult, visitsResult, accountsResult] = await Promise.all([
      supabase.from('budgets').select('*'),
      fetchAllRows<TransactionRow>((from, to) =>
        supabase.from('transactions').select('*').order('date').order('id').range(from, to)
      ),
      supabase.from('categories').select('*'),
      supabase.from('countries_visited').select('*'),
      supabase.from('accounts').select('*'),
    ]);

    if (budgetsResult.error) {
      setError(budgetsResult.error.message);
      setIsLoading(false);
      return;
    }

    setBudgets(budgetsResult.data ?? []);
    setTransactions(txResult.data);
    setCategories(categoriesResult.data ?? []);
    setVisits(visitsResult.data ?? []);
    setAccounts(accountsResult.data ?? []);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const categoryNameById = new Map(categories.map((c) => [c.id, c.name]));
  const progress: BudgetProgress[] = computeBudgetProgress(
    budgets,
    transactions,
    visits,
    homeCountry,
    accounts,
    convertToCurrency
  );

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView contentContainerStyle={styles.content}>
        <ScopeSwitch accent={ACCENT} onColor={ModuleAccentOnColor.spend} />
        <ThemedText type="title" style={{ color: ACCENT }}>
          Budgets
        </ThemedText>
        <ThemedText style={styles.muted}>Monthly spend limits, per category or country. Resets each calendar month.</ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {isLoading ? (
          <ActivityIndicator style={styles.loading} color={ACCENT} />
        ) : progress.length === 0 ? (
          <ThemedText style={styles.muted}>No budgets set yet. Tap + to add one.</ThemedText>
        ) : (
          progress.map(({ budget, spent, remaining, percentUsed }) => {
            const label = budget.category_id ? (categoryNameById.get(budget.category_id) ?? 'Unknown category') : budget.country;
            const barColor = progressColor(percentUsed);
            return (
              <Pressable key={budget.id} onPress={() => router.push(`/spend/budgets/${budget.id}/edit`)}>
                <Surface accentColor={ACCENT}>
                  <ThemedView style={styles.rowBetween}>
                    <ThemedText type="defaultSemiBold">{label}</ThemedText>
                    <ThemedText type="mono">
                      {formatMoney(spent, budget.currency)} / {formatMoney(budget.amount, budget.currency)}
                    </ThemedText>
                  </ThemedView>
                  <View style={styles.barTrack}>
                    <View style={[styles.barFill, { width: `${Math.min(percentUsed, 100)}%`, backgroundColor: barColor }]} />
                  </View>
                  <ThemedText style={[styles.muted, { color: remaining < 0 ? Colors.light.negative : Colors.light.textMuted }]}>
                    {remaining >= 0
                      ? `${formatMoney(remaining, budget.currency)} left this month`
                      : `${formatMoney(Math.abs(remaining), budget.currency)} over this month`}
                  </ThemedText>
                </Surface>
              </Pressable>
            );
          })
        )}
      </ScrollView>

      <Pressable onPress={() => router.push('/spend/budgets/new')} style={[styles.fab, { backgroundColor: ACCENT }]}>
        <IconSymbol name="plus" size={28} color={ModuleAccentOnColor.spend} />
      </Pressable>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 12,
    paddingBottom: 96,
  },
  rowBetween: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 8,
  },
  barTrack: {
    height: 6,
    borderRadius: 3,
    backgroundColor: Colors.light.cardBorder,
    marginTop: 10,
    marginBottom: 6,
    overflow: 'hidden',
  },
  barFill: {
    height: '100%',
    borderRadius: 3,
  },
  muted: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  loading: {
    marginTop: 32,
  },
  error: {
    color: Colors.light.negative,
  },
  fab: {
    position: 'absolute',
    right: 20,
    bottom: 28,
    width: 56,
    height: 56,
    borderRadius: 28,
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: '#000',
    shadowOpacity: 0.2,
    shadowRadius: 6,
    shadowOffset: { width: 0, height: 3 },
    elevation: 4,
  },
});
