import { useEffect } from 'react';
import { Pressable, StyleSheet } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useScope } from '@/contexts/scope-context';
import { SCOPE_OPTIONS } from '@/lib/scope';

/**
 * All / Personal / Business chips. Renders nothing at all until the user
 * has tagged at least one account or card as business — a purely personal
 * user never sees a control that would do nothing for them. Mounting one
 * refreshes the provider's ownership maps, so a screen that shows the
 * switch always filters against current tags.
 */
export function ScopeSwitch({ accent, onColor = Colors.light.backgroundSolid }: { accent: string; onColor?: string }) {
  const { scope, setScope, hasBusinessItems, refresh } = useScope();

  useEffect(() => {
    refresh();
  }, [refresh]);

  if (!hasBusinessItems) return null;

  return (
    <ThemedView style={styles.row}>
      {SCOPE_OPTIONS.map((option) => {
        const isSelected = option.value === scope;
        return (
          <Pressable
            key={option.value}
            onPress={() => setScope(option.value)}
            accessibilityRole="button"
            accessibilityState={{ selected: isSelected }}
            style={[styles.chip, { borderColor: accent, backgroundColor: isSelected ? accent : 'transparent' }]}>
            <ThemedText style={[styles.chipText, isSelected ? { color: onColor } : { color: Colors.light.text }]}>
              {option.label}
            </ThemedText>
          </Pressable>
        );
      })}
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  row: {
    flexDirection: 'row',
    gap: 8,
    marginBottom: 4,
  },
  chip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 16,
    paddingHorizontal: 12,
    paddingVertical: 6,
  },
  chipText: {
    fontSize: 13,
    fontWeight: '600',
  },
});
