import { useFocusEffect } from '@react-navigation/native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { TransactionRow as TransactionRowItem } from '@/components/transaction-row';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { formatMoney } from '@/lib/currency';
import { fetchAllRows } from '@/lib/fetchAll';
import type { PriorResidencyLike } from '@/lib/days';
import {
  attributedLocationForTransaction,
  isExcludedFromCountryTracking,
  isRelatedOutOfCountry,
  yearsWithData,
  type TripLinkMaps,
} from '@/lib/spend';
import { supabase } from '@/lib/supabase';
import { computeTripSummaries } from '@/lib/trips';
import type {
  AccountRow,
  CategoryRow,
  CategoryRuleRow,
  CountryVisitedRow,
  CreditCardRow,
  TransactionRow,
  TripRow,
  TripSegmentRow,
} from '@/types/database';

const ACCENT = ModuleAccents.countries;
type YearOption = 'all' | number;

function formatTotals(totals: { currency: string; amount: number }[]): string {
  if (totals.length === 0) return formatMoney(0, 'USD');
  return totals.map((t) => formatMoney(Math.abs(t.amount), t.currency)).join(' · ');
}

export default function CountrySpendDetailScreen() {
  const { country, year: yearParam } = useLocalSearchParams<{ country: string; year?: string }>();
  const router = useRouter();
  const { convert, homeCountry } = useCurrency();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const [transactions, setTransactions] = useState<TransactionRow[]>([]);
  const [categories, setCategories] = useState<CategoryRow[]>([]);
  const [categoryRules, setCategoryRules] = useState<CategoryRuleRow[]>([]);
  const [accounts, setAccounts] = useState<AccountRow[]>([]);
  const [cards, setCards] = useState<CreditCardRow[]>([]);
  const [visits, setVisits] = useState<CountryVisitedRow[]>([]);
  const [trips, setTrips] = useState<TripRow[]>([]);
  const [tripSegments, setTripSegments] = useState<TripSegmentRow[]>([]);
  const [priorResidencies, setPriorResidencies] = useState<PriorResidencyLike[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedYear, setSelectedYear] = useState<YearOption>(
    yearParam && yearParam !== 'all' && !Number.isNaN(Number(yearParam)) ? Number(yearParam) : 'all'
  );

  const load = useCallback(async () => {
    setError(null);
    const [
      txResult,
      categoriesResult,
      categoryRulesResult,
      accountsResult,
      cardsResult,
      visitsResult,
      tripsResult,
      segmentsResult,
      priorResidenciesResult,
    ] = await Promise.all([
      fetchAllRows<TransactionRow>((from, to) =>
        supabase.from('transactions').select('*').order('date', { ascending: false }).order('id').range(from, to)
      ),
      supabase.from('categories').select('*'),
      supabase.from('category_rules').select('*'),
      supabase.from('accounts').select('*'),
      supabase.from('credit_cards').select('*'),
      supabase.from('countries_visited').select('*'),
      supabase.from('trips').select('*'),
      supabase.from('trip_segments').select('*'),
      supabase.from('prior_residencies').select('*'),
    ]);

    if (txResult.error) {
      setError(txResult.error.message);
      setIsLoading(false);
      return;
    }

    setTransactions(txResult.data);
    setCategories(categoriesResult.data ?? []);
    setCategoryRules(categoryRulesResult.data ?? []);
    setAccounts(accountsResult.data ?? []);
    setCards(cardsResult.data ?? []);
    setVisits(visitsResult.data ?? []);
    setTrips(tripsResult.data ?? []);
    setTripSegments(segmentsResult.data ?? []);
    setPriorResidencies(priorResidenciesResult.data ?? []);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  if (isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  const excludedAccountIds = new Set(accounts.filter((a) => a.excluded_from_country_tracking).map((a) => a.id));

  const tripSummaries = computeTripSummaries(trips, visits, tripSegments);
  const links: TripLinkMaps = {
    stopsById: new Map(visits.map((v) => [v.id, { country: v.country, city: v.city }])),
    segmentCountryById: new Map(
      tripSegments.map((s) => [
        s.id,
        tripSummaries.find((t) => t.id === s.trip_id)?.countries[0] ?? homeCountry ?? 'Unknown',
      ])
    ),
  };

  function isExcluded(tx: TransactionRow) {
    return isExcludedFromCountryTracking(tx, excludedAccountIds);
  }

  const countryTxAllTime = transactions.filter((tx) => {
    if (tx.is_internal_transfer || tx.amount >= 0) return false;
    return (
      attributedLocationForTransaction(tx, visits, homeCountry, isExcluded(tx), links, priorResidencies).country === country
    );
  });

  const availableYears = yearsWithData(countryTxAllTime.map((tx) => tx.date));
  const yearOptions: YearOption[] = ['all', ...availableYears];

  const scopedTx =
    selectedYear === 'all' ? countryTxAllTime : countryTxAllTime.filter((tx) => tx.date.startsWith(String(selectedYear)));

  const inCountryTx = scopedTx.filter(
    (tx) => !isRelatedOutOfCountry(tx, country, visits, homeCountry, isExcluded(tx), links, priorResidencies)
  );
  const relatedTx = scopedTx.filter((tx) =>
    isRelatedOutOfCountry(tx, country, visits, homeCountry, isExcluded(tx), links, priorResidencies)
  );

  function totalsFor(txs: TransactionRow[]) {
    const totalsByCurrency = new Map<string, number>();
    for (const tx of txs) {
      const { amount, currency } = convert(tx.amount, tx.currency);
      totalsByCurrency.set(currency, (totalsByCurrency.get(currency) ?? 0) + amount);
    }
    return Array.from(totalsByCurrency.entries()).map(([currency, amount]) => ({ currency, amount }));
  }

  const totalSpend = totalsFor(scopedTx);

  const accountNameById = new Map(accounts.map((a) => [a.id, a.name]));
  const cardNameById = new Map(cards.map((c) => [c.id, `${c.issuer} · ${c.name}`]));

  function sourceLabel(tx: TransactionRow): string {
    if (tx.account_id) return accountNameById.get(tx.account_id) ?? 'Account';
    if (tx.card_id) return cardNameById.get(tx.card_id) ?? 'Card';
    return 'Unknown source';
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView
        contentContainerStyle={styles.content}
        refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }} numberOfLines={1} adjustsFontSizeToFit>
            {country} spend
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedView style={styles.chipRow}>
          {yearOptions.map((option) => {
            const isSelected = selectedYear === option;
            return (
              <Pressable
                key={String(option)}
                onPress={() => setSelectedYear(option)}
                style={[styles.chip, { borderColor: ACCENT, backgroundColor: isSelected ? ACCENT : 'transparent' }]}>
                <ThemedText style={isSelected ? { color: ModuleAccentOnColor.countries } : undefined}>
                  {option === 'all' ? 'All-time' : String(option)}
                </ThemedText>
              </Pressable>
            );
          })}
        </ThemedView>

        <Surface accentColor={ACCENT}>
          <ThemedText style={styles.muted}>Total spend</ThemedText>
          <ThemedText type="mono" style={styles.totalValue}>
            {formatTotals(totalSpend)}
          </ThemedText>
        </Surface>

        <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
          In {country}
        </ThemedText>
        <ThemedText style={styles.hint}>Spend attributed here by trip dates.</ThemedText>
        {inCountryTx.length === 0 ? <ThemedText style={styles.muted}>Nothing here yet.</ThemedText> : null}
        {inCountryTx.map((tx) => (
          <TransactionRowItem
            key={tx.id}
            transaction={tx}
            accentColor={ACCENT}
            convert={convert}
            categories={categories}
            categoryRules={categoryRules}
            visits={visits}
            homeCountry={homeCountry}
            excludedAccountIds={excludedAccountIds}
            subtitle={sourceLabel(tx)}
            onChange={(updated) => setTransactions((prev) => prev.map((t) => (t.id === updated.id ? updated : t)))}
            onCategoryCreated={(category) => setCategories((prev) => [...prev, category])}
          />
        ))}

        {relatedTx.length > 0 ? (
          <>
            <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
              Related, outside trip dates
            </ThemedText>
            <ThemedText style={styles.hint}>
              Linked to a stop or leg here, but dated outside the trip itself, e.g. paid in advance.
            </ThemedText>
            {relatedTx.map((tx) => (
              <TransactionRowItem
                key={tx.id}
                transaction={tx}
                accentColor={ACCENT}
                convert={convert}
                categories={categories}
                categoryRules={categoryRules}
                visits={visits}
                homeCountry={homeCountry}
                excludedAccountIds={excludedAccountIds}
                subtitle={sourceLabel(tx)}
                onChange={(updated) => setTransactions((prev) => prev.map((t) => (t.id === updated.id ? updated : t)))}
                onCategoryCreated={(category) => setCategories((prev) => [...prev, category])}
              />
            ))}
          </>
        ) : null}
      </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  centered: { alignItems: 'center', justifyContent: 'center' },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 8,
    marginBottom: 8,
  },
  chipRow: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
  },
  chip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 16,
    paddingHorizontal: 16,
    paddingVertical: 8,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  totalValue: {
    fontSize: 22,
  },
  hint: {
    opacity: 0.6,
    fontSize: 12,
    color: Colors.light.textMuted,
    marginBottom: 4,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
