const ACCENT = ModuleAccents.countries;
const WEEKDAY_LABELS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

// Same visual language as components/trip-calendar-grid.tsx's month view
// (that one's two-party; this screen is always exactly one), so a
// single-country calendar reads as the same kind of thing as the
// connections travel calendar rather than a differently-styled one-off.
// Taller than that grid's rows since this screen has no other UI sharing
// the width — content is also capped (see styles.content) so day cells
// stay close to square on a wide desktop viewport instead of going short
// and wide.
const ROW_HEIGHT = 52;
const BAND_HEIGHT = 14;
const CONTENT_MAX_WIDTH = 480;

type Band = { key: string; startIndex: number; endIndex: number };

/** Contiguous runs of `true` within one week's 7 flags — the bar segments to draw. */
function computeBands(flags: boolean[]): Band[] {
  const bands: Band[] = [];
  let i = 0;
  while (i < flags.length) {
    if (!flags[i]) {
      i++;
      continue;
    }
    let j = i;
    while (j + 1 < flags.length && flags[j + 1]) j++;
    bands.push({ key: `band-${i}`, startIndex: i, endIndex: j });
    i = j + 1;
  }
  return bands;
}

// Constructs a LOCAL midnight Date from a "YYYY-MM-DD" string — `new
// Date(dateString)` parses as UTC midnight instead, which can land on the
// wrong local calendar day depending on timezone. Same fix lib/days.ts's
// own parseDateOnly applies; needed here too since this screen builds
// Date objects directly from stored date strings.
function parseDateOnlyLocal(dateString: string): Date {
  const [year, month, day] = dateString.split('-').map(Number);
  return new Date(year, month - 1, day);
}

/**
 * Which days in `visits` were attributed to `country` within `year` — a
 * plain date-string Set, same "union of covered days" idea as
 * lib/days.ts's day-count functions, just returning the days themselves
 * instead of a count. An ongoing visit (no exit_date) counts through
 * today, not indefinitely.
 *
 * The home country is a special case: unlike every other country, its
 * presence is never logged as its own countries_visited row (you don't log
 * a "trip" to the place you live) — it's the complement of every other
 * country's days, same as the stat card above the grid. Scanning for
 * `visit.country === country` rows here would always come up empty for it,
 * which is exactly the "no bars for my home country" bug this fixes.
 */
function daySetForYear(
  visits: CountryVisitedRow[],
  country: string,
  isHomeCountry: boolean,
  year: number,
  today: Date
): Set<string> {
  if (isHomeCountry) return homeCountryDaySetForYear(visits, country, year, today);
  const todayStr = toDateOnlyString(today);
  const yearStart = `${year}-01-01`;
  const yearEnd = `${year}-12-31`;
  const days = new Set<string>();
  for (const visit of visits) {
    if (visit.country !== country) continue;
    const d = parseDateOnlyLocal(visit.entry_date);
    const endDate = parseDateOnlyLocal(visit.exit_date ?? todayStr);
    while (d <= endDate) {
      const key = toDateOnlyString(d);
      if (key >= yearStart && key <= yearEnd) days.add(key);
      d.setDate(d.getDate() + 1);
    }
  }
  return days;
}

/** First month within `year` that has any highlighted day, else the current month (if `year` is this year) or January. */
function firstMonthWithData(daySet: Set<string>, year: number, today: Date): Date {
  const sorted = Array.from(daySet).sort();
  if (sorted.length === 0) {
    return year === today.getFullYear() ? new Date(today.getFullYear(), today.getMonth(), 1) : new Date(year, 0, 1);
  }
  const [y, m] = sorted[0].split('-').map(Number);
  return new Date(y, m - 1, 1);
}

/**
 * A single-person, single-country month calendar — "show me just the days
 * I was in Portugal" for whichever country/year a residency notice
 * flagged. Distinct from app/connections/calendar.tsx, which is a
 * two-party overlap view; this one only ever highlights one thing.
 */
export default function CountryCalendarScreen() {
  const { country, year: yearParam } = useLocalSearchParams<{ country: string; year?: string }>();
  const router = useRouter();
  const { homeCountry } = useCurrency();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const [visits, setVisits] = useState<CountryVisitedRow[]>([]);
  const [priorResidencies, setPriorResidencies] = useState<PriorResidencyLike[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const { width: windowWidth } = useWindowDimensions();
  const [rowWidth, setRowWidth] = useState(windowWidth - 32);

  const parsedYearParam = yearParam ? Number(yearParam) : null;
  const [selectedYear, setSelectedYear] = useState(
    parsedYearParam && !Number.isNaN(parsedYearParam) ? parsedYearParam : new Date().getFullYear()
  );
  const [displayMonth, setDisplayMonth] = useState<Date | null>(null);

  // Wherever you lived at a given year's December 31 is that year's home
  // country (see lib/days.ts's effectiveHomeCountryFor) — NOT always
  // whatever the current home country setting is, so this is computed
  // fresh per year rather than once as a single flag. A prior residency
  // elsewhere doesn't retroactively turn its years into "regular visited
  // country" years for THIS country, and conversely doesn't make THIS
  // country's own past years count as home just because it's home now.
  function isHomeCountryForYear(year: number): boolean {
    return country === effectiveHomeCountryFor(`${year}-12-31`, homeCountry, priorResidencies);
  }

  const load = useCallback(async () => {
    const [visitsResult, priorResidenciesResult] = await Promise.all([
      supabase.from('countries_visited').select('*'),
      supabase.from('prior_residencies').select('*'),
    ]);
    const loaded = visitsResult.data ?? [];
    const loadedPriorResidencies = priorResidenciesResult.data ?? [];
    setVisits(loaded);
    setPriorResidencies(loadedPriorResidencies);
    // Land on the first month within the selected year that actually has a
    // highlighted day, rather than always January — a flagged year's
    // relevant days are usually clustered later in it. Only done once, on
    // first load — after that, month/year navigation below owns displayMonth.
    // Uses loadedPriorResidencies directly rather than isHomeCountryForYear
    // (which reads priorResidencies state) — that state update above hasn't
    // actually applied yet at this point in the same tick.
    const isHome = country === effectiveHomeCountryFor(`${selectedYear}-12-31`, homeCountry, loadedPriorResidencies);
    setDisplayMonth(
      (prev) => prev ?? firstMonthWithData(daySetForYear(loaded, country, isHome, selectedYear, new Date()), selectedYear, new Date())
    );
    setIsLoading(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [country, homeCountry]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  function selectYear(year: number) {
    setSelectedYear(year);
    setDisplayMonth(firstMonthWithData(daySetForYear(visits, country, isHomeCountryForYear(year), year, new Date()), year, new Date()));
  }

  function jumpToMonth(date: Date) {
    setDisplayMonth(date);
    setSelectedYear(date.getFullYear());
  }

  function changeMonth(delta: number) {
    setDisplayMonth((d) => {
      const base = d ?? new Date(selectedYear, 0, 1);
      const next = new Date(base.getFullYear(), base.getMonth() + delta, 1);
      if (next.getFullYear() !== selectedYear) setSelectedYear(next.getFullYear());
      return next;
    });
  }

  if (isLoading || !displayMonth) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  const today = new Date();
  const todayStr = toDateOnlyString(today);
  const isHomeCountrySelectedYear = isHomeCountryForYear(selectedYear);
  const highlighted = daySetForYear(visits, country, isHomeCountrySelectedYear, selectedYear, today);
  const countryRanges = visits
    .filter((v) => v.country === country)
    .map((v) => ({ start: v.entry_date, end: v.exit_date }));
  const availableYears = Array.from(
    new Set([
      ...yearsSpannedByRanges(countryRanges),
      ...yearsSpannedByRanges(priorResidencies.filter((r) => r.country === country).map((r) => ({ start: r.start_date, end: r.end_date }))),
      new Date().getFullYear(),
      selectedYear,
    ])
  ).sort((a, b) => b - a);

  const yearDays = isHomeCountrySelectedYear
    ? homeCountryDaysForYear(visits, country, selectedYear)
    : daysInCountryForYear(visits, country, selectedYear);

  const weeks = computeWeekRows(displayMonth, 'month');
  const dayWidth = rowWidth / 7;

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">‹ Back</ThemedText>
          </Pressable>
          <ThemedText type="title" style={[{ color: ACCENT }, styles.titleText]} numberOfLines={1} adjustsFontSizeToFit>
            {country}
          </ThemedText>
          <View style={styles.titleSpacer} />
        </ThemedView>

        <Surface accentColor={ACCENT}>
          <ThemedText style={styles.muted}>Days in {country} in {selectedYear}</ThemedText>
          <ThemedText type="mono" style={styles.yearDaysValue}>
            {yearDays}
          </ThemedText>
        </Surface>

        <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chipRow}>
          {availableYears.map((y) => {
            const isSelected = y === selectedYear;
            return (
              <Pressable
                key={y}
                onPress={() => selectYear(y)}
                style={[styles.chip, { borderColor: ACCENT, backgroundColor: isSelected ? ACCENT : 'transparent' }]}>
                <ThemedText style={isSelected ? { color: ModuleAccentOnColor.countries } : undefined}>{y}</ThemedText>
              </Pressable>
            );
          })}
        </ScrollView>

        <ThemedView style={styles.monthHeader}>
          <Pressable onPress={() => changeMonth(-1)} hitSlop={10}>
            <ThemedText style={[styles.nav, { color: ACCENT }]}>‹</ThemedText>
          </Pressable>
          <MonthYearJump value={displayMonth} onChange={jumpToMonth} accentColor={ACCENT} />
          <Pressable onPress={() => changeMonth(1)} hitSlop={10}>
            <ThemedText style={[styles.nav, { color: ACCENT }]}>›</ThemedText>
          </Pressable>
        </ThemedView>

        <ThemedView onLayout={(e) => setRowWidth(e.nativeEvent.layout.width)}>
          <ThemedView style={styles.weekdayRow}>
            {WEEKDAY_LABELS.map((label) => (
              <ThemedText key={label} style={[styles.weekdayLabel, { width: dayWidth }]}>
                {label}
              </ThemedText>
            ))}
          </ThemedView>

          {weeks.map((week, weekIndex) => {
            const flags = week.map((day) => highlighted.has(toDateOnlyString(day)));
            const bands = computeBands(flags);
            return (
              <View key={weekIndex} style={styles.row}>
                <View style={styles.dayNumberRow}>
                  {week.map((day) => {
                    const dayStr = toDateOnlyString(day);
                    const inMonth = day.getMonth() === displayMonth.getMonth();
                    const isToday = dayStr === todayStr;
                    return (
                      <View key={dayStr} style={{ width: dayWidth, alignItems: 'center' }}>
                        <ThemedText
                          type={isToday ? 'defaultSemiBold' : 'default'}
                          style={[
                            styles.dayNumber,
                            !inMonth ? styles.dayNumberMuted : null,
                            isToday ? { color: ACCENT } : null,
                          ]}>
                          {day.getDate()}
                        </ThemedText>
                      </View>
                    );
                  })}
                </View>
                <View style={styles.bandArea}>
                  {bands.map((band) => {
                    const left = band.startIndex * dayWidth + 1;
                    const width = (band.endIndex - band.startIndex + 1) * dayWidth - 2;
                    const startDate = formatDateDisplay(toDateOnlyString(week[band.startIndex]));
                    const endDate = formatDateDisplay(toDateOnlyString(week[band.endIndex]));
                    return (
                      <View
                        key={band.key}
                        style={[styles.band, { left, width, backgroundColor: ACCENT }]}
                        accessibilityLabel={startDate === endDate ? startDate : `${startDate} to ${endDate}`}
                      />
                    );
                  })}
                </View>
              </View>
            );
          })}
        </ThemedView>

        <ThemedText style={styles.legendHint}>Bars mark days spent in {country}.</ThemedText>
      </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

