import { supabase } from '@/lib/supabase';

const BASE_CURRENCY = 'USD';
const STALE_AFTER_MS = 24 * 60 * 60 * 1000;

type FrankfurterRatesResponse = {
  base: string;
  rates: Record<string, number>;
};

/** Frankfurter's /v1/currencies returns { "AUD": "Australian Dollar", ... } for every currency it supports. */
type FrankfurterCurrenciesResponse = Record<string, string>;

/**
 * The full code->name map Frankfurter supports, not a fixed subset —
 * fetched fresh each time refreshExchangeRates() actually runs, which is
 * already gated to once per 24h by refreshExchangeRatesIfStale(). That gate
 * is the caching: there's no separate storage for this map on its own,
 * since it's only ever needed right before (and to enrich) the rates fetch.
 */
async function fetchSupportedCurrencies(): Promise<FrankfurterCurrenciesResponse> {
  const response = await fetch('https://api.frankfurter.dev/v1/currencies');
  if (!response.ok) return {};
  return response.json();
}

/** Fetches current rates from Frankfurter for every currency it supports and upserts them (with full names) into exchange_rates. */
export async function refreshExchangeRates(): Promise<void> {
  const currencyNames = await fetchSupportedCurrencies();
  const symbols = Object.keys(currencyNames)
    .filter((c) => c !== BASE_CURRENCY)
    .join(',');
  if (!symbols) return;

  const response = await fetch(
    `https://api.frankfurter.dev/v1/latest?base=${BASE_CURRENCY}&symbols=${symbols}`
  );
  if (!response.ok) return;

  const payload: FrankfurterRatesResponse = await response.json();
  const now = new Date().toISOString();

  // Frankfurter's rates are "units of X per 1 base" — rate_to_base needs the
  // inverse, since it's "multiply an amount in X by this to get an amount in base".
  const rows = [
    { currency: BASE_CURRENCY, rate_to_base: 1, name: currencyNames[BASE_CURRENCY] ?? null, updated_at: now },
    ...Object.entries(payload.rates).map(([currency, unitsPerBase]) => ({
      currency,
      rate_to_base: 1 / unitsPerBase,
      name: currencyNames[currency] ?? null,
      updated_at: now,
    })),
  ];

  await supabase.from('exchange_rates').upsert(rows, { onConflict: 'currency' });
}

/** Refreshes rates only if the last refresh is missing or older than 24 hours. */
export async function refreshExchangeRatesIfStale(): Promise<void> {
  try {
    const { data } = await supabase
      .from('exchange_rates')
      .select('updated_at')
      .eq('currency', BASE_CURRENCY)
      .maybeSingle();

    const lastUpdated = data?.updated_at;
    const isStale = !lastUpdated || Date.now() - new Date(lastUpdated).getTime() > STALE_AFTER_MS;
    if (!isStale) return;

    await refreshExchangeRates();
  } catch {
    // Best-effort refresh — fall back to whatever rates are already seeded/cached.
  }
}
