import { useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput } from 'react-native';
import { SvgXml } from 'react-native-svg';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { showAlert } from '@/lib/alert';
import { supabase } from '@/lib/supabase';

const TINT = Colors.light.tint;

type PendingEnrollment = { factorId: string; qrCodeXml: string; secret: string };

export default function MfaScreen() {
  const router = useRouter();
  const { refreshMfaStatus } = useAuth();

  const [isLoading, setIsLoading] = useState(true);
  const [enrolledFactorId, setEnrolledFactorId] = useState<string | null>(null);
  const [pending, setPending] = useState<PendingEnrollment | null>(null);
  const [code, setCode] = useState('');
  const [isBusy, setIsBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [justEnabled, setJustEnabled] = useState(false);

  useEffect(() => {
    supabase.auth.mfa.listFactors().then(({ data, error: listError }) => {
      if (listError) {
        setError(listError.message);
      } else {
        setEnrolledFactorId(data?.totp[0]?.id ?? null);
      }
      setIsLoading(false);
    });
  }, []);

  async function handleStartEnroll() {
    setError(null);
    setIsBusy(true);
    const { data, error: enrollError } = await supabase.auth.mfa.enroll({ factorType: 'totp' });
    setIsBusy(false);
    if (enrollError) {
      setError(enrollError.message);
      return;
    }
    setPending({ factorId: data.id, qrCodeXml: data.totp.qr_code, secret: data.totp.secret });
  }

  async function handleVerify() {
    if (!pending || code.trim().length !== 6) {
      setError('Enter the 6-digit code from your authenticator app.');
      return;
    }
    setError(null);
    setIsBusy(true);
    const { error: verifyError } = await supabase.auth.mfa.challengeAndVerify({ factorId: pending.factorId, code: code.trim() });
    setIsBusy(false);
    if (verifyError) {
      setError(verifyError.message);
      return;
    }
    setEnrolledFactorId(pending.factorId);
    setPending(null);
    setCode('');
    setJustEnabled(true);
    await refreshMfaStatus();
  }

  function handleCancelEnroll() {
    // Leaves the unverified factor behind server-side (Supabase allows
    // multiple unverified factors and they don't affect AAL), but there's
    // no unenroll-without-verifying flow worth building for a screen the
    // user can just re-open — enrolling again simply creates a fresh one.
    setPending(null);
    setCode('');
    setError(null);
  }

  function handleTurnOff() {
    if (!enrolledFactorId) return;
    showAlert('Turn off two-factor authentication?', 'Your account will only require a password to sign in.', [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Turn off',
        style: 'destructive',
        onPress: async () => {
          setError(null);
          setIsBusy(true);
          const { error: unenrollError } = await supabase.auth.mfa.unenroll({ factorId: enrolledFactorId });
          setIsBusy(false);
          if (unenrollError) {
            setError(unenrollError.message);
            return;
          }
          setEnrolledFactorId(null);
          setJustEnabled(false);
          await refreshMfaStatus();
        },
      },
    ]);
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: TINT }}>
            Two-Factor Authentication
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {isLoading ? (
          <ActivityIndicator style={styles.loading} color={TINT} />
        ) : enrolledFactorId ? (
          <>
            <Surface accentColor={TINT}>
              <ThemedText type="defaultSemiBold">Two-factor authentication is on</ThemedText>
              <ThemedText style={styles.muted}>
                {justEnabled
                  ? "You'll be asked for a code from your authenticator app the next time you sign in."
                  : 'A code from your authenticator app is required every time you sign in.'}
              </ThemedText>
            </Surface>
            <Pressable onPress={handleTurnOff} disabled={isBusy} style={[styles.button, styles.buttonOutline, { borderColor: Colors.light.negative }]}>
              {isBusy ? (
                <ActivityIndicator color={Colors.light.negative} />
              ) : (
                <ThemedText style={{ color: Colors.light.negative, fontWeight: '600' }}>Turn off</ThemedText>
              )}
            </Pressable>
          </>
        ) : pending ? (
          <>
            <ThemedText style={styles.muted}>
              Scan this code with an authenticator app (like Google Authenticator or Authy), then enter the 6-digit
              code it generates below.
            </ThemedText>
            <ThemedView style={styles.qrBox}>
              <SvgXml xml={pending.qrCodeXml} width={200} height={200} />
            </ThemedView>
            <ThemedText style={styles.hint}>Can&apos;t scan? Enter this code manually:</ThemedText>
            <ThemedText type="mono" selectable style={styles.secret}>
              {pending.secret}
            </ThemedText>

            <TextInput
              value={code}
              onChangeText={(text) => setCode(text.replace(/\D/g, '').slice(0, 6))}
              placeholder="123456"
              placeholderTextColor={Colors.light.textMuted}
              keyboardType="number-pad"
              maxLength={6}
              style={[styles.input, { color: Colors.light.text, borderColor: TINT }]}
            />
            <Pressable onPress={handleVerify} disabled={isBusy} style={[styles.button, { backgroundColor: TINT }]}>
              {isBusy ? (
                <ActivityIndicator color={Colors.light.backgroundSolid} />
              ) : (
                <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Verify &amp; enable</ThemedText>
              )}
            </Pressable>
            <Pressable onPress={handleCancelEnroll} style={styles.cancelLink}>
              <ThemedText type="link">Cancel</ThemedText>
            </Pressable>
          </>
        ) : (
          <>
            <Surface accentColor={TINT}>
              <ThemedText type="defaultSemiBold">Two-factor authentication is off</ThemedText>
              <ThemedText style={styles.muted}>
                Add a second step at sign-in using an authenticator app on your phone: a code from the app, in
                addition to your password.
              </ThemedText>
            </Surface>
            <Pressable onPress={handleStartEnroll} disabled={isBusy} style={[styles.button, { backgroundColor: TINT }]}>
              {isBusy ? (
                <ActivityIndicator color={Colors.light.backgroundSolid} />
              ) : (
                <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Enable</ThemedText>
              )}
            </Pressable>
          </>
        )}
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 4,
  },
  muted: {
    opacity: 0.7,
    fontSize: 13,
    color: Colors.light.textMuted,
  },
  hint: {
    opacity: 0.7,
    fontSize: 12,
    color: Colors.light.textMuted,
    marginTop: 12,
  },
  loading: {
    marginTop: 32,
  },
  qrBox: {
    alignItems: 'center',
    marginVertical: 16,
  },
  secret: {
    textAlign: 'center',
    fontSize: 15,
    letterSpacing: 1,
    marginTop: 4,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 14,
    fontSize: 22,
    letterSpacing: 6,
    textAlign: 'center',
    marginTop: 16,
    marginBottom: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  buttonOutline: {
    backgroundColor: 'transparent',
    borderWidth: StyleSheet.hairlineWidth,
  },
  cancelLink: {
    marginTop: 12,
    alignItems: 'center',
  },
  error: {
    color: Colors.light.negative,
  },
});
