import { Platform, StyleSheet, View } from 'react-native';
import MapView, { Marker, PROVIDER_DEFAULT, PROVIDER_GOOGLE, type Region } from 'react-native-maps';

import type { MapMarker } from '@/lib/mapMarker';

const MAP_HEIGHT = 300;
// How much room to leave around the markers' own bounding box, and the
// smallest zoom level to ever show — a single marker (or several very
// close together) would otherwise zoom in absurdly tight.
const REGION_PADDING_FACTOR = 1.6;
const MIN_DELTA = 20;

function computeInitialRegion(markers: MapMarker[]): Region {
  if (markers.length === 0) {
    return { latitude: 20, longitude: 0, latitudeDelta: 100, longitudeDelta: 100 };
  }
  const lats = markers.map((m) => m.lat);
  const lons = markers.map((m) => m.lon);
  const minLat = Math.min(...lats);
  const maxLat = Math.max(...lats);
  const minLon = Math.min(...lons);
  const maxLon = Math.max(...lons);
  return {
    latitude: (minLat + maxLat) / 2,
    longitude: (minLon + maxLon) / 2,
    latitudeDelta: Math.max((maxLat - minLat) * REGION_PADDING_FACTOR, MIN_DELTA),
    longitudeDelta: Math.max((maxLon - minLon) * REGION_PADDING_FACTOR, MIN_DELTA),
  };
}

/**
 * iOS/Android's real map — Apple Maps by default on iOS (no API key
 * needed), Google Maps on Android (needs android.config.googleMaps.apiKey
 * in app.json). Web has no react-native-maps support at all, so
 * connections-map.web.tsx's stylized SVG stands in there instead — Metro's
 * platform extension resolution picks whichever of the two matches the
 * build target, so callers just import from './connections-map'.
 */
export function ConnectionsMap({ markers, accentColor, onSelectMarker }: { markers: MapMarker[]; accentColor: string; onSelectMarker: (id: string) => void }) {
  return (
    <View style={styles.container}>
      <MapView
        style={styles.map}
        initialRegion={computeInitialRegion(markers)}
        provider={Platform.OS === 'android' ? PROVIDER_GOOGLE : PROVIDER_DEFAULT}>
        {markers.map((m) => (
          <Marker
            key={m.id}
            coordinate={{ latitude: m.lat, longitude: m.lon }}
            title={m.label}
            pinColor={accentColor}
            onPress={() => onSelectMarker(m.id)}
          />
        ))}
      </MapView>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    height: MAP_HEIGHT,
    borderRadius: 12,
    overflow: 'hidden',
  },
  map: {
    flex: 1,
  },
});
