import type { ConvertedAmount } from '@/contexts/currency-context';
import { effectiveHomeCountryFor, type PriorResidencyLike } from '@/lib/days';
import type { CountryVisitedRow, TransactionRow } from '@/types/database';

/** Distinct calendar years present among these YYYY-MM-DD date strings, most recent first. Powers an "All-time / 2026 / 2025 / ..." year toggle populated from actual data, not a fixed range. */
export function yearsWithData(dates: string[]): number[] {
  const years = new Set(dates.map((d) => Number(d.slice(0, 4))));
  return Array.from(years).sort((a, b) => b - a);
}

/**
 * Every calendar year touched by any of these [start, end] ranges, most
 * recent first. Deliberately NOT yearsWithData(starts) — a single stop that
 * ran from 2019 through 2022 only has ONE start date, so a start-only year
 * list would show just "2019" even though the stay also covered 2020-2022.
 * A null end (still ongoing) is treated as running through `today`.
 */
export function yearsSpannedByRanges(
  ranges: { start: string; end: string | null }[],
  today: Date = new Date()
): number[] {
  const years = new Set<number>();
  const todayYear = today.getFullYear();
  for (const range of ranges) {
    const startYear = Number(range.start.slice(0, 4));
    const endYear = range.end ? Number(range.end.slice(0, 4)) : todayYear;
    for (let y = startYear; y <= endYear; y++) years.add(y);
  }
  return Array.from(years).sort((a, b) => b - a);
}

export type CategorySpend = {
  categoryId: string | null;
  categoryName: string;
  totals: { currency: string; amount: number }[];
};

/**
 * Groups by category, then by currency within each category. Each amount is
 * run through `convert` first — when a real display currency is selected,
 * everything collapses into a single currency per category; when "Local" is
 * selected, convert is a no-op and this falls back to per-currency grouping
 * since nothing unifies them.
 */
export function summarizeSpendByCategory(
  transactions: TransactionRow[],
  categoryNameById: Map<string, string>,
  convert: (amount: number, fromCurrency: string) => ConvertedAmount
): CategorySpend[] {
  const byCategory = new Map<string, { categoryName: string; totals: Map<string, number> }>();

  for (const tx of transactions) {
    const { amount, currency } = convert(tx.amount, tx.currency);
    const key = tx.category_id ?? 'uncategorized';
    const categoryName = tx.category_id ? (categoryNameById.get(tx.category_id) ?? 'Unknown') : 'Uncategorized';
    if (!byCategory.has(key)) {
      byCategory.set(key, { categoryName, totals: new Map() });
    }
    const entry = byCategory.get(key)!;
    entry.totals.set(currency, (entry.totals.get(currency) ?? 0) + amount);
  }

  return Array.from(byCategory.entries())
    .map(([categoryId, { categoryName, totals }]) => ({
      categoryId: categoryId === 'uncategorized' ? null : categoryId,
      categoryName,
      totals: Array.from(totals.entries()).map(([currency, amount]) => ({ currency, amount })),
    }))
    .sort(
      (a, b) =>
        b.totals.reduce((sum, t) => sum + t.amount, 0) - a.totals.reduce((sum, t) => sum + t.amount, 0)
    );
}

export type CategoryTrend = {
  categoryId: string | null;
  categoryName: string;
  currentAmount: number;
  previousAmount: number;
  currency: string;
  change: number;
};

/**
 * Compares two summarizeSpendByCategory() results, current period vs
 * previous. Sorted by the size of the change (biggest movers first), not by
 * current-period total — a category that doubled is more interesting here
 * than one that's simply the largest.
 *
 * Only the first currency total per category is compared — in practice
 * that's the only one, since a real display currency collapses everything.
 * "Local" mode can leave a category split across currencies; this doesn't
 * attempt to reconcile that for trend purposes.
 */
export function compareSpendByCategory(current: CategorySpend[], previous: CategorySpend[]): CategoryTrend[] {
  type Entry = { name: string; current: number; previous: number; currency: string };
  const byId = new Map<string, Entry>();

  for (const entry of current) {
    const key = entry.categoryId ?? 'uncategorized';
    byId.set(key, {
      name: entry.categoryName,
      current: entry.totals[0]?.amount ?? 0,
      previous: 0,
      currency: entry.totals[0]?.currency ?? '',
    });
  }
  for (const entry of previous) {
    const key = entry.categoryId ?? 'uncategorized';
    const amount = entry.totals[0]?.amount ?? 0;
    const currency = entry.totals[0]?.currency ?? '';
    const existing = byId.get(key);
    if (existing) {
      existing.previous = amount;
    } else {
      byId.set(key, { name: entry.categoryName, current: 0, previous: amount, currency });
    }
  }

  return Array.from(byId.entries())
    .map(([categoryId, v]) => ({
      categoryId: categoryId === 'uncategorized' ? null : categoryId,
      categoryName: v.name,
      currentAmount: v.current,
      previousAmount: v.previous,
      currency: v.currency,
      change: v.current - v.previous,
    }))
    .sort((a, b) => Math.abs(b.change) - Math.abs(a.change));
}

/**
 * Narrows compareSpendByCategory's output down to movers worth actually
 * flagging — a category swinging from $8 to $12 is a 50% change but not
 * worth interrupting anyone about, so both a relative AND an absolute floor
 * have to clear before something counts as "significant." Uncategorized is
 * excluded entirely — it's a data-quality gap, not a spending trend.
 * previousAmount === 0 (a brand-new category this period) always counts,
 * since there's no meaningful percentage to compute against zero.
 */
export function significantSpendTrends(
  trends: CategoryTrend[],
  opts: { minRelativeChange?: number; minAbsoluteChange?: number } = {}
): CategoryTrend[] {
  const minRelativeChange = opts.minRelativeChange ?? 0.4;
  const minAbsoluteChange = opts.minAbsoluteChange ?? 50;
  return trends.filter((t) => {
    if (t.categoryId === null) return false;
    if (Math.abs(t.change) < minAbsoluteChange) return false;
    if (t.previousAmount === 0) return true;
    return Math.abs(t.change) / Math.abs(t.previousAmount) >= minRelativeChange;
  });
}

export type Attribution = { country: string; city: string | null };

/**
 * Attributes a date to a country and city — a trip to somewhere other than
 * home covering that date, or the home country (with no city) as a
 * fallback. This is computed fresh here, not read from
 * transactions.attributed_country_id: that column exists but nothing has
 * ever populated it, and countries in this app are tracked by name (see
 * lib/countries.ts), not by a countries table id that column's name
 * implies. Deriving it avoids relying on a stored value that's never been
 * kept in sync with countries_visited edits.
 */
export function attributedLocationForDate(
  date: string,
  visits: Pick<CountryVisitedRow, 'country' | 'city' | 'entry_date' | 'exit_date'>[],
  homeCountry: string | null,
  /** transactions.excluded_from_travel_spend — when true, skips trip matching entirely even if the date falls within one, same as if no trip covered that date. */
  excludeFromTrip = false,
  /** Falls back to whichever prior residency (app/account/prior-residencies.tsx) covers `date`, if any, instead of always the CURRENT home country — a transaction dated during a past residency abroad shouldn't attribute to wherever you live now. Defaults to none for callers that haven't loaded this data yet, reproducing the old always-current-home behavior. */
  priorResidencies: PriorResidencyLike[] = []
): Attribution {
  if (!excludeFromTrip) {
    const trip = visits.find((v) => date >= v.entry_date && (!v.exit_date || date <= v.exit_date));
    if (trip) return { country: trip.country, city: trip.city };
  }
  return { country: effectiveHomeCountryFor(date, homeCountry, priorResidencies) ?? 'Unknown', city: null };
}

/** Country-only convenience wrapper around attributedLocationForDate, for callers that don't need city. */
export function attributedCountryForDate(
  date: string,
  visits: Pick<CountryVisitedRow, 'country' | 'city' | 'entry_date' | 'exit_date'>[],
  homeCountry: string | null,
  excludeFromTrip = false,
  priorResidencies: PriorResidencyLike[] = []
): string {
  return attributedLocationForDate(date, visits, homeCountry, excludeFromTrip, priorResidencies).country;
}

/**
 * Resolves a trip_stop_id/trip_segment_id to a country/city, for
 * attributedLocationForTransaction below. segmentCountryById maps a segment
 * to its trip's PRIMARY country (lib/trips.ts's computeTripSummaries(...).countries[0])
 * rather than something derived from the segment's own from_label/to_label —
 * those are free text, not a resolvable single country in general (a leg can
 * cross borders), so the whole trip's primary country is the closest
 * meaningful attribution.
 */
export type TripLinkMaps = {
  stopsById: Map<string, Pick<CountryVisitedRow, 'country' | 'city'>>;
  segmentCountryById: Map<string, string>;
};

/**
 * Layers an explicit stop/leg link on top of attributedLocationForDate — an
 * opt-IN override (as opposed to excluded_from_travel_spend, an opt-OUT),
 * set via app/transactions/[id].tsx's Trip field or by linking an expense
 * from the Trip Detail screen. Takes priority over date-based matching
 * entirely, regardless of whether the transaction's own date falls inside
 * the linked trip's range. `links` is optional so this is a strict superset
 * of attributedLocationForDate — omitting it reproduces the exact same
 * result, for callers that haven't been updated to load the link maps yet.
 */
export function attributedLocationForTransaction(
  tx: Pick<TransactionRow, 'date' | 'trip_stop_id' | 'trip_segment_id'>,
  visits: Pick<CountryVisitedRow, 'country' | 'city' | 'entry_date' | 'exit_date'>[],
  homeCountry: string | null,
  excludeFromTrip: boolean,
  links?: TripLinkMaps,
  priorResidencies: PriorResidencyLike[] = []
): Attribution {
  if (links && tx.trip_stop_id) {
    const stop = links.stopsById.get(tx.trip_stop_id);
    if (stop) return { country: stop.country, city: stop.city };
  }
  if (links && tx.trip_segment_id) {
    const country = links.segmentCountryById.get(tx.trip_segment_id);
    if (country) return { country, city: null };
  }
  return attributedLocationForDate(tx.date, visits, homeCountry, excludeFromTrip, priorResidencies);
}

/**
 * True when a transaction only counts as `country` because of an explicit
 * stop/leg link — the pure date-based attribution (ignoring any link) would
 * land somewhere else (typically home). Powers the Country Detail "In
 * {country}" vs "Related" split: a linked transaction whose date already
 * fell inside the trip doesn't need the "Related" callout, since the date
 * alone would already have gotten it right.
 */
export function isRelatedOutOfCountry(
  tx: Pick<TransactionRow, 'date' | 'trip_stop_id' | 'trip_segment_id'>,
  country: string,
  visits: Pick<CountryVisitedRow, 'country' | 'city' | 'entry_date' | 'exit_date'>[],
  homeCountry: string | null,
  excludeFromTrip: boolean,
  links: TripLinkMaps,
  priorResidencies: PriorResidencyLike[] = []
): boolean {
  const withLink = attributedLocationForTransaction(tx, visits, homeCountry, excludeFromTrip, links, priorResidencies);
  if (withLink.country !== country) return false;
  const dateOnly = attributedLocationForDate(tx.date, visits, homeCountry, excludeFromTrip, priorResidencies);
  return dateOnly.country !== country;
}

export type CountrySpend = {
  country: string;
  totals: { currency: string; amount: number }[];
};

type VisitForAttribution = Pick<CountryVisitedRow, 'country' | 'city' | 'entry_date' | 'exit_date'>;

/** True if either the transaction itself opted out of trip attribution, or its account is flagged to always attribute to home (accounts.excluded_from_country_tracking) — e.g. an investment account, where a trade made while traveling shouldn't read as spend in that country. */
export function isExcludedFromCountryTracking(
  tx: Pick<TransactionRow, 'account_id' | 'excluded_from_travel_spend'>,
  excludedAccountIds: Set<string>
): boolean {
  return tx.excluded_from_travel_spend || (!!tx.account_id && excludedAccountIds.has(tx.account_id));
}

/** Same grouping technique as summarizeSpendByCategory, grouped by attributed country instead of category. */
export function summarizeSpendByCountry(
  transactions: TransactionRow[],
  visits: VisitForAttribution[],
  homeCountry: string | null,
  convert: (amount: number, fromCurrency: string) => ConvertedAmount,
  excludedAccountIds: Set<string> = new Set(),
  links?: TripLinkMaps
): CountrySpend[] {
  const byCountry = new Map<string, Map<string, number>>();

  for (const tx of transactions) {
    const country = attributedLocationForTransaction(
      tx,
      visits,
      homeCountry,
      isExcludedFromCountryTracking(tx, excludedAccountIds),
      links
    ).country;
    const { amount, currency } = convert(tx.amount, tx.currency);
    if (!byCountry.has(country)) byCountry.set(country, new Map());
    const totals = byCountry.get(country)!;
    totals.set(currency, (totals.get(currency) ?? 0) + amount);
  }

  return Array.from(byCountry.entries())
    .map(([country, totals]) => ({
      country,
      totals: Array.from(totals.entries()).map(([currency, amount]) => ({ currency, amount })),
    }))
    .sort(
      (a, b) =>
        b.totals.reduce((sum, t) => sum + t.amount, 0) - a.totals.reduce((sum, t) => sum + t.amount, 0)
    );
}

export type CitySpend = {
  country: string;
  city: string;
  totals: { currency: string; amount: number }[];
  topCategory: { categoryId: string | null; categoryName: string } | null;
};

/**
 * Groups transactions by (country, city) pair, computing both a total and
 * the top spend category per city — parallel to summarizeSpendByCountry,
 * but only ever includes transactions attributed to an actual trip city;
 * home-country fallback transactions have no city and are excluded, since
 * "cities visited" is inherently about trips, not home-base spend.
 */
export function summarizeSpendByCity(
  transactions: TransactionRow[],
  visits: VisitForAttribution[],
  homeCountry: string | null,
  categoryNameById: Map<string, string>,
  convert: (amount: number, fromCurrency: string) => ConvertedAmount,
  excludedAccountIds: Set<string> = new Set(),
  links?: TripLinkMaps,
  priorResidencies: PriorResidencyLike[] = []
): CitySpend[] {
  type Bucket = {
    country: string;
    city: string;
    totals: Map<string, number>;
    categoryTotals: Map<string, number>;
  };
  const byCity = new Map<string, Bucket>();

  for (const tx of transactions) {
    const { country, city } = attributedLocationForTransaction(
      tx,
      visits,
      homeCountry,
      isExcludedFromCountryTracking(tx, excludedAccountIds),
      links,
      priorResidencies
    );
    if (!city) continue;
    const key = `${country}�${city}`;
    if (!byCity.has(key)) {
      byCity.set(key, { country, city, totals: new Map(), categoryTotals: new Map() });
    }
    const bucket = byCity.get(key)!;
    const { amount, currency } = convert(tx.amount, tx.currency);
    bucket.totals.set(currency, (bucket.totals.get(currency) ?? 0) + amount);
    const categoryKey = tx.category_id ?? 'uncategorized';
    bucket.categoryTotals.set(categoryKey, (bucket.categoryTotals.get(categoryKey) ?? 0) + amount);
  }

  return Array.from(byCity.values())
    .map((bucket) => {
      let topCategoryKey: string | null = null;
      let topAmount = -Infinity;
      for (const [categoryKey, amount] of bucket.categoryTotals.entries()) {
        if (amount > topAmount) {
          topAmount = amount;
          topCategoryKey = categoryKey;
        }
      }
      const topCategory =
        topCategoryKey === null
          ? null
          : {
              categoryId: topCategoryKey === 'uncategorized' ? null : topCategoryKey,
              categoryName:
                topCategoryKey === 'uncategorized' ? 'Uncategorized' : (categoryNameById.get(topCategoryKey) ?? 'Unknown'),
            };

      return {
        country: bucket.country,
        city: bucket.city,
        totals: Array.from(bucket.totals.entries()).map(([currency, amount]) => ({ currency, amount })),
        topCategory,
      };
    })
    .sort(
      (a, b) =>
        b.totals.reduce((sum, t) => sum + t.amount, 0) - a.totals.reduce((sum, t) => sum + t.amount, 0)
    );
}
