const ACCENT = ModuleAccents.countries;
const DEFAULT_COLOR = Colors.light.tint;

type Tab = 'countries' | 'trips';
type ChartMode = 'calendar' | 'venn';
type VennRangeMode = 'week' | 'month' | 'year';
type SharedRow = { user_id: string; country: string; city: string | null; entry_date: string; exit_date: string | null };
type JointRow = { country: string; mine: CountrySummary | null; partner: CountrySummary | null };

/**
 * Wraps a country/city overlap card with the plan-together gate: an
 * accepted agreement renders exactly like the old always-tappable card
 * (onPressAccepted -> shared notes); anything else (no agreement, pending,
 * declined) renders the same visual card but not pressable, plus a small
 * action row for proposing/accepting/declining. Used by both the country-
 * level "Planned together" and city-level "Same city" sections, which
 * otherwise duplicate this exact gating logic.
 */
function PlanTogetherCard({
  country,
  plan,
  myId,
  partnerLabel,
  busy,
  onPropose,
  onRespond,
  accentColor,
  onPressAccepted,
  children,
}: {
  country: string;
  plan: TripPlanRequestRow | undefined;
  myId: string;
  partnerLabel: string;
  busy: boolean;
  onPropose: (country: string) => void;
  onRespond: (requestId: string, status: 'accepted' | 'declined') => void;
  accentColor: string;
  onPressAccepted: () => void;
  children: ReactNode;
}) {
  const isAccepted = plan?.status === 'accepted';

  const card = (
    <Surface accentColor={accentColor} style={styles.card}>
      {children}
      {isAccepted ? (
        <ThemedText style={styles.notesHint}>Tap for shared planning notes</ThemedText>
      ) : !plan ? (
        <Pressable disabled={busy} onPress={() => onPropose(country)} hitSlop={6}>
          <ThemedText type="link">Plan together?</ThemedText>
        </Pressable>
      ) : plan.status === 'pending' && plan.requested_by === myId ? (
        <ThemedText style={styles.muted}>Waiting for {partnerLabel} to accept.</ThemedText>
      ) : plan.status === 'pending' ? (
        <ThemedView style={styles.planActionRow}>
          <ThemedText style={styles.muted}>{partnerLabel} wants to plan this together.</ThemedText>
          <Pressable disabled={busy} onPress={() => onRespond(plan.id, 'accepted')} hitSlop={6}>
            <ThemedText type="link">Accept</ThemedText>
          </Pressable>
          <Pressable disabled={busy} onPress={() => onRespond(plan.id, 'declined')} hitSlop={6}>
            <ThemedText style={{ color: Colors.light.negative }}>Decline</ThemedText>
          </Pressable>
        </ThemedView>
      ) : (
        <ThemedView style={styles.planActionRow}>
          <ThemedText style={styles.muted}>Declined.</ThemedText>
          <Pressable disabled={busy} onPress={() => onPropose(country)} hitSlop={6}>
            <ThemedText type="link">Propose again?</ThemedText>
          </Pressable>
        </ThemedView>
      )}
    </Surface>
  );

  return isAccepted ? <Pressable onPress={onPressAccepted}>{card}</Pressable> : card;
}

export default function ConnectionTravelScreen() {
  const { connectionId, tab: requestedTab } = useLocalSearchParams<{ connectionId: string; tab?: string }>();
  const router = useRouter();
  const { session } = useAuth();
  const { homeCountry, hiddenFlagCountries } = useCurrency();
  const display = useConnectionDisplay(connectionId);
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const [tab, setTab] = useState<Tab | null>(null);

  const [myVisits, setMyVisits] = useState<CountryVisitedRow[]>([]);
  const [partnerVisited, setPartnerVisited] = useState<SharedRow[]>([]);
  const [partnerPlanned, setPartnerPlanned] = useState<SharedRow[]>([]);
  const [myColor, setMyColor] = useState<string | null>(null);
  const [myName, setMyName] = useState<string | null>(null);
  const [myHomeCity, setMyHomeCity] = useState<string | null>(null);
  const [partnerHomeCity, setPartnerHomeCity] = useState<string | null>(null);
  const [partnerHomeCountry, setPartnerHomeCountry] = useState<string | null>(null);
  const [partnerColor, setPartnerColor] = useState<string | null>(null);
  const [canShowCountries, setCanShowCountries] = useState(false);
  const [canShowTrips, setCanShowTrips] = useState(false);
  const [planRequests, setPlanRequests] = useState<TripPlanRequestRow[]>([]);
  const [planBusy, setPlanBusy] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [viewMode, setViewMode] = useState<CalendarViewMode>('month');
  const [chartMode, setChartMode] = useState<ChartMode>('calendar');
  const [vennRangeMode, setVennRangeMode] = useState<VennRangeMode>('month');
  const [currentDate, setCurrentDate] = useState(new Date());

  const load = useCallback(async () => {
    if (!session) return;
    setError(null);
    const myId = session.user.id;

    const [
      myVisitsResult,
      partnerVisitedResult,
      partnerPlannedResult,
      myColorResult,
      partnerColorResult,
      incomingRequestsResult,
      myHomeCityResult,
      partnerHomeCityResult,
      planRequestsResult,
    ] = await Promise.all([
      supabase.from('countries_visited').select('*'),
      supabase.rpc('shared_countries_visited', { p_connection_id: connectionId }),
      supabase.rpc('shared_trips_planned', { p_connection_id: connectionId }),
      supabase.from('user_settings').select('calendar_color, full_name').eq('user_id', myId).maybeSingle(),
      supabase.rpc('connection_partner_calendar_color', { p_connection_id: connectionId }),
      supabase
        .from('connection_share_requests')
        .select('module')
        .eq('connection_id', connectionId)
        .eq('to_user_id', myId)
        .eq('status', 'accepted'),
      supabase.from('user_settings').select('home_city').eq('user_id', myId).maybeSingle(),
      // Gated on the partner's OWN accepted 'countries' share to me (same
      // RPC the map screen uses) — needed for the reverse "same city"
      // direction below: me traveling to where THEY live, not just them
      // traveling to where I live.
      supabase.rpc('shared_home_location', { p_connection_id: connectionId }).maybeSingle(),
      fetchTripPlanRequests(connectionId),
    ]);

    if (myVisitsResult.error) {
      setError(myVisitsResult.error.message);
      setIsLoading(false);
      return;
    }
    if (partnerVisitedResult.error) {
      setError(partnerVisitedResult.error.message);
      setIsLoading(false);
      return;
    }
    if (partnerPlannedResult.error) {
      setError(partnerPlannedResult.error.message);
      setIsLoading(false);
      return;
    }

    // A tab only shows once the partner has an accepted share to ME for
    // that module — one-directional, not the old "both sides toggled it"
    // mutual check. Not just a privacy nicety: the RPCs themselves enforce
    // this too, so this is purely about which tabs to offer, not a
    // substitute security boundary.
    const acceptedModules = new Set((incomingRequestsResult.data ?? []).map((r) => r.module));
    const showCountries = acceptedModules.has('countries');
    const showTrips = acceptedModules.has('trips_planned');
    setCanShowCountries(showCountries);
    setCanShowTrips(showTrips);
    setTab((prev) => {
      if (prev === 'countries' && showCountries) return prev;
      if (prev === 'trips' && showTrips) return prev;
      // A requested tab (e.g. from a deep link) wins on first load, as long
      // as it's actually been shared with (and accepted by) me.
      if (requestedTab === 'trips' && showTrips) return 'trips';
      if (requestedTab === 'countries' && showCountries) return 'countries';
      if (showCountries) return 'countries';
      if (showTrips) return 'trips';
      return null;
    });

    setMyVisits(myVisitsResult.data ?? []);
    // Defensive filter, not a substitute for the server-side fix: the RPCs
    // should already exclude my own rows, but never trust "partner" data
    // without confirming it isn't actually mine.
    setPartnerVisited((partnerVisitedResult.data ?? []).filter((v) => v.user_id !== myId));
    setPartnerPlanned((partnerPlannedResult.data ?? []).filter((v) => v.user_id !== myId));
    setMyColor(myColorResult.data?.calendar_color ?? null);
    setMyName(myColorResult.data?.full_name ?? session.user.email?.split('@')[0] ?? null);
    setPartnerColor(partnerColorResult.data ?? null);
    setMyHomeCity(myHomeCityResult.data?.home_city ?? null);
    setPartnerHomeCity(partnerHomeCityResult.data?.home_city ?? null);
    setPartnerHomeCountry(partnerHomeCityResult.data?.home_country ?? null);
    if (planRequestsResult.error) setError(planRequestsResult.error);
    setPlanRequests(planRequestsResult.data);
    setIsLoading(false);
  }, [session, connectionId, requestedTab]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  async function handleProposePlan(country: string) {
    if (!session) return;
    setPlanBusy(country);
    const { error: proposeError } = await proposeTripPlan(connectionId, country, session.user.id);
    setPlanBusy(null);
    if (proposeError) {
      setError(proposeError);
      return;
    }
    load();
  }

  async function handleRespondPlan(requestId: string, status: 'accepted' | 'declined') {
    setPlanBusy(requestId);
    const { error: respondError } = await respondToTripPlan(requestId, status);
    setPlanBusy(null);
    if (respondError) {
      setError(respondError);
      return;
    }
    load();
  }

  if (isLoading || display.isLoading) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  const partnerLabel = display.displayName;
  const today = toDateOnlyString(new Date());

  // ---- Countries visited tab ----
  const myVisitedCountries = new Set(myVisits.filter((v) => v.entry_date <= today).map((v) => v.country));
  const partnerVisitedCountries = new Set(partnerVisited.filter((v) => v.entry_date <= today).map((v) => v.country));
  const mySummaries = summarizeCountries(myVisits).filter(
    (s) => s.country !== homeCountry && myVisitedCountries.has(s.country)
  );
  const partnerSummaries = summarizeCountries(partnerVisited).filter((s) => partnerVisitedCountries.has(s.country));
  const countrySet = new Set([...mySummaries.map((s) => s.country), ...partnerSummaries.map((s) => s.country)]);
  const countryRows: JointRow[] = Array.from(countrySet)
    .map((country) => ({
      country,
      mine: mySummaries.find((s) => s.country === country) ?? null,
      partner: partnerSummaries.find((s) => s.country === country) ?? null,
    }))
    .sort(
      (a, b) => (b.mine?.daysUsed ?? 0) + (b.partner?.daysUsed ?? 0) - ((a.mine?.daysUsed ?? 0) + (a.partner?.daysUsed ?? 0))
    );
  const traveledTogether = filterOverlapsByTense(computeSameCountryOverlaps(myVisits, partnerVisited), 'past');

  // ---- Trips planned tab ----
  const resolvedMyColor = myColor ?? DEFAULT_COLOR;
  const resolvedPartnerColor = display.colorOverride ?? partnerColor ?? Colors.light.icon;
  const effectiveRangeMode: VennRangeMode = chartMode === 'venn' ? vennRangeMode : viewMode;

  function goPrev() {
    setCurrentDate((d) => {
      if (effectiveRangeMode === 'year') return new Date(d.getFullYear() - 1, d.getMonth(), 1);
      if (effectiveRangeMode === 'month') return new Date(d.getFullYear(), d.getMonth() - 1, 1);
      return addDays(d, -7);
    });
  }
  function goNext() {
    setCurrentDate((d) => {
      if (effectiveRangeMode === 'year') return new Date(d.getFullYear() + 1, d.getMonth(), 1);
      if (effectiveRangeMode === 'month') return new Date(d.getFullYear(), d.getMonth() + 1, 1);
      return addDays(d, 7);
    });
  }
  function goToday() {
    setCurrentDate(new Date());
  }

  const rangeDays =
    effectiveRangeMode === 'year' ? computeYearRangeDays(currentDate) : computeRangeDays(currentDate, effectiveRangeMode);
  const rangeLabel =
    effectiveRangeMode === 'year'
      ? String(currentDate.getFullYear())
      : effectiveRangeMode === 'month'
        ? currentDate.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })
        : `${rangeDays[0].toLocaleDateString(undefined, { month: 'short', day: 'numeric' })} – ${rangeDays[rangeDays.length - 1].toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}`;

  // Fallback location for any day neither side has a logged trip for, fed
  // ONLY into the Venn diagram below — without this, two people simply
  // living in (or one just visiting) the same home city never counts
  // toward "same city" days, since home presence has no countries_visited
  // row of its own to match against. Deliberately NOT used for the
  // calendar-band view (computeDayCells) — home presence would render as a
  // near-permanent colored band there, which is noise rather than signal
  // for a calendar meant to highlight actual trips.
  const myHome = homeCountry && myHomeCity ? { country: homeCountry, city: myHomeCity } : null;
  const partnerHome = partnerHomeCountry && partnerHomeCity ? { country: partnerHomeCountry, city: partnerHomeCity } : null;

  const buckets = computeVennBuckets(rangeDays, myVisits, partnerPlanned, myHome, partnerHome);
  const plannedTogether = filterOverlapsByTense(computeSameCountryOverlaps(myVisits, partnerPlanned), 'future');

  // Trip-vs-trip overlaps (both sides have a logged visit to the same
  // city) — misses the case where one side just LIVES there, which has no
  // countries_visited row of its own to compare against. That's a
  // one-sided check via findVisitsToCity (same helper the Summary
  // notification uses), and it has to run in BOTH directions: partner
  // traveling to my home city, AND me traveling to partner's home city.
  // An earlier version only checked the first direction, so this section
  // only ever showed up for whichever of the two of us the city belonged
  // to — the traveler on the other side never saw it on their own
  // connection page, even though it's the same overlap from either side.
  const tripOverlapCities = filterCityOverlapsByTense(computeSameCityOverlaps(myVisits, partnerPlanned), 'future');
  const coveredKeys = new Set(tripOverlapCities.map((o) => `${o.country}|${o.city.toLowerCase()}`));
  const partnerComingToMyCity = myHomeCity ? findVisitsToCity(partnerPlanned, myHomeCity) : [];
  const meGoingToPartnerCity = partnerHomeCity ? findVisitsToCity(myVisits, partnerHomeCity) : [];
  const oneSidedVisits = [...partnerComingToMyCity, ...meGoingToPartnerCity];
  const oneSidedRangesByKey = new Map<string, CityOverlap['ranges']>();
  const oneSidedLabelByKey = new Map<string, { country: string; city: string }>();
  for (const visit of oneSidedVisits) {
    if (!visit.city) continue;
    const key = `${visit.country}|${visit.city.toLowerCase()}`;
    if (coveredKeys.has(key)) continue;
    const ranges = oneSidedRangesByKey.get(key) ?? [];
    ranges.push({ start: visit.entry_date, end: visit.exit_date, isPast: false });
    oneSidedRangesByKey.set(key, ranges);
    oneSidedLabelByKey.set(key, { country: visit.country, city: visit.city });
  }
  const oneSidedOverlaps: CityOverlap[] = Array.from(oneSidedRangesByKey.entries()).map(([key, ranges]) => ({
    ...oneSidedLabelByKey.get(key)!,
    ranges,
  }));
  // A country already showing up in "Planned together" above is, in
  // practice, the same joint trip — if you're both headed to the same
  // country at overlapping times, you're headed to the same city too, so
  // repeating it down here just duplicates the exact same card. "Same
  // city" is for cases "Planned together" doesn't already cover: the
  // one-sided "they're coming to where I live" kind of match.
  const plannedTogetherCountries = new Set(plannedTogether.map((o) => o.country));
  const sameCityPlanned = [...tripOverlapCities, ...oneSidedOverlaps].filter(
    (o) => !plannedTogetherCountries.has(o.country)
  );

  // A raw date/country overlap is just a signal — shared_trip_notes (and
  // any attached document) additionally requires an ACCEPTED row here for
  // that country, enforced at the RLS layer too (see 052_trip_plan_requests.sql),
  // not just this UI gate. share_trips_planned only controls whether the
  // overlap cards below show up at all; this controls whether tapping one
  // reaches notes/docs.
  const planByCountry = new Map(planRequests.map((p) => [p.country, p]));

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel
        connections={swipeConnections}
        isLoading={isConnectionsLoading}
        accentColor={ACCENT}
        activeConnectionId={connectionId}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }} numberOfLines={1} adjustsFontSizeToFit>
            {myName ?? 'You'} and {partnerLabel} Travel
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        <SharedModuleNav connectionId={connectionId} accentColor={ACCENT} active="travel" />
        <ScrollView
          contentContainerStyle={styles.content}
          refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
          {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
          {display.error ? <ThemedText style={styles.error}>{display.error}</ThemedText> : null}

          {canShowCountries || canShowTrips ? (
            <ThemedView style={styles.toggleRow}>
              {canShowCountries ? (
                <Pressable
                  onPress={() => setTab('countries')}
                  style={[styles.chip, { borderColor: ACCENT }, tab === 'countries' ? { backgroundColor: ACCENT } : null]}>
                  <ThemedText style={tab === 'countries' ? styles.chipTextActive : undefined}>
                    Countries visited
                  </ThemedText>
                </Pressable>
              ) : null}
              {canShowTrips ? (
                <Pressable
                  onPress={() => setTab('trips')}
                  style={[styles.chip, { borderColor: ACCENT }, tab === 'trips' ? { backgroundColor: ACCENT } : null]}>
                  <ThemedText style={tab === 'trips' ? styles.chipTextActive : undefined}>Trips planned</ThemedText>
                </Pressable>
              ) : null}
            </ThemedView>
          ) : (
            <ThemedText style={styles.muted}>
              Nothing shared yet. Enable a module for this connection in sharing settings.
            </ThemedText>
          )}

          {tab === 'countries' ? (
            <>
              <ThemedView style={styles.legendRow}>
                <ThemedText type="defaultSemiBold">You</ThemedText>
                <ThemedText type="defaultSemiBold">{partnerLabel}</ThemedText>
              </ThemedView>

              {countryRows.length === 0 ? <ThemedText style={styles.muted}>Nothing to show yet.</ThemedText> : null}
              {countryRows.map((row) => (
                <Surface key={row.country} accentColor={ACCENT} style={styles.card}>
                  <ThemedView style={styles.cardHeader}>
                    <CountryFlag countryName={row.country} hiddenFlagCountries={hiddenFlagCountries} size={24} />
                    <ThemedText type="defaultSemiBold">{row.country}</ThemedText>
                  </ThemedView>
                  <ThemedView style={styles.splitRow}>
                    <ThemedView style={styles.splitHalf}>
                      {row.mine ? (
                        <>
                          <ThemedText type="mono" style={styles.splitValue}>
                            {row.mine.daysUsed} days
                          </ThemedText>
                          <ThemedText style={[styles.splitCaption, row.mine.overLimit ? styles.overLimit : styles.muted]}>
                            {row.mine.daysRemaining} remaining
                          </ThemedText>
                        </>
                      ) : (
                        <ThemedText style={styles.muted}>Not visited</ThemedText>
                      )}
                    </ThemedView>
                    <ThemedView style={styles.splitDivider} />
                    <ThemedView style={styles.splitHalf}>
                      {row.partner ? (
                        <>
                          <ThemedText type="mono" style={styles.splitValue}>
                            {row.partner.daysUsed} days
                          </ThemedText>
                          <ThemedText
                            style={[styles.splitCaption, row.partner.overLimit ? styles.overLimit : styles.muted]}>
                            {row.partner.daysRemaining} remaining
                          </ThemedText>
                        </>
                      ) : (
                        <ThemedText style={styles.muted}>Not visited</ThemedText>
                      )}
                    </ThemedView>
                  </ThemedView>
                </Surface>
              ))}

              <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
                Traveled together
              </ThemedText>
              {traveledTogether.length === 0 ? (
                <ThemedText style={styles.muted}>No overlapping trips to the same country yet.</ThemedText>
              ) : null}
              {traveledTogether.map((overlap) => (
                <Pressable
                  key={overlap.country}
                  onPress={() =>
                    router.push(`/connections/${connectionId}/trip-notes?country=${encodeURIComponent(overlap.country)}`)
                  }>
                  <Surface accentColor={ACCENT} style={styles.card}>
                    <ThemedView style={styles.cardHeader}>
                      <CountryFlag countryName={overlap.country} hiddenFlagCountries={hiddenFlagCountries} size={24} />
                      <ThemedText type="defaultSemiBold">{overlap.country}</ThemedText>
                      <IconSymbol name="chevron.right" size={16} color={ACCENT} style={styles.chevron} />
                    </ThemedView>
                    {overlap.ranges.map((range, index) => (
                      <ThemedText key={index} type="mono" style={styles.muted}>
                        {formatDateDisplay(range.start)} → {formatDateDisplay(range.end)}
                      </ThemedText>
                    ))}
                    <ThemedText style={styles.notesHint}>Tap for shared planning notes</ThemedText>
                  </Surface>
                </Pressable>
              ))}
            </>
          ) : tab === 'trips' ? (
            <>
              {!myColor ? (
                <ThemedText style={styles.hint}>
                  You haven&apos;t set a calendar color yet. Tap the settings icon from the swipe panel to pick one for
                  a clearer view.
                </ThemedText>
              ) : null}

              <ThemedView style={styles.legendRow}>
                <ThemedView style={styles.legendItem}>
                  <ThemedView style={[styles.swatch, { backgroundColor: resolvedMyColor }]} />
                  <ThemedText style={styles.muted}>You</ThemedText>
                </ThemedView>
                <ThemedView style={styles.legendItem}>
                  <ThemedView style={[styles.swatch, { backgroundColor: resolvedPartnerColor }]} />
                  <ThemedText style={styles.muted}>{partnerLabel}</ThemedText>
                </ThemedView>
              </ThemedView>

              <ThemedView style={styles.toggleRow}>
                <Pressable
                  onPress={() => setChartMode('calendar')}
                  style={[styles.chip, { borderColor: ACCENT }, chartMode === 'calendar' ? { backgroundColor: ACCENT } : null]}>
                  <ThemedText style={chartMode === 'calendar' ? styles.chipTextActive : undefined}>Calendar</ThemedText>
                </Pressable>
                <Pressable
                  onPress={() => setChartMode('venn')}
                  style={[styles.chip, { borderColor: ACCENT }, chartMode === 'venn' ? { backgroundColor: ACCENT } : null]}>
                  <ThemedText style={chartMode === 'venn' ? styles.chipTextActive : undefined}>Venn diagram</ThemedText>
                </Pressable>
              </ThemedView>

              {chartMode === 'calendar' ? (
                <ThemedView style={styles.toggleRow}>
                  <Pressable
                    onPress={() => setViewMode('month')}
                    style={[styles.chip, { borderColor: ACCENT }, viewMode === 'month' ? { backgroundColor: ACCENT } : null]}>
                    <ThemedText style={viewMode === 'month' ? styles.chipTextActive : undefined}>Month</ThemedText>
                  </Pressable>
                  <Pressable
                    onPress={() => setViewMode('week')}
                    style={[styles.chip, { borderColor: ACCENT }, viewMode === 'week' ? { backgroundColor: ACCENT } : null]}>
                    <ThemedText style={viewMode === 'week' ? styles.chipTextActive : undefined}>Week</ThemedText>
                  </Pressable>
                </ThemedView>
              ) : (
                <ThemedView style={styles.toggleRow}>
                  <Pressable
                    onPress={() => setVennRangeMode('week')}
                    style={[styles.chip, { borderColor: ACCENT }, vennRangeMode === 'week' ? { backgroundColor: ACCENT } : null]}>
                    <ThemedText style={vennRangeMode === 'week' ? styles.chipTextActive : undefined}>Week</ThemedText>
                  </Pressable>
                  <Pressable
                    onPress={() => setVennRangeMode('month')}
                    style={[styles.chip, { borderColor: ACCENT }, vennRangeMode === 'month' ? { backgroundColor: ACCENT } : null]}>
                    <ThemedText style={vennRangeMode === 'month' ? styles.chipTextActive : undefined}>Month</ThemedText>
                  </Pressable>
                  <Pressable
                    onPress={() => setVennRangeMode('year')}
                    style={[styles.chip, { borderColor: ACCENT }, vennRangeMode === 'year' ? { backgroundColor: ACCENT } : null]}>
                    <ThemedText style={vennRangeMode === 'year' ? styles.chipTextActive : undefined}>Year</ThemedText>
                  </Pressable>
                </ThemedView>
              )}

              <ThemedView style={styles.navRow}>
                <Pressable onPress={goPrev} hitSlop={12}>
                  <ThemedText type="link">←</ThemedText>
                </Pressable>
                <Pressable onPress={goToday}>
                  <ThemedText type="defaultSemiBold">{rangeLabel}</ThemedText>
                </Pressable>
                {effectiveRangeMode === 'month' ? (
                  <MonthYearJump
                    value={currentDate}
                    onChange={setCurrentDate}
                    accentColor={ACCENT}
                    renderTrigger={(open) => (
                      <Pressable onPress={open} hitSlop={10}>
                        <IconSymbol name="calendar" size={16} color={ACCENT} />
                      </Pressable>
                    )}
                  />
                ) : null}
                <Pressable onPress={goNext} hitSlop={12}>
                  <ThemedText type="link">→</ThemedText>
                </Pressable>
              </ThemedView>

              {chartMode === 'calendar' ? (
                <TripCalendarGrid
                  currentDate={currentDate}
                  viewMode={viewMode}
                  myTrips={myVisits}
                  partnerTrips={partnerPlanned}
                  myColor={resolvedMyColor}
                  partnerColor={resolvedPartnerColor}
                  myHome={myHome}
                  partnerHome={partnerHome}
                />
              ) : (
                <TripVennDiagram
                  buckets={buckets}
                  myColor={resolvedMyColor}
                  partnerColor={resolvedPartnerColor}
                  myLabel="You"
                  partnerLabel={partnerLabel}
                />
              )}

              <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
                Planned together
              </ThemedText>
              {plannedTogether.length === 0 ? (
                <ThemedText style={styles.muted}>No overlapping future trips to the same country yet.</ThemedText>
              ) : null}
              {plannedTogether.map((overlap) => {
                const plan = planByCountry.get(overlap.country);
                return (
                  <PlanTogetherCard
                    key={overlap.country}
                    country={overlap.country}
                    plan={plan}
                    myId={session?.user.id ?? ''}
                    partnerLabel={partnerLabel}
                    busy={planBusy !== null}
                    onPropose={handleProposePlan}
                    onRespond={handleRespondPlan}
                    accentColor={ACCENT}
                    onPressAccepted={() =>
                      router.push(`/connections/${connectionId}/trip-notes?country=${encodeURIComponent(overlap.country)}`)
                    }>
                    <ThemedView style={styles.cardHeader}>
                      <CountryFlag countryName={overlap.country} hiddenFlagCountries={hiddenFlagCountries} size={24} />
                      <ThemedText type="defaultSemiBold">{overlap.country}</ThemedText>
                      {plan?.status === 'accepted' ? (
                        <IconSymbol name="chevron.right" size={16} color={ACCENT} style={styles.chevron} />
                      ) : null}
                    </ThemedView>
                    {overlap.ranges.map((range, index) => (
                      <ThemedText key={index} type="mono" style={styles.muted}>
                        {formatDateDisplay(range.start)} → {formatDateDisplay(range.end)}
                      </ThemedText>
                    ))}
                  </PlanTogetherCard>
                );
              })}

              {sameCityPlanned.length > 0 ? (
                <>
                  <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
                    Same city
                  </ThemedText>
                  {sameCityPlanned.map((overlap) => {
                    const plan = planByCountry.get(overlap.country);
                    return (
                      <PlanTogetherCard
                        key={`${overlap.country}-${overlap.city}`}
                        country={overlap.country}
                        plan={plan}
                        myId={session?.user.id ?? ''}
                        partnerLabel={partnerLabel}
                        busy={planBusy !== null}
                        onPropose={handleProposePlan}
                        onRespond={handleRespondPlan}
                        accentColor={ACCENT}
                        onPressAccepted={() =>
                          router.push(
                            `/connections/${connectionId}/trip-notes?country=${encodeURIComponent(overlap.country)}`
                          )
                        }>
                        <ThemedView style={styles.cardHeader}>
                          <CountryFlag countryName={overlap.country} hiddenFlagCountries={hiddenFlagCountries} size={24} />
                          <ThemedText type="defaultSemiBold">
                            {overlap.city}, {overlap.country}
                          </ThemedText>
                          {plan?.status === 'accepted' ? (
                            <IconSymbol name="chevron.right" size={16} color={ACCENT} style={styles.chevron} />
                          ) : null}
                        </ThemedView>
                        {overlap.ranges.map((range, index) => (
                          <ThemedText key={index} type="mono" style={styles.muted}>
                            {formatDateDisplay(range.start)} → {formatDateDisplay(range.end)}
                          </ThemedText>
                        ))}
                      </PlanTogetherCard>
                    );
                  })}
                </>
              ) : null}
            </>
          ) : null}
        </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

