import { FlagIcon } from '@/components/flag-icon';
import { ThemedText } from '@/components/themed-text';
import { NEUTRAL_FLAG_ICON, flagCodeForCountry } from '@/lib/countries';

/**
 * Convenience wrapper around FlagIcon for the common case: given a country
 * NAME (not a code) plus the viewer's hidden-flags list, render the right
 * thing — the neutral globe marker if hidden, the real flag if not, or
 * nothing if the name isn't in lib/countries.ts's COUNTRIES at all. This is
 * what every screen should use; FlagIcon itself is the lower-level
 * code-only renderer.
 */
export function CountryFlag({
  countryName,
  hiddenFlagCountries = [],
  size = 24,
}: {
  countryName: string;
  hiddenFlagCountries?: readonly string[];
  size?: number;
}) {
  if (hiddenFlagCountries.includes(countryName)) {
    return <ThemedText style={{ fontSize: size * 0.85 }}>{NEUTRAL_FLAG_ICON}</ThemedText>;
  }
  const code = flagCodeForCountry(countryName);
  if (!code) return null;
  return <FlagIcon code={code} size={size} />;
}
