import { useRouter } from 'expo-router';
import { useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { PasswordInput } from '@/components/password-input';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { supabase } from '@/lib/supabase';

const TINT = Colors.light.tint;

export default function ChangePasswordScreen() {
  const router = useRouter();
  const { session, resetPasswordForEmail } = useAuth();

  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);
  const [isSendingReset, setIsSendingReset] = useState(false);
  const [resetSent, setResetSent] = useState(false);

  // For someone who's still signed in but can't remember their CURRENT
  // password (the field handleSave verifies against) — sends the same
  // reset-link email the signed-out /login "Forgot password?" flow uses,
  // via the already-known session email, so they don't need to sign out
  // first just to reach that flow.
  async function handleForgotPassword() {
    if (!session?.user.email) return;
    setError(null);
    setResetSent(false);
    setIsSendingReset(true);
    const result = await resetPasswordForEmail(session.user.email);
    setIsSendingReset(false);
    if (result.error) {
      setError(result.error);
      return;
    }
    setResetSent(true);
  }

  async function handleSave() {
    setSuccess(false);
    if (!currentPassword || !newPassword || !confirmPassword) {
      setError('Fill in all three fields.');
      return;
    }
    if (newPassword !== confirmPassword) {
      setError('New password and confirmation do not match.');
      return;
    }
    if (newPassword.length < 6) {
      setError('New password must be at least 6 characters.');
      return;
    }
    if (!session?.user.email) {
      setError('No signed-in user.');
      return;
    }

    setError(null);
    setIsSaving(true);

    // Verifies the current password by actually re-authenticating with it —
    // Supabase has no separate "check this password" call, and updateUser()
    // alone would happily accept any current session without checking it.
    const { error: verifyError } = await supabase.auth.signInWithPassword({
      email: session.user.email,
      password: currentPassword,
    });
    if (verifyError) {
      setIsSaving(false);
      setError('Current password is incorrect.');
      return;
    }

    const { error: updateError } = await supabase.auth.updateUser({ password: newPassword });
    setIsSaving(false);

    if (updateError) {
      setError(updateError.message);
      return;
    }

    setCurrentPassword('');
    setNewPassword('');
    setConfirmPassword('');
    setSuccess(true);
  }

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ScrollView contentContainerStyle={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: TINT }}>
            Change Password
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
        {success ? <ThemedText style={styles.success}>Password updated.</ThemedText> : null}
        {resetSent ? (
          <ThemedText style={styles.success}>Check your email for a reset link.</ThemedText>
        ) : null}

        <ThemedText type="defaultSemiBold">Current password</ThemedText>
        <PasswordInput
          value={currentPassword}
          onChangeText={setCurrentPassword}
          placeholder="Current password"
          accentColor={TINT}
          style={styles.input}
        />
        <Pressable onPress={handleForgotPassword} disabled={isSendingReset} hitSlop={8} style={styles.forgotButton}>
          <ThemedText type="link" style={styles.forgotText}>
            {isSendingReset ? 'Sending...' : 'Forgot your current password?'}
          </ThemedText>
        </Pressable>

        <ThemedText type="defaultSemiBold">New password</ThemedText>
        <PasswordInput
          value={newPassword}
          onChangeText={setNewPassword}
          autoComplete="new-password"
          placeholder="At least 6 characters"
          accentColor={TINT}
          style={styles.input}
        />

        <ThemedText type="defaultSemiBold">Confirm new password</ThemedText>
        <PasswordInput
          value={confirmPassword}
          onChangeText={setConfirmPassword}
          autoComplete="new-password"
          placeholder="Repeat new password"
          accentColor={TINT}
          style={styles.input}
        />

        <Pressable onPress={handleSave} disabled={isSaving} style={[styles.button, { backgroundColor: TINT }]}>
          {isSaving ? (
            <ActivityIndicator color={Colors.light.backgroundSolid} />
          ) : (
            <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Save</ThemedText>
          )}
        </Pressable>
      </ScrollView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  forgotButton: {
    alignItems: 'flex-end',
    marginBottom: 4,
  },
  forgotText: {
    fontSize: 13,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  error: {
    color: Colors.light.negative,
  },
  success: {
    color: Colors.light.positive,
  },
});
