import { useFocusEffect } from '@react-navigation/native';
import { Link } from 'expo-router';
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet } from 'react-native';

import { CandlestickChart } from '@/components/candlestick-chart';
import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { DateInput } from '@/components/date-input';
import { ScopeSwitch } from '@/components/scope-switch';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useScope } from '@/contexts/scope-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { formatMoney } from '@/lib/currency';
import { fetchAllRows } from '@/lib/fetchAll';
import { formatDateDisplay } from '@/lib/format';
import { computeLiquidityBreakdown } from '@/lib/liquidity';
import { supabase } from '@/lib/supabase';
import { resolveWealthCurrency } from '@/lib/wealthCurrency';
import { computeWealthSeries, generatePeriods, generatePeriodsInRange, type Period } from '@/lib/wealthSeries';
import type { AccountRow, BalanceSnapshotRow, TransactionRow } from '@/types/database';

const ACCENT = ModuleAccents.wealth;

type Granularity = 'week' | 'month' | 'custom';

const GRANULARITY_OPTIONS: { value: Granularity; label: string }[] = [
  { value: 'week', label: 'Week' },
  { value: 'month', label: 'Month' },
  { value: 'custom', label: 'Custom' },
];

export default function WealthScreen() {
  const { displayCurrency, homeCountry, availableCurrencies, convertToCurrency } = useCurrency();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const [granularity, setGranularity] = useState<Granularity>('month');
  const [customStart, setCustomStart] = useState(() => {
    const d = new Date();
    d.setDate(d.getDate() - 30);
    return d;
  });
  const [customEnd, setCustomEnd] = useState(new Date());

  const { filterTransactions, filterAccounts, filterSnapshots } = useScope();
  const [allTransactions, setTransactions] = useState<TransactionRow[]>([]);
  const [allAccounts, setAccounts] = useState<AccountRow[]>([]);
  const [allSnapshots, setSnapshots] = useState<BalanceSnapshotRow[]>([]);
  const transactions = filterTransactions(allTransactions);
  const accounts = filterAccounts(allAccounts);
  const snapshots = filterSnapshots(allSnapshots);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [txResult, accountsResult, snapshotsResult] = await Promise.all([
      fetchAllRows<TransactionRow>((from, to) =>
        supabase.from('transactions').select('*').order('date').order('id').range(from, to)
      ),
      supabase.from('accounts').select('*'),
      fetchAllRows<BalanceSnapshotRow>((from, to) =>
        supabase.from('balance_snapshots').select('*').order('date').order('id').range(from, to)
      ),
    ]);

    if (txResult.error) {
      setError(txResult.error.message);
      setIsLoading(false);
      return;
    }

    setTransactions(txResult.data);
    setAccounts(accountsResult.data ?? []);
    setSnapshots(snapshotsResult.data);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  useEffect(() => {
    setSelectedIndex(null);
  }, [granularity]);

  const wealthCurrency = resolveWealthCurrency(displayCurrency, homeCountry, availableCurrencies);

  const periods: Period[] =
    granularity === 'custom' ? generatePeriodsInRange(customStart, customEnd) : generatePeriods(granularity, 12);

  const candles = isLoading
    ? []
    : computeWealthSeries({
        transactions,
        accounts,
        balanceSnapshots: snapshots,
        periods,
        convert: (amount, fromCurrency) => convertToCurrency(amount, fromCurrency, wealthCurrency.currency),
      });

  const effectiveIndex = selectedIndex ?? candles.length - 1;
  const selected = candles[effectiveIndex] ?? null;

  const liquidity = isLoading
    ? null
    : computeLiquidityBreakdown({
        accounts,
        transactions,
        balanceSnapshots: snapshots,
        convert: (amount, fromCurrency) => convertToCurrency(amount, fromCurrency, wealthCurrency.currency),
      });

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView contentContainerStyle={styles.content}>
        <ScopeSwitch accent={ACCENT} onColor={ModuleAccentOnColor.wealth} />
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Wealth
          </ThemedText>
          <Link href="/wealth/currency-exposure">
            <ThemedText type="link">Currency exposure</ThemedText>
          </Link>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <ThemedView style={styles.chipRow}>
          {GRANULARITY_OPTIONS.map((option) => {
            const isSelected = option.value === granularity;
            return (
              <Pressable
                key={option.value}
                onPress={() => setGranularity(option.value)}
                style={[
                  styles.chip,
                  { borderColor: ACCENT, backgroundColor: isSelected ? ACCENT : 'transparent' },
                ]}>
                <ThemedText style={isSelected ? { color: ModuleAccentOnColor.wealth } : undefined}>
                  {option.label}
                </ThemedText>
              </Pressable>
            );
          })}
        </ThemedView>

        {granularity === 'custom' ? (
          <ThemedView style={styles.customRow}>
            <DateInput
              value={customStart}
              onChange={(date) => {
                setCustomStart(date);
                // Keep the invariant (end never before start) when start moves past the current end, not just when picking end.
                if (customEnd < date) setCustomEnd(date);
              }}
              accentColor={ACCENT}
            />
            <ThemedText>&rarr;</ThemedText>
            <DateInput value={customEnd} onChange={setCustomEnd} accentColor={ACCENT} minimumDate={customStart} />
          </ThemedView>
        ) : null}

        {isLoading ? (
          <ActivityIndicator style={styles.loading} color={ACCENT} />
        ) : candles.length === 0 ? (
          <ThemedText style={styles.muted}>No data yet.</ThemedText>
        ) : (
          <>
            <ThemedView style={styles.chartCard}>
              <CandlestickChart
                candles={candles}
                selectedIndex={effectiveIndex}
                onSelectCandle={setSelectedIndex}
                currency={wealthCurrency.currency}
              />
            </ThemedView>

            {wealthCurrency.source !== 'display' ? (
              <ThemedText style={styles.muted}>
                {wealthCurrency.source === 'home-country'
                  ? `Showing in ${wealthCurrency.currency} (from your home country)`
                  : `Showing in ${wealthCurrency.currency} (default, `}
                {wealthCurrency.source === 'default' ? (
                  <Link href="/account">
                    <ThemedText type="link" style={styles.muted}>
                      set your home country in Account settings
                    </ThemedText>
                  </Link>
                ) : null}
                {wealthCurrency.source === 'default' ? ')' : null}
              </ThemedText>
            ) : null}

            {selected ? (
              <Surface accentColor={ACCENT}>
                <ThemedText type="defaultSemiBold">
                  {formatDateDisplay(selected.periodStart)} &rarr; {formatDateDisplay(selected.periodEnd)}
                </ThemedText>
                <ThemedView style={styles.breakdownRow}>
                  <ThemedText style={styles.muted}>Starting position</ThemedText>
                  <ThemedText type="mono">{formatMoney(selected.open, wealthCurrency.currency)}</ThemedText>
                </ThemedView>
                <ThemedView style={styles.breakdownRow}>
                  <ThemedText style={styles.muted}>Income</ThemedText>
                  <ThemedText type="mono">{formatMoney(selected.income, wealthCurrency.currency)}</ThemedText>
                </ThemedView>
                <ThemedView style={styles.breakdownRow}>
                  <ThemedText style={styles.muted}>Spend</ThemedText>
                  <ThemedText type="mono">{formatMoney(selected.spend, wealthCurrency.currency)}</ThemedText>
                </ThemedView>
                <ThemedView style={styles.breakdownRow}>
                  <ThemedText style={styles.muted}>Net change</ThemedText>
                  <ThemedText type="mono" style={selected.net >= 0 ? styles.positive : styles.negative}>
                    {formatMoney(selected.net, wealthCurrency.currency)}
                  </ThemedText>
                </ThemedView>
                <ThemedView style={[styles.breakdownRow, styles.endingRow]}>
                  <ThemedText type="defaultSemiBold">Ending position</ThemedText>
                  <ThemedText type="mono" style={{ fontWeight: '600' }}>
                    {formatMoney(selected.close, wealthCurrency.currency)}
                  </ThemedText>
                </ThemedView>
              </Surface>
            ) : null}

            {liquidity ? (
              <Surface accentColor={ACCENT}>
                <ThemedText type="defaultSemiBold">Liquidity (today)</ThemedText>
                <ThemedText style={styles.muted}>
                  Investments and real estate count as illiquid, so unrealized gains don&apos;t skew what&apos;s
                  actually spendable right now.
                </ThemedText>
                <ThemedView style={styles.breakdownRow}>
                  <ThemedText style={styles.muted}>Liquid</ThemedText>
                  <ThemedText type="mono">{formatMoney(liquidity.liquidNetWorth, wealthCurrency.currency)}</ThemedText>
                </ThemedView>
                <ThemedView style={styles.breakdownRow}>
                  <ThemedText style={styles.muted}>Illiquid</ThemedText>
                  <ThemedText type="mono">{formatMoney(liquidity.illiquidNetWorth, wealthCurrency.currency)}</ThemedText>
                </ThemedView>
              </Surface>
            ) : null}
          </>
        )}
      </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 12,
    paddingBottom: 48,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  chipRow: {
    flexDirection: 'row',
    gap: 8,
  },
  chip: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 16,
    paddingHorizontal: 16,
    paddingVertical: 8,
  },
  customRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
  },
  dateInput: {
    flex: 1,
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
  },
  chartCard: {
    borderWidth: StyleSheet.hairlineWidth,
    borderColor: 'transparent',
  },
  breakdownRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
  },
  endingRow: {
    marginTop: 4,
    paddingTop: 8,
    borderTopWidth: StyleSheet.hairlineWidth,
    borderTopColor: Colors.light.cardBorder,
  },
  positive: {
    color: Colors.light.positive,
  },
  negative: {
    color: Colors.light.negative,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  loading: {
    marginTop: 32,
  },
  error: {
    color: Colors.light.negative,
  },
});
