import DateTimePicker from '@react-native-community/datetimepicker';
import { useState } from 'react';
import { Platform, Pressable, StyleSheet } from 'react-native';

import { ThemedText } from '@/components/themed-text';
import { formatTimeDisplay } from '@/lib/format';
import type { TimeInputProps } from './time-input-types';

function parseTimeString(time: string): Date {
  const [hours, minutes] = time.split(':').map(Number);
  const d = new Date();
  d.setHours(hours, minutes, 0, 0);
  return d;
}

/**
 * Calendar-popup time picker, mirroring components/date-input.tsx exactly
 * (same library, same cross-platform split — see that file for why a web
 * counterpart exists at all). Only the time-of-day ever crosses this
 * component's boundary as a value; the Date object DateTimePicker requires
 * is just a throwaway carrier for today's date, never read.
 */
export function TimeInput({ value, onChange, accentColor, placeholder = 'Select a time' }: TimeInputProps) {
  const [showPicker, setShowPicker] = useState(false);

  return (
    <>
      <Pressable onPress={() => setShowPicker(true)} style={[styles.input, { borderColor: accentColor }]}>
        <ThemedText type="mono">{value ? formatTimeDisplay(value) : placeholder}</ThemedText>
      </Pressable>
      {showPicker ? (
        <DateTimePicker
          value={value ? parseTimeString(value) : new Date()}
          mode="time"
          display={Platform.OS === 'ios' ? 'spinner' : 'default'}
          onChange={(_event, date) => {
            setShowPicker(false);
            if (date) {
              const hh = String(date.getHours()).padStart(2, '0');
              const mm = String(date.getMinutes()).padStart(2, '0');
              onChange(`${hh}:${mm}`);
            }
          }}
        />
      ) : null}
    </>
  );
}

const styles = StyleSheet.create({
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
});
