import { useFocusEffect } from '@react-navigation/native';
import { Link, useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { TransactionCategoryFilter } from '@/components/transaction-category-filter';
import { TransactionRow as TransactionRowItem } from '@/components/transaction-row';
import { TransactionSortControl } from '@/components/transaction-sort-control';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { formatMoney } from '@/lib/currency';
import { fetchAllRows } from '@/lib/fetchAll';
import { formatDateDisplay } from '@/lib/format';
import { summarizeSpendByCategory } from '@/lib/spend';
import { supabase } from '@/lib/supabase';
import { filterByCategory, type TransactionCategoryFilterValue } from '@/lib/transactionFilter';
import { sortTransactions, type TransactionSortDirection, type TransactionSortField } from '@/lib/transactionSort';
import type {
  AccountRow,
  CategoryRow,
  CategoryRuleRow,
  CountryVisitedRow,
  CreditCardRow,
  LoyaltyAccountRow,
  TransactionRow,
} from '@/types/database';

const ACCENT = ModuleAccents.cards;
// Card-linked transactions never have an account_id, so account-level
// country-tracking exclusion never applies here.
const EMPTY_ACCOUNT_IDS = new Set<string>();

export default function CardDetailScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const router = useRouter();
  const { convert, homeCountry } = useCurrency();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();

  const [card, setCard] = useState<CreditCardRow | null>(null);
  const [paymentAccount, setPaymentAccount] = useState<AccountRow | null>(null);
  const [points, setPoints] = useState<LoyaltyAccountRow[]>([]);
  const [transactions, setTransactions] = useState<TransactionRow[]>([]);
  const [categories, setCategories] = useState<CategoryRow[]>([]);
  const [categoryRules, setCategoryRules] = useState<CategoryRuleRow[]>([]);
  const [visits, setVisits] = useState<CountryVisitedRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<TransactionSortField>('date');
  const [sortDirection, setSortDirection] = useState<TransactionSortDirection>('desc');
  const [categoryFilter, setCategoryFilter] = useState<TransactionCategoryFilterValue>('all');

  const load = useCallback(async () => {
    setError(null);
    const [cardResult, pointsResult, transactionsResult, categoriesResult, categoryRulesResult, visitsResult] =
      await Promise.all([
        supabase.from('credit_cards').select('*').eq('id', id).single(),
        supabase.from('loyalty_accounts').select('*').eq('card_id', id),
        fetchAllRows<TransactionRow>((from, to) =>
          supabase.from('transactions').select('*').eq('card_id', id).order('date', { ascending: false }).order('id').range(from, to)
        ),
        supabase.from('categories').select('*'),
        supabase.from('category_rules').select('*'),
        supabase.from('countries_visited').select('*'),
      ]);

    if (cardResult.error) {
      setError(cardResult.error.message);
    } else {
      setCard(cardResult.data);
    }
    if (cardResult.data?.payment_account_id) {
      const { data: accountData } = await supabase
        .from('accounts')
        .select('*')
        .eq('id', cardResult.data.payment_account_id)
        .maybeSingle();
      setPaymentAccount(accountData ?? null);
    } else {
      setPaymentAccount(null);
    }
    if (pointsResult.data) setPoints(pointsResult.data);
    if (transactionsResult.data) setTransactions(transactionsResult.data);
    if (categoriesResult.data) setCategories(categoriesResult.data);
    if (categoryRulesResult.data) setCategoryRules(categoryRulesResult.data);
    if (visitsResult.data) setVisits(visitsResult.data);
    setIsLoading(false);
  }, [id]);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  if (isLoading || !card) {
    return (
      <ThemedView variant="screen" style={[styles.flex, styles.centered]}>
        <ActivityIndicator color={ACCENT} />
      </ThemedView>
    );
  }

  const categoryNameById = new Map(categories.map((c) => [c.id, c.name]));
  const spendByCategory = summarizeSpendByCategory(transactions, categoryNameById, convert);
  const fee = convert(card.annual_fee, card.fee_currency);
  const sortedTransactions = sortTransactions(
    filterByCategory(transactions, categoryRules, categoryFilter),
    sortField,
    sortDirection
  );

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel connections={swipeConnections} isLoading={isConnectionsLoading} accentColor={ACCENT}>
      <ScrollView
        contentContainerStyle={styles.content}
        refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            {card.name}
          </ThemedText>
          <Pressable onPress={() => router.push(`/cards/${id}/edit`)} hitSlop={12}>
            <ThemedText type="link">Edit</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        <Surface accentColor={ACCENT}>
          <ThemedText type="defaultSemiBold">
            {card.issuer} · {card.name}
          </ThemedText>
          <ThemedText type="mono" style={styles.muted}>
            {formatMoney(fee.amount, fee.currency)}/yr
          </ThemedText>
          <ThemedText type="mono" style={styles.muted}>
            Renews {formatDateDisplay(card.renewal_date)}
          </ThemedText>
          {paymentAccount ? (
            <Pressable onPress={() => router.push(`/accounts/${paymentAccount.id}`)}>
              <ThemedText style={styles.muted}>Paid from {paymentAccount.name}</ThemedText>
            </Pressable>
          ) : (
            <ThemedText style={styles.muted}>No payment account set</ThemedText>
          )}
          {!card.is_active ? <ThemedText style={styles.flagged}>Inactive</ThemedText> : null}
        </Surface>

        <ThemedView style={styles.sectionHeader}>
          <ThemedText type="subtitle" style={{ color: ACCENT }}>
            Points
          </ThemedText>
          <Pressable onPress={() => router.push(`/cards/loyalty/new?cardId=${id}`)}>
            <ThemedText type="link">Add</ThemedText>
          </Pressable>
        </ThemedView>
        {points.length === 0 ? <ThemedText style={styles.muted}>No points programs tracked yet.</ThemedText> : null}
        {points.map((p) => (
          <Link key={p.id} href={`/cards/loyalty/${p.id}`} asChild>
            <Pressable>
              <Surface accentColor={ACCENT}>
                <ThemedText type="defaultSemiBold">{p.program}</ThemedText>
                <ThemedText type="mono" style={styles.muted}>
                  {p.balance.toLocaleString()} points
                </ThemedText>
              </Surface>
            </Pressable>
          </Link>
        ))}

        <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
          Spend by category
        </ThemedText>
        {spendByCategory.length === 0 ? (
          <ThemedText style={styles.muted}>No transactions yet.</ThemedText>
        ) : null}
        {spendByCategory.map((entry) => (
          <Surface key={entry.categoryId ?? 'uncategorized'} accentColor={ACCENT}>
            <ThemedText type="defaultSemiBold">{entry.categoryName}</ThemedText>
            <ThemedText type="mono" style={styles.muted}>
              {entry.totals.map((t) => formatMoney(t.amount, t.currency)).join(' · ')}
            </ThemedText>
          </Surface>
        ))}

        <ThemedView style={styles.sectionHeader}>
          <ThemedText type="subtitle" style={{ color: ACCENT }}>
            Transactions
          </ThemedText>
          <Pressable onPress={() => router.push(`/transactions/new?cardId=${id}`)}>
            <ThemedText type="link">Add</ThemedText>
          </Pressable>
        </ThemedView>
        <ThemedView style={styles.filterSortRow}>
          <TransactionCategoryFilter
            categories={categories}
            value={categoryFilter}
            onChange={setCategoryFilter}
            accentColor={ACCENT}
          />
          <TransactionSortControl
            sortField={sortField}
            sortDirection={sortDirection}
            onChange={(field, direction) => {
              setSortField(field);
              setSortDirection(direction);
            }}
            accentColor={ACCENT}
          />
        </ThemedView>
        {sortedTransactions.length === 0 ? <ThemedText style={styles.muted}>No transactions yet.</ThemedText> : null}
        {sortedTransactions.map((tx) => (
          <TransactionRowItem
            key={tx.id}
            transaction={tx}
            accentColor={ACCENT}
            convert={convert}
            categories={categories}
            categoryRules={categoryRules}
            visits={visits}
            homeCountry={homeCountry}
            excludedAccountIds={EMPTY_ACCOUNT_IDS}
            onChange={(updated) => setTransactions((prev) => prev.map((t) => (t.id === updated.id ? updated : t)))}
            onCategoryCreated={(category) => setCategories((prev) => [...prev, category])}
          />
        ))}
      </ScrollView>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  centered: { alignItems: 'center', justifyContent: 'center' },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  sectionHeader: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginTop: 16,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  filterSortRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    flexWrap: 'wrap',
    gap: 8,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  amount: {
    fontSize: 16,
  },
  flagged: {
    color: Colors.light.negative,
    fontSize: 14,
  },
  error: {
    color: Colors.light.negative,
  },
});
