import { useLocalSearchParams, useRouter } from 'expo-router';
import { useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, TextInput } from 'react-native';

import { SelectModal } from '@/components/select-modal';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Colors, ModuleAccents } from '@/constants/theme';
import { useAuth } from '@/contexts/auth-context';
import { supabase } from '@/lib/supabase';

const ACCENT = ModuleAccents.countries;

const ROLE_OPTIONS = [
  { value: 'full', label: 'Full: sees everything, gets their own synced copy' },
  { value: 'contributor', label: 'Contributor: sees the itinerary, can add documents' },
];

export default function InviteTripCollaboratorScreen() {
  const { tripId } = useLocalSearchParams<{ tripId: string }>();
  const router = useRouter();
  const { session } = useAuth();

  const [email, setEmail] = useState('');
  const [role, setRole] = useState<'full' | 'contributor'>('contributor');
  const [showRolePicker, setShowRolePicker] = useState(false);
  const [isSending, setIsSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  async function handleSend() {
    if (!session || !tripId) return;
    const trimmedEmail = email.trim();
    if (!trimmedEmail) {
      setError('Enter an email address.');
      return;
    }

    setError(null);
    setSuccess(false);
    setIsSending(true);
    const myId = session.user.id;

    const { data: otherId, error: lookupError } = await supabase.rpc('find_user_id_by_email', {
      p_email: trimmedEmail,
    });

    if (lookupError) {
      setIsSending(false);
      setError(lookupError.message);
      return;
    }
    if (!otherId) {
      setIsSending(false);
      setError('No Cluster user found with that email.');
      return;
    }
    if (otherId === myId) {
      setIsSending(false);
      setError('You can’t invite yourself.');
      return;
    }

    const { data: existing, error: existingError } = await supabase
      .from('trip_collaborators')
      .select('*')
      .eq('trip_id', tripId)
      .eq('collaborator_user_id', otherId)
      .maybeSingle();

    if (existingError) {
      setIsSending(false);
      setError(existingError.message);
      return;
    }

    if (existing) {
      if (existing.status === 'pending') {
        setIsSending(false);
        setError('An invite is already pending for this person.');
        return;
      }
      if (existing.status === 'accepted') {
        setIsSending(false);
        setError('This person is already collaborating on this trip.');
        return;
      }
      const { error: reopenError } = await supabase
        .from('trip_collaborators')
        .update({ role, status: 'pending', responded_at: null })
        .eq('id', existing.id);
      setIsSending(false);
      if (reopenError) {
        setError(reopenError.message);
        return;
      }
      setSuccess(true);
      setEmail('');
      return;
    }

    const { error: insertError } = await supabase
      .from('trip_collaborators')
      .insert({ trip_id: tripId, inviter_user_id: myId, collaborator_user_id: otherId, role });

    setIsSending(false);
    if (insertError) {
      setError(insertError.message);
      return;
    }
    setSuccess(true);
    setEmail('');
  }

  const roleLabel = ROLE_OPTIONS.find((o) => o.value === role)?.label ?? '';

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ThemedView style={styles.content}>
        <ThemedView style={styles.titleRow}>
          <ThemedText type="title" style={{ color: ACCENT }}>
            Invite a Collaborator
          </ThemedText>
          <Pressable onPress={() => router.back()} hitSlop={12}>
            <ThemedText type="link">Done</ThemedText>
          </Pressable>
        </ThemedView>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
        {success ? (
          <ThemedText style={styles.success}>Invite sent. They&apos;ll need to accept it before it takes effect.</ThemedText>
        ) : null}

        <ThemedText type="defaultSemiBold">Their email</ThemedText>
        <TextInput
          value={email}
          onChangeText={setEmail}
          autoCapitalize="none"
          autoCorrect={false}
          keyboardType="email-address"
          placeholder="friend@example.com"
          placeholderTextColor={Colors.light.textMuted}
          style={[styles.input, { color: Colors.light.text, borderColor: ACCENT }]}
        />

        <ThemedText type="defaultSemiBold">Role</ThemedText>
        <Pressable onPress={() => setShowRolePicker(true)} style={[styles.input, { borderColor: ACCENT }]}>
          <ThemedText>{roleLabel}</ThemedText>
        </Pressable>
        <SelectModal
          visible={showRolePicker}
          onClose={() => setShowRolePicker(false)}
          options={ROLE_OPTIONS}
          selectedValue={role}
          onSelect={(value) => setRole(value as 'full' | 'contributor')}
        />

        <Pressable onPress={handleSend} disabled={isSending} style={[styles.button, { backgroundColor: ACCENT }]}>
          {isSending ? (
            <ActivityIndicator color={Colors.light.backgroundSolid} />
          ) : (
            <ThemedText style={{ color: Colors.light.backgroundSolid, fontWeight: '600' }}>Send invite</ThemedText>
          )}
        </Pressable>
      </ThemedView>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 8,
  },
  input: {
    borderWidth: StyleSheet.hairlineWidth,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    fontSize: 16,
    marginBottom: 8,
  },
  button: {
    borderRadius: 8,
    paddingVertical: 16,
    alignItems: 'center',
    marginTop: 8,
  },
  error: {
    color: Colors.light.negative,
  },
  success: {
    color: Colors.light.positive,
  },
});
