import type { StyleSpecification } from '@maplibre/maplibre-gl-style-spec';
import { Camera, GeoJSONSource, Layer, Map as MapLibreMap } from '@maplibre/maplibre-react-native';
import { useEffect, useMemo, useState } from 'react';
import { StyleSheet, View, type NativeSyntheticEvent } from 'react-native';

import { loadMapStyle } from '@/lib/worldMapStyle';
import { arcLegPath, type RoutePoint } from '@/lib/tripRoute';

// See multi-trip-route-map.web.tsx's own comment — deliberately compact.
const MAP_HEIGHT = 180;
const DIMMED_OPACITY = 0.25;

export type TripOverlay = {
  tripId: string;
  name: string;
  dateRange: string;
  color: string;
  points: RoutePoint[];
};

function tripLegsGeoJSON(trips: TripOverlay[], selectedTripId: string | null) {
  return {
    type: 'FeatureCollection' as const,
    features: trips.flatMap((trip) =>
      trip.points.slice(0, -1).map((point, legIndex) => ({
        type: 'Feature' as const,
        properties: { tripId: trip.tripId, color: trip.color, dimmed: !!selectedTripId && selectedTripId !== trip.tripId },
        geometry: {
          type: 'LineString' as const,
          coordinates: arcLegPath(point, trip.points[legIndex + 1]).map((p) => [p.lon, p.lat]),
        },
      }))
    ),
  };
}

function tripStopsGeoJSON(trips: TripOverlay[], selectedTripId: string | null) {
  return {
    type: 'FeatureCollection' as const,
    features: trips.flatMap((trip) =>
      trip.points.map((point) => ({
        type: 'Feature' as const,
        properties: { tripId: trip.tripId, color: trip.color, dimmed: !!selectedTripId && selectedTripId !== trip.tripId },
        geometry: { type: 'Point' as const, coordinates: [point.lon, point.lat] },
      }))
    ),
  };
}

/**
 * Native counterpart to multi-trip-route-map.web.tsx — see that file for
 * the full reasoning (one color per trip, same MapLibre + OpenFreeMap
 * Positron engine as the Countries/Cities map instead of a different
 * raster-tile engine, so the passport screen's two tabs actually match).
 */
export function MultiTripRouteMap({
  trips,
  selectedTripId,
  onSelectTrip,
  height = MAP_HEIGHT,
}: {
  trips: TripOverlay[];
  selectedTripId: string | null;
  onSelectTrip: (tripId: string) => void;
  height?: number;
}) {
  const allPoints = useMemo(() => trips.flatMap((t) => t.points), [trips]);
  const legsData = useMemo(() => tripLegsGeoJSON(trips, selectedTripId), [trips, selectedTripId]);
  const stopsData = useMemo(() => tripStopsGeoJSON(trips, selectedTripId), [trips, selectedTripId]);
  const [mapStyle, setMapStyle] = useState<StyleSpecification | null>(null);
  useEffect(() => {
    let cancelled = false;
    loadMapStyle().then((loaded) => {
      if (!cancelled) setMapStyle(loaded);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  function handlePress(event: NativeSyntheticEvent<{ features: GeoJSON.Feature[] }>) {
    const tripId = event.nativeEvent.features[0]?.properties?.tripId as string | undefined;
    if (tripId) onSelectTrip(tripId);
  }

  if (!mapStyle) {
    return <View style={[styles.container, { height }]} />;
  }

  const initialViewState =
    allPoints.length > 1
      ? {
          bounds: [
            Math.min(...allPoints.map((p) => p.lon)),
            Math.min(...allPoints.map((p) => p.lat)),
            Math.max(...allPoints.map((p) => p.lon)),
            Math.max(...allPoints.map((p) => p.lat)),
          ] as [number, number, number, number],
          padding: { top: 24, bottom: 24, left: 24, right: 24 },
        }
      : { center: (allPoints.length === 1 ? [allPoints[0].lon, allPoints[0].lat] : [0, 20]) as [number, number], zoom: 4 };

  return (
    <View style={[styles.container, { height }]}>
      <MapLibreMap
        style={styles.map}
        mapStyle={mapStyle}
        compass={false}
        scaleBar={false}
        logo={false}
        dragPan={false}
        touchZoom={false}
        touchRotate={false}
        touchPitch={false}>
        <Camera initialViewState={initialViewState} />
        <GeoJSONSource id="trip-legs" data={legsData} onPress={handlePress}>
          <Layer
            id="trip-legs-line"
            type="line"
            layout={{ 'line-cap': 'round', 'line-join': 'round' }}
            paint={{
              'line-color': ['get', 'color'],
              'line-width': 4,
              'line-opacity': ['case', ['get', 'dimmed'], DIMMED_OPACITY, 1],
            }}
          />
        </GeoJSONSource>
        <GeoJSONSource id="trip-stops" data={stopsData} onPress={handlePress}>
          <Layer
            id="trip-stops-circle"
            type="circle"
            paint={{
              'circle-color': ['get', 'color'],
              'circle-radius': 5,
              'circle-stroke-width': 2,
              'circle-stroke-color': '#FBFBF9',
              'circle-opacity': ['case', ['get', 'dimmed'], DIMMED_OPACITY, 1],
              'circle-stroke-opacity': ['case', ['get', 'dimmed'], DIMMED_OPACITY, 1],
            }}
          />
        </GeoJSONSource>
      </MapLibreMap>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 12,
    overflow: 'hidden',
  },
  map: {
    flex: 1,
  },
});
