import { useFocusEffect } from '@react-navigation/native';
import { Link, useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { Pressable, RefreshControl, ScrollView, StyleSheet } from 'react-native';

import { AssetLiabilitySunburst, type SunburstAccount } from '@/components/asset-liability-sunburst';
import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { ScopeSwitch } from '@/components/scope-switch';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useScope } from '@/contexts/scope-context';
import { useTour } from '@/contexts/tour-context';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { latestSnapshotByAccount, transactionSumByAccount } from '@/lib/accountBalance';
import { formatMoney } from '@/lib/currency';
import { supabase } from '@/lib/supabase';
import { resolveWealthCurrency } from '@/lib/wealthCurrency';
import type { AccountRow } from '@/types/database';

const ACCENT = ModuleAccents.accounts;
const ASSETS_COLOR = ModuleAccents.wealth;
const LIABILITIES_COLOR = ModuleAccents.spend;

export default function AccountsScreen() {
  const router = useRouter();
  const { displayCurrency, homeCountry, availableCurrencies, convertToCurrency } = useCurrency();
  const { reportTap, step } = useTour();
  const isFabHighlighted = step?.highlightAnchor === 'accounts-fab';
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();
  const { filterAccounts } = useScope();
  const [allAccounts, setAccounts] = useState<AccountRow[]>([]);
  const accounts = filterAccounts(allAccounts);
  const [balanceByAccount, setBalanceByAccount] = useState<Map<string, number>>(new Map());
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [accountsResult, snapshotsResult, transactionsResult] = await Promise.all([
      supabase.from('accounts').select('*').order('name'),
      supabase.from('balance_snapshots').select('*').order('date', { ascending: false }),
      supabase.from('transactions').select('account_id, amount').not('account_id', 'is', null),
    ]);

    if (accountsResult.error) {
      setError(accountsResult.error.message);
      setIsLoading(false);
      return;
    }

    const latestSnapshots = latestSnapshotByAccount(snapshotsResult.data ?? []);
    const transactionSums = transactionSumByAccount(transactionsResult.data ?? []);

    const balances = new Map<string, number>();
    for (const account of accountsResult.data ?? []) {
      if (account.tracking_method === 'balance_based') {
        balances.set(account.id, latestSnapshots.get(account.id)?.balance ?? 0);
      } else {
        balances.set(account.id, transactionSums.get(account.id) ?? 0);
      }
    }

    setAccounts(accountsResult.data ?? []);
    setBalanceByAccount(balances);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const assets = accounts.filter((a) => a.account_type === 'asset');
  const liabilities = accounts.filter((a) => a.account_type === 'liability');

  // These totals sum across accounts that may be in different currencies,
  // so — same as the Home/Wealth screens — "Local" isn't a coherent option
  // here (it would sum raw numbers from different currencies as if they
  // were the same unit); resolveWealthCurrency picks a single real
  // currency to compute in instead, falling back to the home country's
  // currency, then USD.
  const wealthCurrency = resolveWealthCurrency(displayCurrency, homeCountry, availableCurrencies);

  function toSunburstAccounts(group: AccountRow[]): SunburstAccount[] {
    return group.map((account) => ({
      id: account.id,
      label: account.name,
      amount: Math.abs(convertToCurrency(balanceByAccount.get(account.id) ?? 0, account.currency, wealthCurrency.currency)),
    }));
  }

  const assetSlices = toSunburstAccounts(assets);
  const liabilitySlices = toSunburstAccounts(liabilities);
  const assetsTotal = assetSlices.reduce((sum, a) => sum + a.amount, 0);
  const liabilitiesTotal = liabilitySlices.reduce((sum, a) => sum + a.amount, 0);
  const totalsCurrency = wealthCurrency.currency;

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel
        connections={swipeConnections}
        isLoading={isConnectionsLoading}
        accentColor={ACCENT}
        destinationModule="accounts">
        <ScrollView
          style={isFabHighlighted ? styles.tourDimmed : undefined}
          contentContainerStyle={styles.content}
          refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
          <ScopeSwitch accent={ACCENT} onColor={ModuleAccentOnColor.accounts} />
          <ThemedText type="title" style={{ color: ACCENT }}>
            Accounts
          </ThemedText>
          {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

          <ThemedView style={styles.tierRow}>
            <Pressable style={styles.tileFlex} onPress={() => router.push('/accounts/assets')}>
              <Surface accentColor={ASSETS_COLOR} style={styles.tierTile}>
                <ThemedText style={styles.muted}>Assets</ThemedText>
                <ThemedText type="mono" style={styles.tierValue} numberOfLines={1} adjustsFontSizeToFit>
                  {formatMoney(assetsTotal, totalsCurrency)}
                </ThemedText>
              </Surface>
            </Pressable>
            <Pressable style={styles.tileFlex} onPress={() => router.push('/accounts/liabilities')}>
              <Surface accentColor={LIABILITIES_COLOR} style={styles.tierTile}>
                <ThemedText style={styles.muted}>Liabilities</ThemedText>
                <ThemedText type="mono" style={styles.tierValue} numberOfLines={1} adjustsFontSizeToFit>
                  {formatMoney(liabilitiesTotal, totalsCurrency)}
                </ThemedText>
              </Surface>
            </Pressable>
          </ThemedView>

          <Pressable onPress={() => router.push('/accounts/plaid')}>
            <Surface accentColor={ACCENT} style={styles.plaidRow}>
              <ThemedView style={styles.plaidText}>
                <ThemedText type="defaultSemiBold">Connect a Bank (test)</ThemedText>
                <ThemedText style={styles.muted}>Sandbox only, no real bank connection yet.</ThemedText>
              </ThemedView>
              <IconSymbol name="chevron.right" size={18} color={ACCENT} />
            </Surface>
          </Pressable>

          {wealthCurrency.source !== 'display' ? (
            <ThemedText style={styles.muted}>
              {wealthCurrency.source === 'home-country'
                ? `Showing in ${wealthCurrency.currency} (from your home country)`
                : `Showing in ${wealthCurrency.currency} (default, `}
              {wealthCurrency.source === 'default' ? (
                <Link href="/account">
                  <ThemedText type="link" style={styles.muted}>
                    set your home country in Account settings
                  </ThemedText>
                </Link>
              ) : null}
              {wealthCurrency.source === 'default' ? ')' : null}
            </ThemedText>
          ) : null}

          {!isLoading ? (
            <AssetLiabilitySunburst
              assets={assetSlices}
              liabilities={liabilitySlices}
              assetsColor={ASSETS_COLOR}
              liabilitiesColor={LIABILITIES_COLOR}
            />
          ) : null}

          <ThemedView style={styles.legendRow}>
            <ThemedView style={styles.legendItem}>
              <ThemedView style={[styles.swatch, { backgroundColor: ASSETS_COLOR }]} />
              <ThemedText style={styles.muted}>Assets ({assets.length})</ThemedText>
            </ThemedView>
            <ThemedView style={styles.legendItem}>
              <ThemedView style={[styles.swatch, { backgroundColor: LIABILITIES_COLOR }]} />
              <ThemedText style={styles.muted}>Liabilities ({liabilities.length})</ThemedText>
            </ThemedView>
          </ThemedView>
        </ScrollView>

        <Pressable
          onPress={() => {
            reportTap('accounts-fab');
            router.push('/accounts/new/edit');
          }}
          style={[styles.fab, { backgroundColor: ACCENT }, isFabHighlighted ? styles.fabHighlighted : null]}>
          <IconSymbol name="plus" size={28} color={ModuleAccentOnColor.accounts} />
        </Pressable>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  plaidRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  plaidText: {
    flex: 1,
    gap: 2,
    marginRight: 12,
  },
  content: {
    padding: 16,
    gap: 16,
    paddingBottom: 96,
  },
  tierRow: {
    flexDirection: 'row',
    gap: 8,
    alignSelf: 'stretch',
  },
  tileFlex: {
    flex: 1,
  },
  tierTile: {
    gap: 4,
  },
  tierValue: {
    fontSize: 18,
  },
  legendRow: {
    flexDirection: 'row',
    gap: 20,
  },
  legendItem: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
  },
  swatch: {
    width: 12,
    height: 12,
    borderRadius: 6,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
  fab: {
    position: 'absolute',
    right: 20,
    bottom: 28,
    width: 56,
    height: 56,
    borderRadius: 28,
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: '#000',
    shadowOpacity: 0.2,
    shadowRadius: 6,
    shadowOffset: { width: 0, height: 3 },
    elevation: 4,
  },
  fabHighlighted: {
    borderWidth: 4,
    borderColor: Colors.light.tint,
    shadowColor: Colors.light.tint,
    shadowOpacity: 0.6,
    shadowRadius: 10,
    elevation: 10,
  },
  // Applied to everything OTHER than the tour's currently-highlighted
  // element, when there is one — see app/index.tsx's own copy of this
  // style for why plain opacity on a wrapper beats a separately-positioned
  // overlay trying to track the element's screen position.
  tourDimmed: {
    opacity: 0.3,
  },
});
