import type { ConvertedAmount } from '@/contexts/currency-context';
import type { TransactionRow } from '@/types/database';

export type RecurringCadence = 'weekly' | 'monthly' | 'annual' | 'irregular';

export type RecurringMerchant = {
  merchant: string;
  currency: string;
  occurrences: number;
  /** Positive magnitude — same sign convention as the rest of this app's spend totals. */
  averageAmount: number;
  totalSpent: number;
  cadence: RecurringCadence;
  lastDate: string;
  /** lastDate + the typical gap between charges — null for 'irregular', where there's no consistent enough interval to project forward. */
  estimatedNextDate: string | null;
  /** averageAmount × charges-per-year implied by cadence — null for 'irregular', where that math would just amplify noise into a misleading number. */
  annualizedCost: number | null;
};

const MS_PER_DAY = 24 * 60 * 60 * 1000;

const OCCURRENCES_PER_YEAR: Record<'weekly' | 'monthly' | 'annual', number> = {
  weekly: 52,
  monthly: 12,
  annual: 1,
};

function classifyCadence(averageGapDays: number): RecurringCadence {
  if (averageGapDays >= 5 && averageGapDays <= 9) return 'weekly';
  if (averageGapDays >= 25 && averageGapDays <= 35) return 'monthly';
  if (averageGapDays >= 350 && averageGapDays <= 380) return 'annual';
  return 'irregular';
}

function addDays(dateStr: string, days: number): string {
  const d = new Date(dateStr);
  d.setDate(d.getDate() + Math.round(days));
  return d.toISOString().slice(0, 10);
}

/**
 * Detects recurring/subscription-like charges — the same merchant, in the
 * same currency, repeating at a roughly consistent interval. Pure
 * computation over transactions already in memory, same shape as
 * lib/spend.ts's summarize* functions: nothing here is persisted, and
 * there's no "dismiss/not a subscription" override yet — a merchant that
 * happens to repeat (e.g. two unrelated one-off charges to the same store)
 * just shows up as 'irregular' rather than being hideable.
 */
export function detectRecurringMerchants(
  transactions: Pick<TransactionRow, 'merchant' | 'amount' | 'currency' | 'date' | 'is_internal_transfer'>[],
  convert: (amount: number, fromCurrency: string) => ConvertedAmount
): RecurringMerchant[] {
  const groups = new Map<string, { merchant: string; currency: string; dates: string[]; amounts: number[] }>();

  for (const tx of transactions) {
    if (tx.is_internal_transfer || tx.amount >= 0 || !tx.merchant) continue;
    const merchantKey = tx.merchant.trim().toLowerCase();
    if (!merchantKey) continue;
    const { amount, currency } = convert(tx.amount, tx.currency);
    const key = `${merchantKey}::${currency}`;
    if (!groups.has(key)) {
      groups.set(key, { merchant: tx.merchant.trim(), currency, dates: [], amounts: [] });
    }
    const group = groups.get(key)!;
    group.dates.push(tx.date);
    group.amounts.push(Math.abs(amount));
  }

  const results: RecurringMerchant[] = [];
  for (const group of groups.values()) {
    if (group.dates.length < 2) continue;

    const sortedDates = [...group.dates].sort();
    const gaps: number[] = [];
    for (let i = 1; i < sortedDates.length; i++) {
      gaps.push((new Date(sortedDates[i]).getTime() - new Date(sortedDates[i - 1]).getTime()) / MS_PER_DAY);
    }
    const averageGap = gaps.reduce((sum, g) => sum + g, 0) / gaps.length;
    const cadence = classifyCadence(averageGap);
    const averageAmount = group.amounts.reduce((sum, a) => sum + a, 0) / group.amounts.length;
    const totalSpent = group.amounts.reduce((sum, a) => sum + a, 0);
    const lastDate = sortedDates[sortedDates.length - 1];

    results.push({
      merchant: group.merchant,
      currency: group.currency,
      occurrences: group.dates.length,
      averageAmount,
      totalSpent,
      cadence,
      lastDate,
      estimatedNextDate: cadence === 'irregular' ? null : addDays(lastDate, averageGap),
      annualizedCost: cadence === 'irregular' ? null : averageAmount * OCCURRENCES_PER_YEAR[cadence],
    });
  }

  return results.sort((a, b) => (b.annualizedCost ?? b.totalSpent) - (a.annualizedCost ?? a.totalSpent));
}

/** Sum of every confidently-recurring merchant's cost, normalized to a monthly figure — weekly ×52/12, annual ÷12 — for a single "~$X/mo" summary number. Irregular merchants are excluded since they have no annualizedCost to normalize. */
export function totalMonthlyRecurringCost(merchants: RecurringMerchant[]): number {
  return merchants.reduce((sum, m) => sum + (m.annualizedCost ?? 0) / 12, 0);
}
