import { useFocusEffect } from '@react-navigation/native';
import { useRouter } from 'expo-router';
import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, RefreshControl, ScrollView, StyleSheet } from 'react-native';

import { ConnectionsSwipePanel } from '@/components/connections-swipe-panel';
import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { IconSymbol } from '@/components/ui/icon-symbol';
import { Colors, ModuleAccentOnColor, ModuleAccents } from '@/constants/theme';
import { useSwipeConnections } from '@/hooks/use-swipe-connections';
import { DOCUMENT_TYPE_OPTIONS } from '@/lib/documents';
import { formatDateDisplay } from '@/lib/format';
import { supabase } from '@/lib/supabase';
import type { DocumentRow } from '@/types/database';

const ACCENT = ModuleAccents.documents;

export default function DocumentsScreen() {
  const router = useRouter();
  const { connections: swipeConnections, isLoading: isConnectionsLoading } = useSwipeConnections();
  const [documents, setDocuments] = useState<DocumentRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const { data, error: fetchError } = await supabase
      .from('documents')
      .select('*')
      .order('created_at', { ascending: false });

    if (fetchError) {
      setError(fetchError.message);
    } else {
      setDocuments(data ?? []);
    }
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const groups = DOCUMENT_TYPE_OPTIONS.map((option) => ({
    ...option,
    docs: documents.filter((d) => d.doc_type === option.value),
  })).filter((group) => group.docs.length > 0);

  return (
    <ThemedView variant="screen" style={styles.flex}>
      <ConnectionsSwipePanel
        connections={swipeConnections}
        isLoading={isConnectionsLoading}
        accentColor={ACCENT}
        destinationModule="documents">
      <ScrollView
        contentContainerStyle={styles.content}
        refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
        <ThemedText type="title" style={{ color: ACCENT }}>
          Documents
        </ThemedText>
        {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}

        {isLoading ? (
          <ActivityIndicator color={ACCENT} style={styles.sectionSpacing} />
        ) : documents.length === 0 ? (
          <ThemedText style={styles.muted}>No documents yet. Add your first one below.</ThemedText>
        ) : (
          groups.map((group) => (
            <ThemedView key={group.value}>
              <ThemedText type="subtitle" style={[styles.sectionSpacing, { color: ACCENT }]}>
                {group.label}
              </ThemedText>
              {group.docs.map((doc) => (
                <Pressable key={doc.id} onPress={() => router.push(`/documents/${doc.id}`)}>
                  <Surface accentColor={ACCENT} style={styles.docRow}>
                    <ThemedView style={styles.docInfo}>
                      <ThemedText type="defaultSemiBold" numberOfLines={1}>
                        {doc.name}
                      </ThemedText>
                      <ThemedText style={styles.muted}>
                        Uploaded {formatDateDisplay(doc.created_at.slice(0, 10))}
                      </ThemedText>
                    </ThemedView>
                    <IconSymbol name="chevron.right" size={18} color={ACCENT} />
                  </Surface>
                </Pressable>
              ))}
            </ThemedView>
          ))
        )}
      </ScrollView>

      <Pressable onPress={() => router.push('/documents/new')} style={[styles.fab, { backgroundColor: ACCENT }]}>
        <IconSymbol name="plus" size={28} color={ModuleAccentOnColor.documents} />
      </Pressable>
      </ConnectionsSwipePanel>
    </ThemedView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 96,
  },
  sectionSpacing: {
    marginTop: 16,
  },
  docRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 8,
    marginBottom: 8,
  },
  docInfo: {
    flex: 1,
    gap: 2,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
  fab: {
    position: 'absolute',
    right: 20,
    bottom: 28,
    width: 56,
    height: 56,
    borderRadius: 28,
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: '#000',
    shadowOpacity: 0.2,
    shadowRadius: 6,
    shadowOffset: { width: 0, height: 3 },
    elevation: 4,
  },
});
