/** The currency's own symbol ("$", "€", "¥"...) — falls back to the code itself (e.g. "USD") for currencies Intl has no dedicated glyph for. */
export function currencySymbol(currency: string): string {
  try {
    const parts = new Intl.NumberFormat(undefined, { style: 'currency', currency }).formatToParts(0);
    return parts.find((p) => p.type === 'currency')?.value ?? currency;
  } catch {
    return currency;
  }
}

export function formatMoney(
  amount: number,
  currency: string,
  options?: { decimals?: number; compact?: boolean }
): string {
  try {
    return new Intl.NumberFormat(undefined, {
      style: 'currency',
      currency,
      ...(options?.compact
        ? { notation: 'compact', maximumFractionDigits: options?.decimals ?? 1 }
        : options?.decimals != null
          ? { minimumFractionDigits: options.decimals, maximumFractionDigits: options.decimals }
          : {}),
    }).format(amount);
  } catch {
    return `${amount.toFixed(options?.decimals ?? 2)} ${currency}`;
  }
}
