export type TransactionSortField = 'date' | 'amount';
export type TransactionSortDirection = 'asc' | 'desc';

/**
 * "Amount" sorts by spend magnitude (Math.abs), not signed value — a
 * -$4,000 debit and a $4,000 credit are both "big" transactions, and a
 * sign-aware sort would bury large debits at the bottom under every
 * positive credit instead of surfacing the biggest transactions first.
 */
export function sortTransactions<T extends { date: string; amount: number }>(
  transactions: T[],
  field: TransactionSortField,
  direction: TransactionSortDirection
): T[] {
  const sorted = [...transactions].sort((a, b) => {
    const cmp = field === 'date' ? a.date.localeCompare(b.date) : Math.abs(a.amount) - Math.abs(b.amount);
    return direction === 'asc' ? cmp : -cmp;
  });
  return sorted;
}
