import { useFocusEffect } from '@react-navigation/native';
import { Link } from 'expo-router';
import { useCallback, useState, type ReactNode } from 'react';
import { Pressable, RefreshControl, ScrollView, StyleSheet } from 'react-native';

import { Surface } from '@/components/surface';
import { ThemedText } from '@/components/themed-text';
import { Colors } from '@/constants/theme';
import { useCurrency } from '@/contexts/currency-context';
import { useScope } from '@/contexts/scope-context';
import { latestSnapshotByAccount, transactionSumByAccount } from '@/lib/accountBalance';
import { formatMoney } from '@/lib/currency';
import { fetchAllRows } from '@/lib/fetchAll';
import { supabase } from '@/lib/supabase';
import type { AccountRow, BalanceSnapshotRow } from '@/types/database';

export type AccountListRow = { account: AccountRow; amount: number; currency: string };

/**
 * Shared fetch-balances-and-render-a-list for any account filter — pulled
 * out of app/accounts/index.tsx so the new Home-tile destination pages
 * (cash, investments, liabilities, assets) don't each reimplement the same
 * balance computation (latest snapshot for balance_based accounts, summed
 * transactions for transaction_based ones).
 */
export function AccountList({
  accent,
  matches,
  emptyLabel,
  renderExtra,
}: {
  accent: string;
  matches: (account: AccountRow) => boolean;
  emptyLabel: string;
  /** Rendered above the list, given the same filtered/converted rows this list is about to render — e.g. a pie chart. */
  renderExtra?: (rows: AccountListRow[]) => ReactNode;
}) {
  const { convert } = useCurrency();
  const { filterAccounts } = useScope();
  const [allAccounts, setAccounts] = useState<AccountRow[]>([]);
  const accounts = filterAccounts(allAccounts);
  const [balanceByAccount, setBalanceByAccount] = useState<Map<string, number>>(new Map());
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const [accountsResult, snapshotsResult, transactionsResult] = await Promise.all([
      supabase.from('accounts').select('*').order('name'),
      fetchAllRows<BalanceSnapshotRow>((from, to) =>
        supabase.from('balance_snapshots').select('*').order('date', { ascending: false }).order('id').range(from, to)
      ),
      fetchAllRows<{ account_id: string | null; amount: number }>((from, to) =>
        supabase
          .from('transactions')
          .select('account_id, amount')
          .not('account_id', 'is', null)
          .order('date')
          .order('id')
          .range(from, to)
      ),
    ]);

    if (accountsResult.error) {
      setError(accountsResult.error.message);
      setIsLoading(false);
      return;
    }

    const latestSnapshots = latestSnapshotByAccount(snapshotsResult.data ?? []);
    const transactionSums = transactionSumByAccount(transactionsResult.data ?? []);

    const balances = new Map<string, number>();
    for (const account of accountsResult.data ?? []) {
      if (account.tracking_method === 'balance_based') {
        balances.set(account.id, latestSnapshots.get(account.id)?.balance ?? 0);
      } else {
        balances.set(account.id, transactionSums.get(account.id) ?? 0);
      }
    }

    setAccounts(accountsResult.data ?? []);
    setBalanceByAccount(balances);
    setIsLoading(false);
  }, []);

  useFocusEffect(
    useCallback(() => {
      load();
    }, [load])
  );

  const rows: AccountListRow[] = accounts.filter(matches).map((account) => {
    const converted = convert(balanceByAccount.get(account.id) ?? 0, account.currency);
    return { account, amount: converted.amount, currency: converted.currency };
  });

  return (
    <ScrollView
      contentContainerStyle={styles.content}
      refreshControl={<RefreshControl refreshing={isLoading} onRefresh={load} />}>
      {error ? <ThemedText style={styles.error}>{error}</ThemedText> : null}
      {!isLoading && renderExtra ? renderExtra(rows) : null}
      {rows.length === 0 && !isLoading ? <ThemedText style={styles.muted}>{emptyLabel}</ThemedText> : null}
      {rows.map(({ account, amount, currency }) => (
        <Link key={account.id} href={`/accounts/${account.id}`} asChild>
          <Pressable>
            <Surface accentColor={accent}>
              <ThemedText type="defaultSemiBold">
                {account.name}
                {account.institution ? ` · ${account.institution}` : ''}
              </ThemedText>
              <ThemedText type="mono" style={styles.muted}>
                {formatMoney(amount, currency)}
              </ThemedText>
            </Surface>
          </Pressable>
        </Link>
      ))}
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  content: {
    padding: 16,
    gap: 8,
    paddingBottom: 48,
  },
  muted: {
    opacity: 0.7,
    fontSize: 14,
    color: Colors.light.textMuted,
  },
  error: {
    color: Colors.light.negative,
  },
});
